def sol():
	ok = []
	curr = 1
	first = a[0]
	i = 1
	while i < n:
		if abs(a[i] - first) <= d:
			if curr < k:
				curr += 1
			else:
				ok.append(a[i]) 
		else:
			if curr < k:
				for x in ok:
					if abs(x-a[i-1]) <= d:
						curr += 1
				if curr < k:
					return False
			ok = []
			first = a[i]
		i += 1
	return True

