def is_prime(n):
  if n in [2, 3, 5, 7]:
    return True
  elif 0 in [n%2, n%3, n%5, n%7]:
    return False
  else:
    check_max = math.floor(math.sqrt(n))
    for i in range(2, check_max):
      if n % i == 0:
        return False
    else:
      return True

