def prime_factorize(n):
    ans = []
    for i in range(2, int(n ** (1 / 2)) + 1):
        c = 1
        while True:
            if n % i:
                break
            c *= i
            n //= i
        if c > 1:
            ans.append(c)
        if n == 1:
            break
    if not n == 1:
        ans.append(n)
    return ans

def is_Prime(i):
    if i == 2:
        return True
    if i % 2 == 0 or i == 1:
        return False
    s = int(i ** (1 / 2))
    while True:
        if s == 1:
            return True
        if i % s == 0:
            return False
        s -= 1

