def solve():
    def root(x):
        if par[x] == x:
            return x
        par[x] = root(par[x])
        return par[x]

    def unite(x,y):
        x = root(x)
        y = root(y)
        if rank[x] < rank[y]:
            par[x] = y
        else:
            par[y] = x
            if rank[x] == rank[y]:
                rank[x] += 1

    n,d = LI()
    a = LI()
    b = [a[i]+d*i for i in range(n)]
    mb = [[None]*2 for i in range(n)]
    mb[n-1][0] = b[n-1]
    mb[n-1][1] = n-1
    for i in range(n-1)[::-1]:
        if b[i] < mb[i+1][0]:
            mb[i][0] = b[i]
            mb[i][1] = i
        else:
            mb[i][0] = mb[i+1][0]
            mb[i][1] = mb[i+1][1]
    a = [a[i]-d*i for i in range(n)]
    ma = [[None]*2 for i in range(n)]
    ma[0][0] = a[0]
    ma[0][1] = 0
    for i in range(n-1):
        if a[i+1] < ma[i][0]:
            ma[i+1][0] = a[i+1]
            ma[i+1][1] = i+1
        else:
            ma[i+1][0] = ma[i][0]
            ma[i+1][1] = ma[i][1]
    par = [i for i in range(n)]
    rank = [0]*n
    q = []
    for i in range(n):
        if i < n-1:
            q.append((a[i]+mb[i+1][0],i,mb[i+1][1]))
        if i > 0:
            q.append((b[i]+ma[i-1][0],i,ma[i-1][1]))
    q.sort()
    ans = 0
    for nd,x,y in q:
        if root(x) != root(y):
            unite(x,y)
            ans += nd
    print(ans)
    return

