            graph[l[0]] = set()
        if l[1] not in graph:
            graph[l[1]] = set()
        graph[l[0]].add(l[1])
        graph[l[1]].add(l[0])

    while 1:
        taka_options = taka(graph, v)
        taka_options_copy = dict(taka_options)
        for node in taka_options.keys():
            if node == u:
                continue
            visited_dfs = set()
            aokiFlag = 0
            DFSresult = DFS(graph, u, node, v, visited_dfs, aokiFlag)
            # print(DFSresult)
            if not DFSresult:
                del taka_options_copy[node]

        # print(taka_options_copy)
