def sum_by_digit_and_K(digit, K):
  temp = 9 ** K 
  res = []
  for i in range(1, digit+1-K):
    res.append(comb(i,K-1) * temp)
  print(res)
  return sum(res)

def solve(N, K, digit, let):
  res = 0
  for i in range(K):
    res += let[i] * sum_by_digit_and_K(digit-i, K-i)
  return res

