def refine(b_arr , revert = False):
    need = 0
    fract = []
    flag = 0
    lr_d = 1
    if revert :
        if(len(b_arr)%2 == 1):
            lr_d = 0

    for index , i in enumerate(b_arr):
        if((index+ lr_d) % 2 == 1):
            need += i
        else:
            need -= i
        if( need < 0):
            ad = b_arr[flag:index]+[b_arr[index] + need]
            if revert:
                fract.append(ad[::-1])
            else:
                fract.append(ad)
            flag = index+1
            need = 0
    if need >= 0 :
        if b_arr[flag:] :
            if revert:
                fract.append(b_arr[flag:][::-1])
            else:
                fract.append(b_arr[flag:])

    return [*filter(lambda x: x != [0] , fract)]


