    l = 0
    r = 0
    alada = []
    flag = 0
    for index , i in enumerate(arr):
        if((index+ 1) % 2 == 1):
            l += i
        else:
            r += i
        if (l == r):
            alada.append(arr[flag:index+1])
            flag = index + 1
            l , r = 0 , 0
    return alada

