    if l > r:
        k = arr[-1]-arr[-2]-(l-r)
    elif l < r:
        k = arr[0]-arr[1]-(r-l)
    else:
        k = arr[0]-arr[1]
    return k

def count(arr , memo = {}):
    ky = tuple(arr)
    if ( ky in memo):
        return memo[ky]

    if(len(arr) == 2 and arr[0] == arr[1]):
        return arr[0]

    k = rem_lr(arr)
    n_arr = [arr[0]-k] + arr[1:-1]+ [arr[-1]-k]
    possible = 0
    possible += k
    alada = devide(n_arr)
    for each in alada:
        possible += count(each)
    l = len(alada)
    possible += (l*(l-1))//2
    memo[ky] = possible
    return possible



