import heapq


def solve(a):
    pq = list()
    heapq.heapify(pq)
    delta = 0
    k = 0
    for i in range(len(a)):
        for x in a[i]:
            if k <= i:
                delta += x
                heapq.heappush(pq, -x)
                k += 1
            elif pq:
                delta += x
                heapq.heappush(pq, -x)
                delta += heapq.heappop(pq)
    return delta


