    i = 0
    k = n-1
    if l == n*(n-1)+1:
        return [1]
    while i < l:
        i += 2*k
        k -= 1
    s = []
    a = n
    for j in range(i+1-l):
        if j%2 == 0:
            s.append(a)
            a -= 1
        else:
            s.append(n-k-1)
    s = s[::-1]
    k = n-k
    a = k
    add = False
    if r == n*(n-1)+1:
        r -= 1
        add = True
    for j in range(r-i):
        if j%2 == 0:
            if a == n:
                k += 1
                a = k
            s.append(k)
        else:
            a += 1
            s.append(a)
    if add:
