def can_fill(n, m, k):
    if (k == 0):
        return (n % 2 == 0)
    else:
        if (n % 2 == 0):
            if (m == 1 or 2 * k < m):
                return False
            elif (m % 2 == 1):
                return (k % 2 == 0) and (2 * k < m * n) 
            else:
                return (k % 2 == 0)       
        if (n % 2 == 1):
            if (2 * k < m or 2 * k < n * (m - 1)):
                return False
            return can_fill(n - 1, m, k - m / 2)
    return False


