def solve():
    n, i = Read.list_int()
    a = Read.list_int()

    maxK = math.floor(2 ** ((i * 8) / n))
    a.sort()

    d = {}
    for i in a:
        if i in d:
            d[i] += 1
        else:
            d[i] = 1

    d = list(d.values())

    if maxK >= len(d):
        print(0)
        return

    s_max = 0
    for i in range(maxK):
        s_max += d[i]

    c_sum = s_max
    end = maxK - 1

    for i in range(maxK, len(d)):
        c_sum = c_sum - d[i - maxK] + d[i]
        if c_sum > s_max:
            s_max = c_sum
            end = i

    result = 0
    for i in range(end - maxK + 1):
        result += d[i]

    for i in range(end + 1, len(d)):
        result += d[i]

    print(result)




