def dig_to_num(digits):
	num = 0
	for i in range(len(digits)):
		num += digits[i] * (10 ** i)
	return num

def num_to_dig(num):
	return [(num // (10 ** i)) % 10 for i in range(len(str(num)))]


def solve(n, k):
	i = 0
	digits = num_to_dig(n)
	chosen_digits = [None] * k

	def debug_print():
		if not DEB:
			return
		print('\n\tn = {}\n\ti = {}\n\tk-beautiful = {}\n\tchosen = {}'.format(n, i, dig_to_num(list(reversed(digits))), chosen_digits))

	# we want the most valuable digits, last in the list
	digits.reverse()


	while i < len(digits):
		debug_print()

		dig = digits[i]

		if i < k:
			chosen_digits[i] = dig
			digits[i] = dig
			i += 1
			continue

		if dig in chosen_digits:
			digits[i] = dig
			i += 1

		else:
			if dig > max(chosen_digits):
				# add minimum amount needed to make n beautiful up to i
				i -= 1
				dig = digits[i]
				L = len(digits) - i
				n += (dig + 1) * 10 ** (L - 1) - n % (10 ** L)
				digits = num_to_dig(n)
				digits.reverse()
				continue

			else:
				chosen_with_dig = chosen_digits + [dig]
				chosen_with_dig.sort()
				dig = chosen_with_dig[(chosen_with_dig.index(dig) + 1) % len(chosen_with_dig)]
				digits[i] = dig
				i += 1

	debug_print()

	# reversing again back to normal
	digits.reverse()

	return dig_to_num(digits)


