    for counter, guest in enumerate(company.list_of_guests):
        if counter > 0:
            if company.list_of_guests[counter-1].money == guest.money:
                continue
        company.compute_total_friendship_given_specified_guest(guest)

    print(company.maximum_sum_of_friendship)

def binsearch(x, list1):
    answer = None
    left = 0
    right = len(list1) - 1
    while answer == None:
        i = (left + right) // 2
        if list1[i] == x:
            answer = i
        elif list1[i] > x:
            right = i
        else:
            left = i
        if right - left < 2:
            if list1[right] == x:
                return right
            if list1[left] == x:
                return left
            else:
                return right
    return answer



