def minprime(n):
  if n %2==0:
      return 2
  if n%3==3:
      return 3
  max_t=10**5+9
  for k in range(6,max_t,6):
      if n%(k-1)==0:
          return k-1
      if n%(k+1)==0:
          return k+1
  return n

