def checkarr(arr):
    if len(arr) != 3:
        exit()
    xnum, dotnum = 0, 0
    for i in arr:
        if i == 'x':
            xnum += 1
        elif i == '.':
            dotnum += 1
    if xnum == 2 and dotnum == 1:
        return True
    return False

def check_horizontal(tab):
    for i in range(4):
        for j in range(2):
            arr = tab[i][j:j+3]
            if checkarr(arr):
                print(arr)
                return True
    return False

def check_vertical(tab):
    for i in range(2):
        for j in range(4):
            arr = [tab[i][j], tab[i+1][j], tab[i+2][j]]
            if checkarr(arr):
                return True
    return False

def check_diag(tab):
    for i in range(2):
        for j in range(2):
            arr = [tab[i][j], tab[i+1][j+1], tab[i+2][j+2]]
            if checkarr(arr):
                return True
    for i in range(3, 4):
        for j in range(2):
            arr = [tab[i][j], tab[i - 1][j + 1], tab[i - 2][j + 2]]
            if checkarr(arr):
                return True
    return False

if check_horizontal(table):
    print('YES')
elif check_diag(table):
    print('YES')
elif check_vertical(table):
    print('YES')
else:
    print('NO')

import fractions

def prime_generator(upper):
    primes = [2, 3]
    yield 2
    yield 3

    for i in range(5, upper+1, 2):
        is_prime = True
        for p in primes:
            if p ** 2 > i:
                break
            if i % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(i)
            yield i

