def query(query_lower, query_upper, range_lower, range_upper, index):
    if query_lower <= range_lower and query_upper >= range_upper:
        return seg_tree[index]
    if query_lower > range_upper or query_upper < range_lower:
        return -1
    mid = (range_lower + range_upper) >> 1
    return max(query(query_lower, query_upper, range_lower, mid, index << 1),
               query(query_lower, query_upper, mid+1, range_upper, index << 1 | 1))


def update(pos, val, range_lower, range_upper, index):
    if range_lower == range_upper:
        seg_tree[index] = max(seg_tree[index], val)
        return
    mid = (range_lower + range_upper) >> 1
    if pos <= mid:
        update(pos, val, range_lower, mid, index << 1)
    else:
        update(pos, val, mid+1, range_upper, index << 1 | 1)
    seg_tree[index] = max(seg_tree[index << 1], seg_tree[index << 1 | 1])





