def gcd(a,b):
    if a < b:
        a,b = b,a
    #
    xa, xb, ya, yb = 1, 0, 0, 1
    while b != 0:
        _xb, _yb = xb, yb
        xb = xa - (a//b)*xb
        yb = ya - (a//b)*yb
        xa, ya = _xb, _yb
        a, b = b, a%b

        #print(a, b, xa, ya, xb, yb)

    return (a, xa, ya)

def ans(a,b,c):
    if c == 0:
        return 'Yes'
    s, x, y = gcd(a,b)
    if c % s != 0:
        return 'No'
    x *= c//s
    y *= c//s
    if x > 0 and y > 0:
        return 'Yes'
    if x > 0:
        x, y = y, x
        a, b = b, a
    # x < 0
    n = abs(x) // (b // s) + 1
    if abs(x) % (b // s) == 0:
        n -= 1
    y = y - n*(a//s)
    if y > 0:
        return 'Yes'
    return 'No'

