            while i > 0:
                i = (i - 1) // 2
                st1[i] = max(st1[i * 2 + 1], st1[i * 2 + 2])

        def query_max(l, r):
            L = l + N0;
            R = r + N0
            ret = 0
            while L < R:
                if L % 2:
                    ret = max(ret, st1[L - 1])
                    L += 1
                if R % 2:
                    R -= 1
                    ret = max(ret, st1[R - 1])
                L //= 2;
                R //= 2
            return ret

        def update_min(i, x):
            i += N0 - 1
            st0[i] = min(st0[i], x)
            while i > 0:
                i = (i - 1) // 2
                st0[i] = min(st0[i * 2 + 1], st0[i * 2 + 2])

        def query_min(l, r):
