def mex(a: list):
    mx, i = 0, 0
    a.sort()
    if not (0 in a) or not len(a):
        return 0
    if len(a) == 1:
        return 1
    while i < len(a):
        if a[i] - mx > 1:
            return mx + 1
        mx = a[i]
        i += 1
    return mx + 1

