#!/usr/bin/env python3

def msb(x):
	i = 0
	p = 1

	assert x != 0

	while (p < x):
		i += 1
		p = p << 1

	return i

def solve():
	n, m = map(int, input().split(" "))
	M = m + 1

	if n == 0:
		return m + 1
	elif m == 0:
		if n == 0:
			return 1
		else:
			return 0

	ub = max(msb(n), msb(M))

	mex = 0
	p = 1 << (ub - 1)
	for bit in range(ub, 0, -1):
		l_bit = (n & p) > 0
		r_bit = (M & p) > 0
		set_this_bit = False

		if r_bit and not l_bit:
			set_this_bit = True
		elif l_bit and not r_bit:
			return mex

		if set_this_bit:
			mex = mex | p
		p = p >> 1

	return mex

