def findMood(arr, queries):
    n = len(arr)
    t = len(queries)
    if n==0:
        return 0
    preSum = [arr[0]]

    for i in range(1, n):
        preSum.append(preSum[i-1]+arr[i])

    maxm = float('-inf')

    for i in range(t):
        p = queries[i][0]-1
        q = queries[i][1]-1

        if p == 0:
            currSum = preSum[q]
        else:
            currSum = preSum[q]-preSum[p-1]

        if currSum+maxm > currSum:
            maxm = currSum+maxm
        elif currSum > maxm:
            maxm = currSum

    if maxm<=0:
        return 0

    return maxm


