import math
import sys

def get_next(x):
    t = (-3 + math.sqrt(12 * x - 3)) / 6.0
    t = math.floor(t)
    for i in range(max(t - 6, 1), t + 7):
        nx = x + i ** 3
        if nx < (i + 1) ** 3:
            return nx, i
    assert(False)

def can_be_lower(cur, to_go, high):
    if cur > high:
        return False
    for i in range(to_go):
        cur = get_next(cur)[0]
        if cur > high:
            return False
    return True

def get_highest(cur, to_go, le, high):
    orig_le = le
    rg = 10 ** 5 + 123
    while rg - le > 1:
        mid = (le + rg) // 2
        if can_be_lower(cur + mid ** 3, to_go - 1, high):
            le = mid
        else:
            rg = mid
    for x in range(max(orig_le, le - 15), le + 1):
        yield cur + x ** 3

def solve(high):
    level = 0
    cur = 1
    while cur <= high:
        level += 1
        cur = get_next(cur)[0]

    cur = [1]
    for i in range(level - 1):
        to_go = level - i - 1
        lst_nx = []
        for x in cur:
            nx, mn = get_next(x)
            for nx in get_highest(x, to_go, mn, high):
                lst_nx.append(nx)
        cur = list(set(lst_nx))

    return level, max(cur)

