def read_int(n):
    return read_type(int, n)


def read_float(n):
    return read_type(float, n)


def read_type(t, n):
    return list(map(lambda x: t(x), read_line().split(' ')))[:n]


def read_line(n=0):
    if n == 0:
        return input().rstrip()
    else:
        return input().rstrip()[:n]


def think(data):
    mode = 10 ** 9 + 7
    num_of_digits = num_of_bits(max(data))

    result = 0
    for i in range(num_of_digits):
        num_of_zero = 0
        num_of_one = 0
        for d in data:
            if is_flag_set(d, i):
                num_of_one += 1
            else:
                num_of_zero += 1
        result += num_of_zero * num_of_one * (1 << i)
        result %= mode
    # return naive_think(data)
    return result


def is_flag_set(d, bits):
    return (d >> bits) % 2 == 1


def naive_think(data):
    mode = 10 ** 9 + 7
    result = 0
    for i in range(len(data)):
        for j in range(i + 1, len(data)):
            result += data[i] ^ data[j]
            result %= mode
    return result


def write(result):
    print(result)


def num_of_bits(n):
    count = 0
    while n > 0:
        n //= 2
        count += 1
    return count


