def dfs(N, L, s, node = None, blocks = None):
    depth = [-1] * N

    stack = [(0, s)]
    while stack:
        d, p = stack.pop()
        depth[p] = d

        if blocks is not None:
            if d == 0:
                depth[p] = -1
            else:
                if d == blocks[p]:
                    continue

                if node is not None and p in node:
                    depth[p] =  d + 2 * ((blocks[p] - d) // 2)
                    continue

        for q in L[p]:
            if blocks is not None:
                if blocks[q] < d + 1:
                    continue

            if depth[q] != -1:
                continue
            stack.append((d + 1, q))
    return depth


