def solve(n,k,l):
    d = [[0 for i in range(n)] for i in range(n)]
    for i in range(n):
        for j in range(i+1,n):
            d[i][j] = abs(l[i][0] - l[j][0]) + abs(l[i][1] - l[j][1])
            if(d[i][j]>2*k):
                return -1
            elif(d[i][j]>k):
                index = binary_search(d[i],i,j,d[i][j]-k)
                if(index == -1):
                    return -1
    return 1

def binary_search(arr, low, high, x): 
    if high >= low: 
        mid = (high + low) // 2
        if arr[mid] == x: 
            return mid 
        elif arr[mid] > x: 
            return mid 
        else: 
            return binary_search(arr, mid + 1, high, x) 
    else: 
        return -1

