def gcd(a, b):
    """Compute the greatest common divisor of a and b"""
    while b > 0:
        a, b = b, a % b
    return a


def lcmf(a, b):
    """Compute the lowest common multiple of a and b"""
    return a * b // gcd(a, b)


def main():
    cc = int(input())
    for ccc in range(cc):
        a, b, q = [int(v) for v in input().split()]
        data = []
        lcm = lcmf(a, b)
        for i in range(0, lcm+1):
            if (i % a) % b != (i % b) % a:
                data.append(1)
            else:
                data.append(0)

        res = []
        for cccc in range(q):
