from heapq import heappush, heappop

cache = {}


def remaining_expected_cost(a):
    global n, b, cache
    key = tuple(i for i in range(n) if a[i] != b[i])
    if key in cache:
        return cache[key]
    return sum(a[i] for i in key)


def stack(node):
    global heap, n
    for i in range(n - 1):
        for j in range(i + 1, n):
            swapped = (i, j)
            if swapped == node[2]:
                continue
            a = node[3][:]
            w1, w2 = a[i], a[j] = a[j], a[i]
            spent_cost = node[1] + w1 + w2
            rec = remaining_expected_cost(a)
            if not rec:
                return spent_cost
            heappush(heap, (spent_cost + rec, spent_cost, swapped, a))
    return False


