from itertools import permutations
from collections import deque


def has_cycle(n, g):
    for start in range(n):
        prev = [-1] * n
        t = [-1] * n

        q = deque()
        q.append(start)
        t[start] = 0

        while q:
            v = q.popleft()

            for w in g[v]:
                if t[w] != -1:
                    if t[w] >= t[v]:
                        return True
                else:
                    t[w] = t[v] + 1
                    prev[w] = v
                    q.append(w)
    return False


def test(n, a):
    g = [[] for _ in range(n)]
    for i in range(n):
        j = i - 1
        while j >= 0 and a[j] < a[i]:
            j -= 1
        if j >= 0:
            g[i].append(j)
            g[j].append(i)
        j = i + 1
        while j < n and a[j] < a[i]:
            j += 1
        if j < n:
            g[i].append(j)
            g[j].append(i)
    return has_cycle(n, g)


