def dfs(graph, node, visited):
	if visited[node] == False:
		visited[node] = True
		component = 1
		try:
			for i in graph[node]:
				if visited[i] == False:
					component += dfs(graph, i, visited)
		except:
			pass
			#print('second error')
		return component
	else:
		return 0


