def process(a, b, k):
    # a is constraining and should be processed first
    result = 0
    bIndices = {i for _, i in b}
    used = set()
    aNeeded, bNeeded = k, k
    for val, i in a:
        if aNeeded == 0:
            break
        if i in bIndices:
            bNeeded -= 1
        aNeeded -= 1
        used.add(i)
        result += val
    for val, i in b:
        if bNeeded == 0:
            break
        if i in used:
            continue
        result += val
        bNeeded -= 1
    return result


