class Stack:
	def __init__(self):
		self.stk = []

	def push(self, value):
		self.stk.append(value)

	def pop(self):
		return self.stk.pop()

	def peek(self):
		return self.stk[-1]

	def empty(self):
		return len(self.stk) == 0


def fun(array):
	a, s = 0, Stack()
	for i, value in enumerate(array):
		while value > a:
			a += 1
			s.push(a)

		if s.peek() == value:
			s.pop()
		else:
			return False
	return True

