def isin(l,x):
    left=0
    right=len(l)-1
    if x<l[0]:
        return -1
    while left<=right:
        mid=left + (right -left)//2
        if l[mid]==x:
            return mid
        elif l[mid]<x:
            ans=mid
            left=mid+1
        else:
            right=mid-1
    return ans

