import sys

def binary_search(left, right, count):
    while right - left > 1:
        middle = (left + right) // 2
        if middle * (middle + 1) // 2 < count:
            left = middle
        else:
            right = middle
    if right * (right + 1) // 2 < count:
        return right
    else:
        return left

