from math import *

def nStep(n):
    if (n==0):
        return 0
    for i in range(2,floor(sqrt(n)+2),1):
        if (n % i == 0):
            return floor(n/i)+nStep(n % i)
    return 1
def main():
    global n
    n=int(stdin.readline())
    stdout.write(str(nStep(n)))
    return 0



