    while zerobefore and countervariable<=length-1:
        if inputlist[countervariable]!=0:
            zerobefore=False
        else:
            chainedzeros+=1
            countervariable+=1
    if chainedzeros>1:
        return [True,countervariable]
    else:
        return [False,countervariable]
