        oddodd+=-1
    while oddmissing!=0 and len(chainoddodd)!=0:
        oddmissing+=-1
        chainoddodd[-1]+=-1
        if chainoddodd[-1]==0:
            chainoddodd.pop()
    while oddmissing!=0 and len(odd)!=0:
        oddmissing+=-1
        odd[-1]+=-1
        if odd[-1]==0:
            odd.pop()
    if evenmissing>=oddmissing:
        evenmissing+=-oddeven
    else:
        oddmissing+=-oddeven
    while oddmissing!=0 and len(chainoddeven)!=0:
        oddmissing+=-1
        chainoddeven[-1]+=-1
        if chainoddeven[-1]==0:
            chainoddeven.pop()
            complexity+=1
    while evenmissing!=0 and len(chainoddeven)!=0:
        evenmissing+=-1
        chainoddeven[-1]+=-1
        if chainoddeven[-1]==0:
            chainoddeven.pop()
            complexity+=1
    complexity+=oddeven+len(chainoddeven)+2*len(chainoddodd)+2*len(chaineveneven)+2*oddodd+2*eveneven+len(odd)+len(even)
    return complexity

