class UnionFind():
    def __init__(self,size):
        self.data=[-1 for i in range(size)]
    def root(self,x):
        if self.data[x]<0:
            return x
        else:
            self.data[x]=self.root(self.data[x])
            return self.data[x]
    def united(self,x,y):
        return self.root(x)==self.root(y)
    def unite(self,x,y):
        x=self.root(x)
        y=self.root(y)
        if x!=y:
            x,y=sorted((x,y))
            self.data[x]+=self.data[y]
            self.data[y]=x
    def dump(self):
        print(self.data)

