	else:
		mid=(start+end)//2
		build(arr,2*cur_pos+1,start,mid,seg,pre)
		build(arr,2*cur_pos+2,mid+1,end,seg,pre)
		seg[cur_pos]=merge(seg[2*cur_pos+1],seg[2*cur_pos+2],arr,start,mid,end)
def merge(L1,R1,arr,low,mid,high):
	# #print(L,R,len(L),len(R))
	L=L1[0]
	R=R1[0]
	i=0
	j=0
	k=low
	while(i<len(L) and j<len(R)):

		if(L[i][1]<R[j][1]):
			if(k!=low):
				pre[k]=pre[k-1]+L[i][0]
			else:
				pre[k]=L[i][0]
			arr[k]=(L[i])
			i+=1
		else:
			if(k!=low):
				pre[k]=pre[k-1]+R[j][0]
			else:
				pre[k]=R[j][0]
			arr[k]=(R[j])
			j+=1
		k+=1
	while(i<len(L)):
		if(k!=low):
			pre[k]=pre[k-1]+L[i][0]
		else:
			pre[k]=L[i][0]
		arr[k]=(L[i])
		i+=1
		k+=1

	while(j<len(R)):
		if(k!=low):
			pre[k]=pre[k-1]+R[j][0]
		else:
			pre[k]=R[j][0]

		arr[k]=(R[j])
		j+=1
		k+=1
	return (arr[low:high+1],pre[low:high+1])
def bs(arr,k,start,end,n):
	if(start<=end):
		mid=(start+end)//2
		if(arr[mid][1]>=k):
			if(mid==0):
				return -1
			return	bs(arr,k,start,mid-1,n)
		else:
			z=bs(arr,k,mid+1,end,n)
			if(z==-1):
				return mid
			else:
				return z
	return -1

