def findClosest(arr,n,target):
    if (target <= arr[0]):
        return arr[0]
    if (target >= arr[n - 1]):
        return arr[n - 1]
    i = 0; j = n; mid = 0
    while (i < j):
        mid = (i + j)//2
        if (arr[mid] == target):
            return arr[mid]
        if (target < arr[mid]) :
            if (mid > 0 and target > arr[mid - 1]):
                return getClosest(arr[mid - 1], arr[mid], target)
            j = mid
        else :
            if (mid < n - 1 and target < arr[mid + 1]):
                return getClosest(arr[mid], arr[mid + 1], target)
            i = mid + 1
    return arr[mid]
