def ways(n,k,a):
    lcost,mid,rcost = 0,0,0
    a.sort()
    for i in range (n-k+1):
        if(a[i]==a[i+k-1]):
            return 0
    for i in range (k):
        lcost += a[k-1]-a[i]
        rcost += a[n-1-i]-a[n-k];
    for i in range (k,n,1):
        if(a[k-1]==a[i]):
            lcost -= 1
        if(a[n-k]==a[n-1-i]):
            rcost -= 1
    mid = 0
    for i in range ((n-1)//2):
        mid += a[n-1-i]-a[i]

    return min(mid-(n-k),min(rcost,lcost))


