def ans(poem):
  ans = 0

  l = 0
  minStart = 0
  while l < len(poem) - 1:
    if l + 2 < len(poem):
      if poem[l] == poem[l+1] and poem[l] == poem[l+2]:
        ans += 2
        l = l+3
        continue
    newR1 = findPalindrome(poem, l, l+1, minStart)
    newR2 = findPalindrome(poem, l-1, l+1, minStart)
    newL = math.inf
    if newR1 is not None or newR2 is not None:
      ans += 1
    else:
      newL = l + 1
    if newR1 is not None:
      minStart = newR1 + 1
      newL = newR1 + 1
    if newR2 is not None:
      # minStart = min(minStart, newR2+1)
      if newR2 + 1 < newL:
        minStart = newR2+1
      newL = min(newL, newR2+1)
    l = newL

  return ans

