import sys

def countbytes(liste):
    participants = []
    number_of_bytes = 0
    for i in liste:
        if i.startswith("+") and i[1:len(i)] not in participants:
            participants.append(i[1:len(i)])
        if i.startswith("-") and i[1:len(i)] in participants:
            participants.remove(i[1:len(i)])
        else:
            for name in participants:
                if i.startswith(name + ":"):
                    message = i.split(":")[1]
                    number_of_bytes += len(message)
    return number_of_bytes

