	L_map = {}
	R_map = {}
	_TL = 0
	_TR = 0
	for i,t in enumerate(tlst):
		_TL += t
		_TR += tlst[len(tlst) - i - 1]
		L_map[i] = _TL
		R_map[i] = _TR
	scoreL = 0
	scoreR = 0
	for i in range(len(plst)):
		x_L = L_map[i]
		x_R = R_map[i]
		scoreL += calcPoint(plst[i], c, x_L)
		scoreR += calcPoint(plst[len(plst) - i - 1], c, x_R)
	if scoreL > scoreR:
		return "Limak"
	if scoreR > scoreL:
		return "Radewoosh"
	return "Tie"

