import math


def is_prime(x):
    # Primality Test
    if x <= 1 or x % 2 == 0:
        return False

    if x == 2:
        return True

    i = 3
    while i <= math.sqrt(x):
        if x % i == 0:
            return False
        i += 2
    return True


