class CodeforcesTask12BSolution:
    def __init__(self):
        self.result = ''
        self.number = 0
        self.solution = 0

    def read_input(self):
        self.number = int(input())
        self.solution = int(input())

    def process_task(self):
        try:
            if len(str(self.solution)) > 1 and str(self.solution)[0] == "0":
                self.result = "WRONG_ANSWER"
            else:
                cnts = [0] * 10
                for c in str(self.number):
                    cnts[int(c)] += 1
                start = min([int(x) for x in str(self.number) if int(x)])
                cnts[start] -= 1
                res = [start]
                for x in range(10):
                    res += [x] * cnts[x]
                real_result = int("".join([str(x) for x in res]))
                self.result = "OK" if real_result == self.solution else "WRONG_ANSWER"
        except ValueError:
            self.result = "WRONG_ANSWER"

    def get_result(self):
        return self.result


