def makeletter(s):
    if s >= 10:
        return chr(ord("A") + s - 10)
    else:
        return str(s)


def to10(k, s):
    curr = 0
    for i in range(-1, len(s) - 1):
        if 'A' <= s[i + 1] <= 'Z':
            curr = curr * k + (ord(s[i + 1]) - ord('A') + 10)
        else:
            curr = curr * k + int(s[i + 1])
    return curr


def from10(k, s):
    ans = ''
    s = int(s)
    while s >= k:
        ans += makeletter(s % k)
        s //= k
    ans += makeletter(s)
    return ans[::-1]

