    a = int(inp[0])
    b = int(inp[1])
    res = 0
    if a == 0 or b == 0:
        return res

    if a < 2 and b < 2:
        return res

    high = max([a,b])
    low = min([a,b])
    diff = high - low
    if low < diff:
        diff = low

    if diff > 2:
        low -= diff
        high -=2*diff
        res += diff

    #low = high +- 1

    if high == 0 or low == 0:
        return res

    if high < 2 and low < 2:
        return res

    if low > high:
        high, low = low, high


    if low == high == 4:
        res += 2
    else:
        res += int(high / 2) + 1

    return res






