def dijkstra(s,n,w,cost):
    d=[float("inf")]*n
    used=[False]*n
    d[s]=0
    while True:
        v = -1
        for i in range(n):
            if (not used[i]) and (v==-1):
               v=i
            elif (not used[i]) and d[i]<d[v]:
                v=i
        if v==-1:
               break
        used[v]=True

        for j in range(n):
               d[j]=min(d[j],d[v]+cost[v][j])
    return d

