mod = 10**9 + 7

def pow_k(x, n):
    """
    O(log n)
    """
    if n == 0:
        return 1
    K = 1
    while n > 1:
        if n % 2 != 0:
            K = (K * x) % mod 
            x = (x ** 2) % mod
            n = (n - 1) // 2
        else:
            x = (x ** 2) % mod
            n = n // 2

    return (K * x) % mod # 指数を割り続け n が 1 に至ったら終了

