from collections import deque
class heap:
    def __init__(self,k):
        self.heap=deque()
        self.len=0
        self.k=k
        self.reversedheap=deque()
    def add(self,x):
        self.heap.appendleft(x)
        self.reversedheap.appendleft(x)
        self.len+=1
        self.standize()
        if self.len>self.k:
            self.pop()
            self.len=self.k
        self.standize()



    def pop(self):
        self.heap.remove(self.reversedheap.popleft())
    def standize(self):        
        t=0
        k=self.len
        while 2*t+1<=k-1:
            if self.reversedheap[t]>self.reversedheap[2*t+1]:
                self.reversedheap[2*t+1],self.reversedheap[t]=self.reversedheap[t],self.reversedheap[2*t+1]
                t=2*t+1
            elif 2*t+2<=k-1 and self.reversedheap[t]>self.reversedheap[2*t+2]:
                self.reversedheap[2*t+2],self.reversedheap[t]=self.reversedheap[t],self.reversedheap[2*t+2]
                t=2*t+2
            else:
                break
        t=0
        while 2*t+1<=k-1:
            if self.heap[t]<self.heap[2*t+1]:
                self.heap[2*t+1],self.heap[t]=self.heap[t],self.heap[2*t+1]
                t=2*t+1
            elif 2*t+2<=k-1 and self.heap[t]<self.heap[2*t+2]:
                self.heap[2*t+2],self.heap[t]=self.heap[t],self.heap[2*t+2]
                t=2*t+2
            else:
                break
    def show(self,x):
        if x in set(self.heap):
            print('YES')
        else:
            print('NO')

