class ArrayStack:
    def __init__(self):
        self._data = []
    def __len__(self):
        return len(self._data)
    def is_empty(self):
        return len(self._data)==0
    def push(self,e):
        self._data.append(e)
    def top(self):
        if self.is_empty():
            raise Empty('Stack is empty')
        return self._data[-1]
    def pop(self):
        if self.is_empty():
            raise Empty('Stack is empty')
        return self._data.pop()

def is_matched(expr):
    S = ArrayStack()
    for c in expr:
        if c == '+' or c == '-':
            if c not in S._data:
                S.push(c)
            elif c != S.pop():
                return False
        else:
            raise ValueError("Please enter '+' or '-'")
    return S.is_empty()

