def main():
    def make_prime_list_2(num):
        if num < 2:
            return []

        # 0のものは素数じゃないとする
        prime_list = [i for i in range(num + 1)]
        prime_list[1] = 0 # 1は素数ではない
        num_sqrt = math.sqrt(num)

        for prime in prime_list:
            if prime == 0:
                continue
            if prime > num_sqrt:
                break

            for non_prime in range(2 * prime, num, prime):
                prime_list[non_prime] = 0

        return [prime for prime in prime_list if prime != 0]

    def search_divisor_num_1(num):
        if num < 0:
            return None
        elif num == 1:
            return 1
        else:
            num_sqrt = math.floor(math.sqrt(num))
            prime_list = make_prime_list_2(num_sqrt)

            divisor_num = 1
            for prime in prime_list:
                count = 1
                while num % prime == 0:
                    num //= prime
                    count += 1
                divisor_num *= count

            if num != 1:
                divisor_num *= 2

            return divisor_num

    def num_divisors_trial_division(n):
        num = 0
        for i in range(1, int(math.sqrt(n) + 1e-9) + 1):
            if n % i == 0:
                num += 1
                if n != i**2:
                    num += 1

        return num

    n = i_input()
    ans = 0
    for i in range(1,n):
        ans += num_divisors_trial_division(i)
    print(ans)

