from math import ceil

def gcdExt(a,b):
    if a<0 or b<0:
        return -1
    if b==0:
        return a,1,0
    g,x1,y1=gcdExt(b,a%b)
    x=y1
    y=x1-(a//b)*y1
    return g,x,y

def gcdNew(a,b):
    flag=0
    if a<b:
        flag=1
        g,x,y=gcdExt(b,a)
    else:
        g,x,y=gcdExt(a,b)
    if flag:
        x,y=y,x
    if a*x+b*y==g:
        return g,x,y
    else:
        return g,-x,-y



