def numberof753bydig(dig,nummustcontain=3):
    if nummustcontain==3:
        ex=3*2**dig-3
    elif nummustcontain==2:
        ex=2*2**dig-1
    elif nummustcontain==1:
        ex=2**dig
    else:
        ex=0
    return 3**dig-ex
def numberof753(n,used=set()):
    if n==0: return 0
    dig=math.ceil(math.log10(n))
    res=0
    if len(used)==0:
        res=sum(numberof753bydig(i) for i in range(1,dig))
    top=n//10**(dig-1)
    if top in (3,5,7):
        res+=numberof753(n%10**(dig-1),used.union({top}))
    if top>3:
        res+=numberof753bydig(dig-1,3-len(used.union({3})))
    if top>5:
        res+=numberof753bydig(dig-1,3-len(used.union({5})))
    if top>7:
        res+=numberof753bydig(dig-1,3-len(used.union({7})))
    if len(used)==3 or {n}=={3,5,7}.difference(used):
        res+=1
    return res
