def get_score(a):
    ans = 0
    for i, v in enumerate(a):
        if i == 0:
            ans += 0 if a[i] == 'L' else 1
        else:
            if a[i] == 'W':
                ans +=2 if a[i-1] == 'W' else 1
            else:
                continue
    return ans

# This function returns a vector of pairs (hole_size, hole_starting_index)
# e.g. For string 'WLWWLLLW', it returns [(1, 1), (3, 4)], where (1, 1) stands
# there is a length-1 hole starting at index 1, and (3, 4) stands that there
# is a length-3 hole starting at index 4.
def get_holes(a):
    h= []
    start_idx, cur_hole_size = -1, 0
    for i in range(len(a)):
        if a[i] == 'W':
            if cur_hole_size > 0:
                h.append((cur_hole_size, start_idx))
                start_idx, cur_hole_size = -1, 0
        else:
            cur_hole_size += 1

            if start_idx == -1:  # not initialized
                start_idx = i

            if i == len(a) - 1:
                h.append((cur_hole_size, start_idx))
    return h

def solve(n_k, a):
    h = get_holes(a)

    # No holes
    if len(h) == 0:
        return get_score(a)

    start_hole, end_hole = [None, None], [None, None]

    # If there is a hole at the end, pop it out.
    if h[len(h)-1][1] + h[len(h)-1][0] == len(a):
        end_hole = h.pop(len(h)-1)

    # If there is hole starting at index 0, pop it out.
    if len(h) > 0 and h[0][1] == 0:
        start_hole = h.pop(0)

    h_sorted = sorted(h)
    if start_hole != [None, None] and end_hole != [None, None]:
        if start_hole[0] >= end_hole[0]:
            h_sorted.append(end_hole)
            h_sorted.append(start_hole)
        else:
            h_sorted.append(start_hole)
            h_sorted.append(end_hole)
    elif start_hole != [None, None]:
        h_sorted.append(start_hole)
    elif end_hole != [None, None]:
        h_sorted.append(end_hole)

    moves_left = n_k[1]
    new_a = ['X'] * len(a)
    while moves_left > 0 and len(h_sorted) > 0:
        cur_hole = h_sorted.pop(0)
        available_move = cur_hole[0] if moves_left >= cur_hole[0] else moves_left
        for i in range(available_move):
            if cur_hole[1] + i < len(new_a):
                new_a[cur_hole[1]+i] = 'W'

        moves_left -= available_move

    # Python won't allow directly modify string
    for i in range(len(a)):
        if new_a[i] == 'X':
            new_a[i] = a[i]

    return get_score(''.join(new_a))

