def refine(b_arr , revert = False):
    need = 0
    fract = []
    flag = 0
    lr_d = 1
    if revert :
        if(len(b_arr)%2 == 1):
            lr_d = 0

    for index , i in enumerate(b_arr):
        if((index+ lr_d) % 2 == 1):
            need += i
        else:
            need -= i
        if( need < 0):
            ad = b_arr[flag:index]+[b_arr[index] + need]
            if revert:
                fract.append(ad[::-1])
            else:
                fract.append(ad)
            flag = index+1
            need = 0
    if need >= 0 :
        if b_arr[flag:] :
            if revert:
                fract.append(b_arr[flag:][::-1])
            else:
                fract.append(b_arr[flag:])

    return [*filter(lambda x: x != [0] , fract)]


def devide(arr):
    l = 0
    r = 0
    alada = []
    flag = 0
    for index , i in enumerate(arr):
        if((index+ 1) % 2 == 1):
            l += i
        else:
            r += i
        if (l == r):
            alada.append(arr[flag:index+1])
            flag = index + 1
            l , r = 0 , 0
    return alada

def rem_lr(arr):
    k = 0
    l = sum(map(lambda x: arr[x] , range(2 , len(arr)-2 , 2)))
    r = sum(map(lambda x: arr[x] , range(3 , len(arr)-2 , 2)))
    if l > r:
        k = arr[-1]-arr[-2]-(l-r)
    elif l < r:
        k = arr[0]-arr[1]-(r-l)
    else:
        k = arr[0]-arr[1]
    return k

def count(arr , memo = {}):
    ky = tuple(arr)
    if ( ky in memo):
        return memo[ky]

    if(len(arr) == 2 and arr[0] == arr[1]):
        return arr[0]

    k = rem_lr(arr)
    n_arr = [arr[0]-k] + arr[1:-1]+ [arr[-1]-k]
    possible = 0
    possible += k
    alada = devide(n_arr)
    for each in alada:
        possible += count(each)
    l = len(alada)
    possible += (l*(l-1))//2
    memo[ky] = possible
    return possible



