    if n == 1:
        print(1)

    ans = ["0" for i in range(n)]
    pos = [set() for i in range(n+1)]
    for i, a in enumerate(arr):
        pos[a].add(i)
    start = 0
    end = n - 1
    for a in range(1, n+1):
        if not pos[a]:
            return ans
        b1 = start in pos[a]
        b2 = end in pos[a]
        ans[n-a] = "1"
        if len(pos[a]) >= 2:
            return ans
        if b1:
            start += 1
        elif b2:
            end -= 1
        else:
            for i in range(1, n+1):
                if not len(pos[i]) == 1:
                    return ans
            ans[0] = "1"
            return ans
    return ans


