def gen_groups(cubes):
    if len(cubes) == 1:
        for y in cubes[0]:
            yield [y]
    elif len(cubes) == 2:
        for x in cubes[0]:
            for y in cubes[1]:
                yield [x, y]
    else:
        for x in cubes[0]:
            for y in cubes[1]:
                for z in cubes[2]:
                    yield [x, y, z]

def solution(cubes):
    numbers = [False] * 1000
    numbers[0] = True

    for group in gen_groups(cubes):
        for i in range(1, len(group)):
            for cde in permutations(group, i):
                # print(cde)
                fish = int("".join(cde))
                # print(fish)
                numbers[fish] = True

    for i, c in enumerate(numbers):
        if not c:
            return i - 1
    return -1

