class Bit:
    def __init__(self, n):
        self.size = n
        self.tree = [0] * (n + 1)

    def range_sum(self, l, r):
        return self.sum(r) - self.sum(l - 1)


    def sum(self, i):
        i += 1
        s = 0
        while i > 0:
            s += self.tree[i]
            i -= i & -i
        return s

    def get(self, i):
        return self.sum(i) - self.sum(i - 1)

    def add(self, i, x):
        i += 1
        while i <= self.size:
            self.tree[i] += x
            i += i & -i


