    for x in li:
        if cn==n:
            return True
        if  cn==x:
            cn+=1
            state=1
        elif state==1 and cn!=x:
            return False

    for x in li:
        if cn==n:
            return True
        if  cn==x:
            cn+=1
            state=1
        elif state==1 and cn!=x:
            return False

        return True


def checkanticlock(n, li):
