# http://codeforces.com/contest/633/problem/A

"""
Has two guns and which deal damage a and b respectively. In order to break the shield
need to deal exactly c units of damage. Find out if this is possible.

This boils down to whether or not ax+by=c has positive solutions.
"""

from math import floor, ceil


def ExtendedEuclidean(a, b):
    if a == 0:
        return b, 0, 1

    gcd, x_1, y_1 = ExtendedEuclidean(b % a, a)

    x = y_1 - (b // a) * x_1
    y = x_1

    return gcd, x, y


def is_plc(a, b, c):
    # Positive Linear Combination
    gcd, x_0, y_0 = ExtendedEuclidean(a, b)
    if c % gcd != 0:
        return False

    x_0, y_0 = x_0 * (c//gcd), y_0 * (c//gcd)

    if x_0 >= 0 and y_0 >= 0:
        return True
    if x_0 < 0 and y_0 < 0:
        return False
    if x_0 < 0:
        k = ceil(x_0 * gcd / b)
    elif y_0 < 0:
        k = floor(-y_0 * gcd / a)

    x_1, y_1 = x_0 - k * b / gcd, y_0 + k * a / gcd

    if x_1 >= 0 and y_1 >= 0:
        return True
    else:
        return False


if __name__ == '__main__':
    a, b, c = map(int, input().split())
    if is_plc(a, b, c):
        print('Yes')
    else:
        print('No')

