class Solution:
    def CalLcm(self,a,b):
        maxm=max(a,b)
        minm=min(a,b)
        if minm==0:
            gcd=maxm
        else:
            while maxm%minm!=0:
                r=maxm%minm
                maxm=minm
                minm=r
            gcd=minm
        lcm=int((a*b)/gcd)
        return lcm
    def MaxLCM(self,n):
        ans=0
        ob1=Solution()   
        if n>=3 and n<=10:
            for i in range(n):
                a=n-i
                b=n-(i+1)
                c=n-(i+2)
                l=ob1.CalLcm(a,b)
                l=ob1.CalLcm(l,c)
                ans=max(ans,l)
        else:
            for i in range(10):
                a=n-i
                b=n-(i+1)
                c=n-(i+2)
                l=ob1.CalLcm(a,b)
                l=ob1.CalLcm(l,c)
                ans=max(ans,l)
        return ans
