def pad(a, k):
  t = a
  m = a % 10
  c = 0
  while t != 0:
    if t % 10 < m:
      m = t % 10
    t //= 10
    c += 1
  while c < k:
    c += 1
    a = a * 10 + m
  return a

def nex(n,k,a0):
  a1 = a0
  nums = set()
  while a0 != 0:
    if a0 % 10 not in nums:
      nums.add(a0 % 10)
    a0 = a0 // 10

  if len(nums) < k:
    while a1 < n:
      a1 *= 10
    return a1 

  k = 0
  while n !=0:
    k += 1
    n = n // 10

  return pad(a1, k)

