def factorization(n):
    arr = []
    temp = n
    so = 1
    for i in range(2, int(-(-n**0.5//1))+1):
        if temp%i==0:
            cnt=0
            while temp%i==0:
                cnt+=1
                temp //= i
            arr.append([i, cnt])
            so *= (cnt + 1)

    if temp!=1:
        arr.append([temp, 1])
        so *= 2

    if arr==[]:
        arr.append([n, 1])
        so *=2

    return so

