def read_values():
    return map(int, input().split())


def read_list():
    return list(read_values())


def read_lists(N):
    return [read_list() for n in range(N)]


def dfs(N, L, s, blocks = None):
    depth = [-1] * N

    stack = [(0, s)]
    while stack:
        d, p = stack.pop()
        depth[p] = d

        if blocks is not None and d == blocks[p]:
            continue

        for q in L[p]:
            if blocks is not None:
                if blocks[q] < d + 1:
                    continue

            if depth[q] != -1:
                continue
            stack.append((d + 1, q))
    return depth


def main():
    N, u, v = read_values()
    u -= 1
    v -= 1
    L = [set() for _ in range(N)]
    for _ in range(N - 1):
        A, B = read_values()
        A -= 1
        B -= 1
        L[A].add(B)
        L[B].add(A)

    depth_A = dfs(N, L, v)
    depth_T = dfs(N, L, u, depth_A)

    res = 0
    for i in range(N):
        a = depth_A[i]
        t = depth_T[i]
        if t <= 0: 
            continue
        res = max(res, t + 2 * ((a - t) // 2))

    print(res)


