def to_s(x):
    return "".join([str(d) for d in x if d > 0])



def have_cubes(x, nums):

    if len(nums) == 0:
        return False

    if len(x) == 1:
        for c in nums:
            if x[0] in c:
                return True
        return False
    else:
        for i, c in enumerate(nums):
            if x[0] in c:
                if have_cubes(x[1:], nums[:i] + nums[i + 1:]):
                    return True
        return False


