import sys

def dfs(graph, node, visited):
	visited[node] = True
	component = 1
	try:
		for i in graph[node]:
			if visited[i] == False:
				component += dfs(graph, i, visited)
	except:
		pass
		#print('second error')
	return component


def get_bad_sequence(graph, n, k):
	ans = pow(n, k, 10 ** 9 + 7)
	visited = dict()
	for i in range(1, n + 1):
		visited[i] = False
	try:
		for i in graph:
			if visited[i] == False:
				member = dfs(graph, i, visited)
				ans -= pow(member, k, 10 ** 9 + 7)
				ans %= 10 ** 9 + 7
	except:
		pass
		#print('first_error')
	return ans


