class scoreRecord:
	def __init__(self, score, penalty):
		self.score = score
		self.penalty = penalty
	def __eq__(self, other):
		return self.score == other.score and self.penalty == other.penalty
	def __lt__(self, other):
		if self.score < other.score:
			return True
		elif self.score > other.score:
			return False
		else:
			if self.penalty > other.penalty:
				return True
			else:
				return False

