def solve(n,a,b,c):
    ans = 0
    d = b-c
    if (a <= d):
        ans += n // a 
        if (n % a > b):
            ans += ((n % a) - b) // d + 1
    else:
        if (n > b):
            ans += (n - b) // d + 1 + ((n - b) % d) // a
    return ans

