import math
def calculateTiming(timeList,L,a):
    breakCount = 0
    if not timeList:
        breakCount = math.floor(L//a) 
    else:
        for i in range(len(timeList)):
            if i == 0:
                breakCount += math.floor(timeList[i][0]//a)
            else:
                if i == len(timeList)-1:
                    breakCount += math.floor((L-(timeList[i][0]+timeList[i][1]))//a)
                else:
                    breakCount += math.floor((timeList[i][0]-(timeList[i-1][0]+timeList[i-1][1]))//a)
    return breakCount

