def Grid(S):
    xmin = 0
    xmax = 0
    ymin = 0
    ymax = 0
    y_s = 0
    x_s = 0
    for c in S:
        if c=='W':
            y_s+=1
        elif c=='S':
            y_s-=1
        elif c=='A':
            x_s-=1
        else:
            x_s+=1
        xmin = min(xmin, x_s)
        xmax = max(xmax, x_s)
        ymin = min(ymin, y_s)
        ymax = max(ymax, y_s)
    return [xmin, xmax, ymin, ymax]

def process(S):
    a, b, c, d = Grid(S)
    answer = (b-a+1)*(d-c+1)
    if a==b and c==d:
        return 1
    if a+1 < b:
        answer = min(answer, (b-a)*(d-c+1))
    if c+1 < d:
        answer = min(answer, (b-a+1)*(d-c))
    return answer

