def F1(s, k):
  siz = len(s)
  pivot = s[0]
  index = 1
  while index < siz:
    if s[index] != pivot: break
    else: index += 1
  if index == siz: return s
  elif pivot > s[index]:
    res = s[:index]
    for i in range(index, siz):
      res += pivot
    return res
  else:
    res = ""
    ch = str(int(pivot) + 1)
    for i in range(siz):
      res += ch
    return res

def replaceF(res, f, start, siz):
  for i in range(start, siz):
    res += f
  # print("res func: " + res)
  return res

def F2(s, k):
  siz = len(s)
  f1 = s[0]
  index = 1
  while index < siz:
    if s[index] != f1: break
    else: index += 1
  if index == siz: return s
  f2 = s[index]
  pos = index + 1
  while pos < siz:
    if s[pos] != f1 and s[pos] != f2: break
    else: pos += 1
  if pos == siz: return s
  minF = min(f1, f2)
  maxF = max(f1, f2)

  # print("pos: " + str(pos))
  # print("maxF: " + maxF)
  # print("minF: " + minF)

  if s[pos] < minF: 
    res = s[:pos]
    return replaceF(res, minF, pos, siz)

  elif s[pos] < maxF:
    res = s[:pos]
    res += maxF
    return replaceF(res, minF, pos + 1, siz)

  elif s[pos - 1] == minF:
    res = s[:(pos-1)]
    res += maxF
    return replaceF(res, minF, pos, siz)

  else:
    stand = pos - 1
    while stand >= 0:
      if s[stand] == minF: break
      else: stand -= 1
    option = False
    for i in range(stand, -1, -1):
      if s[i] == maxF:
        option = True
        break

    if option:
      res = s[:stand]
      res += maxF
      return replaceF(res, minF, stand, siz)

    else:
      res = s[:stand + 1]
      res += str(int(maxF) + 1)
      return replaceF(res, minF, stand + 2, siz)

