def find_memory(memory, num, size, max_size):
    if not memory:
        if max_size >= size:
            memory.append((num, 0, size - 1))
            return True
        return False
    # check if we can fit the memory at the start
    if memory[0][1] >= size:
        memory.insert(0, (num, 0, size - 1))
        return True
    for i in range(len(memory) - 1):
        if memory[i + 1][1] - memory[i][2] > size:
            memory.insert(i + 1, (num, memory[i][2], memory[i][2] + size))
            return True
    # check last element
    if max_size - memory[-1][2] > size:
        memory.append((num, memory[-1][2], memory[-1][2] + size))
        return True
    return False


