def merge(a, k):
    if not a:
        return False, []
    if len(a)*2 < k:
        return False, a

    v = a[0]
    i = 0
    while i < len(a) and a[i] == v:
        i += 1
    j = len(a)-1
    while j >= 0 and a[j] == v:
        j -= 1

    if i > j:
        return True, []
    else:
        n = i + len(a) - j - 1
        if n >= k:
            return True, a[:j+1] + [a[0]] * (n-k) + a[i:]

    return False, a

def group(a, k):
    if not a:
        return []
    if len(a) < k:
        return a

    ans = []
    p = a[0]
    c = 1
    for v in a[1:]:
        if v == p:
            c += 1
        else:
            c %= k
            if c > 0:
                ans += [p] * c
                c = 0
            else:
                for i in range(len(ans)-1, -1, -1):
                    if ans[i] == v:
                        c += 1
                    else:
                        break
                ans = ans[:len(ans)-c]
            c += 1
            p = v
    ans += [p] * (c % k)

    return ans


