def pull_cubes(string):
    length = len(string)
    cube_counter = 0
    before_cube = string[0]
    index = 0
    for i in range(length):
        if index >= length:
            break
        if string[index] is not before_cube:
            if index is not length-1:
                string = string[0:index-1] + string[index+1:]
            else:
                cube_counter += 2
                string = string[0:index-1]
                break
            length -= 2
            cube_counter += 2
            index -= 1
            if len(string) is 0 or len(string) is 1:
                break
            before_cube = string[index]
        else:
            before_cube = string[index]
            index += 1

    return cube_counter, string

