class Point:

  def __init__(self, x, y):
    self.x = x
    self.y = y

  def __sub__(self, other):
    return Point(self.x-other.x, self.y-other.y)

  def __add__(self, other):
    return Point(self.x+other.x, self.y+other.y)

  def __eq__(self, other):
    return self.x == other.x and self.y == other.y

  def __mul__(self, other):
    return Point(self.x * other, self.y * other)

  def __rmul__(self, other):
    return Point(self.x * other, self.y * other)

  def __str__(self):
    return "Point x={x}, y={y}".format(x=self.x, y=self.y)

  def rotate(self):
    return Point(-self.y, self.x)

  def dist(self, other):
    return (other.x - self.x) ** 2 + (other.y - self.y) ** 2

def check_square(A, B, C, D):
  if A.dist(C) == B.dist(D) and A.dist(B) == B.dist(C) == C.dist(D) == D.dist(A) and A + C == B + D or \
    A.dist(D) == B.dist(C) and A.dist(B) == B.dist(D) == D.dist(C) == C.dist(A) and A + D == B + C or \
    A.dist(B) == C.dist(D) and A.dist(C) == C.dist(B) == B.dist(A) == A.dist(D) and A + B == C + D:
      return A!=B and A!=C and A!=D and B!=C and B!= D and C!=D
  return False

def solve(i, rotations, points, homes):
  #print("a")
  if i == 4:
    if check_square(*points):
      #print(*points)
      #print(rotations)
      return rotations
    else:
      return 1000000
  else:
    res = solve(i+1, rotations, points, homes)
    for r in range(1,4):
      points[i] -= homes[i]
      points[i] = points[i].rotate()
      points[i] += homes[i]
      res = min(solve(i+1, rotations+r, points, homes), res)
    points[i] -= homes[i]
    points[i] = points[i].rotate()
    points[i] += homes[i]
    return res

