def main(N, K):
    S = str(N)
    d = len(S)
    if d < K:
        res = 10
        k = 2
        while k < K:
            res = res * 10 + k
            k += 1
        return res

    if N > mx(d, K):
        res = 10
        l = d + 1 - 2 - (K - 2)
        for _ in range(l):
            res *= 10
        k = 2
        while k < K:
            res = res * 10 + k
            k += 1
        return res

    if len(set(S)) == K:
        return N

    for i in range(d - 1, -1, -1):
        up = set(S[:i])
        if len(up) > K: continue
        if len(up) == K:
            n = int(S[i])
            for m in sorted(up):
                if int(m) > n: break
            else: continue
            res = S[:i] + m
            mn = min(up)
            for _ in range(i + 1, d):
                res += mn
            return int(res)
        n = int(S[i])
        if n == 9: continue
        m = str(n + 1)
        res = S[:i] + m
        up.add(m)
        if len(up) == K:
            mn = min(up)
            for _ in range(i + 1, d):
                res += mn
            return int(res)
        k = K - len(up)
        r = d - 1 - i
        if r < k: continue
        res += '0'
        up.add('0')
        k = K - len(up)
        r -= 1
        for _ in range(r - k):
            res += '0'
        for i in range(10):
            if k == 0: break
            m = str(i)
            if m in up: continue
            res += m
            k -= 1
        return int(res)

def mx(keta, K):
    res = '9' * (keta - K)
    n = 9
    for _ in range(K):
        res += str(n)
        n -= 1
    return int(res)

