import sys

class IntervalTree:

    def __init__(self, a, b, val=0):
        self.a = a
        self.b = b
        self.val = val
        if a < b:
            mid = (a + b) // 2
            self.left = IntervalTree(a, mid, val)
            self.right = IntervalTree(mid+1, b, val)

    def update(self, pos, val):
        if (pos < self.a) or (pos > self.b):
            return # out of range
        self.val = max(self.val, val)
        if self.a < self.b:
            self.left.update(pos, val)
            self.right.update(pos, val)

    def get_max(self, a, b):
        if (a <= self.a) and (self.b <= b):
            return self.val
        if (self.b < a) or (b < self.a):
            return -631 # out of bounds
        return max(self.left.get_max(a, b), self.right.get_max(a, b))

    def print(self, indent=''):
        print(indent + "[{0}, {1}]; max = {2}".format(self.a, self.b, self.val))
        if self.a < self.b:
            self.left.print(indent + '  ')
            self.right.print(indent + '  ')

