def find_smallest_geq(x, ll, l, r):
    if l < len(ll)-1 and ll[l] <= x and ll[l+1] > x:
        return l+1
    elif r <= l:
        return l
    elif r == len(ll)-1 and ll[r] < x:
        return len(ll)

    mid = (l+r)//2
    # print(x, l, mid, r, '|', ll[l], ll[mid],  ll[r])

    if ll[mid] == x:
        return mid
    elif ll[mid] > x:
        return find_smallest_geq(x, ll, l, mid)
    elif ll[mid] < x:
        return find_smallest_geq(x, ll, mid+1, r)

