class Node:
    def __init__(self, hasDocOnLeft, hasDocOnRight, next, prev):
        self.hasDocOnLeft = hasDocOnLeft
        self.hasDocOnRight = hasDocOnRight
        self.next = next
        self.prev = prev

    def print_itself_next(self):
        print("=> {}:{}".format(self.hasDocOnLeft, self.hasDocOnRight))
        if self.next:
            self.next.print_itself_next()

    def print_itself_prev(self):
        print("<= {}:{}".format(self.hasDocOnLeft, self.hasDocOnRight))
        if self.prev:
            self.prev.print_itself_prev()


def main():
    n, k, m, t = rmult_int()

    head = None
    tail = None
    node = None
    for i in range(1, n + 1):
        prev = node
        if i < k:
            node = Node(False, True, None, prev)
        elif i > k:
            node = Node(True, False, None, prev)
        else:
            node = Node(True, True, None, prev)
        if prev is not None:
            prev.next = node
        if i == 1:
            head = node
        elif i == n:
            tail = node
    # head.print_itself_next()
    # print("===")

    for i in range(t):
        code, where = rmult_int()
        if code == 0:
            if where > ((n - 1) / 2):
                where = n - where
                node = tail
                for j in range(0, where):
                    node = node.prev
                if node.hasDocOnLeft:
                    node.next = None
                    tail = node
                    n -= where
                else:
                    head = node.prev
                    head.prev = None
                    n -= (n - where)
                    k -= (n - where)
            else:
                node = head
                for j in range(0, where):
                    node = node.next
                if node.hasDocOnRight:
                    head = node
                    head.prev = None
                    n -= where
                    k -= where
                else:
                    tail = node.prev
                    tail.next = None
                    n -= (n - where)
        else:
            if where > ((n + 1) / 2):
                where = (n + 1) - where
                node = tail
