import math


def checkPrime(d):
    tgt = int(math.ceil(math.sqrt(d))) + 1
    # print("tgt : " + str(tgt))

    for i in range(2, tgt):
        # print("i : " + str(i))
        if d % i == 0:
            return False
    return True

def solve(n):
    ret = 0

    if checkPrime(n):
        return 1

    while n > 0:
        if n % 2 == 0:
            return ret + n // 2
        for d in range(2, n + 1):
            if n % d == 0 and checkPrime(d):
                # print("d : " + str(d))
                ret += 1
                n -= d
                break
            elif (n - d) % 2 == 0 and checkPrime(d):
                return ret + (n - d) // 2
    return ret

def driver():
    n = int(input())
    print(solve(n))

