def binsearch(x, list1):
    answer = None
    left = 0
    right = len(list1) - 1
    while answer == None:
        i = (left + right) // 2
        if list1[i] == x:
            answer = i
        elif list1[i] > x:
            right = i
        else:
            left = i
        if right - left < 2:
            if list1[right] == x:
                return right
            if list1[left] == x:
                return left
            else:
                return left
    return answer



