def good_time_to_sell(price):
  global stock
  global purchase_price
  global A

  if stock > 0:
    if purchase_price < price:
      if max(A) < price:
        return True
      else:
        is_down = False

        for a in A:
          if a < price:
            is_down = True
          elif price < a and is_down:
            return True

  return False


def sell(price):
  global money
  global stock

  money += price * stock
  stock = 0


def good_time_to_buy(price):
  global money
  global A

  if price <= money:
    if price < min(A):
      return True
    else:
      for a in A:
        if a < price:
          return False
        elif price < a:
          return True

  return False


def buy(price):
  global money
  global stock

  stock += money // price
  money %= price


