import heapq

class MyHeap(object):
   def __init__(self, initial=None, key=lambda x:x):
       self.key = key
       if initial:
           self._data = [(key(item), item) for item in initial]
           heapq.heapify(self._data)
       else:
           self._data = []

   def push(self, item):
       heapq.heappush(self._data, (self.key(item), item))

   def pop(self):
       return heapq.heappop(self._data)[1]

   def print(self):
       for hd in self._data:
            print(hd)
       print('-------------------------------')

def getminnumerofcoins(n, mpa):

    res = 0

    mpa.sort(key=lambda x: (x[0], -x[1]))
    gap = []

    cur = 0
    for i in range(len(mpa)):
        mp = mpa[i]
        if mp[0] > cur:
            t = [i, mp[0]-cur]
            gap.append(t)
            cur = mp[0]

        cur += 1

    if len(gap) == 0:
        return 0

    hp = MyHeap(key=lambda x: x[1])
    lidx = gap.pop()[0]
    for i in range(lidx, len(mpa)):
        ci = [i, mpa[i][1]]
        hp.push(ci)

    cur = 0
    offset = 0
    for i in range(len(mpa)):
        mp = mpa[i]
        need = mp[0] - cur
        if need > 0:
            for j in range(need):
                if len(hp._data) == 0 and len(gap) > 0:
                    lg = gap.pop()
                    while len(gap) > 0 and lg[1] - offset <= 0:
                        lg = gap.pop()
                    for k in range(lg[0], lidx):
                        ci = [mpa[i][1], k]
                        hp.push(ci)
                    lidx = lg[0]

                c = hp.pop()
                #print(c)
                if c[0] == i:
                    c = hp.pop()
                    #print(c)
                res += c[1]
                cur += 1

        cur += 1

    return res


