from collections import deque
def cal(nums, k):
    q = deque()
    ans = []
    for i, n in enumerate(nums):
        while q and q[-1] > n:
            q.pop()
        q.append(n)
        if i >= k - 1:
            ans.append(q[0])
            if q[0] == nums[i - k + 1]:
                q.popleft()
    return ans

