def FirstCheck(n, m, k):
    max_m = m // 2
    if max_m == 0:
        return False
    max_n = k // max_m

    e_m = m%2
    e_n = k%max_m

    if max_n > n:
        return False

    if e_n == 0:
        if (n - max_n)%2 == 0:
            return True
    return False

def SecondCheck(n, m, k):
    max_n = min(k, n)
    if max_n == 0:
        if n % 2 == 0:
            return True
        else:
            return False

    if max_n == n:
        e_m = n - k % max_n
    else:
        e_m = n - k

    if e_m != 0:
        if (k//max_n + 1)*2 > m:
            return False
        elif m - (k//max_n + 1)*2 > 0:
            if n % 2 != 0:
                return False 
    else:
        if (k//max_n)*2 > m:
            return False
        elif m - (k//max_n)*2 > 0:
            if n % 2 != 0:
                return False

    if (n - e_m)%2 != 0:
        return False


    return True

