from sys import stdin, stdout

class Block:
    def __init__(self, id, position, size):
        self.id = id
        self.position = position
        self.size = size

    def __str__(self):
        return "{0} {1} {2}".format(self.id, self.position, self.size)


class MemoryManager:
    def __init__(self, capacity):
        self.capacity = capacity
        self.blocks = list()
        self.last_block_id = 0

    def get_available_position(self, amount):
        block_count = len(self.blocks)
        if block_count == 0:
            return 0 if amount <= capacity else None

        if block_count == 1:
            block = self.blocks[0]
            avail_position = block.position + block.size
            return avail_position if avail_position + amount <= capacity else None

        prev_block = self.blocks[0]
        for i in range(1, block_count):
            curr_block = self.blocks[i]
            avail_position = prev_block.position + prev_block.size
            avail_amount = curr_block.position - avail_position
            if avail_amount >= amount and avail_position + amount <= capacity:
                return avail_position
            prev_block = curr_block

        return None

    def allocate(self, amount):
        avail_position = self.get_available_position(amount)
        if avail_position == None:
            return None

        self.last_block_id += 1
        self.blocks.append(Block(self.last_block_id, avail_position, amount))
        return self.last_block_id

    def erase(self, block_id):
        for block in self.blocks:
            if block.id == block_id:
                self.blocks.remove(block)
                return True
        return False

    def defragment(self):
        block_count = len(self.blocks)
        if block_count == 0:
            return

        if block_count == 1:
            self.blocks[0].position = 0
            return

        prev_block = self.blocks[0]
        prev_block.position = 0
        for i in range(1, block_count):
            curr_block = self.blocks[i]
            curr_block.position = prev_block.position + prev_block.size
            prev_block = curr_block


class MemoryManagerConsole:
    def __init__(self, memory_manager: MemoryManager):
        self.memory_manager = memory_manager

    def read(self):
        input = stdin.readline().rstrip().split()
        command = input[0]
        if command == 'alloc':
            amount = int(input[1])
            block_id = self.memory_manager.allocate(amount)
            # self.print_blocks()
            return str(block_id or 'NULL')
        elif command == 'erase':
            block_id = int(input[1])
            if self.memory_manager.erase(block_id) == False:
                # self.print_blocks()
                return 'ILLEGAL_ERASE_ARGUMENT'
            # self.print_blocks()
        elif command == 'defragment':
            self.memory_manager.defragment()
            # self.print_blocks()
        return None

    def print_blocks(self):
        for block in self.memory_manager.blocks:
            stdout.write(str(block) + "\n")


