            count += 1
            if i != n // i:
                count += 1
        i += 1
    return count
  elif n > 640000:
    count = 1305179488810
    i = 800
    while i*i <= n:
        if n % i == 0:
            count += 1
            if i != n // i:
                count += 1
        i += 1
    return count
  elif n > 360000:
    count = 4661355
    i = 600
    while i*i <= n:
        if n % i == 0:
            count += 1
            if i != n // i:
                count += 1
        i += 1
    return count
  else:
    count = 0
    i = 1
    while i*i <= n:
        if n % i == 0:
            count += 1
            if i != n // i:
                count += 1
        i += 1
    return count


