POWER2 = [1, 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024, 2048, 4096, 8192, 16384, 32768, 65536, 131072, 262144, 524288]


def compress_list(a):
    x = {}
    cur = a[0]
    num = 1
    for i in range(1, len(a)):
        if a[i] == cur:
            num += 1
        else:
            x[cur] = [num, 0]
            cur = a[i]
            num = 1
    x[cur] = [num, 0]
    return x

def find_idx(v, idx=0):
    while True:
        if POWER2[idx] == v:
            return idx
        if POWER2[idx] > v:
            return idx - 1
        idx += 1


def solve(n, k, a):
    a = sorted(a)
    a = compress_list(a)
    min_ret = 200000000
    while True:
        aa = {}
        for v, __tup in a.items():
            num, cnt = __tup
            if num >= k:
               min_ret = min(min_ret, cnt)
               continue 
            vv  = v // 2
            if vv in a:
                vv_num, vv_cnt = a[vv]
                if vv_num + num >= k:
                    ret = vv_cnt + k - vv_num
                    min_ret = min(min_ret, ret)
                    continue
                aa[vv] = [vv_num + num, vv_cnt + cnt + num]
        if len(a) <= 1:
            break
        a = aa
    return min_ret


