def solve(N, M):
    if N > M:
        return 0
    if N.bit_length() < M.bit_length():
        for i in reversed(range(M.bit_length())):
            if M & (1<<i) < N & (1<<i):
                return M & ~((1<<i) - 1)
        return N^(M+1)
    else:
        for i in range(M.bit_length()):
            if M & (1<<i) == 0:
                if i == 0:
                    x = M + 1
                else:
                    x = (M & ~((1<<i)-1)) | (1<<i)
                return x ^ N
        return N+1

