def locate(i, a, current, rest):
    global N, table
    if a not in table.keys():
        return False
    else:
        #print("###############")
        #print("i={}".format(i))
        #print(current)
        #print("###############\n")
        L = (i - 1 + N) % N
        R = (i + 1 + N) % N
        if i==N-1 and current[L] != -1 and current[R] != -1:
            if a == current[L]^current[R]:
                return True
            else:
                return False
        else:
            current_ = current.copy()
            current_[i] = a
            for j in range(len(rest)):
                rest_ = rest.copy()
                next_a = rest_.pop(j)
                need_search = False
                for t1,t2 in table[a]:
