from collections import defaultdict


def solution(ddict, base, st_pos):
    st_round = st_pos // base
    for x in range(st_pos, base):
        if ddict[x] < st_round + 1:
            return st_round * base + x
        st_round += 1

    while True:
        for x in range(0, base):
            if ddict[x] < st_round + 1:
                return st_round * base + x
        st_round += 1
    return st_round * base



