def util(fuel):
    ti = 0
    global t,k
    for i in range(1, k+2):
        dis = gas[i]-gas[i-1]
        if dis > fuel:
            return False
        ti += max(dis, 2*dis-min(dis, fuel-dis))
    if ti<=t:
        return True
    return False

