def BinSearch(num, array, waste, r_edge, l_edge, difference=1e10,difference1 = -1e10):
    mid = (l_edge + r_edge) // 2
    if r_edge <= l_edge or l_edge >= len(array):
         return difference,difference1

    if array[mid] > num:
        if array[mid] - num < difference:
            difference = array[mid] - num
        return BinSearch(num, array, waste, mid - 1, l_edge, difference,difference1)
    elif array[mid] < num:
        if array[mid] - num > difference1:
            difference1 = array[mid] - num
        return BinSearch(num, array, waste, r_edge, mid + 1, difference,difference1)
    elif array[mid] == num:
        return 0,0



