def get(A,B,N):
    if(N==-1):
        return 0;
    if(max(A,B) >= N):
        return N + 1
    if(A%B == 0 or B%A == 0):
        return N
    GCD = math.gcd(A,B)
    X = GCD * (A/GCD) * (B/GCD)
    Delta = min(max(A,B), N - N//X*X + 1)
    return max(A,B) + max((N//X-1),0)*max(A,B) + (Delta * int(N>=X))

