def pos(sa, k, l=0, r=None):
    if r is None:
        r = len(sa)
    m = (l + r) // 2
    if l == r:
        return l
    elif k > sa[m]:
        return pos(sa, k, m + 1, r)
    elif k < sa[m]:
        return pos(sa, k, l, m)
    else:
        return m


