def binary_search(x,l,r,list):
    if l+1==r:
        if list[l]==x or list[r]==x:
            return True
        else:
            return False
    if l==r:
        return False
    else:
        middle=(l+r)//2
        if x<list[l]:
            return False
        elif x>list[r]:
            return False
        elif x==list[middle]:
            return True
        else:
            if x<list[middle]:
                return binary_search(x,l,middle,list)
            elif x>list[middle]:
                return binary_search(x,middle,r,list)

