def opr(x):
    y = x.copy()
    a = min(y)
    b = max(y)
    if a == b:
        return 'E'
    else:
        if len(y) > 2 and sum(y) >= len(y):
            y.remove(a)
            y.remove(b)
            a = min(y)
            b = max(y)
            if a == b:
                return 'V'
            else:
                return 'U'
        elif sum(y) < len(y):
            return 'U'
        else:
            if b % 2 != 0 or a % 2 != 0:
                return 'U'
            else:
                return 'V'


