def getIndex(l):
    first, last = l[0], l[-1]
    rr, ll = 1, 1
    for i in range(1, len(l)):
        if l[i] != first:
            return 0, i
        else:
            rr += 1
        if l[len(l) - 1 - i] != last:
            return -1, i
        else:
            ll += 1
