def solve(N: int, A: int, B: int, C: int, l: "List[int]"):
    e = [A, B, C]

    ret = float('inf')
    for i in range(4 ** N):
        ls = [0, 0, 0, 0]
        ns = [0, 0, 0, 0]
        for j, ll in enumerate(l):
            key = (i >> (2 * j)) & 0x03
            ls[key] += ll
            ns[key] += 1

        if ns[0] == 0 or ns[1] == 0 or ns[2] == 0:
            continue

        cs = []
        for n in ns:
            if 0 < n:
                cs.append(10 * int(ceil(log(n) / log(2))))
            else:
                cs.append(0)

        c0 =  cs[0] + abs(e[0] - ls[0])
        c1 = c0
        c1 += cs[1] + abs(e[1] - ls[1])
        c1 += cs[2] + abs(e[2] - ls[2])
        if c1 < ret:
            ret = c1

        c2 = c0
        c2 += cs[1] + abs(e[2] - ls[1])
        c2 += cs[2] + abs(e[1] - ls[2])
        if c2 < ret:
            ret = c2
    return ret


