    ls[left_inx], ls[left_inx + 1] = ls[left_inx + 1], ls[left_inx]
    return ls, left_inx

def get_left_inx(ls, left_inx):
    for inx, item in enumerate(ls[left_inx:]):
        if inx + left_inx == item - 1:
            return inx + left_inx
    return 0

