lmap = lambda f, v: list(map(f, v))

def find_valley(h):
    for i in range(1, len(h)):
        if h[i] > h[i-1]:
            end = i
            break
    else:
        return

    valley_h = h[end-1]
    for i in range(end):
        if h[i] == valley_h:
            start = i
            break

    return start, end

def last_stone(n, k, h):
    while k > 0:
        valley = find_valley(h)
        if not valley:
            return -1

        start, end = valley
        peak_h = h[end]
        valley_h = h[start]
        width = end - start
        valley_capacity = width * (peak_h - valley_h)

        if valley_capacity < k:
            k -= valley_capacity
            h[start:end] = [peak_h] * width
        else:
            rest = (k - 1) % width
            return end - rest
    return -1

def main():
    t = int(next(cin).strip())
    for i in range(t):
        n, k = lmap(int, next(cin).strip().split())
        h = lmap(int, next(cin).strip().split())
        print(last_stone(n, k, h))

