import sys

def clockwise(students, n):
    start = students.index(1)
    end = n+start

    for i in range(start, end):
        if (students[i%n] + 1) != students[(i+1)%n]:
            return False

    return True


def counterClockwise(students, n):
    start = students.index(1)

    for i in range(n):
        if (students[(start-i) % n] + 1) != students[(start - i - 1) % n]:
            return False

    return True


