def power(n, k):
    if k == 0:
        return 1
    if n == 1:
        return 1
    if k%2 == 1:
        return power(n,k//2) * power(n, k//2) * n
    else:
        return power(n,k//2) * power(n, k//2)

def union_set_compressed_path(elementA, elementB):
    global components
    setA = components[elementA]
    setB = components[elementB]

    if setB and not setA:
        # Le doy la vuelta para simplificar
        # Así siempre es el setA el que existe y el setB el nuevo
        return union_set_compressed_path(elementB, elementA)

    if setA and not setB:
        components[elementB] = setA
        return setA

    if setA and setB:
        # Si existen los dos sets, comprimo uno de ellos
        components[elementB] = setA
        return setA

    # No existen ninguno de los dos sets:
    components[elementA] = elementA
    components[elementB] = elementA

    return elementA

def union_get_compressed_path(element):
    theSet = components[element]
    if theSet == element:
        return theSet

    components[element] = union_get_compressed_path(theSet)
    return components[element]

