def closest(array, x, first, second, third):
    index_set = {first, second, third}
    first_index = index_set.pop()
    second_index = index_set.pop()
    first_value = array[first_index]
    second_value = array[second_index]
    first_diff = abs(x - first_value)
    second_diff = abs(x - second_value)

    if first_diff > second_diff:
        return second_index
    elif first_diff < second_diff:
        return first_index
    if first_diff == second_diff:
        if first_value > second_value:
            return second_index
        else:
            return first_index


def binary_search(array, x):
    n = len(array)
    left = 0
    right = len(array) - 1
    if x <= array[0]:
        return array[0]
    if x >= array[n - 1]:
        return array[n - 1]
    mid = (left + right) // 2
    while right - left > 1 :
        mid = (left + right) // 2
        value = array[mid]
        if value == x:
            return array[mid]
        if value < x:
            left = mid
        elif value > x:
            right = mid

    closest_index = closest(array, x, left, mid, right)
    return array[closest_index]


