def find_mini(case_str):
    move_dict = {'W':(0, 1), 'S':(0, -1), 'A':(-1, 0), 'D':(1, 0)}
    axis = [0, 0]
    x_rec = [0, 0]
    y_rec = [0, 0]
    for c in case_str:
        axis[0] += move_dict[c][0]
        axis[1] += move_dict[c][1]
        if axis[0] < x_rec[0]:
            x_rec[0] = axis[0]
        if axis[0] > x_rec[1]:
            x_rec[1] = axis[0]
        if axis[1] < y_rec[0]:
            y_rec[0] = axis[1]
        if axis[1] > y_rec[1]:
            y_rec[1] = axis[1]

    width = x_rec[1] - x_rec[0] + 1
    height = y_rec[1] - y_rec[0] + 1


    if width < 3 and height < 3:
        return width * height

    if width > 2 and height > 2:
        if width < height:
            width -=1
        else:
            height -=1
        return width * height

    if width > 2:
        width -=1
    else:
        height -=1
    return width * height



