def solution(arr):
    evens = []
    odds = []
    su = 0
    for a in arr:
        if a%2==0:
            evens.append(a)
        else:
            odds.append(a)
        su+=a
    evens.sort(reverse=True)
    odds.sort(reverse=True)
    if abs(len(evens)-len(odds))<=1:
        return 0
    elif len(evens)==0:
        return sum(odds[1:])
    elif len(odds)==0:
        return sum(evens[1:])
    elif len(evens)>len(odds):
        n = len(odds)
        return sum(evens[n:])
    else:
        n = len(evens)
        return sum(odds[n:])



