y = int(line[3])

maxNum = 100000000000

def solve(n):
    a = n // x
    b = n // y
    both = 0
    pot_a = x
    while True:
        pot_b = y
        if pot_a * pot_b > n:
            break
        while True:
            if pot_a * pot_b > n:
                break
            both += 1
            pot_b *= y
        pot_a *= x

    only_a = a - both
    only_b = b - both
    curr_cnt1 = max(0, cnt1 - only_b)
    curr_cnt2 = max(0, cnt2 - only_a)
    shared = curr_cnt1 + curr_cnt2

    remaining = n - only_a - only_b - both
    if remaining > shared:
        return 1
    elif remaining == shared:
        return 0
    else:
        return -1

def binary_search(left, right):
    middle = (left + right) // 2
    if solve(middle) == 0:
        return middle
    elif solve(middle) == 1:
        return binary_search(left, middle - 1)
    else:
        return binary_search(middle + 1, right)

