def where_more_ones(list_with_values, index):
	if len(list_with_values[index:]) == 0:
		return -1
	elif len(list_with_values[:index]) == 0:
		return 1 


	forward_ones_zeros = [sum(list_with_values[index:]), len(list_with_values[index:])]
	backward_ones_zeros = [sum(list_with_values[:index]), len(list_with_values[:index])]

	forward_ones_zeros[1] = forward_ones_zeros[1] - forward_ones_zeros[0]
	backward_ones_zeros[1] = backward_ones_zeros[1] - backward_ones_zeros[0]
	if forward_ones_zeros[0] == 0:
		return 1
	elif backward_ones_zeros[0] == 0:
		return -1
	value_to_forward = None
	index_of_forward =forward_ones_zeros[1] / forward_ones_zeros[0]
	index_of_backward = backward_ones_zeros[1] / backward_ones_zeros[0]  
	if  index_of_forward > index_of_backward:
		value_to_forward = 1
	elif index_of_backward > index_of_forward:
		value_to_forward = -1 
	else:
		value_to_forward = 1

	return value_to_forward



