import sys

from collections import defaultdict


def solve(io):
	N = io.readInt()
	Q = io.readInt()
	A = io.readIntArray(N)
	B = io.readIntArray(Q)

	freq = defaultdict(lambda: 0)
	for a in A:
		freq[a] += 1

	p = 1
	while p < 2000000000:
		if freq[p] > 1:
			extra = freq[p] - 1
			boost = extra >> 1
			freq[p] -= boost << 1
			freq[p << 1] += boost
		p = p << 1

	for b in B:
		cnt = 0
		p = 1 << 30
		while b > 0 and p > 0:
			want = b // p
			have = min(want, freq[p])
			b -= have * p
			cnt += have
			p = p >> 1
		if b == 0:
			io.println(cnt)
		else:
			io.println(-1)


