def calcBoth(width,height,x,y):
	w = int(width*height/2)+(1 if (width*height)%2==1 else 0)
	b = w - (1 if (width*height)%2==1 else 0)

	if winWite(x,y):
		return w,b
	else:
		return b,w

def winWite(x,y):
	if y%2==0:
		return x%2==0
	else:
		return x%2==1

def calcMid(b,s):
	if (b[0]<=s[0]<=b[2] and b[1]<=s[1]<=b[3]):
		return [s[0], s[1], min(s[2],b[2]), min(s[3],b[3]) ]
	if (b[0]<=s[0]<=b[2] and b[1]<=s[3]<=b[3]):
		return [s[0], max(s[1],b[1]), min(s[2],b[2]), s[3]]
	if (b[0]<=s[2]<=b[2] and b[1]<=s[3]<=b[3]):
		return [max(s[0],b[0]),max(s[1],b[1]),s[2],s[3]]
	if (b[0]<=s[2]<=b[2] and b[1]<=s[1]<=b[3]):
		return [max(s[0],b[0]),s[1],s[2],min(s[3],b[3])]

	if (b[0]<=s[0] and s[2]<=b[2] and s[1]<=b[1] and s[3]>=b[3]):
		return [s[0],b[1],s[2],b[3]]
	if (s[0]<=b[0] and b[2]<=s[2] and b[1]<=s[1] and b[3]>=s[3]):
		return [b[0],s[1],b[2],s[3]]

	return -1

def solve():
	n,m = Many(int)
	f,s = List(int),List(int)

	width = max(f[2],s[2])
	height = max(f[3],s[3])
	w,b = calcBoth(n,m,1,1);

	w = int(w)
	b = int(b)

	whiteW,whiteB = calcBoth(f[2]-f[0]+1,f[3]-f[1]+1,f[0],f[1])
	w-=whiteW
	b-=whiteB

	blackW,blackB = calcBoth(s[2]-s[0]+1,s[3]-s[1]+1,s[0],s[1])
	w-=blackW
	b-=blackB

	if (f[2]-f[0]+1)*(f[3]-f[1]+1)>=(s[2]-s[0]+1)*(s[3]-s[1]+1):
		mid = calcMid(f,s);
	else: 
		mid = calcMid(s,f);

	if (mid!=-1):
		sumW,sumB = calcBoth(mid[2]-mid[0]+1,mid[3]-mid[1]+1,mid[0],mid[1])
		w+=sumW
		b+=sumB
		w-=(mid[2]-mid[0]+1)*(mid[3]-mid[1]+1)

	w+=(f[2]-f[0]+1)*(f[3]-f[1]+1)
	b+=(s[2]-s[0]+1)*(s[3]-s[1]+1)

	print(int(w),int(b))


def main():
	t = One(int)
	while t>0:
		solve()
		t-=1

main()

