def sv1(ls, start):
    sample = []
    for _ in ls:
        sample.append(start)
        start = 1 - start
    memo = []
    for i in range(len(ls)):
        if ls[i] != sample[i]:
            memo.append(i)
    if not memo:
        return 0
    if len(memo) % 2 != 0:
        raise RuntimeError
    ret = 0
    for i in range(0, len(memo), 2):
        ret += abs(memo[i] - memo[i + 1])
    return ret


def sv(ls):
    ls = [1 if i % 2 == 1 else 0 for i in ls]
    odd = sum(ls)
    even = len(ls) - odd
    if abs(odd - even) > 1:
        return -1
    if odd > even:
        return sv1(ls, 1)
    elif odd < even:
        return sv1(ls, 0)
    else:
        return min(sv1(ls, 0), sv1(ls, 1))


