import bisect
from math import atan,pi
import sys

from math import *

def rotate2d(rads,point,origin):
    """
    A rotation function that rotates a point around a point
    to rotate around the origin use [0,0]
    """
    x = point[0] - origin[0]
    yorz = point[1] - origin[1]
    newx = (x*cos(rads)) - (yorz*sin(rads))
    newyorz = (x*sin(rads)) + (yorz*cos(rads))
    newx += origin[0]
    newyorz += origin[1]
    return round(newx),round(newyorz)

rots = [(0,0),(pi/2,1),(-pi/2,1),(pi,2)]

def computeSqDist(pt1,pt2):
    dx = pt1[0]-pt2[0]
    dy = pt1[1]-pt2[1]
    return dx*dx+dy*dy

def computeCenter(pt1,pt2):
    x = (pt1[0]+pt2[0])/2
    y = (pt1[1]+pt2[1])/2
    return (x,y)

def computeAngle(pt1,pt2):
    dx = pt1[0]-pt2[0]
    dy = pt1[1]-pt2[1]
    if(dx == 0):
        return pi/2
    return atan(dy/dx)

def computeAnglePerp(angle):
    anglePerp = angle + pi/2
    if(anglePerp >= pi):
        anglePerp -= pi
    return anglePerp

def isThereSquare(pts):
    lDistCenterAngle = []
    for i1 in range(len(pts)):
        for i2 in range(i1):
            pt1 = pts[i1]
            pt2 = pts[i2]
            dist = computeSqDist(pt1,pt2)
            center = computeCenter(pt1,pt2)
            angle = computeAngle(pt1,pt2)
            lDistCenterAngle.append((dist,center,angle))
    lDistCenterAngle.sort()
    for t in lDistCenterAngle:
        anglePerp = computeAnglePerp(t[2])
        iFirst = bisect.bisect_left(lDistCenterAngle, (t[0],t[1],anglePerp))
        if(iFirst < len(lDistCenterAngle)):
            t2 = lDistCenterAngle[iFirst]
            if(t2[0] == t[0] and t2[1] == t[1] and t2[2] == anglePerp):
                return True
    return False

def computePoint(mole,angle):
    return rotate2d(angle,mole[0],mole[1])


def isSquare(reg,ang1,ang2,ang3,ang4):
    pts = []
    pts.append(computePoint(reg[0],ang1))
    pts.append(computePoint(reg[1],ang2))
    pts.append(computePoint(reg[2],ang3))
    pts.append(computePoint(reg[3],ang4))
    #print(pts)
    return isThereSquare(pts)

def makeCompact(reg):
    minCost = sys.maxsize
    for rot1 in rots:
        for rot2 in rots:
            for rot3 in rots:
                for rot4 in rots:
                    if(isSquare(reg,rot1[0],rot2[0],rot3[0],rot4[0])):
                        cost = rot1[1]+rot2[1]+rot3[1]+rot4[1]
                        minCost = min(minCost,cost)
    if(minCost == sys.maxsize):
        return -1
    else:
        return minCost

def solve(regs):
    for reg in regs:
        print(makeCompact(reg))

