    for i, a in enumerate(A):
        if a >=i and (i ==0 or left_shear[-1] != -1 ):
            left_shear.append(i)
        else:
            left_shear.append(-1)

    right_shear = []
    for i,a in enumerate(A):
        if a >=i and (i == 0 or right_shear[-1] != -1):
            right_shear.append(i)
        else:
            right_shear.append(-1)
    right_shear = right_shear[::-1]

    for i,a in enumerate(A):
