import sys

def bs_small(arr, target):
  start = 0
  end = len(arr) - 1
  if (end == 0):
    return -1
  if (target > arr[end]):
    return arr[end];

  ans = -1;
  while (start <= end):
    mid = (start + end) // 2;
    if (arr[mid] >= target):
      end = mid - 1;

    else:
      ans = mid;
      start = mid + 1;
  if ans !=-1:
    return arr[ans]
  return ans


def bs_large(arr, target):
  start = 0;
  end = len(arr) - 1;

  ans = -1;
  while (start <= end):
    mid = (start + end) // 2;

    if (arr[mid] <= target):
      start = mid + 1;
    else:
      ans = mid;
      end = mid - 1;

  if ans !=-1:
    return arr[ans]
  return ans

def bs(arr, x):
    low = 0
    high = len(arr) - 1
    mid = 0

    while low <= high:

        mid = (high + low) // 2

        # If x is greater, ignore left half
        if arr[mid] < x:
            low = mid + 1

        # If x is smaller, ignore right half
        elif arr[mid] > x:
            high = mid - 1

        # means x is present at mid
        else:
            return mid
    return -1





