    if rest_list == []:
        if (current_list[-1] ^ current_list[0]) == current_list[1]:
            return True
        else:
            return False
    if len(current_list) == 1:
        for num in rest_list:
            current_temp = current_list.copy()
            rest_temp = rest_list.copy()
            current_temp.append(num)
            rest_temp.remove(num)
            if is_circle(current_temp, rest_temp):
                return True
        return False

    next_int = current_list[-1] ^ current_list[-2]
    if next_int in rest_list:
        current_list.append(next_int)
        rest_list.remove(next_int)
        return is_circle(current_list, rest_list)
    else:
        return False


