class PriorityQueue:
    class Reverse:
        def __init__(self, val):
            self.val = val

        def __lt__(self, other):
            return self.val > other.val

        def __repr__(self):
            return repr(self.val)

    def __init__(self, a=None, desc=False):
        import heapq
        self.heapq = heapq
        self.__container = []
        if a:
            self.__container = a[:]

        if desc:
            for i in range(len(self.__container)):
                self.__container[i] = self.Reverse(self.__container[i])
            self.pop = self.__pop_desc
            self.push = self.__push_desc
            self.top = self.__top_desc
            self.pushpop = self.__pushpop_desc
            self.poppush = self.__poppush_desc
        else:
            self.pop = self.__pop_asc
            self.push = self.__push_asc
            self.top = self.__top_asc
            self.pushpop = self.__pushpop_asc
            self.poppush = self.__poppush_asc

        self.heapq.heapify(self.__container)

    @property
    def is_empty(self):
        return not self.__container

    def __pop_asc(self):
        return self.heapq.heappop(self.__container)

    def __pop_desc(self):
        return self.heapq.heappop(self.__container).val

    def __push_asc(self, item):
        self.heapq.heappush(self.__container, item)

    def __push_desc(self, item):
        self.heapq.heappush(self.__container, self.Reverse(item))

    def __top_asc(self):
        return self.__container[0]

    def __top_desc(self):
        return self.__container[0].val

    def __pushpop_asc(self, item):
        return self.heapq.heappushpop(self.__container, item)

    def __pushpop_desc(self, item):
        return self.heapq.heappushpop(self.__container, self.Reverse(item)).val

    def __poppush_asc(self, item):
        return self.heapq.heapreplace(self.__container, item)

    def __poppush_desc(self, item):
        return self.heapq.heapreplace(self.__container, self.Reverse(item)).val

    def sum(self):
        return sum(self.__container)

    def __len__(self):
        return len(self.__container)

    def __str__(self):
        return str(sorted(self.__container))

    def __repr__(self):
        return self.__str__()


