def solve(n, s):

    ss = []
    for c in s:
        if c == ".":
            ss.append(True)
        else:
            ss.append(False)

    len_ss = len(ss)
    result = 0
    if len_ss == 1:
        result = 0
    elif len_ss == 2:
        if ss == [False, True]:
            result = 1
    elif len_ss == 3:
        if ss == [True, True, True]:
            pass
        if ss == [True, True, False]:
            pass
        if ss == [True, False, True]:
            result = result + 1
        if ss == [False, True, True]:
            result = result + 1
        if ss == [True, False, False]:
            pass
        if ss == [False, True, False]:
            result = result + 1
        if ss == [False, False, True]:
            result = result + 1
        if ss == [False, False, False]:
            pass
    else:
        result = 0
        for i, d in enumerate(ss):
            if i > 0 and ss[i-1] is True and ss[i] is False and i+1 < len_ss and ss[i+1] is True:
                ss[i] = True
                result = result + 1
            if i > 0 and ss[i-1] is False and ss[i] is True and i+1 < len_ss and ss[i+1] is True:
