def isPower (x, y): 

    # The only power of 1 
    # is 1 itself 
    if (x == 1): 
        return (y == 1) 

    # Repeatedly compute 
    # power of x 
    pow = 1
    count =0
    while (pow < y): 
        pow = pow * x 
        count +=1

    # Check if power of x 
    # becomes y 
    if(pow == y):
        return count
    else:
        return -1 

def isdiv(n):
