    N = int(input())
    p = list(map(int, input().split(" ")))
    p.insert(0, 0)
    cnt = 0

    for i in range(1, N+1):
        if i == p[i]:
            if i != N:
                p[i], p[i+1] = swap(p[i], p[i+1])
            else:
                p[i-1], p[i] = swap(p[i-1], p[i])
        else:
            pass

