def rec(a: int, b: int) -> int:
    mx = max(a,b)
    mn = min(a,b)
    if gcd(a,b) == mn:
        return (2 * (mx // mn) - 1) * mn

    else:
        return (2 * (mx // mn) * mn)  + rec(mn, mn * (mx // mn))

