import math

def cnt(l, r):
    if l % 2 != 0:
        l += 1
    if r % 2 != 0:
        r -= 1
    l = l // 2
    r = r // 2
    if l <= r :
        return r - l + 1
    return 0

def count(x, l, r):
    if x % 2 == 0:
        return cnt(l, r)
    else:
        return (r - l + 1) - cnt(l, r)

