    i = 2
    while i < 10**5+1:
        if nums[i] != -1:
            primes.append(i)
            n = 1
            temp = n*i
            while temp < 10**5+1:
                nums[temp] = -1
                n += 1
                temp = n*i
        i += 1
    return primes

