def lbig(x, y, z, f):
    if x == 1.0:
        return 0.0

    w = 1.0
    if x < 1.0:
        w = -1.0
        x = 1.0/x

    if f == True:
        return w * (z * log(y) + log(log(x)))

    return w * (log(z) + log(y) + log(log(x)))

def rets(x, y, z, xs, ys, zs, n):
    xss = [
    (lbig(x, y, z, True), xs+'^'+ys+'^'+zs,n+1),
