def check_and_back_or_go_to(li, ind, N, counter, white_charge, black_charge):
    back = True
    # print('see {} {} and {} counter{}'.format(ind, li[ind - 1], li[ind], counter))
    if ind == 0:
        return counter

    # access
    if li[ind - 1] == '#' and li[ind] == '.':
        c = check_and_back_or_go_to(li, ind - 1, N, counter+1, white_charge, black_charge)
        return c
    elif li[ind - 1] == '.' and li[ind] == '.':
        return check_and_back_or_go_to(li, ind - 1, N, counter, white_charge + 1, black_charge)

    elif li[ind - 1] == '#' and li[ind] == '#':
        return check_and_back_or_go_to(li, ind - 1, N, counter, white_charge + 1, black_charge+1)
    elif li[ind - 1] == '.' and li[ind] == '#':
        adder=min([white_charge,black_charge])
        return check_and_back_or_go_to(li, ind - 1, N, counter+adder, 0, 0)
    else:
        c = check_and_back_or_go_to(li, ind - 1, N, counter, white_charge, black_charge)
        return c


