def minimal_swaps(n, animals):
    total_hamsters = animals.count('H')
    total_tigers = animals.count('T')

    if total_hamsters == 0 or total_tigers == 0:
        return 0

    min_swaps = total_tigers

    hamster_count = 0
    window_size = total_hamsters

    for i in range(n):
        if animals[i] == 'H':
            hamster_count += 1
        if i >= window_size:
            if animals[i - window_size] == 'H':
                hamster_count -= 1
        if i >= window_size - 1:
            min_swaps = min(min_swaps, window_size - hamster_count)

    return min_swaps

