    if exponent == 0:
        return 1
    elif exponent % 2 == 0:
        half_pow = binary_power(base, exponent // 2)
        return half_pow * half_pow
    else:
        half_pow = binary_power(base, (exponent - 1) // 2)
        return half_pow * half_pow * base


