class Chem:
    """ Chem representation """
    MAX = 100001

    def __init__(self, args):
        """ Default constructor """

        self.n = args[0]
        self.list = args[1]

    def decant(self, valid, stp, vol, max=MAX):
        new_valid = set()
        first = 1 if not valid else 0
        steps = 0
        prev = None
        while vol > 0:
            if (first or vol in valid):
                if (prev is None or prev % 2 == 1):
                    ssteps = steps + 1
                    svol = vol * 2
                    while svol <= max:
                        if first or svol in valid:
                            new_valid.add(svol)
                            stp[svol] += ssteps
                        else:
                            break
                        svol *= 2
                        ssteps += 1

                new_valid.add(vol)
                stp[vol] += steps
            prev = vol
            vol >>= 1
            steps += 1
        if not first:
            valid.intersection_update(new_valid)
        else:
            valid.update(new_valid)

    def calculate(self):
        """ Main calcualtion function of the class """

        valid = set()
        stp = [0] * self.MAX
        for n in self.list:
            self.decant(valid, stp, n)

        result = None
        for n in valid:
            if result is None or result > stp[n]:
                result = stp[n]

        return str(result)



def get_inputs(test_inputs=None):

    it = iter(test_inputs.split("\n")) if test_inputs else None

    def uinput():
        """ Unit-testable input function wrapper """
        if it:
            return next(it)
        else:
            return sys.stdin.readline()

    # Getting string inputs. Place all uinput() calls here
    num = int(uinput())
    nums = map(int, uinput().split())

    # Decoding inputs into a list
    return [num, nums]


def calculate(test_inputs=None):
    """ Base class calculate method wrapper """
    return Chem(get_inputs(test_inputs)).calculate()



