import sys

sys.setrecursionlimit(10**5)

class BinaryHeap(object):
    PRIORITY_INDEX = 0
    DATA_INDEX = 1

    def __init__(self):
        self.__heap = []  # Our heap array
        self.__index_map = {}  # Our index mappings, data -> array_index

    def insert(self, item, priority):
        packed = (priority, item)  # Packed data in the tuple

        #  The length of the heap will be our index after we insert a new item
        self.__index_map[item] = len(self.__heap)

        self.__heap.append(packed)  # Append our packed item to the heap
        self.__bubble_up(len(self.__heap) - 1)  # Bubble the heap array upwards

    def pop_min(self):
        if self.__heap:  # Make sure we have items in the heap
            result = self.__heap[0][self.DATA_INDEX]  # Grab our resulting data

            self.__swap(0, len(self.__heap) - 1)  # Swap the first and last el

            self.__index_map.pop(result, None)  # Pop our result from the map
            self.__heap.pop()  # Pop the result from the heap

            self.__bubble_down(0)  # Bubble downwards starting at index 0

            return result  # return the resulting data object

        return None  # If the heap is empty return None

    def decrease_key(self, key, priority):
        index = self.__index_map[key]  # What is our array's index?
        updated_pair = (priority, key)  # Construct the new packed tuple

        self.__heap[index] = updated_pair  # Update the key's new array index

        self.__bubble_up(index)  # Bubble upwards from the index of the key

    def is_empty(self):
        return len(self.__heap) == 0

    def __bubble_up(self, pos):
        while pos > 0:  # if `pos` is negative we are above the root node
            parent_pos = floor((pos - 1) / 2)  # The parent node of the tree

            #  if the priority of our position is greater than our parent stop
            if self.__heap[pos][0] >= self.__heap[parent_pos][0]:
                break

            self.__swap(parent_pos, pos)  # we have to swap with our parent
            pos = parent_pos  # We are now at the parent position

    def __bubble_down(self, pos):
        left = 2 * pos + 1  # get our left childs position, adjust for 0th idx
        right = left + 1  # Our right index will be left + 1 in an array
        smallest = pos  # Keep track of the smallest possible position so far

        #  We must check if left is smaller than us to swap
        if left < len(self.__heap) and self.__heap[left][0] < self.__heap[
                smallest][0]:
            smallest = left
        #  Or is right the smallest of them all?
        if right < len(self.__heap) and self.__heap[right][0] < self.__heap[
                smallest][0]:
            smallest = right

        if smallest != pos:  # If we've determined a new smallest element, swap
            self.__swap(pos, smallest)  # Swap with the smallest element
            self.__bubble_down(smallest)  # Recurse down the tree again

    def __swap(self, first_element, second_element):
        tmp = self.__heap[first_element]  # Temporary element to keep trakc of
        exchange = self.__heap[second_element]  # The exchange element

        #  Update our index mappings before we make the switch
        self.__index_map[tmp[self.DATA_INDEX]] = second_element
        self.__index_map[exchange[self.DATA_INDEX]] = first_element

        # Now that our index mappings reflect the change lets change the heap.
        self.__heap[first_element] = exchange
        self.__heap[second_element] = tmp


class Graph(object):
    def __init__(self, verticies=None, edges=None):
        self._graph_dict = {}

        if verticies is not None:
            for vertex in verticies:
                self.add_vertex(vertex)

        if edges is not None:
            if isinstance(edges, type) or isinstance(edges, list):
                for edge in edges:
                    self.add_edge(edge[0], edge[1])

    def add_vertex(self, vertex):
        if vertex not in self._graph_dict:
            self._graph_dict[vertex] = set()

    def add_edge(self, source, destination):
        self.add_vertex(source)
        self.add_vertex(destination)
        self._graph_dict[source].add(destination)

    def is_edge(self, source, destination):
        return (self.is_vertex(source) and
                destination in self._graph_dict[source])

    def is_vertex(self, vertex):
        return vertex in self._graph_dict

    def neighbours(self, vertex):
        return self._graph_dict[vertex]

    def vertices(self):
        return self._graph_dict.keys()

def least_cost_path(graph, start, end, cost, heuristic=lambda u, v: 0):
    priority_queue = BinaryHeap()

    priority_queue.insert(start, 0)

    path_costs = {start: 0}

    path = {start: None}

    while not priority_queue.is_empty():
        vertex = priority_queue.pop_min()

        if vertex == end:
            shortest_path = [vertex]

            while vertex != start:
                vertex = path[vertex]

                shortest_path.append(vertex)

            shortest_path.reverse()
            return shortest_path

        for neighbour in graph.neighbours(vertex):
            current_cost = path_costs[vertex] + cost(vertex, neighbour)

            if neighbour not in path_costs or current_cost < path_costs[neighbour]:
                path_costs[neighbour] = current_cost

                priority = current_cost + heuristic(end, neighbour)
                priority_queue.insert(neighbour, priority)

                path[neighbour] = vertex

    return []  # if we found no path, return an empty array


def main():
    n, m = map(int, input().split(' '))

    g = Graph()
    costs = {}
    for i in range(m):
        source, destination, cost = map(int, input().split(' '))
        g.add_edge(source, destination)
        costs[(source, destination)] = cost

    lcp = least_cost_path(g, 1, len(g.vertices()), lambda s,d: costs[(s,d)])

    if len(lcp) != 0:
        print(' '.join(str(vertex) for vertex in lcp))
    else:
        print('-1')

