def one_N(a):
    res = 1
    mod_N = 10 ** 9 + 7
    while(a**res < mod_N ):
        res += 1
    return res -1

def simplify_mod(a,n):
    mod_N = 10**9 + 7
    one = one_N(a)
    res = 1
    for i in range(n//one):
        res = (res%mod_N)*(a**one%mod_N)
    res = (res%mod_N)*(a**(one*(n//one))%mod_N)
    return res



