# Dijkstra as shown in class
def dijkstra(graph, startNode):
    
    pq = PriorityQueue()
    graph[startNode - 1].cost = 0
    pq.put((0, startNode))
    
    while not pq.empty():
        currDist, current = pq.get()
        currNode = graph[current - 1]
        currNode.visited = True
        for edge in currNode.neighbors:
            nextNode = graph[edge.dest - 1]
            newCost = currDist + edge.weight
            
            if not nextNode.visited and newCost < nextNode.cost:
                nextNode.cost = newCost
                nextNode.prev = copy.deepcopy(currNode.prev)
                nextNode.prev.append(current)
                pq.put((newCost, edge.dest))
                
