    while True:
        try:
            string += input()
            string += "\n"
        except EOFError:
            break

    list_words = re.split(pattern, string)
    lenght = len(list_words) - 1

    for it in list_words:
        if 0 <= len(it) <= 2:
            lenght += len(it)
            continue
        tmp = ""
        for i in range(len(it) - 2):
            tmp += it[i]
