from collections import defaultdict
from email.policy import default


class Graph:
    def __init__(self, nNodes, edges):
        self.numNodes = nNodes
        self.edges = edges
        # self.nodes = list(range(1, nNodes + 1))
        self.graph = {node: [] for node in range(1, self.numNodes+1)}
        for edge in edges:
            self.graph[edge[0]].append(edge[1])
            self.graph[edge[1]].append(edge[0])

    # dfs
    def dfs(self, start):
        visited = []
        stack = [start]
        while stack:
            node = stack.pop()
            if node not in visited:
                visited.append(node)
                stack.extend(self.graph[node])
        return visited

    # bfs
    def bfs(self, start):
        mark = defaultdict(int)
        queue = [start]
        mark[start] = 1
        while queue:
            node = queue.pop(0)
            for i in self.get_neighbors(node): 
                if mark[i] == 0:
                    mark[i] = mark[node]*(-1)
                    queue.extend(self.graph[node])
        return sum(value == 1 for value in mark.values())

    def add_edge(self, node1, node2):
        self.graph[node1].append(node2)
        self.graph[node2].append(node1)

    def add_node(self, node):
        self.graph[node] = []

    def remove_edge(self, node1, node2):
        self.graph[node1].remove(node2)
        self.graph[node2].remove(node1)

    def remove_node(self, node):
        for neighbor in self.graph[node]:
            self.graph[neighbor].remove(node)
        del self.graph[node]

    def get_neighbors(self, node):
        return self.graph[node]

    def get_edges(self):
        return self.edges

    def get_graph(self):
        return self.graph

    def get_nodes(self):
        return list(range(self.numNodes))


