from typing import List


def is_prime(num: int | float) -> bool:
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def get_prime_list_less_than(num: int) -> List[int]:
    """
    Returns a list of all primes less than num.
    """
    prime_list = []
    for i in range(2, num + 1):
        if is_prime(i):
            prime_list.append(i)
    return prime_list


def get_divisors(num: int | float) -> List[int]:
    """
    Returns a list of all divisors of num.
    """
    divisors = []
    for i in range(1, int(num**0.5) + 1):
        if num % i == 0:
            divisors.append(i)
            if i != num // i:
                divisors.append(num // i)
    return divisors


def almost_prime(num: int | float, prime_list: List[int]) -> bool:
    """
    A number is called almost prime if it has exactly two distinct prime divisors.
    """
    divisors = get_divisors(num)
    c = 0
    for i in divisors:
        for j in prime_list:
            if i == j:
                c += 1
    return c == 2


