def dfs(n, node, visited, graph, store):
  if node == n:
    return [n]

  if node in store:
    return []

  store[node] = 1


  for ele in graph[node]:
    v = ele[0]
    w = ele[1]

    if (w+visited[node] <= visited[ele[0]]) and ele[0] not in store:
      res = dfs(n, ele[0], visited, graph, store)

      if res != []:
        return res+[node]

  return []













def solve():
  n, m = get_ints()
  tm = m

  graph = {}
  visited = {}

  for i in range(1, n+1):
    visited[i] = float("inf")

  visited[1] = 0

  while tm:
    a, b, w = get_ints()

    if a not in graph:
      graph[a] = [[b, w]]
    else:
      graph[a].append([b, w])

    if b not in graph:
      graph[b] = [[a, w]]
    else:
      graph[b].append([a, w])


    tm -= 1

  queue = [[0, 1]]
  heapq.heapify(queue)

  while queue:
    distance, node = heapq.heappop(queue)

    if visited[node] >= distance:
      visited[node] = distance

    if node not in graph:
      continue

    for ele in graph[node]:
      v = ele[0]
      w = ele[1]

      if distance+w <= visited[v]:
        heapq.heappush(queue, [distance+w, v])


  # print("visited:-", visited)

  if visited[n] == float("inf"):
    print(-1)
    return

  res = dfs(n, 1, visited, graph, {})
  res.reverse()
  print(*res)





















