def count(x, y, levels):
    if levels[y] < levels[x] :
        return count(y, x, levels)
    l1 = levels[y]
    l2 = levels[x]
    yo = y
    while l1-l2 > 1:
        l1 -= 1
        y = parents[y]
    if parents[y] == x:
        return (size[x]-size[y])*(size[yo])
    return (size[x])*(size[yo])

