# Function to precompute prime numbers up to the square root of 10^12
def sieve(n):
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, int(math.sqrt(n) + 1)):
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
    primes = [i for i in range(2, n + 1) if is_prime[i]]
    return set(primes)

