        v+=eat
        cand-=eat
        cand-=cand//10
        
    return v>=n/2

def candies(n):
    l=1
    r=n
    sol=n
    
    while l<r:
        m=(l+r)//2
        
        if check(n,m):
            sol=m
            if m and not check(n,m-1):
                break
            r=m
            
            
        else:
            if sol<r-(l+2)//2:
                break
            l=m+1
            
    return sol

