    for i in range(1,n-1):
        left = -1*(f[i][0] - f[i][1] > f[i-1][0])
        right = f[i][0] + f[i][1] < f[i+1][0]
        if left + right == 0 and left == -1:
            curr.append(2)
        else:
            curr.append(left + right)
    curr += [0]
    flag = True
    while flag:
        flag = False
        for i in range(1,n-1):
            if curr[i] != 0:
                if (curr[i] == -1 and curr[i-1] == 0) or (curr[i] == 1 and curr[i+1] == 0) or (curr[i] == 2 and (curr[i-1] == 0 or curr[i+1] == 0)):
                    ans += 1
                    curr[i] = 0
                    flag = True
    rem = ''.join([str(i) for i in curr]).split('0')
    for i in rem:
        if len(i):
            neg = i.count('-')
            pos = len(i) - 2*neg
            if neg > pos:
                ans += neg
            else:
                ans += pos
    return ans + 2

