import heapq


def main():
    n, m = map(int, input().split())
    adj_list = [{} for _ in range(n)]
    for i in range(m):
        ai, bi, wi = map(int, input().split())
        ai -= 1
        bi -= 1
        if bi not in adj_list[ai]:
            adj_list[ai][bi] = wi
        else:
            adj_list[ai][bi] = min(wi, adj_list[ai][bi])
        if ai not in adj_list[bi]:
            adj_list[bi][ai] = wi
        else:
            adj_list[bi][ai] = min(wi, adj_list[bi][ai])

    min_weight_heap = []
    heapq.heappush(min_weight_heap, (0, 0))
    length = [float("inf") for _ in range(n)]
    length[0] = 0
    shortest_path = [-1 for _ in range(n)]
    visited = {}

    while min_weight_heap:
        l, v = heapq.heappop(min_weight_heap)
        visited[v] = None
        for u in adj_list[v]:
            if u not in visited:
                w = adj_list[v][u]
                new_w = length[v] + w
                if new_w < length[u]:
                    length[u] = new_w
                    shortest_path[u] = v
                    heapq.heappush(min_weight_heap, (new_w, u))

    if length[-1] == float("inf"):
        print(-1)
        return
    p = n - 1
    path = f"{p + 1} "
    while p != 0:
        p = shortest_path[p]
        path = f"{p + 1} " + path
    print(path)


