def is_prime(n):
    if n <= 1:
        return False
    elif n <= 3:
        return True
    elif n % 2 == 0 or n % 3 == 0:
        return False
    for i in range(5, int(n ** 0.5) + 1, 6):
        if n % i == 0 or n % (i + 2) == 0:
            return False
    return True


def nth_prime(n):
    if n < 1:
        raise ValueError
    count, number = 0, 3
    while count < n:
        rev = int(str(number)[::-1])
        if is_prime(number) and is_prime(rev) and number != rev:
            count += 1
        number += 2
    return number - 2

