from functools import lru_cache

@lru_cache(maxsize=None)
def primes(n):
    primes=[4,9,25]
    for i in range(6,n):
        for j in range(2,int(i**0.5)+1):
            if i%j==0 and j!=int(i**0.5):
                continue
            elif i%j!=0 and j==int(i**0.5):
                primes.append(i**2)
    return primes


