def first(n):
    if n == 0:
        return None
    for i in range(len(str(n))):
        if (n >> i) & 1 == 1:
            return i


def is_count_more_then_2(n):
    for i in range(2):
        n = n & (n - 1)
    return bool(n)


def load_cmd_data():
    n, m = [int(i) for i in input().split()]
    graph = [[0] * n for i in range(n)]
    for i in range(m):
        x, y = [int(j) - 1 for j in input().split()]
        graph[x][y] = 1
        graph[y][x] = 1
    return n, graph.copy()


def solve(n, graph):
    # n = 10  # количество вершин в графе
    dp = [[0] * n for i in range(1 << n)]
    for i in range(n):
        mask = 1 << i
        dp[mask][i] = 1
    # graph = [[0] * n for i in range(n)]
    for mask in range(1, 1 << n):
        for i in range(n):
            for j in range(n):
                if graph[i][j] == 1 and mask ^ (mask - 1) != 0 and (mask >> i) & 1 == 1 and i != first(mask):
                    dp[mask][i] += dp[mask ^ (1 << i)][j]

    answer = 0
    # for line in dp:
    #     print(line)
    for mask in range(1, 1 << n):
        for i in range(n):
            if is_count_more_then_2(mask) and graph[first(mask)][i] == 1:
                answer += dp[mask][i]
    return answer // 2


def main():
    n, arr = load_cmd_data()
    print(solve(n, arr))


