import math

def sieveOfEratosthenes(n):
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    
    for i in range(2, int(math.sqrt(n)) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    
    return is_prime

def isTPrime(num, is_prime):
    root = int(math.sqrt(num))
    if root * root != num or not is_prime[root]:
        return False
    return True

