from collections import deque


def rook_bishop_and_king(r1_int, c1_int, r2_int, c2_int) -> tuple:
    if r1_int == r2_int or c1_int == c2_int:
        rook_move = 1
    else:
        rook_move = 2

    bishop_move = 0
    r1_c1_reach = set()
    r_curr, c_curr = r1 + 1, c1 + 1
    while 1 <= r_curr <= 8 and 1 <= c_curr <= 8:
        r1_c1_reach.add((r_curr, c_curr))
        r_curr, c_curr = r_curr + 1, c_curr + 1
    r_curr, c_curr = r1 + 1, c1 - 1
    while 1 <= r_curr <= 8 and 1 <= c_curr <= 8:
        r1_c1_reach.add((r_curr, c_curr))
        r_curr, c_curr = r_curr + 1, c_curr - 1
    r_curr, c_curr = r1 - 1, c1 + 1
    while 1 <= r_curr <= 8 and 1 <= c_curr <= 8:
        r1_c1_reach.add((r_curr, c_curr))
        r_curr, c_curr = r_curr - 1, c_curr + 1
    r_curr, c_curr = r1 - 1, c1 - 1
    while 1 <= r_curr <= 8 and 1 <= c_curr <= 8:
        r1_c1_reach.add((r_curr, c_curr))
        r_curr, c_curr = r_curr - 1, c_curr - 1
    if (r2, c2) in r1_c1_reach:
        bishop_move = 1

    if bishop_move == 0:
        r2_c2_reach = set()
        r_curr, c_curr = r2 + 1, c2 + 1
        while 1 <= r_curr <= 8 and 1 <= c_curr <= 8:
            r2_c2_reach.add((r_curr, c_curr))
            r_curr, c_curr = r_curr + 1, c_curr + 1
        r_curr, c_curr = r2 + 1, c2 - 1
        while 1 <= r_curr <= 8 and 1 <= c_curr <= 8:
            r1_c1_reach.add((r_curr, c_curr))
            r_curr, c_curr = r_curr + 1, c_curr - 1
        r_curr, c_curr = r2 - 1, c2 + 1
        while 1 <= r_curr <= 8 and 1 <= c_curr <= 8:
            r1_c1_reach.add((r_curr, c_curr))
            r_curr, c_curr = r_curr - 1, c_curr + 1
        r_curr, c_curr = r2 - 1, c2 - 1
        while 1 <= r_curr <= 8 and 1 <= c_curr <= 8:
            r2_c2_reach.add((r_curr, c_curr))
            r_curr, c_curr = r_curr - 1, c_curr - 1
        for each in r2_c2_reach:
            if each in r1_c1_reach:
                bishop_move = 2
                break

    king_r1_c1_reach = deque()
    visited = set()
    king_r1_c1_reach.append((r1, c1))
    parent = dict()
    found = False
    while len(king_r1_c1_reach) > 0:
        r_curr, c_curr = king_r1_c1_reach.popleft()
        # print(r_curr, c_curr, visited)
        if (r_curr, c_curr) == (r2, c2):
            found = True
            break
        if 1 <= c_curr + 1 <= 8:
            if (r_curr, c_curr + 1) not in visited:
                king_r1_c1_reach.append((r_curr, c_curr + 1))
                parent[(r_curr, c_curr + 1)] = (r_curr, c_curr)
                visited.add((r_curr, c_curr + 1))
        if 1 <= r_curr + 1 <= 8 and 1 <= c_curr + 1 <= 8:
            if (r_curr + 1, c_curr + 1) not in visited:
                king_r1_c1_reach.append((r_curr + 1, c_curr + 1))
                parent[(r_curr + 1, c_curr + 1)] = (r_curr, c_curr)
                visited.add((r_curr + 1, c_curr + 1))
        if 1 <= r_curr + 1 <= 8:
            if (r_curr + 1, c_curr) not in visited:
                king_r1_c1_reach.append((r_curr + 1, c_curr))
                parent[(r_curr + 1, c_curr)] = (r_curr, c_curr)
                visited.add((r_curr + 1, c_curr))
        if 1 <= r_curr + 1 <= 8 and 1 <= c_curr - 1 <= 8:
            if (r_curr + 1, c_curr - 1) not in visited:
                king_r1_c1_reach.append((r_curr + 1, c_curr - 1))
                parent[(r_curr + 1, c_curr - 1)] = (r_curr, c_curr)
                visited.add((r_curr + 1, c_curr - 1))
        if 1 <= c_curr - 1 <= 8:
            if (r_curr, c_curr - 1) not in visited:
                king_r1_c1_reach.append((r_curr, c_curr - 1))
                parent[(r_curr, c_curr - 1)] = (r_curr, c_curr)
                visited.add((r_curr, c_curr - 1))
        if 1 <= r_curr - 1 <= 8 and 1 <= c_curr - 1 <= 8:
            if (r_curr - 1, c_curr - 1) not in visited:
                king_r1_c1_reach.append((r_curr - 1, c_curr - 1))
                parent[(r_curr - 1, c_curr - 1)] = (r_curr, c_curr)
                visited.add((r_curr - 1, c_curr - 1))
        if 1 <= r_curr - 1 <= 8:
            if (r_curr - 1, c_curr) not in visited:
                king_r1_c1_reach.append((r_curr - 1, c_curr))
                parent[(r_curr - 1, c_curr)] = (r_curr, c_curr)
                visited.add((r_curr - 1, c_curr))
        if 1 <= r_curr - 1 <= 8 and 1 <= c_curr + 1 <= 8:
            if (r_curr - 1, c_curr + 1) not in visited:
                king_r1_c1_reach.append((r_curr - 1, c_curr + 1))
                parent[(r_curr - 1, c_curr + 1)] = (r_curr, c_curr)
                visited.add((r_curr - 1, c_curr + 1))
        # print(king_r1_c1_reach)

    if not found:
        king_move = 0
    else:
        r_curr, c_curr = r2, c2
        king_move = 0
        while True:
            if (r_curr, c_curr) == (r1, c1):
                break
            else:
                r_curr, c_curr = parent[(r_curr, c_curr)]
                king_move += 1

    return rook_move, bishop_move, king_move


