from queue import PriorityQueue


class Graph:

    def __init__(self, n, m):
        self._num_of_vertices = n
        self._num_of_edges = m
        self._edges = [[-1 for i in range(n)] for j in range(n)]

    def add_edge(self, v, u, w):
        self.edges[v][u] = w
        self.edges[u][v] = w

    @property
    def vertices(self):
        return self._num_of_vertices

    @property
    def edges(self):
        return self._edges

    @property
    def num_edges(self):
        return self._num_of_edges

    def printPath(self, parent, end):
        if parent[end] == -1:
            print(end + 1, end=' ')
            return
        self.printPath(parent, parent[end])
        print(end + 1, end=' ')

    def find_way(self, start, end):
        distance = {k: float('inf') for k in range(self.vertices)}
        distance[start] = 0
        parent = [-1 for i in range(self.vertices)]
        visited = []

        pq = PriorityQueue()
        pq.put((0, start))

        while not pq.empty():
            (dist, curr) = pq.get()
            visited.append(curr)

            for neigh in range(self.vertices):
                if self.edges[curr][neigh] != -1:
                    distan = self.edges[curr][neigh]
                    if neigh not in visited:
                        old_cost = distance[neigh]
                        new_cost = dist + distan
                        if new_cost < old_cost:
                            parent[neigh] = curr
                            pq.put((new_cost, neigh))
                            distance[neigh] = new_cost

        self.printPath(parent, end)

    def input_graph(self):
        for i in range(self._num_of_edges):
            [u, v, w] = map(int, input().split())
            self.add_edge(u - 1, v - 1, w)


if __name__ == '__main__':
    [n, m] = map(int, input().split())
    g = Graph(n, m)
    g.input_graph()
    g.find_way(0, n - 1)

