        for nie in graph[node]:
            if nie!=par:
                d[node][1]+=1
                helper(nie,node)
                for j in range(k):
                    d[node][j+1]+=d[nie][j]
    helper(0,-1)
    ans=[0]
    for el in d:
        ans[0]+=el[k]
    def solver(node,par):
        if par==-1:
            for nie in graph[node]:
                solver(nie,node)
        else :
            
            p=d[par][:]
