            for el in range(2,k+1):
                p[el]-=d[node][el-1]
            d[node][1]+=1
            ans[0]+=p[k-1]
            for el in range(2,k+1):
                d[node][el]+=p[el-1]
            for nie in graph[node]:
                if nie !=par:
                    solver(nie,node)
    solver(0,-1)
