def find_range(a, seq):
    return (seq.find(a), seq.rfind(a))


def solve(rs, k):
    overlap = 0
    i = 0
    while i < len(rs):
        j = i + 1
        while j < len(rs):
            x = rs[i]
            y = rs[j]
            if i != j and x[0] >= 0 and y[0] >= 0:
                if x[1] >= y[0]:
                    overlap += 1
            j += 1
        i += 1
    return overlap >= k


