def combinacao(e, comb):
  if(e == comb):
    return 1
  if(e < comb):
    return 0
  
  x = e -comb
  result = 1
  if(x > comb):
    while(e > x):
      result = result * e
      e = e - 1
    while(comb > 1):
      result = result / comb
      comb = comb - 1
  else:
    while(e > comb):
      result = result * e
      e = e - 1
    while(x > 1):
      result = result / x
      x = x - 1
  
  return result

