import random


def is_prime(n, k=5):
    # 对于小于6的数，可以直接判断是否为质数
    if n < 6:
        return n == 2 or n == 3 or n == 5

    # 将n-1拆分为(2^r) * d的形式
    r, d = 0, n - 1
    while d % 2 == 0:
        r += 1
        d //= 2

    # 进行k轮Miller-Rabin测试
    for _ in range(k):
        a = random.randint(2, n - 2)

        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue

        for _ in range(r - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False

    return True
