from collections import Counter

def can_form_names(guest, host, pile):
    guest_count = Counter(guest)
    host_count = Counter(host)
    pile_count = Counter(pile)
    
    for letter, count in guest_count.items():
        if pile_count[letter] < count:
            return False

    for letter, count in host_count.items():
        if pile_count[letter] < count:
            return False

    for letter, count in pile_count.items():
        if letter not in guest_count and letter not in host_count:
            return False
    
    return True


