def search(lst, x):
    low = 0
    mid = 0
    high = len(lst)-1
    while low <= high:
        mid = (low+high)//2
        if lst[mid] < x:
            low = mid + 1
        elif lst[mid] > x:
            high = mid - 1
        else:
            return mid
    return low

