    global count
    for i in range(len(left)):
        if left[i] != None:
            for j in range(len(right)):
                if right[j]!=None:
                    if right[j][1] >= left[i][1]:
                        right[j] = None
                    elif right[j][1] >= left[i][0] and right[j][1] < left[i][1]:
                        left[i] = None
                    else:
                        left[i] = None
                        count+=1
    return left + right

