def dis(from_loc: tuple[int, ...], to_loc: tuple[int, ...], *, manhattan_distance = False) -> int:
    result = 0
    if not manhattan_distance:
        for i in range(min(len(from_loc), len(to_loc))):
            result += (from_loc[i] - to_loc[i]) * (from_loc[i] - to_loc[i])
    else:
        for i in range(min(len(from_loc), len(to_loc))):
            result += abs(from_loc[i] - to_loc[i])
    return result

def vector(from_loc: tuple[int, int], to_loc: tuple[int, int]) -> tuple[int, int]:
    return to_loc[0] - from_loc[0], to_loc[1] - from_loc[1]

def product_loc(from_loc: tuple[int, int], first_loc: tuple[int, int], second_loc: tuple[int, int]) -> int:
    vector1 = vector(from_loc, first_loc)
    vector2 = vector(from_loc, second_loc)
    return vector1[0] * vector2[1] - vector2[0] * vector1[1]

def product_vec(vector1: tuple[int, int], vector2: tuple[int, int]) -> int:
    return vector1[0] * vector2[1] - vector2[0] * vector1[1]

def dot(from_loc: tuple[int, int], first_loc: tuple[int, int], second_loc: tuple[int, int]) -> int:
    vector1 = vector(from_loc, first_loc)
    vector2 = vector(from_loc, second_loc)
    return vector1[0] * vector2[0] + vector1[1] * vector2[1]

def get_line_equation(first_loc: tuple[int, int], second_loc: tuple[int, int])\
        -> [tuple[int, int, int] | None]:

    if first_loc == second_loc:
        return None

    line_vector = vector(first_loc, second_loc)
    line_gcd = gcd(line_vector[0], line_vector[1])
    line_a, line_b = line_vector[1] // line_gcd, -line_vector[0] // line_gcd
    line_c = - line_b * first_loc[1] - line_a * first_loc[0]
    if line_a < 0:
        line_a, line_b, line_c = -line_a, -line_b, -line_c
    elif line_a == 0:
        if line_b < 0:
            line_b, line_c = -line_b, -line_c
    return line_a, line_b, line_c

def get_point_loc(line_equation: tuple[int, int, int], *, x_loc: int = None, y_loc: int = None) \
        -> [tuple[float, float] | None]:

    line_a, line_b, line_c = line_equation
    if y_loc is None and line_b != 0:
        return float(x_loc), -(line_a * x_loc + line_c) / line_b
    elif x_loc is None and line_a != 0:
        return -(line_b * y_loc + line_c) / line_a, float(y_loc)
    else:
        return None


