def count(x, lst, n):
    flag = x - 1
    distinct_numbers = set()
    count_cache = {}  # 缓存已经计算的结果
    while flag <= n - 1:
        if flag in count_cache:
            distinct_numbers.update(count_cache[flag])  # 直接取出缓存的结果
            break
        else:
            distinct_numbers.add(lst[flag])
            count_cache[flag] = distinct_numbers.copy()  # 缓存当前位置的结果
            flag += 1
    return len(distinct_numbers)

