def modulo(M):
    m = 1000000007
    for i in range(len(M)):
        for j in range(len(M[i])):
            M[i][j] %= m
    return M


def mult_M(M1, M2):
    Mr = deepcopy(M)
    for i in range(len(M)):
        for j in range(len(M[i])):
            Mr[i][j] = 0
            for k in range(len(M[i])):
                Mr[i][j] += M1[i][k] * M2[k][j]
    Mr = modulo(Mr)
    return Mr


def square_M(M1):
    return mult_M(M1, M1)


def pow_M(M1, power):
    s = int(sqrt(power))
    M2 = deepcopy(M1)
    for i in range(power - s*s):
        M2 = mult_M(M1, M2)
    return mult_M(pow_M(square_M(M1), s), M2)

