import sys
from collections import defaultdict, Counter
sys.setrecursionlimit(1000000000)


def dfs(u, graph, visited, colors, counter):
    visited[u] = True
    try:
        for v in list(graph[u].keys()):
            if not visited.get(v, False):
                colors[v] = not colors.get(u, False)
                counter[not colors.get(u, False)] += 1
                dfs(v, graph, visited, colors, counter)
    except:
        pass


def solver(graph, n):
    visited = dict()
    colors = dict()
    counter = Counter()
    for node in list(graph.keys()):
        if not visited.get(node, False):
            counter[True] += 1
            colors[node] = True
            dfs(node, graph, visited, colors, counter)

    # print(counter)
    return (counter[False]*counter[True])-(n-1)


def main():
    input = sys.stdin.readline
    n = int(input())
    graph = defaultdict(dict)
    for _ in range(n-1):
        u, v = map(int, input().split())
        graph[u][v] = 1
        graph[v][u] = 1

    print(solver(graph, n))


