def recurse(index, cur_indent, need_indent):
  global numbers;

  if(index >= len(numbers)):
    if(need_indent):
      return 0;
    else:
      return 1;
  #print(numbers[index], cur_indent, need_indent)

  sum = 0;
  if(numbers[index] == 's'):
    if(need_indent):
      sum += recurse(index + 1, cur_indent, need_indent - 1);
    else:
      sum += recurse(index + 1, cur_indent, need_indent);
  elif(numbers[index] == 'f'):
    for i in range(0, cur_indent):
      sum += recurse(index + 1, cur_indent, need_indent + 1 if(need_indent==0) else need_indent);
    sum += recurse(index + 1, cur_indent + 1, need_indent + 1);
  return sum;

