def query(pos,x,y,e,d):
  if e>=x and d<=y:
    return(segt[pos])
  elif d<x or e>y:
    return [0,0,0]
  else:
    mid=d+(e-d)//2
    de=query(pos*2,x,y,e,mid)
    dd=query(pos*2+1,x,y,mid+1,d)
    q=[0,0,0]
    q[0]=de[0]+dd[0]
    comum=0
    if de[1]<dd[2]:
      comum=de[1]
    else:
      comum=dd[2]
    
    q[0]+=comum
    q[1]=de[1]+dd[1]-comum
    q[2]=de[2]+dd[2]-comum
    return q




