import heapq as heap

def path(parent, n):
    li = []
    curr = n
    while(curr!=-1):
        li.append(curr)
        curr = parent[curr]
    li.reverse()
    return ' '.join(map(str, li))

def dijkstra(g, s, n):
    dis = [float('infinity') for i in range(n+1)]
    vis = dict()
    dis[s] = 0
    parent = {1:-1}
    q = [(0, s)]
    while len(q)> 0:
        _, x = heap.heappop(q)
        if x in vis:
            continue
        vis[x]=True
        for y, w in g[x].items():
            if dis[x] + w < dis[y]:
                heap.heappush(q, (dis[x]+w, y))
                dis[y] = dis[x] + w
                parent[y] = x
    if dis[n] == 'inf':
        return -1
    return path(parent, n)

