def possess_list(lst):
    l, r = 0, len(lst)
    if l > r - 1:
        return 0
    if l == r - 1:
        if lst[l] > 1:
            return possess_list([lst[l] // 2, lst[l] % 2, lst[l] // 2])
        else:
            return [lst[l]]
    mid = (l + r) // 2
    left_arr, right_arr = lst[l:mid], lst[mid:r]
    return possess_list(left_arr) + possess_list(right_arr)


def count_ones(lst, vl, vr):  # l-1:r
    ans: int = 0
    lst = possess_list(lst)
    if vr < vl or vl < 1: # r<l-1
        return 0
    for i in range(vl - 1, vr):
        if lst[i] == 1:
            ans += 1
    return ans


