class Solution:
    def clean_tree(self, graph: Dict[int, set]) -> None:
        queue = deque([(1, -1)])
        while queue:
            u, p = queue.popleft()
            graph[u].discard(p)
            for v in graph[u]:
                queue.append((v, u))

    def solve(self):
        n, k = Input.list(int)
        if k == 1: return n - 1
        graph = defaultdict(set)
        for _ in range(n - 1):
            u, v = Input.list(int)
            graph[u].add(v)
            graph[v].add(u)
        self.clean_tree(graph)

        @lru_cache(None)
        def dfs(i: int) -> Counter:
            counter = Counter([0])
            for j in graph[i]:
                sub = dfs(j)
                for key, val in sub.items():
                    if key >= k: continue
                    counter[key + 1] += val
            return counter

        def pass_through(i: int) -> int:
            acc = Counter()
            res = 0
            for j in graph[i]:
                sub = dfs(j)
                for key, val in sub.items():
                    res += acc[k - key - 2]
                for key, val in sub.items():
                    acc[key] += val
            return res

        res = 0
        for i in range(n):
            res += dfs(i)[k]
            res += pass_through(i)
        print(res)

    def main(self):
        self.solve()


