def prime(n):
    global ans
    res = []

    i = 2
    while i <= math.sqrt(n):
        if n % i == 0:
            res.append(i)
            n = n//i
        else:
            i+=1
    if n!=1:
        res.append(n)
    if len(set(res))==2:
        ans+=1


