def ans(n, k, s):
    p = s.index('G')
    t = s.index('T')
    if p > t:
        s = list(reversed(s))
        p, t = t, p

    while True:
        if s[p + k] == '#' or p + k > t:
            return False
        if s[p + k] == 'T':
            return True
        p += k


def process_file(in_name, out_name):
    with open(in_name, 'r') as fin:
        with open(out_name, 'w') as fout:
            def read():
                return fin.readline().rstrip('\n')

            def write(*args, end='\n'):
                text = ' '.join(map(str, args)) + end
                fout.write(text)
                print(text, end='')

            t = int(fin.readline())
            for i in range(t):
                read()
                write('Case #{T}: \n'.format(T=i + 1), end='')
                solve(read, write)
                write()


