def getSumOfColumn(array) :
    length = len(array)
    mid = int((length-1)/2)
    tot = 0
    for i in range(length) :
        if i != mid :
            tot += array[i][mid]
    return tot
def getDiagonals(array,reverse=False) :
    length = len(array)
    tot = 0
    if reverse == False :
        for i in range(length) :
            if length%2!=0 :
                if i != int((length-1)/2) :
                    tot += array[i][i]
            else :
                tot += array[i][i]
    else :
        i=0
        j=length
        for i in range(length) :
            if length%2!=0 :
                if i != length-i-1 :
                    tot+=array[i][length-i-1]
            else :
                tot += array[i][length-i-1]
    return tot
