def can_form_names(guest_name, host_name, pile_letters):
    # Count the occurrences of each letter in the guest's name
    guest_counts = {}
    for letter in guest_name:
        guest_counts[letter] = guest_counts.get(letter, 0) + 1

    # Count the occurrences of each letter in the host's name
    host_counts = {}
    for letter in host_name:
        host_counts[letter] = host_counts.get(letter, 0) + 1

    # Count the occurrences of each letter in the pile
    pile_counts = {}
    for letter in pile_letters:
        pile_counts[letter] = pile_counts.get(letter, 0) + 1

    # Check if all letters in the guest's name are present in the pile with the correct count
    for letter, count in guest_counts.items():
        if letter not in pile_counts or pile_counts[letter] < count:
            return False

    # Check if all letters in the host's name are present in the pile with the correct count
    for letter, count in host_counts.items():
        if letter not in pile_counts or pile_counts[letter] < count:
            return False

    # Check if there are no extra letters in the pile that are not needed to form the names
    for letter, count in pile_counts.items():
        if letter not in guest_counts and letter not in host_counts:
            return False

    return True

