def graph_dict(edges):
    graph = {}
    for start,end in edges:
        if start not in graph:
            graph[start] = [end]
        else:
            graph[start].append(end)
        if end not in graph:
            graph[end] = [start]
        else:
            graph[end].append(start)
    return graph

def get_paths(graph,start,end,path = []):
    path = path+ [start]
    
    if start==end:
        return path
    paths = []
    
    for node in graph[start]:
        if node not in path:
            new_paths = get_paths(graph,node,end,path)
            for p in new_paths:
                paths.append(p)
                
    return paths
