enum = enumerate

def dijkstra(n, es, ws):

  g = {}

  # remove multi-edges
  for i, e in enum(es):
    if e in g:
      g[e] = min(g[e], ws[i])
    else:
      g[e] = ws[i]

  # store neighbors
  nbrs = defaultdict(set)

  for i, e in enum(es):
    v, to = e
    nbrs[v].add(to)
    nbrs[to].add(v)

  vs = list(range(1, n + 1))
  ps = {}
  ds = {i: float('inf') for i in vs[1: ]}
  ds[1] = 0  
  marked = {i : False for i in vs}

  next_v_to_explore = []
  for i in vs:
    heappush(next_v_to_explore, (ds[i], i))

  while(next_v_to_explore):
    _, v = heappop(next_v_to_explore)    
    if marked[v]:
      continue
    # print('vertex being explored is', v)
    for vv in nbrs[v]:
      # print('edge being considered is', (v, vv))
      if (v, vv) in g:
        w = g[(v, vv)]
      else:
        w = g[(vv, v)]

      if ds[vv] > ds[v] + w:
        ds[vv] = ds[v] + w
        ps[v] = vv
        heappush(next_v_to_explore, (ds[vv], vv))
        # print('graph updated, new graph is now', ds)
        # print('graph updated, path is now', ps)
        if vv == n:
          break
    marked[v] = True

  # print(g)
  # print(ds)

  if ds[n] == float('inf'):
    print(-1)
  else:
    # print(ds)
    # print(ps)
    path = []
    i = 1
    while i != n:
      path.append(i)
      i = ps[i]
    path.append(n)

    print(' '.join(str(i) for i in path))

