def replace(mat, n, m):
    mat[0][0] = 1
    mat[0][1] = 2
    for j in range(0, 2 * n):
        if j != 0:
            if j % 2 == 0:
                mat[0][j] = mat[0][j - 1] + (n + 1)
            else:
                mat[0][j] = mat[0][j - 1] + 1
    for i in range(1, m):
        for j in range(0, 2 * n):
            mat[i][j] = mat[i][j] + mat[i - 1][j] + 2

    return mat


