def solve(n: int, k: int, arr) -> int:
    if n <= k:
        return sum(arr)
    cur, res, idx = sum(arr[:k]), sum(arr[:k]), 0
    for i in range(k, n):
        cur = cur + arr[i] - arr[i - k]
        if cur < res:
            idx = i - k + 1
            res = cur
    return idx + 1


