from queue import Queue

def addEdge(s, t, flow):
    E[s].append((s,t,flow))
    E[t].append((t,s,0))

def mkLevel():
    global src, des, E, lvl
    for i in range(n):
        lvl[i] = -1
    lvl[src] = 0
    
    q = Queue()
    q.put(src)
    while (not q.empty()):
        cur = q.get()
        for j in range(len(E[cur])):
            to = E[cur][j][1]
            if (lvl[to] < 0 and E[cur][j][2] > 0):
                lvl[to] = lvl[cur] + 1
                q.put(to)
                if (to == des):
                    return True
    return False

def extend(cur, lim):
    global des, E
    if (lim == 0 or cur == des):
        return lim
    flow = 0
    for j in range(len(E[cur])):
        if (flow >= lim):
            break
        to = E[cur][j][1]
        lim0 = min(lim-flow, E[cur][j][2])
        if (E[cur][j][2] > 0 and lvl[to] == lvl[cur] + 1):
            newf = extend(to, lim0)
            if (newf > 0):
                E[cur][j] = (E[cur][j][0], E[cur][j][1], E[cur][j][2] - newf)
                E[to][j]  = (E[to][j][0],  E[to][j][1],  E[to][j][2] + newf)
                flow += newf
    if (flow == 0):
        lvl[cur] = -1
    return flow

def Dinic():
    flow = 0
    newf = 0
    while (mkLevel()):
        newf = extend(src, INF)
        while (newf > 0):
            flow += newf
            newf = extend(src, INF)
    return flow

