import heapq
from collections import namedtuple

INF = 10 ** 17

Path = namedtuple('Path', ['cost', 'node_to', 'prev'])


class Edge:
    def __init__(self, node_from, node_to, cost):
        self.node_from = node_from
        self.node_to = node_to
        self.cost = cost


class Node:
    def __init__(self, node_number):
        self.node_number = node_number
        self.edges_list = []

    def add_neighbour(self, other, cost):
        self.edges_list.append(Edge(self, other, cost))


class PathHistory:
    def __init__(self, start_node, history):
        self.start_node = start_node
        self.history = history

    def construct(self, node_to):
        path = [node_to]
        prev = self.history.get(node_to)

        if node_to == self.start_node:
            return path

        if prev is None:
            # raise Exception('Path between {} and {} does not exist'.format(self.start_node, node_to))
            return -1

        while prev is not None:
            path.append(prev)
            prev = self.history.get(prev)

        return path[::-1]


class Graph:
    def __init__(self, n):
        self.n = n
        self.nodes = {}
        for i in range(n):
            node_number = i+1
            self.nodes[node_number] = Node(node_number)

    def add_edge(self, v1, v2, cost):
        self.nodes[v1].add_neighbour(v2, cost)

    def dijkstra(self, node_number):
        distances = {i+1: INF for i in range(self.n)}
        distances[node_number] = 0
        previous = {node_number: None}
        queue = []
        visited = {node_number}

        for edge in self.nodes[node_number].edges_list:
            queue.append(Path(edge.cost, edge.node_to, node_number))
        heapq.heapify(queue)

        while True:
            top = None
            while len(queue) > 0:
                top = heapq.heappop(queue)
                if top.node_to not in visited:
                    break
            if top is None or top.node_to in visited:
                break
            distances[top.node_to] = top.cost
            previous[top.node_to] = top.prev
            visited.add(top.node_to)

            for edge in self.nodes[top.node_to].edges_list:
                if edge.node_to not in visited:
                    heapq.heappush(queue, Path(top.cost + edge.cost,
                                               edge.node_to,
                                               top.node_to))

        return distances, PathHistory(node_number, previous)


def read():
    return [int(v) for v in input().split()]


def read_graph():
    n, m = read()
    g = Graph(n)
    for _ in range(m):
        v1, v2, cost = read()
        g.add_edge(v1, v2, cost)
        g.add_edge(v2, v1, cost)
    return g


def main():
    g = read_graph()
    distances, path_history = g.dijkstra(1)
    for v in path_history.construct(g.n):
        print(v, end=' ')


