import sys


def calculate_move(move, current_coordinates, grid):
    number_of_took_steps = 0
    rows, columns = grid
    x, y = current_coordinates
    dx, dy = move

    while (
        (x + dx <= rows and x + dx >= 1) 
        and (y + dy <= columns and y + dy >= 1)
    ):
        x += dx
        y += dy
        number_of_took_steps += 1

    return (number_of_took_steps, (x, y))


def calculate_total_number_of_steps():
    grid = tuple(map(int, sys.stdin.readline().strip().split()))
    current_coordinates = tuple(map(int, sys.stdin.readline().strip().split()))
    number_of_vectors = int(sys.stdin.readline().strip())
    moves = [
        tuple(map(int, sys.stdin.readline().strip().split()))
        for _ in range(number_of_vectors)
    ]
    number_of_steps = 0

    for move in moves:
        steps, current_coordinates = calculate_move(
            move,
            current_coordinates,
            grid
        )
        number_of_steps += steps

    return number_of_steps


if __name__ == '__main__':
    print(calculate_total_number_of_steps())

