from collections import defaultdict


def make_tree(graph, root):
    tree = defaultdict(set)

    def _make(v):
        for child in graph[v]:
            if child not in tree:
                tree[v].add(child)
                _make(child)

    _make(root)
    return tree


def traverse(tree, y, x, N):
    X = 0
    Y = 0

    def routine(v, x_found):
        nonlocal X, Y
        if v == x:
            x_found = True
        if x_found:
            X += 1

        findings=[x_found]
        for child in tree[v]:
            findings.append(routine(child, x_found))
        x_found = any(findings)
        if v==y or not x_found:
            Y+=1
        return any(findings)

    routine(y, False)
    return N * (N-1) - X*Y

