def lcm(a, b, c):
    m = a * b
    while a != 0 and b != 0:
        if a > b:
            a %= b
        else:
            b %= a
    b = m // (a + b)
    m = b * c
    while c != 0 and b != 0:
        if c > b:
            c %= b
        else:
            b %= c
    return m // (c + b)


