import sys
from collections import Counter

c_counts = {"n": 3, "i": 1, "e": 3, "t": 1}


def count_nineteens(s):
    min_possible = sys.maxsize
    s_c_counts = Counter(s)
    for c, count in c_counts.items():
        possible = s_c_counts[c] // c_counts[c]
        min_possible = min(min_possible, possible)

    if min_possible == sys.maxsize:
        return 0

    return min_possible


def main():
    s = input()
    print(count_nineteens(s))


