def binpow(a, deg):
    if deg == 0:
        return 1
    if deg == 1:
        return a
    x = binpow(a, deg // 2)
    if deg % 2 == 0:
        return x * x
    return x * x * a


def gval1(s):
    global k, b, deg
    if k == 1:
        return 1 + b * s
    return binpow(k, s) + b * (binpow(k, s) - 1) // (k - 1)

def gval2(s):
    global k, b, t, deg
    if k == 1:
        return t + b * s
    return t * (binpow(k, s)) + b * (binpow(k, s) - 1) // (k - 1)

