def prime(n):
    if(n<2):
        return 0
    
    for i in range(2,n//2+1):
        if(n%i==0):
            return 0

    return 1

def pgcd(a,b):
    if a<b:
        a,b=b,a
    while b!=0:
        a,b=b,a%b
    return a


def ppcm(a,b):
    return (a*b//pgcd(a,b))

def setU(n):
    i=n+1
    while not prime(i):
        i+=1

    return i

def setV(n):
    i=n

    while not prime(i):
        i-=1
    
    return i

