    directions = [(0,1),(0,-1),(1,0),(-1,0)]

    def inbound(r,c):
        return 0 <= r < n and 0 <= c < m
    memo = defaultdict(int)
    def dfs(r,c):
        
        ans = 0
        
        if not memo[(r,c)]:
            for x,y in directions:
                R = r + x
                C = c + y

                if inbound(R,C) and (R,C) not in memo and maze[R][C] == ".":
                    ans += dfs(R,C)
            if maze[r][c] == ".":
                ans += 1
            memo[(r,c)] = ans
        return memo[(r,c)]

    ans = maze.copy()
    for r in range(n):
        for c in range(m):
            if maze[r][c] == "*":
                memo = defaultdict(int)
                ans[r][c] = dfs(r,c) + 1

    for i in range(n):
        for val in ans[i]:
            print(val,end="")
        print()
        
