def dominoes(m, n):
  """
  Finds the maximum number of dominoes that can be placed on a rectangular board of size m * n.

  Args:
    m: The width of the board.
    n: The height of the board.

  Returns:
    The maximum number of dominoes that can be placed on the board.
  """

  if m < n:
    m, n = n, m

  count = 0
  for i in range(m):
    for j in range(n):
      if (i + j) % 2 == 0:
        count += 1

  return count


