dp = [[-1 for _ in range(2001)]for _ in range(2000)]
MOD = int(1e9+7)
def dfs(number , i , remainer , d , m ,limit , res = 0):
    if i==-1:
        return remainer == 0

    if not limit and dp[i][remainer] != -1:
        return dp[i][remainer]

    lower = 1 if len(number) == i+1 else 0
    upper = number[i] if limit else 9
    if i%2==len(number)%2 :
        if lower<=d<=upper:
            res += dfs(number,i-1 , (remainer*10+d)%m , d , m , limit and d==upper)
        else:
            res += 0
    else:
        for x in range(lower, upper+1):
            if x==d:
                continue
            res += dfs(number,i-1 , (remainer*10+x)%m , d , m , limit and x==upper)
    res %= MOD
    if not limit:
        dp[i][remainer] = res
    return res

def solve(n,d,m):
    number = [int(i) for i in list(n)]
    number.reverse()
    res = dfs(number,len(number)-1,0,d,m,True,0)
    return res
        
