def main():
    n = int(input())
    data = list(map(int, input().split()))
    cache = defaultdict(list)
    for i, x in enumerate(data):
        cache[x].append(i)

    erase = set()
    for key, value in cache.items():
        if value[1] - value[0] == 1:
            erase.add(key)

    for key in erase:
        del cache[key]

    result = 0

    while cache:
        min_dist = float('inf')
        best_x = 0

        for key, value in cache.items():
            d = value[1] - value[0]
            if d < min_dist:
                min_dist = d
                best_x = key

        (data[cache[best_x][1]],
         data[cache[best_x][1] - 1]) = (data[cache[best_x][1] - 1],
                                        data[cache[best_x][1]])
        neighbor = cache[best_x][1]
        neighbor_x = data[neighbor]
        if neighbor_x in cache:
            if cache[neighbor_x][0] == neighbor - 1:
                cache[neighbor_x][0] += 1
            else:
                cache[neighbor_x][1] += 1
            if cache[neighbor_x][1] - cache[neighbor_x][0] == 1:
                del cache[neighbor_x]
        cache[best_x][1] -= 1
        result += 1

        if cache[best_x][1] - cache[best_x][0] == 1:
