import sys
from collections import defaultdict


def dfs(start, graph):
	visited = []
	queue = [start]
	steps = 1
	while len(queue) != 0:
		s = queue.pop()
		if s not in visited:
			visited.append(s)
		for node in graph[s]:
			if node == start and steps >= 3:
				if len(graph[s]) == 2:
					return visited, True
				return visited, False
			if node not in visited:
				queue.append(node)
		steps += 1
	return visited, False


