    l = -1
    tmp = a-2
    while(tmp>=0):
        if start!=s[tmp]:
            l = tmp
            break
        tmp = tmp-1

    r = -1
    tmp = a
    while(tmp<len(s)):
        if start!=s[tmp]:
            r = tmp
            break
        tmp = tmp+1
    return[a-l-1,r-a+1]

