def make_sets(s):
  comeco = True
  final = True

  result_set = set()
  open = []
  close = []
  for i in range(len(s)):
    ra = True
    ta = True
    if(s[i]==')' and comeco):
      ra = False
    if(s[i]==')' and final):
      ta = False

    if(ra):
      if s[i]=='(':
        comeco = False
        open.append(i)
      elif(len(open)>0):
        result_set.add((open.pop()+1,i+1))
    if(ta):
      if s[i]==')':
        final = False
        close.append(len(s)-i)
      elif(len(close)>0):
        result_set.add((i+1,close.pop()+1))

  return result_set
