def binary_search(arr, i, start, end):
    mid = start + (end - start) // 2
    if end >= start:
        if arr[mid] == i:
            return True
        elif i < arr[mid]:
            return binary_search(arr, i, start, mid - 1)
        else:
            return binary_search(arr, i, mid + 1, end)
    return False


