def algorithm(current, cost, time):
    if current == n - 1:
        return cost
    value = a[current]
    a[current] = -1
    x = stations[current][0]
    y = stations[current][1]
    less = -1
    for i in range(1, n):
        if a[i] > -1:
            difference = d * (abs(x - stations[i][0]) + abs(y - stations[i][1])) - (time + value)
            current_less = algorithm(i, cost + difference, 0) if difference > 0 \
                else algorithm(i, cost, time - difference)
            if (less == -1 or less > current_less) and current_less > -1:
                less = current_less
    a[current] = value
    return less


