def can_restore_names(guest_name, host_name, pile_letters):
    from collections import Counter

    # Count the occurrences of each letter in the guest's name and host's name
    guest_counter = Counter(guest_name)
    host_counter = Counter(host_name)

    # Count the occurrences of each letter in the pile of letters
    pile_counter = Counter(pile_letters)

    # Check if the pile contains the correct number of letters for both names
    for letter, count in guest_counter.items():
        if pile_counter[letter] < count:
            return False

    for letter, count in host_counter.items():
        if pile_counter[letter] < count:
            return False

    # Check if there are no extra letters in the pile
    for letter, count in pile_counter.items():
        if letter not in guest_counter and letter not in host_counter:
            return False

    return True


