def solve() -> None:
    n, x, y = next_ints()
    mn, mx = inf, -inf
    for _ in range(n):
        t_x, t_y = next_ints()
        mn = min(mn, dis((x, y), (t_x, t_y)))
        mx = max(mx, dis((x, y), (t_x, t_y)))
    print(pi * (mx - mn))

