import sys,math
def power(x, y, p): 
    res = 1; # Initialize result 
  
    # Update x if it is  
    # more than or equal to p 
    x = x % p;  
  
    while (y > 0):  
          
        # If y is odd, multiply 
        # x with the result 
        if (y & 1): 
            res = (res * x) % p; 
  
        # y must be even now 
        y = y >> 1; # y = y/2 
        x = (x * x) % p; 
          
    return res; 
def modInverse(b,m): 
	g = math.gcd(b, m) 
	if (g != 1): 
		# print("Inverse doesn't exist") 
		return -1
	else: 
		# If b and m are relatively prime, 
		# then modulo inverse is b^(m-2) mode m 
		return pow(b, m - 2, m) 
 
 
# Function to compute a/b under modulo m 
def modDivide(a,b,m): 
	a = a % m 
	inv = modInverse(b,m) 
	if(inv == -1): 
		print("Division not defined") 
	else: 
		return (inv*a) % m    
