def bin_search(songs, query):
    left = 0
    right = len(songs) - 1
    m = (left + right) // 2
    while left <= right:
        m = (left + right) // 2
        if songs[m][0] < query <= songs[m][1]:
            return m + 1
        if query > songs[m][1]:
            left = m + 1
        else:
            right = m - 1
    return m + 1


