def allocCmd(memory, id, size):
    cnt = 0
    ind = 0
    for i in range(len(memory)):
        if memory[i] == '0':
            if cnt == 0:
                ind = i
            cnt += 1
        else:
            cnt = 0
            ind = 0
        if cnt == size:
            break

    if (cnt < size):
        return "NULL"
    pos = ind
    while pos != ind + size:
        memory[pos] = str(id)
        pos += 1

    return memory

def eraseCmd(memory, id, size):
    cnt = 0
    ind = 0
    for i in range(len(memory)):
        if memory[i] == str(id):
            if cnt == 0:
                ind = i
            cnt += 1
        else:
            cnt = 0
            ind = 0
        if cnt == size:
            break

    if (cnt < size):
        return "ILLEGAL_ERASE_ARGUMENT"
    pos = ind
    while pos != ind + size:
        memory[pos] = "0"
        pos += 1

    return memory

def defragmentCmd(manager, memorySize):
    keys = manager.keys()
    d = []
    for k in keys:
        size = manager[k]
        for i in range(size):
            d.append(str(k))
    while len(d) < memorySize:
        d.append('0')
    return d

