def main(n, s):
    def good():
        nonlocal s, n
        for i in range(0, n - 1):
            if s[i] == s[i + 1]:
                return False
        return True
    def num(t):
        nonlocal s
        ret = 0
        for c in s:
            if c == t:
                ret += 1
        return ret
    def swap():
        nonlocal s, n
        for i in range(0, n - 3):
            if s[i] == s[i + 1] and s[i + 2] == s[i + 3]:
                temp = s[i + 1]
                s[i + 1] = s[i + 2]
                s[i + 2] = temp
                return
    def paint():
        nonlocal s, n
        for i in range(0, n - 1):
            if s[i] == s[i + 1] and s[i + 1] == s[i + 2]:
                if s[i + 1] == 'r':
                    s[i + 1] = 'b'
                else:
                    s[i + 1] = 'r'
                return

    ans = 0
    while not good():
        if abs(num('b') - num('r')) > 1:
            paint()
        else:
            swap()
        ans += 1
    return ans

