def build(curr,l,r):
    if l>r:
        return 
    if l == r:
        tree[curr] = [a[l]]
        return
    mid = (l+r)//2
    build(2*curr+1,l,mid)
    build(2*curr+2,mid+1,r)
    tree[curr] = sorted(tree[2*curr+1]+tree[2*curr+2])
    
build(0,0,n-1)

def query1(curr,x,l,r,ql,qr):
    
    if ql<=l and qr>=r:
        nums = bisect.bisect_left(tree[curr],x)
        return nums
    if ql>r or qr<l:
        return 0
    mid = (l+r)//2
    return query1(2*curr+1,x,l,mid,ql,qr)+query1(2*curr+2,x,mid+1,r,ql,qr)  
    
def query2(curr,x,l,r,ql,qr):
    
    if ql<=l and qr>=r:
        nums = len(tree[curr])-bisect.bisect_right(tree[curr],x)
        return nums
    if ql>r or qr<l:
        return 0
    mid = (l+r)//2
    return query2(2*curr+1,x,l,mid,ql,qr)+query2(2*curr+2,x,mid+1,r,ql,qr)
