def solve(arr,n):
    end = n-1
    start = 0
    for i in range(n-1,-1,-1):
        if arr[i]:
            break
        end -= 1
    for i in range(end):
        if arr[i]:
            break
        start += 1

    arr = arr[start:end+1]
    if not len(arr):
        return 0
    if len(arr) == 1 :
        return arr[0]
    if len(arr) == 2 :
        return arr[0] or arr[1]
    last_val = arr[0]
    count = 2
    for i in range(1,len(arr)-1):
        if (not arr[i] and not last_val) or (not arr[i] and not arr[i+1]):
            last_val = arr[i]
            continue
        else:
            count += 1
        last_val = arr[i]
    return count





