BRACKETS = [ 
    ('<', '>'),
    ('{', '}'),
    ('[', ']'),
    ('(', ')'),
]

IMPOSSIBLE = 'Impossible'

def is_opening(w):
    return w in [b[0] for b in BRACKETS]

def same_kind(w1, w2):
    return (w1, w2) in BRACKETS

def solve(word):
    temp = []
    result = 0 
    for w in word:
        if is_opening(w):
            temp.append(w)
        else:
            if len(temp) == 0:
                return IMPOSSIBLE
            wo = temp.pop()
            if not is_opening(wo):
                return IMPOSSIBLE
            if not same_kind(wo, w):
                result += 1
    if len(temp) != 0:
        return IMPOSSIBLE
    return result
                
