class Node:
    def __init__(self, id):
        self.friends = {}
        self.id = id
        self.color = None

    def add(self, node):
        self.friends[node.id] = node

    def dfs(self, color):
        self.color = color
        for i in self.friends:
            fr = self.friends[i]
            # Si no esta pintado
            if fr.color == None:
                fr.dfs(color)

def search_groups(nodes):
    color = 0
    # Itero sobre los nodos
    for node in nodes:
        # Si el nodo no tiene color, hago dfs asignando el color
        if node.color == None:
            node.dfs(color)
            color += 1
    return color

def check(nodes, col):

    color_count = [0 for i in range(col)]

    for node in nodes:
        color_count[node.color] += 1

    for node in nodes:
        if len(node.friends) < color_count[node.color] - 1:
            return "NO"
        elif len(node.friends) > color_count[node.color] - 1:
            raise "ERROR"
    return "YES"

