def isAmazing(score_index, l_scores):
    amazing = False
    less, great = 0, 0
    for i in l_scores[0:score_index]:
        if l_scores[score_index] < i:
            less += 1
        if l_scores[score_index] > i:
            great += 1
    if less == score_index or great == score_index:
