def sumTastes(combi):
    sumT = 0
    for i in combi:
        sumT += tastes[i]
    sumTsurK = sumT/k
    sumC = 0
    for i in combi:
        sumC += calories[i]
        if(sumC > sumTsurK):
            return -1
    if(sumT == k*sumC):
        return sumT
    else:
        return -1 

