def min_strokes(n, planks):
    if n == 0:
        return 0
    min_plank = min(planks)
    segments = []
    current_segment = []

    for i in range(n):
        if planks[i] == min_plank:
            if current_segment:
                segments.append(current_segment)
                current_segment = []
        else:
            current_segment.append(planks[i] - min_plank)

    if current_segment:
        segments.append(current_segment)

    segment_strokes = sum(min_strokes(len(segment), segment) for segment in segments)
    return min(n, min_plank + segment_strokes)

