from collections import defaultdict
import heapq

class WeightedGraph():
    def __init__(self, n):
        self.adj_list = defaultdict(list)
        self.weights = dict()
        self.V = n
        self.E = 0

    def add_edge(self, u, v, weight):
        self.adj_list[u].append(v)
        self.adj_list[v].append(u)
        self.weights[(u, v)] = weight
        self.weights[(v, u)] = weight
        self.E += 1

    def weight(self, u, v):
        return self.weights[(u, v)]

    def neighbors(self, v):
        return self.adj_list[v]

    def dijkstra(self, u, v):
        S = set()
        mh = [(0, u)]
        d = [float('inf') for x in range(self.V)]
        d[u] = 0

        prev_node = dict()
        while len(mh) > 0:
            cost, node = heapq.heappop(mh)
            if not node in S:
                S.add(node)

                if node == v:
                    return cost, prev_node

                for w in self.adj_list[node]:
                    if d[w] > self.weight(node, w) + cost:
                        prev_node[w] = node
                        d[w] = self.weight(node, w) + cost
                        item = (self.weight(node, w) + cost, w)
                        heapq.heappush(mh, item)


        return None



    def find_reachable(self, v, depth_limit):
        if self.E == 0:
            return 1

        _, x = self._reachable(v, 0, depth_limit, [False] * (self.V + 1))
        return x

    def _reachable(self, v, depth, depth_limit, visited):
        visited[v] = True
        ctr = 1
        for n in self.neighbors(v):
            if not visited[n]:
                if depth < depth_limit:
                    visited, _ctr = self._reachable(n, depth + 1, depth_limit, visited)
                    ctr += _ctr

        return visited, ctr

    def dfs(self, v, visited):
        """
        Mark all reachable nodes as visited
        """
        visited[v] = True
        for n in self.neighbors(v):
            if not visited[n]:
                visited[n] = True
                visited = self.dfs(n, visited)

        return visited

    def find_connected_components(self):
        if self.E == 0:
            return self.V
        num_vertices = self.V
        visited = [False] * (num_vertices + 1)
        components = 0
        for v in range(1, num_vertices + 1):
            if not visited[v]:
                visited = self.dfs(v, visited)
                components += 1

        return components
