# Generic Comparable Class
from functools import total_ordering
@total_ordering
class Comparable(object):
    def _compare(self, other, method):
        try: return method(self._cmpkey(), other._cmpkey())
        except (AttributeError, TypeError): return NotImplemented
    def __lt__(self, other):
        return self._compare(other, lambda s, o: s < o)
    def __eq__(self, other):
        return self._compare(other, lambda s, o: s == o)

# Graph classes & utilities
from heapq import heapify, heappush, heappop
from typing import List
MAX = 2**31
class Node(Comparable):
    def __init__(self, id):
        self.id = id
        self.cost = MAX
        self.edges = []
        heapify(self.edges)
        self.vis = False
        self.prev = None
    def _cmpkey(self):
        return self.cost, self.id
    def addEdge(self, edge):
        heappush(self.edges, edge)

class Edge(Comparable):
    def __init__(self, dest, weight):
        self.dest = dest
        self.weight = weight
    def _cmpkey(self):
        return self.weight

def dijkstra(nodes: List[Node], start: Node, end: Node = None):
    start.cost = 0
    pq = [start]
    heapify([start])
    while pq:
        node = heappop(pq)
        if node.vis: continue
        node.vis = True
        if end is not None and node == end: return
        for edge in node.edges:
            newCost = node.cost + edge.weight
            if edge.dest.cost > newCost:
                edge.dest.cost = newCost
                edge.dest.prev = node
                heappush(pq, edge.dest)

def findPath(end: Node):
    path = []
    temp = end
    while temp:
        path.append(temp)
        temp = temp.prev
    path.reverse()
    return path

