class Graphs:
    def __init__(self):
        self.graph = collections.defaultdict(list)
    def add_edge(self, m):
        for _ in range(m):
            u,v=[int(i)-1 for i in input().split()]
            
            self.graph[u].append(v)
            self.graph[v].append(u)

    def count_dis(self,k,n):
        dp = [[0] * (k + 1) for _ in range(n)]
        @bootstrap
        def dfs(i, fa):
            dp[i][0] = 1
            for j in self.graph[i]:
                if j != fa:
                    yield dfs(j, i)
                    for s in range(1, k + 1):
                        dp[i][s] += dp[j][s - 1]
            yield
        dfs(0, -1)

        return dp


    
    
    def count_num(self,n,dp,k):
        res=0
        visit=[False]*n
        def dfs(root):
            nonlocal res
            visit[root]=True
            tmp=0
            res+=dp[root][-1]
            for child in self.graph[root]:
                
                
                if not visit[child]:
                    dfs(child)
                    for x in range(1, k ):
                        tmp+=dp[child][x-1]*(dp[root][k-x]-dp[child][k-x-1])
            res+=tmp//2
        dfs(0)
        return res
                    


