def Precedence_Order(opd):
    if opd == '+':
        return 1
    elif opd == "-":
        return 2
    elif opd == "*":
        return 3
    else:
        return 0

def Operation(num1, num2, opd):

    if opd == '+':
        return str(num1) + str(num2)
