def main():
    from collections import defaultdict
    import errno, sys

    n, m = map(int, input().split())
    n += 1
    gg = list(range(n))
    ab = [[] for _ in range(n)]

    def root(x):
        while x != gg[x]:
            x = gg[x]
        return x

    def setroot(x, r):
        stack = [x]
        while x != gg[x]:
            x = gg[x]
            stack.append(x)
        for x in stack:
            gg[x] = r

    for _ in range(m):
        a, b = map(int, input().split())
        ab[a].append(b)
        u, v = root(a), root(b)
        if u < v:
            setroot(b, u)
        elif u > v:
            setroot(a, v)
    for a in range(n):
        gg[a] = root(a)

    groups = defaultdict(list)
    for a, b in enumerate(gg):
        groups[b].append(a)
    clr = [0] * n

    def dfs(x):
        if ab[x]:
            clr[x] = 1
            for child in ab[x]:
                cl = clr[child]
                if not cl:
                    dfs(child)
                elif cl == 1:
                    raise TabError
        clr[x] = 2

    res = 0
    for l in groups.values():
        le = len(l) - 1
        if le:
            res += le
            try:
                for a in l:
                    if not clr[a]:
                        dfs(a)
            except TabError:
                res += 1
    print(res)


