def binary_search(alist,N,item):
    '''寻找小于等于item的第一个数的索引'''
    first = 0
    last = N-1
    while first<=last:
        midpoint = (first + last)//2
        if alist[midpoint] == item:
            return midpoint
        elif item < alist[midpoint]:
            if alist[midpoint-1]<=item:
                return midpoint-1
            last = midpoint-1
        else:
            if alist[midpoint+1]>item:
                return midpoint
            first = midpoint+1
