class Tree:
    class Node:
        __slots__ = '_range_','_left_','_right_','_value_'
        def __init__(self,range,left,right,value = None):
            self._right_ = right
            self._range_ = range 
            self._left_ = left 
            self._value_ = value
    def __init__(self,N):
        self.N = N
        self.tree = self.make_tree(1,N)
    def make_tree(self,l,r):
        if l == r:
            c = self.Node((l,r),None,None,None)
            return(c)
        else:
            size = (r-l+1)//2
            left  = self.make_tree(l,l + size -1)
            right = self.make_tree(l + size,r)
            c = self.Node((l,r),left,right,None)
            return(c)    
    def make_query(self,l,r,x,tree):
        # print(l,r,x,"anjiichid")
        ra = tree._range_
        # print(ra)
        # print(l,r,ra,tree._value_)
        if tree._value_ == None:
            if l <= ra[0] and r >= ra[1]:
                tree._value_ = x
                # print(l,r,ra,tree._value_,"amiket")
                return
            elif l > ra[1] or r < ra[0]:
                # print(l,r,ra,tree._value_,"am")
                return
            else:
                self.make_query(l,r,x,tree._left_)
                self.make_query(l,r,x,tree._right_)
                # print(l,r,ra,tree._value_,"t")
                return
        elif tree._value_ >= tree._range_[0] and tree._value_ <= tree._range_[1] and ((ra[1] >= l and ra[0] <= l) or (ra[0] <= r and ra[1] >= l)):
            k = int(tree._value_)
            # print(k,x,"ijixs")
            p = tree
            if p._right_ == None:
                if k == p._range_[0]:
                    p._value_ = x
                return
            while True:
                # print(p._right_._value_,p._right_._range_) 
                # print(p._left_._value_,p._left_._range_) 
                rar = p._right_._range_
                ral = p._left_._range_
                # print(p,k,rar,ral)
                if rar[0] == rar[1] == k:
                    if p._right_._value_ == None:
                        p._right_._value_ = x
                        # print(p._right_._value_,p._right_._range_) 
                    break
                elif rar[0]  <= k and rar[1] >= k:
                    p = p._right_
                elif ral[0] == ral[1] == k:
                    if p._left_._value_ == None:
                        p._left_._value_ = x
                        # print(p._left_._value_,p._left_._range_) 
                    break
                else:
                    p = p._left_  
                                
        else:
            return  
    def answer_query(self,q,tree):
        ma = tree._value_
        p = tree
        while p._right_ != None:
            rar = p._right_._range_
            ral = p._left_._range_            
            if rar[0]  <= q and rar[1] >= q:
                op = p._right_._value_
                if op != None and op != q:
                    ma = op
                p = p._right_
            else:
                op = p._left_._value_
                if op != None and op != q:
                    ma = op
                p = p._left_
        return(ma)                    
            






