def find_nearby(array, n, x):

    if x <= array[0]:
        return array[0]
    if x >= array[len(array)-1]:
        return array[len(array)-1]
    
    left = 0; right = n; mid = 0
    while ( left < right):
        mid = ( left + right ) // 2

        if array[mid] == x:
            return array[mid]
        
        if x < array[mid]:
            if (mid > 0 and x > array[mid - 1]):
                return find_closer(array[mid - 1], array[mid], x)
 
            right = mid
        if x > array[mid]:
            if (mid < n - 1 and x < array[mid + 1]):
                return find_closer(array[mid], array[mid + 1], x)
                 
            left = mid + 1
    
    return array[mid]

def find_closer(a,b,x):
    if ( abs(x-a) >= abs(x-b) ):
        return b
    else:
        return a

