import math

def num_to_binary(n):
    ret = []
    while n != 0:
        ret.append(n % 2)
        n //= 2
    return list(reversed(ret))


def solve(start, target):
    if target <= start:
        p2 = 0
    else:
        p2 = math.ceil(math.log2(target / start))

    cur = start * 2**p2
    count = p2

    excess = cur - target
    count += excess >> p2 + sum(num_to_binary(excess % (2**p2)))

    return count


def str_to_list_numbers(s):
    return [int(ds) for ds in s.split()]


def main():
    n, m = str_to_list_numbers(input())
    print(solve(n, m))


