import sys
from collections import defaultdict

input = sys.stdin.readline

def bipart(graph, n):
    visited = [False]*(n+1)
    index = [0]*(n+1)
    u = set()
    v = set()

    for i in range(1,n+1):
        if not visited[i]:
            if len(u)<len(v):
                u.add(i)
            else:
                v.add(i)

            stack = [i]
            visited[i] = True
            while(stack):
                temp = stack[-1]
                for child in graph[temp]:
                    if not visited[child]:
                        stack.append(child)
                        visited[child] = True
                        if temp in u:
                            v.add(child)
                        else:
                            u.add(child)
                        break
                else:
                    stack.pop()
    return (len(u)*len(v)-n+1)

