import sys
from typing import List

input = sys.stdin.readline


class Solution:
    def make_ranker(self, str):
        if str[1] == '<':
            return [str[0], str[2]]
        else:
            return [str[2], str[0]]

    def make_output(self, ranker_string):
        return f'{ranker_string[0]}{ranker_string[1]}{ranker_string[2]}'

    def solve(self, str1, str2, str3):
        ranker = self.make_ranker(str1)

        ranker2 = self.make_ranker(str2)
        if ranker2[0] == ranker[0]:
            ranker[1] = f'{ranker[2]}{ranker2[2]}'
        elif ranker2[1] == ranker[0]:
            ranker = [ranker2[0]] + ranker
        elif ranker2[0] == ranker[1]:
            ranker = ranker + [ranker2[1]]
        elif ranker2[1] == ranker[1]:
            ranker[0] = f'{ranker[0]}{ranker2[0]}'

        if len(ranker) == 3 and ranker[0] == ranker[2]:
            return 'Impossible'

        ranker3 = self.make_ranker(str3)
        if len(ranker) == 3:
            if ranker.index(ranker3[0]) < ranker.index(ranker3[1]):
                return self.make_output(ranker)
            else:
                return 'Impossible'
        else:
            doubt_index = ranker.index(f'{ranker3[0]}{ranker3[1]}')
            if doubt_index == -1:
                doubt_index = ranker.index(f'{ranker3[1]}{ranker3[0]}')
            if doubt_index == -1:
                return 'Impossible'
            elif doubt_index == 0:
                ranker = ranker3 + ranker[1:]
            elif doubt_index == 1:
                ranker = [ranker[0]] + ranker3

            return self.make_output(ranker)


    def main(self):
        print(self.solve(input(), input(), input()))


