def gcd(a, b):
    if a==0:
        return (b, 0, 1)
    g, x1, y1 = gcd(b%a, a)
    x = y1 - (b // a) * x1
    y = x1
    return (g, x, y)
	
def solve(a, b, x, y, r):
    k = (r-x)//a
    y = (-y) % b
    y = (y-x) % b
    
    gg, X, Y = gcd(a, b)
    if y % gg != 0:
        return 0
    X *= y // gg
    dd = b//gg
    X -= (X//dd) * dd
    if X < 0:
        X += dd
    elif X >= dd:
        X -= dd
    if X > k:
        return 0
    return (k-X)//dd + 1
        
    
