                    ms = 0
                    ns_left -= dict_burger['S']
                else:
                    ms = (dict_burger['S'] - ns_left) * ps
                    ns_left = 0
                if nc_left >= dict_burger['C']:
                    mc = 0
                    nc_left -= dict_burger['C']
                else:
                    mc = (dict_burger['C'] - nc_left) * pc
                    nc_left = 0
                if money >= ms + mc:
                    max_2 += 1
                    money -= (ms + mc)
                else:
                    break
                if nc_left == 0 and ns_left == 0:
