    primes = [2]
    for i in range(3,10**5,2):
        isprime = True
        for j in primes:
            if i%j==0:
                isprime = False
                break
            if i<j**2:
                break
        if isprime:
            primes.append(i)
    Taj = []
    for prime in primes:
        if n%prime==0:
            o = prime
            while True:
                Taj.append(prime)
                n = n//o
                if n%o!=0:
                    break
    return Taj
