import math
def f(a,b,c):
  #ax+by=cを満たす最小の非負整数yを返す,存在しないなら-1
  x,y=[0],[0]
  g=math.gcd(a,b)
  if c==0:
    return 0
  elif c%g!=0:
    return -1
  else:
    if g==1:
      extgcd(a,b,x,y)
      return ((y[0]*c//g)%a)
    else:
      return f(a//g,b//g,c//g)
 
def extgcd(a,b,x,y):
  if b==0:
    x[0],y[0]=1,0
    return a
  else:
    d=extgcd(b,a%b,y,x)
    y[0]-=(a//b)*x[0]
    return d


def calc(a1,b1,a2,b2,n):
  if n<0:
    return 0
  y0=f(a1,a2,b2-b1)
  if y0==-1:
    return 0
  lcm=a1*a2//math.gcd(a1,a2)
  L1=lcm//a1
  L2=lcm//a2
  
  y0=(-y0)%L2
  x0=(a2*y0+b2-b1)//a1
  
  # x=x0-L1*k>=0 
  # y=y0+L2*k>=0
  # a1*x+b1<=n
  # -y0/lcm<=k<=x0/lcm
  
  left=max((-x0+(L1-1))//L1,(-y0+(L2-1))//L2)
  right=((n-b1)//a1-x0)//L1
  #print(x0,y0,L1,L2,left,right)
  return max(0,right-left+1)

def solve(a1,b1,a2,b2,L,R):
  return calc(a1,b1,a2,b2,R)-calc(a1,b1,a2,b2,L-1)

def naive(a1,b1,a2,b2,L,R):
  res=0
  for x in range(L,R+1):
    if x%a1==b1%a1 and x%a2==b2%a2:
      k=(x-b1)//a1
      l=(x-b2)//a2
      if k>=0 and l>=0:
        res+=1
  return res

