class Dij:
    
    from_node = 0
    parentOf = dict()

    @staticmethod
    def get_path(start : int, dest: int):
        x = dest
        path = []
        while Dij.parentOf[x] != x:
            path.append(x)
            x = Dij.parentOf[x]
        path.append(start)
        path.reverse()
        return path
        

        

    @staticmethod
    def run(from_node : int):
        Dij.parentOf[from_node] = from_node
        Dij.from_node = from_node
        costs[from_node] = 0
        Dij._dijkstra(node=from_node, acc_cost=0, nodesQueue=[Path(from_node, 0)])
    
    @staticmethod
    def _dijkstra(node : int, acc_cost : int, nodesQueue : list):
        adj = all_adj_lists[node]
        nodesQueue = nodesQueue[1:]

        for path in adj:
            newCost = acc_cost + path.cost
            if costs[path.to] > newCost:
                costs[path.to] = newCost
                nodesQueue.append(path)
                Dij.parentOf[path.to] = node
        
        if len(nodesQueue) > 0:
            nodesQueue.sort(key=Path.getCost)
            first = nodesQueue[0]
            Dij._dijkstra(node=first.to,
                    acc_cost=acc_cost + first.cost,
                    nodesQueue=nodesQueue,)


