def solve(m, d, b):

    @lru_cache(None)
    def call(pos, remain, f):

        # print (pos, remain, f)

        nonlocal d

        if pos == len(b):
            if remain:
                return 0
            return 1

        # even
        if (pos + 1) % 2 == 0:

            if d <= int(b[pos]):
                next_remain = (remain * 10 + d) % m

                # print (pos, next_remain, d)

                if d == int(b[pos]):
                    if pos == len(b) or pos == len(b) - 1:
                        return 1

                    return call(pos + 1, next_remain, f)

                return call(pos + 1, next_remain, 0)

            return 0

        # odd
        if f:
            # == b
            res = 0

            for i in range(10):                

                if (pos == 0 and i == 0) or (i == d):
                    continue

                next_remain = (remain * 10 + i) % m

                # print (pos, i, next_remain)

                if i < int(b[pos]):
                    # next_f = 0
                    res += call(pos + 1, next_remain, 0)

                elif i == int(b[pos]):
                    # next_f = 1
                    res += call(pos + 1, next_remain, f)

            return res

        else:
            # < b
            res = 0
            for i in range(10):

                next_remain = (remain * 10 + i) % m
                res += call(pos + 1, next_remain, 0)

            return res

    ans = call(0, 0, 1)
    return ans % (10**9 + 7)


