class Coordenada:
    def __init__(self, linha, coluna):
        self.linha = linha
        self.coluna = coluna

    def __eq__(self, other):
        return self.linha == other.linha and self.coluna == other.coluna

    def __lt__(self, other):
        if self.linha == other.coluna:
            return self.coluna < other.coluna
        else:
            return self.linha < self.linha


def binary_search(vetor, x, inicio=0, fim=None):
    if fim == None:
        fim = len(vetor) - 1
    if inicio > fim:
        return -1
    meio = (inicio + fim)//2
    if vetor[meio] == x:
        return meio
    elif vetor[meio] < x:
        return binary_search(vetor, x, meio+1, fim)
    else:
        return binary_search(vetor, x, inicio, meio-1)


def ordem(vetor, x, inicio=0, fim=None):
    if fim == None:
        fim = len(vetor) - 1
    meio = (inicio + fim) // 2
    if inicio > fim:
        return inicio
    if vetor[meio] == x:
        return meio
    elif vetor[meio] < x:
        return ordem(vetor, x, meio+1, fim)
    else:
        return ordem(vetor, x, inicio, meio-1)

def get_index(linha, coluna, n, m):
    linha -= 1
    coluna -= 1
    return linha * m + coluna


