from collections import defaultdict


def make_tree(graph, root):
    tree = defaultdict(set)

    def _make(v):
        for child in graph[v]:
            if child not in tree:
                tree[v].add(child)
                _make(child)

    _make(root)
    return tree


def traverse(tree, y, x):
    Y = 0
    NO_X = 0
    NO_Y = 0
    X = 0

    def routine(v, x_found):
        nonlocal Y, NO_X, NO_Y, X
        if v == x:
            x_found = True
        if x_found:
            X += 1
        else:
            Y += 1

        findings=[x_found]
        for child in tree[v]:
            findings.append(routine(child, x_found))
        x_found = any(findings)
        if x_found and v != y:
            NO_Y += 1
        else:
            NO_X += 1
        return any(findings)

    routine(y, False)
    #print(Y, NO_Y, X, NO_X)
    return Y *(Y-1) + NO_Y*(NO_Y-1) + X*NO_X

