def solve(ma, ca):
    i = 0
    j = 0
    best_cheese = [None] * len(ma)
    hungry = 0
    while i < len(ma):
        if ma[i] <= ca[j]:
            if (
                best_cheese[i] is None or
                abs(ca[j] - ma[i]) < abs(ca[best_cheese[i]] - ma[i])
                or (
                    abs(ca[j] - ma[i]) == abs(ca[best_cheese[i]] - ma[i]) and
                    i - 1 >= 0 and
                    best_cheese[i - 1] == best_cheese[i]
                )
            ):
                best_cheese[i] = j
            i += 1
        else:
            best_cheese[i] = j
            if j + 1 < len(ca):
                j += 1
            else:
                i += 1

    # print('best_cheese:', best_cheese)

    for i in range(1, len(ma)):
        if (
