class graph_maker:
    def __init__ (self,n):
        self.matrix = [[0 for i in range(n)] for i in range(n)]

    def add_edge(self,u,v,weight):
        if self.matrix[u][v] == 0:
            temp = [weight]
            self.matrix[u][v] = temp
            self.matrix[v][u] = temp
        else:
            self.matrix[u][v].append(weight)
            self.matrix[v][u].append(weight)

    def graph_do(self):
        return self.matrix

def dijkstra(n,graph):
    for i in range(n):    # removing all the self loops from the graph
        graph[i][i] = 0     #and multiple edges from the graph
        for j in range(n):
            if type(graph[i][j]) == list:
                graph[i][j] = min(graph[i][j])

    infinite = float('inf')            #creating a variable which gives reference to infinite
    dist = [infinite]*(n-1)            #creating an distance list & assigning to infinite
    visited = [True]*n                 #creating an array where we take care of all visited node
    parent = [-1]*n                    #creating an array just to track the path 
    dist.insert(0,0)                   #assigning the distance value of source = 0 

    while True:
        min_dist = min(dist)            #finding the minimum distance among all the node
        ind = dist.index(min_dist)      #finding the position of the node which has the minimum distance

        if min_dist != infinite:        #checking whether all the nodes aren't get visited
            if visited[ind]:            #checking that the node with the minimum distance is not visited
                visited[ind] = False
                for i in range(n):
                    if visited[i]:
                        if graph[ind][i] != 0:
                            di = min_dist + graph[ind][i]
                            if di<dist[i]:
                                dist[i] = di
                                parent[i] = ind
                dist[ind] = infinite
        else:
            break
    if visited[n-1]:
        return -1
    return parent

def show_path(path,j):
    if path[j]==-1:
        print(j+1,end=" ")
        return
    show_path(path,path[j])
    print(j+1,end=" ")

if __name__ == "__main__":
    n,m = map(int,input().split())
    gr = graph_maker(n)
    for i in range(m):
        u,v,w = map(int,input().split())
        gr.add_edge(u-1,v-1,w)
        
    graph = gr.matrix
    del gr
    pa = dijkstra(n,graph)
    if pa == -1:
        print(-1) 
    else:
        show_path(pa,n-1)

