def posiciones(tabla, i, j, n):
    n = 0
    if j < n - 1 and tabla[i][j+1] == 'o':
        n += 1
    if j > 0 and tabla[i][j-1] == "o":
        n += 1
    if i < n - 1 and tabla[i+1][j] == "o":
        n += 1
    if i > 0 and tabla[i-1][j] == "o":
        n += 1
    if n % 2 == 0: return True
    else: return False

def solve(tabla, n):
    for i in range(n):
        for j in range(n):
            if posiciones(tabla, i, j, n) is False:
                return False
    return True

