def frac_to_string(num: int, den: int, target: int) -> str:
    num, den = abs(num), abs(den)

    if num % den == 0:
        return -1

    rem = num % den
    rems = {}
    is_repeating = False
    location = 1

    while rem > 0 and not is_repeating:
        if rem in rems:
            is_repeating = True
            return -1
        else:
            rems[rem] = location

        rem *= 10
        temp = rem // den
        rem %= den

        if temp == target:
            return location

        location += 1

    return location


