def calculate_height(paper, width):
    has_white = False
    square_start = False
    for i in range(len(paper)):
        if 'B' in paper[i] and not square_start:
            square_start = True
            start_index = i
            last_index = i + 1
        if 'B' in paper[i] and square_start:
            last_index = i + 1
        if not has_white:
            if 'W' in paper[i]:
                has_white = True
    if not has_white:
        return -1
    if last_index > len(paper):
        last_index = len(paper)
    new_paper = paper[start_index:last_index]
    square_length = len(new_paper)
    if square_length > width:
        return -1
    return sum([(square_length - row.count('B')) for row in new_paper])


