from queue import Queue


def rook(start_x, start_y, end_x, end_y, G):
    n = len(G)
    Q = Queue()

    G[start_y][start_x] = 0

    Q.put((start_y, start_x))
    while not Q.empty():
        y, x = Q.get()
        # row
        for i in range(n):
            if i == x or G[y][i] != -1:
                continue
            else:
                G[y][i] = G[y][x] + 1
                if y == end_y and i == end_x:
                    return G[end_y][end_x]
                Q.put((y, i))
        # col
        for i in range(n):
            if i == y or G[i][x] != -1:
                continue
            else:
                G[i][x] = G[y][x] + 1
                if i == end_y and x == end_x:
                    return G[end_y][end_x]
                Q.put((i, x))


def bishop(start_x, start_y, end_x, end_y, G):
    n = len(G)
    Q = Queue()

    G[start_y][start_x] = 0

    Q.put((start_y, start_x))
    while not Q.empty():
        y, x = Q.get()
        for i in range(1, n):
            if y - i >= 0 and x - i >= 0 and G[y - i][x - i] == -1:
                G[y - i][x - i] = G[y][x] + 1
                if y - i == end_y and x - i == end_x:
                    return G[end_y][end_x]
                Q.put((y - i, x - i))
            if y + i < n and x + i < n and G[y + i][x + i] == -1:
                G[y + i][x + i] = G[y][x] + 1
                if y + i == end_y and x + i == end_x:
                    return G[end_y][end_x]
                Q.put((y + i, x + i))
            if y + i < n and x - i >= 0 and G[y + i][x - i] == -1:
                G[y + i][x - i] = G[y][x] + 1
                if y + i == end_y and x - i == end_x:
                    return G[end_y][end_x]
                Q.put((y + i, x - i))
            if y - i >= 0 and x + i < n and G[y - i][x + i] == -1:
                G[y - i][x + i] = G[y][x] + 1
                if y - i == end_y and x + i == end_x:
                    return G[end_y][end_x]
                Q.put((y - i, x + i))


def king(start_x, start_y, end_x, end_y, G):
    n = len(G)
    Q = Queue()

    G[start_y][start_x] = 0

