def goLeft(u, k, d):
	if k == 0:
		return (u, k)
	else:
		return (u - 2**(k - 1), k - 1)

def goRight(u, k, d):
	if k == 0:
		return (u, k)
	else:
		return (u + 2**(k - 1), k - 1)

def goUp(u, k, d):
	if k == d - 1:
		return (u, k)
	elif getk(u - 2**k) == k + 1:
		return (u - 2**k, k + 1)
	else:
		return (u + 2**k, k + 1)

