def read_int():
    return int(sys.stdin.readline())

def read_ints():
    return list(map(int, sys.stdin.readline().split()))

def read_string():
    return sys.stdin.readline().split()[0]

def read_strings():
    return sys.stdin.readline().split()

def YES():
    write('YES')

def NO():
    write('NO')

def write(x):
    sys.stdout.write(x + '\n')


def solve():
    n = read_int()
    trees = []
    for _ in range(n):
        trees.append(read_ints())
    # dp[i][j] = max trees among trees[i...] that can be fell if last occupied point is j
    dp = [[-1, -1] for _ in range(n)]

    def dfs(i, j):
        # j = last occupied point
        # compressed state: i = current tree, j = 0 if tree[i] cannot be fell left, 1 otherwise
        # we just use j as last tree point for convenience of the function but the state only depends on the boolean value of j
        if i == n: # no more trees to fell
            return 0
        if j >= trees[i][0]: # you have no way to fell this tree
            return dfs(i+1, j)
        
        # but first check if left is possible (because if left is possible, it is optimal to fell left - greedy choice property)
        canLeft = 1 if trees[i][0] - j > trees[i][1] else 0
        if dp[i][canLeft] != -1:
            return dp[i][canLeft]
        ans = 0
        if canLeft == 1:
            ans = max(ans, 1 + dfs(i+1, trees[i][0]))
        else:
            if i == n-1: # you can definitely fell this tree right
                ans = 1
            else:
                # check if it is possible to fell this tree right (check next occupied point)
                if trees[i][0] + trees[i][1] < trees[i+1][0]:
                    ans = max(ans, 1 + dfs(i+1, trees[i][0]+trees[i][1]))
                ans = max(ans, dfs(i+1, j)) # try not felling this tree anyway
        dp[i][canLeft] = ans
        return ans
    print(dfs(0, -inf))

