import queue

def main():
    lines = fileinput.input()
    lines[0]

    # Graph construction
    vertices = dict()
    n = 1
    for line in lines:
        line = line.split(" ")
        a = int(line[0])
        b = int(line[1])
        cost = int(line[2])
        try:
            vert_a = vertices[a]
        except KeyError:
            vert_a = Vertex(a)
            vertices[a] = vert_a
        try:
            vert_b = vertices[b]
        except KeyError:
            vert_b = Vertex(b)
            vertices[b] = vert_b
        n = max(n, a)
        n = max(n, b)
        vert_a.edges.append(Edge(vert_a, vert_b, cost))
        vert_b.edges.append(Edge(vert_b, vert_a, cost))

    # All vertices now represented in graph
    goal = vertices[n]

    pq = queue.PriorityQueue()
    root = vertices[1]
    pq.put(Edge(root, root, 0))

    # now we try to get from root to goal
    while not pq.empty():
        cur_edge = pq.get()
        if cur_edge.to_vertex == goal:
            path = [cur_edge.to_vertex.name]
            parent_vertex = cur_edge.parent
            while parent_vertex != root:
                path.append(parent_vertex.name)
                parent_vertex = parent_vertex.parent
            path.append(root.name)
            print(" ".join(str(name) for name in reversed(path)))
            return
        if not cur_edge.to_vertex.visited:
            cur_edge.to_vertex.visited = True
            cur_edge.to_vertex.parent = cur_edge.parent
            for neighbor_edge in cur_edge.to_vertex.edges:
                assert(neighbor_edge.parent == cur_edge.to_vertex)
                if not neighbor_edge.to_vertex.visited:
                    pq.put(Edge(neighbor_edge.parent, neighbor_edge.to_vertex,
                                cur_edge.cost + neighbor_edge.cost))

    # Failed to find goal
    print(-1)

class Vertex:
    def __init__(self, name):
        self.name = name
        self.visited = False
        self.edges = [Edge(self, self, 0)]
        self.parent = None

    def __eq__(self, other):
        try:
            return self.name == other.name
        except:
            return false

    def __repr__(self):
        return "Vertex {} with {} neighbors".format(self.name, len(self.edges))

class Edge:
    def __init__(self, parent, to_vertex, cost):
        self.parent = parent
        self.to_vertex = to_vertex
        self.cost = cost

    def __eq__(self, other):
        try:
            return self.cost == other.cost
        except:
            return false

    def __repr__(self):
        return "Edge from vertex {} to vertex {} with cost {}".format(self.parent.name, self.to_vertex.name, self.cost)

    def __gt__(self, other):
        try:
            return self.cost > other.cost
        except:
            return false

