    if root is None: 
        root = node 
    else: 
        if root.val < node.val: 
            if root.right is None: 
                root.right = node 
                return root.val
            else: 
                return insert(root.right, node) 
        else: 
            if root.left is None: 
                root.left = node 
                return root.val
            else: 
                return insert(root.left, node) 

