import sys

class Dijkstra:
    
    def __init__(self, vertices):
        # from 1 to v
        self.V = (vertices + 1)
        self.graph = [[0 for row in range(self.V)] for j in range(self.V)]
        # print(len(self.graph), len(self.graph[0]))
        
    def add_edge(self, src, dest, weight):
        # directed graph
        if self.graph[src][dest] != 0:
            self.graph[src][dest] = min(self.graph[src][dest], weight)
            self.graph[dest][src] = min(self.graph[dest][src], weight)
        else:
            self.graph[src][dest] = weight
            self.graph[dest][src] = weight
        
    def minimum_distance(self, dist, visited):
        min_dist = sys.maxsize
        min_idx = None
        
        for v in range(1, len(dist)):
            if dist[v] < min_dist and visited[v] != True:
                min_dist = dist[v]
                min_idx = v
        # print(min_idx)
        return min_idx
        
    def shortest_path(self, src): 
        dist = [sys.maxsize] * self.V
        visited = [False] * self.V
        self.parent = [None] * self.V
        
        dist[src] = 0
        
        for _ in range(1, self.V):
            # find minimum distance vertex which is not visited yet
            u = self.minimum_distance(dist, visited)
            visited[u] = True
            
            for v in range(1, self.V):
                if self.graph[u][v] > 0 and visited[v] != True:
                    if self.graph[u][v] + dist[u] < dist[v]:
                        dist[v] = self.graph[u][v] + dist[u]
                        self.parent[v] = u
        
        return dist
        
    def print_path(self, src, dest):
        self.shortest_path(src)
        # print(self.parent)
        if src == dest:
            return src
            
        path = []
        path.append(dest)
        i = dest
        
        while self.parent[i] != src:
            if self.parent[i] not in path:
                path.append(self.parent[i])
                i = self.parent[i]
            else:
                return -1
        path.append(src)
        return " ".join(str(x) for x in reversed(path))
            
            


def main():
    n, m = (int(x) for x in input().split())
    g = Dijkstra(n)
    for _ in range(m):
        v1, v2, w = (int(x) for x in input().split())
        g.add_edge(v1, v2, w)
    print(g.print_path(1, n))

