    return all(digit in '47' for digit in str(x))

def gen_lucky_count(n):
    count = 0
    for i in range(1, n + 1):
        if lucky(i):
            count += 1
    return count

def count_lucky_positions(n, k):
    if k > 10**15:
        return -1
    
    F = [1]
    p = 1
    i = 1
    while p <= 10**15:
        p *= i
        F.append(p)
        i += 1
    
    if n <= 14:
        if k > F[n]:
            return -1
        lucky_permutation = [i for i in range(1, n + 1)]
        for i in range(n):
            if lucky(i + 1) and lucky_permutation[i] == k:
                return 1
        return 0
    else:
        lucky_permutation = [i for i in range(n - 14, n + 1)]
        count = gen_lucky_count(n - 15)
        for i in range(n - 14, n + 1):
            if lucky(lucky_permutation[i - n + 14]) and lucky(i):
                count += 1
        return count

