import sys

def dfs(graph,dp,n,i,parentVeritce):
    if i<=0:
        return 10000000000
    if dp[n][i] != -1:
        return dp[n][i]
    dp[n][i] = 10000000000
    for vertice,time in graph[n]:
        newvalue= dfs(graph,dp,vertice,i-1,parentVeritce)+time
        if dp[n][i]>=newvalue:
            dp[n][i] = newvalue
            parentVeritce[n][i] = vertice
    
    return dp[n][i]

def solveWithDFS(graph,dp, total,parentVeritce):
    for x in range(len(graph)-1,0,-1):
        calculated = dfs(graph,dp,len(graph)-1,x,parentVeritce)
        if (calculated<=total):
            return x
    return 0
