def is_ballanced(s: str):
    return s.count(one) == s.count(zero)

cache = {}

def longest_ballanced_len(l, r, s):


    if l == r:
        return 0

    if r - l + 1 == 2:
        if s[l] == s[r]:
            return 0
        else:
            return 2

    if (l, r) in cache:
        return cache[l, r]

    if is_ballanced(s[l:r + 1]):
        length = r - l + 1
        cache[l, r] = length
        return length

    l1 = longest_ballanced_len(l + 1, r, s)
    l2 = longest_ballanced_len(l, r - 1, s)

    length = max(l1, l2)
    cache[l, r] = length
    return length



