from typing import List, Tuple

def bigmod(b: int, p: int, m: int) -> int:
    if p == 0:
        return 1
    if p & 1:
        ret = bigmod(b, p//2, m) % m
        return ((b % m) * ret * ret) % m
    else:
        ret = bigmod(b, p//2, m) % m
        return (ret * ret) % m

def knapsack(i: int, tym: int, t: List[int], c: List[int], n: int, dp: List[List[int]]) -> int:
    if tym >= n:
        return 0
    if i == n + 1:
        return 1000000000000000
    if dp[i][tym] != -1:
        return dp[i][tym]

    dp[i][tym] = min(knapsack(i+1, tym, t, c, n, dp), knapsack(i+1, tym+t[i]+1, t, c, n, dp) + c[i])
    return dp[i][tym]

