# "Tightens" a into b
def tighten(a, b):
    c = [a[0], a[1]]
    if b[0] > c[0]:
        # too far
        if b[0] > c[1]:
            return None
        else:
            c[0] = b[0]
    if b[1] < c[1]:
        c[1] = b[1]
    return c


