def is_t_prime(num):
    # 判断一个数是否为T-prime
    # T-prime的特点是有且仅有三个正因子，即平方根也是质数
    if num == 1:
        return False
    sqrt_num = int(math.sqrt(num))
    if sqrt_num * sqrt_num == num and is_prime(sqrt_num):
        return True
    return False

def is_prime(num):
    # 判断一个数是否为质数
    if num == 1:
        return False
    for i in range(2, int(math.sqrt(num))+1):
        if num % i == 0:
            return False
    return True

