# 欧拉值的欧拉值递归下去只有logn种
def GetPhi(k):
    if k in Phi:
        return Phi[k]
    p = 2
    phi = k
    while p * p <= k:
        if k % p == 0:
            while k % p == 0:
                k //= p
            phi = phi // p * (p - 1)
        p += 1
    if k > 1:
        phi = phi // k * (k - 1)
    Phi[k] = phi
    return phi


