from math import sqrt

def divide_into_p(p, a):
    q = a // (p+1)
    r = a % (p+1)
    if r == 0:
        return q
    elif q + r >= p:
        return q+1
    else:
        return None

def divisible_into_p(p, lst):
    lgth = 0
    for l in lst:
        dp = divide_into_p(p, l)
        if dp == None:
            return None
        else:
            lgth += dp
    return lgth

def check_all_p(balls):
    a = balls[0]
    sqrt_a = int(sqrt(a)) +1
    for i in range(1, sqrt_a+1):
        p = a//i+1
        dp = divisible_into_p(p, balls)
        if dp != None:
            return dp
    for i in range(1, sqrt_a+1):
        p = sqrt_a+1 - i
        dp = divisible_into_p(p, balls)
        if dp != None:
            return dp
        
