def proc(n, a):
    primes = set(range(2, 10 ** 5))
    for e in range(2, 317):
        if e not in primes:
            continue
        for j in range(e * 2, 10 ** 5, e):
            primes.discard(j)
    primes = sorted(primes)

    def factorize(x):
        res = []
        for p in primes:
            if p > x:
                break
            if x % p != 0:
                continue
            res.append(p)
            while x % p == 0:
                x //= p
        return res

    t = defaultdict(int)
    for e in a:
        factors = factorize(e)
        new_val = (max(t[f] for f in factors) if factors else 0) + 1

        for f in factors:
            t[f] = new_val

    return max(t.values())


