class PointReplacement:
 
    def __init__(self, s):
        self.s = list(s)
        self.replacements = 0
 
    def initialize(self):
        cnt = 0
        for idx in range(1,len(s)):
            if self.s[idx] == self.s[idx-1] == ".":
                cnt += 1
            else:
                self.replacements += cnt
                cnt = 0
        if cnt > 0:
            self.replacements += cnt

    def replace(self, index, char):
        if len(self.s) == 1: return
        idx = index - 1
        idxVal = self.s[idx]
        # char replace point
        if idxVal == '.' and char != '.':
            if idx == 0:
                if self.s[idx+1] == ".":
                    self.replacements -= 1
            elif idx == len(self.s)-1:
                if self.s[idx-1] == ".":
                    self.replacements -= 1
            else:
                if self.s[idx+1]==self.s[idx-1]==".":
                    self.replacements -= 2
                elif self.s[idx+1] == "." or self.s[idx-1] == ".":
                    self.replacements -= 1
        # point replace char
        if idxVal != '.' and char == '.':
            if idx == 0:
                if self.s[idx+1] == ".":
                    self.replacements += 1
            elif idx == len(self.s)-1:
                if self.s[idx-1] == ".":
                    self.replacements += 1
            else:
                if self.s[idx+1]==self.s[idx-1]==".":
                    self.replacements += 2
                elif self.s[idx+1] == "." or self.s[idx-1] == ".":
                    self.replacements += 1
        self.s[idx] = char
 
