    i = 0
    j = N - 1
    while(i < j):
        if (A[i] + A[j] == X):
            return True
        elif(A[i] + A[j] < X):
            i += 1
        else:
            j -= 1
    return 0

def shortest_path(k, n, neighbors):
    mark=[-1]*(n+1)
    mark[k]=0
    bfs_queue = [k]
 
    i=0
    while i < len(bfs_queue):
        u = bfs_queue[i]
        for v in neighbors[u]:
            if mark[v]==-1:
                mark[v]=mark[u]+1
                bfs_queue.append(v)
        i+=1
    return mark


