class TreeNode(object):
    def __init__(self):
        self.left=-1
        self.right=-1
        self.sum_num=[0,0,0]
    def __str__(self):
        return '[%s,%s,%s]'%(self.left,self.right,self.sum_num)
    def __repr__(self):
        return '[%s,%s,%s]'%(self.left,self.right,self.sum_num)
class Tree(object):
    def __init__(self,n,arr):
        self.n=n
        self.max_size=4*n
        self.tree=[TreeNode() for i in range(self.max_size)]
        self.arr=arr
    def _build(self,index,left,right):
        self.tree[index].left=left
        self.tree[index].right=right
        if left==right:
            self.tree[index].sum_num=self.arr[left-1]
        else:
            mid=(left+right)//2
            self._build(index*2,left,mid)
            self._build(index*2+1,mid+1,right)
            self.pushup_sum(index)
    def build(self):
        self._build(1,1,self.n)
    def pushup_sum(self,k):
        t=min(self.tree[k*2].sum_num[1],self.tree[k*2+1].sum_num[2])
        self.tree[k].sum_num[0]=self.tree[k*2].sum_num[0]+self.tree[k*2+1].sum_num[0]+t
        self.tree[k].sum_num[1] = self.tree[k * 2].sum_num[1] + self.tree[k * 2 + 1].sum_num[1] - t
        self.tree[k].sum_num[2] = self.tree[k * 2].sum_num[2] + self.tree[k * 2 + 1].sum_num[2] - t
    def _query(self,ql,qr,i,l,r,):
        if l>=ql and r<=qr:
            return self.tree[i].sum_num
        else:
            mid=(l+r)//2
            res_l=[0,0,0]
            res_r=[0,0,0]
            res_s=[0,0,0]
            if ql<=mid:
                res_l=self._query(ql,qr,i*2,l,mid,)
            if qr>mid:
                res_r=self._query(ql,qr,i*2+1,mid+1,r,)
            t=min(res_l[1],res_r[2])
            for i in range(3):
                res_s[0]=res_l[0]+res_r[0]+t
                res_s[1] = res_l[1] + res_r[1] - t
                res_s[2] = res_l[2] + res_r[2] - t
            return res_s
    def query(self,ql,qr):
        return self._query(ql,qr,1,1,self.n)
