import queue
from collections import namedtuple

Aresta = namedtuple('Aresta', ['vertice', 'peso'])

class grafoSemDir(object):
    def __init__(self, numVertices):
        self.numVertices = numVertices
        self.adjacency_list = [[] for _ in range(numVertices)]

    def addAresta(self, origem, dest, peso):
        assert origem < self.numVertices
        assert dest < self.numVertices
        self.adjacency_list[origem].append(Aresta(dest, peso))
        self.adjacency_list[dest].append(Aresta(origem, peso))

    def getVertice(self):
        for v in range(self.numVertices):
            yield v

    def getAresta(self, vertice):
        for e in self.adjacency_list[vertice]:
            yield e


def dijkstra(grafo, origem, dest):
    q = queue.PriorityQueue()
    distancia = []; pais = []
    pesoInicial = float("inf")

    for i in grafo.getVertice():
        peso = pesoInicial
        if(origem == i):
            peso = 0
        distancia.append(peso)
        pais.append(None)

    q.put(([0, origem]))
    while(not q.empty()):
        v_tuple = q.get()
        v = v_tuple[1]

        for e in grafo.getAresta(v):
            candidatoDist = distancia[v] + e.peso
            if(distancia[e.vertice] > candidatoDist):
                distancia[e.vertice] = candidatoDist
                pais[e.vertice] = v

                #Detecção de ciclos negativos.
                if candidatoDist < -1000:
                    return [-1], -1

                q.put(([distancia[e.vertice], e.vertice]))

    final = dest; menorCam = []
    while final is not None:
        menorCam.append(final)
        final = pais[final]

    menorCam.reverse()

    return menorCam, distancia[dest]


