def how_many_lines_needed(msg, max_line_len):
    pos = 0
    line_cnt = 0
    while pos < len(msg):
        line_cnt += 1
        line_end = pos + max_line_len
        if line_end >= len(msg):
            break
        while line_end > pos and msg[line_end - 1] != ' ' and msg[line_end - 1] != '-':
            line_end -= 1
        if line_end == pos:
            return INF
        pos = line_end
    return line_cnt


def main(max_line_count, msg):
    if max_line_count == 1:
        return len(msg)
    l, r = 0, len(msg)
    while r - l > 1:
        m = (l + r) // 2
        ln = how_many_lines_needed(msg, m)
        if  ln <= max_line_count:
            r = m
        else:
            l = m
    print(r)

