class Solution:
    @staticmethod
    def main():
        recipe = input()
        stocks = input().split()
        breadStock = int(stocks[0])
        sausageStock = int(stocks[1])
        cheeseStock = int(stocks[2])
        costs = input().split()
        costPerBread = int(costs[0])
        costPerSausage = int(costs[1])
        costPerCheese = int(costs[2])
        totalMoney = int(input())

        breadRequired = 0
        sausageRequired = 0
        cheeseRequired = 0

        for c in recipe:
            if c == 'B':
                breadRequired += 1
            elif c == 'S':
                sausageRequired += 1
            else:
                cheeseRequired += 1

        if breadRequired > 0:
            totalMoney += breadStock * costPerBread
        if sausageRequired > 0:
            totalMoney += sausageStock * costPerSausage
        if cheeseRequired > 0:
            totalMoney += cheeseStock * costPerCheese

        low = 0
        high = totalMoney
        burgersMade = 0

        while low <= high:
            burgers = low + (high - low) // 2

            if Solution.isPossible(burgers, breadRequired, sausageRequired, cheeseRequired,
                                   costPerBread, costPerSausage, costPerCheese, totalMoney):
                burgersMade = burgers
                low = burgers + 1
            else:
                high = burgers - 1

        print(burgersMade)

    @staticmethod
    def isPossible(burgersRequired, breadRequired, sausageRequired, cheeseRequired,
                   costPerBread, costPerSausage, costPerCheese, totalMoney):
        expense = (breadRequired * burgersRequired * costPerBread) + \
                  (sausageRequired * burgersRequired * costPerSausage) + \
                  (cheeseRequired * burgersRequired * costPerCheese)

        return expense <= totalMoney


