    l = set()
    c = n
    if p >= m:
        return set()
    for i in str(n):
        #print(i)
        z = int(i)
        if g(c-z) == -1:
            p +=1
            r = c -z
            if g(r - r%10 + 10) + p > m:
                continue
            l = l | resolver(c-z,p,m)
        else:
            #if c -z + p > m:continue
            l.add(g(c-z) + p)
    return l
    
