def solve(n, m, arr):
    b_cells = []
    for row in range(n):
        for col in range(m):
            if arr[row][col] == 'B':
                b_cells.append((row, col))

    if len(b_cells) < 2:
        return 1

    top = b_cells[0][0]
    right = b_cells[0][1]
    bottom = b_cells[0][0]
    left = b_cells[0][1]
    for cell in b_cells:
        if cell[1] < left:
            left = cell[1]
        elif cell[1] > right:
            right = cell[1]
        if cell[0] < top:
            top = cell[0]
        elif cell[0] > bottom:
            bottom = cell[0]
    square_len = max(bottom - top, right - left) + 1
    
    new_top = max(bottom - square_len + 1, 0)
    new_left = max(right - square_len + 1, 0)
    
    new_right = new_top + square_len - 1
    new_bottom = new_left + square_len - 1

    if new_right > m or new_bottom > n:
        return -1

    count = 0
    for row in range(new_top, new_bottom + 1):
        for col in range(new_left, new_right + 1):
            if arr[row][col] == 'W':
                count += 1
    return count

