    root = [1] * (n+1)
    nodes = [None]
    cnt = collections.defaultdict(int)
    for i in range(1, n+1):
        v, l, r = map(int, input().split())
        cnt[v] += 1
        nodes.append((v, l, r))
        if l != -1:
            root[l] = 0
        if r != -1:
            root[r] = 0

    root_idx = 0
    for i in range(1, n+1):
        if root[i]:
            root_idx = i
            break
    res = n

    def find(i, low, high):
        nonlocal res
        if i < 0:
            return
        v, l, r = nodes[i]
        if low <= v <= high:
            res -= cnt[v]
        if low < v:
            find(l, low, min(high, v-1))
        if high > v:
            find(r, max(low, v+1), high)

    find(root_idx, 0, 10**9)
    print(res)


