def DIVISORS(M, sorted=True):
    res = []
    for i in range(1, M + 1):
        if i * i > M:
            break
        if M % i == 0:
            res.append(i)
            res.append(M//i)
    res = list(set(res))
    if sorted:
        res.sort()
    return res


def PRIME_SIEVE(M):
    '''
    return PRIME_LIST[0,M]
    '''
    isprime = [True]*(M + 1)
    primes = []
    isprime[0] = isprime[1] = False
    for i in range(2, M + 1):
        if isprime[i]:
            primes.append(i)
            for j in range(i*i, M + 1, i):
                isprime[j] = False
    return primes


