from collections import defaultdict
from queue import PriorityQueue
from math import inf

INF = inf

class AdjacentNode:
  def __init__(self, node: int, weight: int):
    self.node = node
    self.weight = weight


class WeightedGraph:
  def __init__(self, node_count):
    self.node_count = node_count
    self.value = [[] for i in range(node_count)]

  def add_edge(self, node_a: int, node_b: int, weight: int):
    self.value[node_a - 1].append([node_b, weight])

class Dijkstra:
  def __init__(self, graph: WeightedGraph, origin: int, destination: int):
    self.destination = destination
    self.weights = [INF] * graph.node_count
    self.previous = [None] * graph.node_count
    self.visited = [False] * graph.node_count
    self.weights[origin - 1] = 0
    self.graph = graph
    self.queue = PriorityQueue()
    self.queue.put((0, origin))


  def run(self):
    while(not self.queue.empty()):

      min_value, current_node = self.queue.get()

      if (self.visited[current_node - 1]):
        continue

      self.visited[current_node - 1] = True

      if (self.weights[current_node - 1] < min_value):
        continue

      for node, weight in self.graph.value[current_node - 1]:
        if (self.visited[node - 1]):
          continue

        new_weight = self.weights[current_node - 1] + weight

        if (new_weight > self.weights[node - 1]):
          continue

        self.weights[node - 1] = new_weight
        self.previous[node - 1] = current_node
        self.queue.put_nowait((new_weight, node))

      if (current_node == self.destination):
        return (self.previous, self.weights[self.destination - 1])
    return (self.previous, INF)

