def dfs(u, color, parent, graph, colors):
    colors[u] = color
    for v in graph[u]:
        if v == parent:
            continue
        if colors[v] == color:
            return False
        if colors[v] == 0 and not dfs(v, 3-color, u, graph, colors):
            return False
    return True

def max_edges(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    colors = [0] * (n+1)
    if not dfs(1, 1, 0, graph, colors):
        return 0
    cnt = [0, 0]
    for i in range(1, n+1):
        cnt[colors[i]-1] += 1
    return cnt[0] * cnt[1] - (n-1)

