dp = [[-1,-1] for i in range(101)]
dp[0][0] = 1

def solve(n, k , came, d):
    if n == 0:
        if came == 0:
            return 1
        return 0
    if k == 0:
        return 0
    if dp[n][came]!=-1:
        return dp[n][came]
    ans = 0
    for i in range(1,k+1):
        if n-i >= 0:
            if i >= d:
                ans += solve(n-i, k, 0, d)
            else:
                ans += solve(n-i, k, came, d)
    dp[n][came] = ans
    return dp[n][came]

