import random

def random_priority():
    return random.getrandbits(30)

class EmptyTreapNode:
    cnt = 0
    def insert(x):
        return x
    def erase(x):
        return EmptyTreapNode
    def contains(x):
        return False
    def at(index):
        return None
    def lower_bound(x):
        return 0

class TreapNode:
    def __init__(self, x):
        self.x = x
        self.y = random_priority()
        self.cnt = 1
        self.left = EmptyTreapNode
        self.right = EmptyTreapNode

    def update_cnt(self):
        self.cnt = 1 + self.left.cnt + self.right.cnt

    def rotate_right(self):
        root = self.left
        self.left = root.right
        root.right = self
        self.update_cnt()
        root.update_cnt()
        return root

    def rotate_left(self):
        root = self.right
        self.right = root.left
        root.left = self
        self.update_cnt()
        root.update_cnt()
        return root

    def insert(self, n):
        if n.x < self.x:
            self.left = self.left.insert(n)
            if n.y > self.y:
                return self.rotate_right()
            self.cnt += 1
            return self
        else:
            self.right = self.right.insert(n)
            if n.y > self.y:
                return self.rotate_left()
            self.cnt += 1
            return self

    def erase(self, x):
        if x != self.x:
            if x < self.x:
                self.left = self.left.erase(x)
            else:
                self.right = self.right.erase(x)
            self.update_cnt()
            return self
        if self.left is EmptyTreapNode:
            return self.right
        if self.right is EmptyTreapNode:
            return self.left
        if self.left.y >= self.right.y:
            root = self.rotate_right()
            root.right = root.right.erase(x)
        else:
            root = self.rotate_left()
            root.left = root.left.erase(x)
        root.update_cnt()
        return root

    def contains(self, x):
        if x < self.x:
            return self.left.contains(x)
        if x > self.x:
            return self.right.contains(x)
        if x == self.x:
            return True

    def at(self, index):
        left_cnt = self.left.cnt
        if index < left_cnt:
            return self.left.at(index)
        if index > left_cnt:
            return self.right.at(index - left_cnt - 1)
        return self.x

    def lower_bound(self, x):
        if x <= self.x:
            return self.left.lower_bound(x)
        return 1 + self.left.cnt + self.right.lower_bound(x)

class Treap:
    def __init__(self, iterable=()):
        self.root = EmptyTreapNode
        for x in iterable:
            self.insert(x)

    def at(self, index):
        return self.root.at(index)

    def erase(self, x):
        self.root = self.root.erase(x)

    def insert(self, x):
        self.root = self.root.insert(TreapNode(x))

    def lower_bound(self, x):
        return self.root.lower_bound(x)

    def contains(self, x):
        return self.root.contains(x)

    def __len__(self):
        return self.root.cnt

    def __getitem__(self, index):
        return self.at(index)

    def __delitem__(self, index):
        return self.erase(self[index])

    def add(self, x):
        self.insert(x)

