def build_log(n):
    dp = [0] * (n + 1)
    dp[1] = 0
    for i in range(2, n + 1):
        dp[i] = dp[i // 2] + 1
    return dp


class SparseTable:
    def __init__(self, lg, fn):
        self.lg = lg
        self.fn = fn

    def build(self, arr):
        dp = [dict() for _ in range(len(arr))]

        for i in range(len(arr)):
            dp[i][0] = arr[i]

        def helper(idx, l):
            if l in dp[idx]:
                return dp[idx][l]

            dp[idx][l] = self.fn(
                helper(idx, l - 1), helper(idx + (1 << (l - 1)), l - 1)
            )
            return dp[idx][l]

        for i in range(len(arr)):
            helper(i, self.lg[len(arr) - i])

        def query(l, r):
            k = self.lg[r - l + 1]
            return self.fn(dp[l][k], dp[r - 2**k + 1][k])

        return query


def solve():
