def sort_insert(lst: list) -> list:
    for i in range(1, len(lst)):
        j = i
        while (j > 0) and (lst[j] < lst[j-1]):
            lst[j], lst[j-1], = lst[j-1], lst[j]
            j -= 1
    return lst

def bin_search_count(lst: list, target: int) -> int:
    l, r = -1, len(lst)
    while r > (l+1):
        mid = (l + r) // 2
        elem = lst[mid]
        if elem <= target:
            l = mid
        else:
            r = mid
    if l == -1:
        return 0
    elif l == len(lst):
        return len(lst)
    return l+1


