import heapq

n, L = [int(x) for x in input().split()]
costs = [int(x) for x in input().split()]

def heuristic(remaining, lowest_cost_per_liter):
    return remaining * lowest_cost_per_liter

def neighbors(remaining, costs):
    return ((max(0, remaining - 2 ** power), cost) for power, cost in enumerate(costs))

def a_star(L, costs):
    lowest_cost_per_liter = min(cost / 2 ** power for power, cost in enumerate(costs))

    # State is (h, remaining)
    g_score = {}
    g_score[L] = 0

    f_score = {}
    f_score[L] = heuristic(L, lowest_cost_per_liter)

    open_queue = [(f_score[L], L)]
    open_set = {L}

    while len(open_queue) > 0:
        current_f, current_remaining = heapq.heappop(open_queue)

        if current_remaining == 0:
            return g_score[0]

        if current_remaining not in open_set:
            continue

        open_set.remove(current_remaining)
        for new_remaining, cost in neighbors(current_remaining, costs):
            new_g_score = g_score[current_remaining] + cost
            if new_remaining not in g_score or new_g_score < g_score[new_remaining]:
                g_score[new_remaining] = new_g_score
                f_score[new_remaining] = new_g_score + heuristic(new_remaining, lowest_cost_per_liter)

                heapq.heappush(open_queue, (f_score[new_remaining], new_remaining))

                if new_remaining not in open_set:
                    open_set.add(new_remaining)

    return None

# A quick optimization - we can assume we'll always use the lowest cost per liter
# when available.
