def dijkstra(algus_tipp, siht_tipp):
    # alguses, märgime, et kõik tipud on lõpmatult kaugel.
    # Selleks võib kasutada ka lihtsalt mõnda suurt numbrit
    kaugused = [float('inf')] * n
    # Kaugus alguskohast
    kaugused[algus_tipp-1] = 0
    heap = [(0, algus_tipp)]
    while len(heap) > 0:
        # Võtame vähima maksumusega tipu
        kaugus, tipp = heappop(heap)
        if tipp == siht_tipp:
            # Lõpus, tagastame tulemuse
            break
        # Kui oleme siin varem olnud, jätame vahele
        if kaugus > kaugused[tipp-1]:
            continue
        if tipp in stargates:
            for naaberTipp, kaal in stargates[tipp]:
                if kaugus + kaal < kaugused[naaberTipp-1]:
                    wait = 0
                    while kaugus + kaal + wait in canttravel[naaberTipp]:
                        wait += 1
                    kaugused[naaberTipp-1] = kaugus + kaal + wait
                    # Paneme uue kaaluga tipu omal siis heapi
                    heappush(heap, (kaugus + kaal + wait, naaberTipp))
                    # Kui vaja rada taastada, sea `eelmine[naaberTipp] = tipp`
    return kaugused[siht_tipp-1]
 
