def insertion_sort(l):
    for i in range(len(l)):
        for j in (range(i)):
            k = i - j
            if l[k] >= l[k - 1]:
                l[k - 1], l[k] = l[k], l[k - 1]
            else:
                break
    return l



def selection_sort(l):
    for i in range(len(l)):
        min_ind = i
        min_val = l[i]
        for j in range(i, len(l)):
            if min_val > l[j]:
                min_val = l[j]
                min_ind = j
        l[i], l[min_ind] = l[min_ind], l[i]
    return l


def bubble_sort(l):
    for i in range(len(l) - 1):
        for j in range(len(l) - 1 - i):
            if l[j] > l[j + 1]:
                l[j], l[j + 1] = l[j + 1], l[j]
    return l


