class IntervalTree:
    def __init__(self, n):
        self.n = n
        self.st = [0] * ((n << 2) + 7)
        self.lazy = [0] * ((n << 2) + 7)
    
    def fix(self, id, l, r):
        if self.lazy[id] == 0:
            return
        if self.lazy[id] > self.st[id]:
            self.st[id] = self.lazy[id]
        if l < r:
            self.lazy[id << 1] = max(self.lazy[id << 1], self.lazy[id])
            self.lazy[id << 1 | 1] = max(self.lazy[id << 1 | 1], self.lazy[id])
        self.lazy[id] = 0
    
    def update(self, u, v, value, id = 1, l = 1, r = -1):
        if r < 0:
            r = self.n
        if r < u or l > v:
            return
        self.fix(id, l, r)
        if u <= l and r <= v:
            self.lazy[id] = max(self.lazy[id], value)
            self.fix(id, l, r)
            return
        
        mid = (l + r) >> 1
        self.update(u, v, value, id << 1, l, mid)
        self.update(u, v, value, id << 1 | 1, mid + 1, r)
        self.st[id] = max(self.st[id << 1], self.st[id << 1 | 1])
    
    def get(self, u, v, id = 1, l = 1, r = -1):
        if r < 0:
            r = self.n
        self.fix(id, l, r)
        if l > v or r < u:
            return -1
        if u <= l and r <= v:
            return self.st[id]
        
        mid = (l + r) >> 1
        return max(self.get(u, v, id << 1, l, mid), self.get(u, v, id << 1 | 1, mid + 1, r))

