class Segment:
    def __init__(self, i, l, r):
        self.i = i
        self.l = l
        self.r = r

def mergeSort(segments, left, right):
    if left >= right:
        return
    else:
        middle = (left + right) // 2
        mergeSort(segments, left, middle)
        mergeSort(segments, middle + 1, right)
        merge(segments, left, middle, right)


def merge(segments, left, middle, right):
    inf = 1000000001
    L = segments[left: middle + 1]
    R = segments[middle + 1: right + 1]
    L.append(Segment(inf, inf, inf))
    R.append(Segment(inf, inf, inf))
    i = 0
    j = 0
    k = left
    while i < (middle - left + 1 + 1) and j < (right - middle + 1 + 1) and (L[i].l != inf or R[j].l != inf):
        if L[i].l < R[j].l:
            segments[k] = L[i]
            i += 1
        else:
            segments[k] = R[j]
            j += 1
        k += 1


