def ispalindrom(S: str) -> bool:
    length = len(S)
    counted = {i:S.count(i) for i in set(S)}
    values = counted.values()
    if not length % 2:
        return all([i % 2 == 0 for i in values])
    else:
        count_odd = 0
        for i in values:
            if count_odd > 1:
                return False
            if i % 2:
                count_odd += 1
        return True
    

def main() -> None:
    S = input()
    return First if ispalindrom(S) else Second


