def counting(s,l):
    return s.count(l)

def helper_delete(line, letter):
    return list(filter(lambda x: x != letter, line))

def help_filter(linet,y,i):
    length = len(linet) // 2
    line = linet[:length]  # split into two halves to increase filter speeds
    line2 = linet[length:]
    numl = counting(line, i)
    numl2 = counting(line2, i)
    if y>=numl:
        line = helper_delete(line,i)
        y-=numl
        if y == 0:
            print(''.join(line + line2))
    else:
        for num in range(numl):
            line.remove(i)
            y -= 1
            if y == 0:
                print(''.join(line + line2))
                break

    if y>=numl2:
        line2 = helper_delete(line2, i)
        y -= numl2
        if y == 0:
            print(''.join(line + line2))
    else:
        for num in range(numl2):
            line2.remove(i)

            y -= 1
            if y == 0:
                print(''.join(line + line2))
                break
    return y,line+line2


