def elect(a):
    if len(a)<=1:
        return 'No'
    elif len(a)==2:
        if a[0]==a[1]:
            return 'Yes'
        return 'No'
    i=0
    j=0
    for l in range (len(a)-1):
        if a[l]!=a[l+1]:
            i+=1
        else:
            j+=1
    if i==len(a)-1:
        return'No'
    elif j == len(a)-1 and (j+1)%2==0:
        return a
    elif j == len(a)-1:
        return 'No'
    while len(a)>2:
        p=a.pop(0)
        if p=='+' and a[0]=='-':
            if a[1]==a[0]:
                a.pop(0)
                a.pop(0)
                a.append(p)
            else:
                a.pop(0)
                a.append(p)
        elif p=='-' and a[0]=='+':
            if a[1]==a[0]:
                a.pop(0)
                a.pop(0)
                a.append(p)
        else:
            a.append(p)
        i=0
        for l in range (len(a)-1):
            if a[l]==a[l+1]:
                i+=1
        if i==len(a)-1:
            break
    return elect(a)
