def max_tables(r, g, b):
    if r + g + b < 3:
        return 0
    if r < 1 or g < 1 or b < 1:
        return 0
    min_balloons = min(r, g, b)
    max_balloons = max(r, g, b)
    if max_balloons > 2 * (min_balloons + (r+g+b - min_balloons - max_balloons)):
        t = (r + g + b - max_balloons) // 3
        return t + min(max_balloons, t + (r+g+b - min_balloons - max_balloons))
    else:
        r -= min_balloons
        g -= min_balloons
        b -= min_balloons
        t = (r + g + b) // 3
        return t + min_balloons

