    elif((number_characters_c == number_characters_a) or (number_characters_c == number_characters_b)):
        return True

def check_string_order(string):
    string_index = 0
    string_size = len(string)
    for letter in ["a", "b", "c"]:
        if(string[string_index] == letter):
            while(string[string_index] == letter):
                string_index += 1
                if(string_index == string_size):
                    break
        else:
            return False
    return True
    

