def dfs(svertex, adjm):
    clrs = [0] * len(adjm)  # 0-white, 1-gray, 2-black
    stack = [svertex]
    clrs[svertex] = 1
    while len(stack):
        cv = stack.pop()
        if clrs[cv]: #if cv is white
            clrs[cv] = 1 #make it gray
            for adjn in range(len(adjm)): #add all white adjacent nodes to stack
                if adjm[cv][adjn] and clrs[adjn] != 2:
                    stack.append(adjm[cv][adjn])
        if clrs[cv] == 1:
            return False #means that cycle is found
    return True


