def grandi(n1, n2, k1, k2):
    if n1 == 0:
        return 0
    s = set()
    for i in range(1, min(n1, k1 + 1)):
        s.add(grandi(n2, n1 - i, k2, k1))
    i = 0
    while i in s:
        i += 1
    return i


