def get_divisers(a, b, c):
  if b > c:
    b, c = c, b
  first = find_first(a, b)
  last = find_last(a, c)
  return (last - first) // a + 1

def find_first(a, b):
  val = b
  while val % a != 0:
    val += 1
  return val

def find_last(a, c):
  val = c
  while val % a != 0:
    val -= 1
  return val 

