def lucky(x):
    return str(x).count('4') + str(x).count('7') == len(str(x))

def factorial(n):
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

def generate_lucky(n):
    if n == 0:
        return 0
    s = str(n)
    count = 0
    for c in s:
        if c in ('4', '7'):
            count += 1
    return 2 ** count

def form(X, k, F):
    result = []
    n = len(X)
    indexes = list(range(n))
    for i in range(n):
        index = k // F[n - i - 1]
        k %= F[n - i - 1]
        result.append(X.pop(index))
    return result

