def find_path(graph, start, end, path=[]):
    path = path + [start]
    if start == end:
        return path
    if not start in graph:
        return None
    if graph[start] not in path:
        newpath = find_path(graph, graph[start], end, path)
        if newpath: return newpath
    return None



