statements = statements[:rez+1]

memo = dict()

def calc(ind,ident):
    if (ind, ident) in memo:
        return memo[ind, ident]
    if ind == len(statements):
        return 1
    ALL = 0
    if statements[ind] == 's':
        for k in range(1, ident + 1):
            ALL += calc(ind + 1, k)
    else:
        for k in range(1, ident + 1):
            i = ind
            size = k
            while i < len(statements) and statements[i] == 'f':
                i += 1
                size += 1
            i += 1
            if i < len(statements):
                ALL += calc(i, size)
            else:
                ALL += 1
    memo[ind,ident] = ALL % MOD
    return memo[ind, ident]

