def solve():
    def dfs(start, depth):
        used[start] = 1
        if depth not in m:
            m[depth] = [words[start]]
        else:
            m[depth].append(words[start])

        for u in g[start]:
            dfs(u, depth + 1)

    def parse(it, ind_world, childs):
        used[ind_world] = 1
        if it >= len(s):
            return 0
        rem_childs = childs * 1
        i = it * 1
        while rem_childs != 0:
            g[ind_world].append(i)
            i = parse(i + 1, i, s[i])
            rem_childs -= 1
        return i

