import random
import sys
from math import inf
from types import GeneratorType


class FastIO:
    def __init__(self):
        self.random_seed = random.randint(0, 10 ** 9 + 7)
        return

    @staticmethod
    def read_int():
        return int(sys.stdin.readline().strip())

    @staticmethod
    def read_float():
        return float(sys.stdin.readline().strip())

    @staticmethod
    def read_list_ints():
        return list(map(int, sys.stdin.readline().strip().split()))

    @staticmethod
    def read_list_floats():
        return list(map(float, sys.stdin.readline().strip().split()))

    @staticmethod
    def read_list_ints_minus_one():
        return list(map(lambda x: int(x) - 1, sys.stdin.readline().strip().split()))

    @staticmethod
    def read_str():
        return sys.stdin.readline().strip()

    @staticmethod
    def read_list_strs():
        return sys.stdin.readline().strip().split()

    @staticmethod
    def read_list_str():
        return list(sys.stdin.readline().strip())

    @staticmethod
    def st(x):
        return print(x)

    @staticmethod
    def lst(x):
        return print(*x)

    @staticmethod
    def round_5(f):
        res = int(f)
        if f - res >= 0.5:
            res += 1
        return res

    @staticmethod
    def max(a, b):
        return a if a > b else b

    @staticmethod
    def min(a, b):
        return a if a < b else b

    @staticmethod
    def ceil(a, b):
        return a // b + int(a % b != 0)

    def hash_num(self, x):
        return x ^ self.random_seed

    @staticmethod
    def accumulate(nums):
        n = len(nums)
        pre = [0] * (n + 1)
        for i in range(n):
            pre[i + 1] = pre[i] + nums[i]
        return pre

    def inter_ask(self, lst):
        self.lst(lst)
        sys.stdout.flush()  # which is necessary
        res = self.read_int()
        return res

    def inter_out(self, lst):
        self.lst(lst)
        sys.stdout.flush()   # which is necessary
        return

    @staticmethod
    def bootstrap(f, queue=[]):
        def wrappedfunc(*args, **kwargs):
            if queue:
                return f(*args, **kwargs)
            else:
                to = f(*args, **kwargs)
                while True:
                    if isinstance(to, GeneratorType):
                        queue.append(to)
                        to = next(to)
                    else:
                        queue.pop()
                        if not queue:
                            break
                        to = queue[-1].send(to)
                return to

        return wrappedfunc


class Solution:
    def __init__(self):
        return

    @staticmethod
    def main(ac=FastIO()):
        n, m, limit = ac.read_list_ints()
        dct = [[] for _ in range(n)]
        degree = [0]*n
        for _ in range(m):
            u, v, t = ac.read_list_ints()
            u -= 1
            v -= 1
            dct[u].append([v, t])
            degree[v] += 1
        stack = [0]
        sub = [None]*n
        sub[0] = [0] + [inf]*(n-1)
        parent = [[-1]*n for _ in range(n)]
        while stack:
            nex = []
            for i in stack:
                for j, t in dct[i]:
                    if not sub[j]:
                        tmp = [inf]*n
                    else:
                        tmp = sub[j]
                    for k in range(n-1):
                        x = sub[i][k] + t
                        if x < tmp[k+1]:
                            tmp[k+1] = x
                            parent[j][k+1] = i
                    sub[j] = tmp
                    degree[j] -= 1
                    if not degree[j]:
                        nex.append(j)
                if i != n-1:
                    sub[i] = None
            stack = nex[:]
        for j in range(n-1, -1, -1):
            if sub[-1][j] <= limit:
                ac.st(j+1)
                path = [n-1]
                for x in range(j, 0, -1):
                    path.append(parent[path[-1]][x])
                path.reverse()
                ac.lst([x+1 for x in path])
                break

        return


