def cheapest_available(position, fuel, station, price):
    min_price = 999999
    for j in range(len(station)):
        if station[j] > position and price[j] < min_price and station[j] - position <= fuel:
            location = station[j]
            min_price = price[j]
    return(location, min_price)
def cheaper(position, current_price, station, price):
    for j in range(len(station)):
        if station[j] > position and price[j] < current_price:
            return (station[j], price[j])
    return False
def route(position, destination, fuel, maxfuel, station, price, money):
    if destination - position <= fuel:
        return money
    elif possible(destination, maxfuel, station) is False:
        return -1
    else:
        (temp1, temp2) = cheapest_available(position, fuel, station, price)
        if cheaper(temp1, temp2, station, price) is False:
            if destination - temp1 <= maxfuel:
                return money + (destination - fuel - position)*temp2
            else:
                return route(temp1, destination, maxfuel, maxfuel, station, price, money + (maxfuel - fuel + temp1 - position)*temp2)
        else:
            (pep1, pep2) = cheaper(temp1, temp2, station, price)
            if pep1 - temp1 <= maxfuel:
                return route(temp1, destination, pep1 - temp1 , maxfuel, station, price, money + (pep1 - fuel)*temp2)
            else:
                return route(temp1, destination, maxfuel, maxfuel, station, price, money + (maxfuel - fuel + temp1)*temp2)

