# 输入n,输出该问题下数列lst的最终长度2^n-1
def find_n(a):
    left = 1
    right = a

    while left <= right:
        mid = (left + right) // 2
        lower_bound = 2**(mid-1) - 1
        upper_bound = 2**mid - 1

        if lower_bound <= a <= upper_bound:
            temp = 2**mid - 1
            return (temp,mid)
        elif a <= lower_bound:
            right = mid - 1
        else:
            left = mid + 1

    return -1

def count_ones(n,l,r):   
    L,T = find_n(n)
    lst = [1] * L
    op_index = [L // 2]

    for i in range(T-1,0,-1):
        if i < T - 1:
            index = 0
            for num in range(len(op_index)):
                num += index
                op_index[num:num+1] = [op_index[num]-2**i,op_index[num]+2**i]
                index += 1
        if n % 2 == 0:
            for item in op_index:
                lst[item] = 0
        n = n // 2

    res = lst[l-1:r].count(1)
    return res


