    def _swap(self, i, j):
        xi, xj = self._heap[i], self._heap[j]
        self._item_to_pos[xi], self._item_to_pos[xj] = j, i
        self._heap[i], self._heap[j] = xj, xi

    def _swap_if_needed(self, pos):
        if _left(pos) > self._end():
            return None
        if _right(pos) > self._end() or self._heap[_left(pos)] < self._heap[_right(pos)]:
            smaller_child = _left(pos)
        else:
            smaller_child = _right(pos)
        if self._heap[pos] < self._heap[smaller_child]:
            return None
        self._swap(pos, smaller_child)
        return smaller_child

    def _siftup(self, pos):
        while pos:
            pos = _parent(pos)
            if self._swap_if_needed(pos) is None:
                break
        return pos

    def _siftdown(self, pos):
        while pos is not None:
            new_pos = self._swap_if_needed(pos)
            if new_pos is None:
                break
            pos = new_pos
        return pos

    def insert(self, x):
        self._heap.append(x)
        self._item_to_pos[x] = self._end()
        self._siftup(self._end())

    def pop(self):
        item = self._heap[0]
        self.remove(item)
        return item

    def remove(self, item):
        pos = self._item_to_pos[item]
        self._swap(pos, self._end())
        self._heap.pop()
        del self._item_to_pos[item]
        self._siftup(pos)
        self._siftdown(pos)

#!! non-hashable items
