def dijkstra(g, start, end):
    distances = dict.fromkeys(g, float('inf'))
    parents = dict.fromkeys(g)
    distances[start] = 0
    pending = PQ()
    pending.insert((0, start))
    while pending:
        _, current = pending.pop()
        if current == end:
            break
        for v, weight in g[current]:
            if weight < 0:
                raise RuntimeError('negative edge weight')
            if distances[current] + weight < distances[v]:
                parents[v] = current
                if distances[v] != float('inf'):
                    # (distances[v], v) must still be in pending
                    pending.remove((distances[v], v))
                distances[v] = distances[current] + weight
                # add v, or add back v with the new priority, to the heap
                pending.insert((distances[v], v))
    else:
        return None
    path = []
    v = end
    while v is not None:
        path.append(v)
        v = parents[v]
    return path[::-1]


def main():
