second_to_first = [dict() for _ in second]

def solve():
    for i, (f1, f2) in enumerate(first):
        for j, (s1, s2) in enumerate(second):
            intersection = {f1, f2} & {s1, s2}
            if len(intersection) == 1:
                common = intersection.pop()
                first_to_second[i][j] = second_to_first[j][i] = common

    for i in range(len(first_to_second)):
        if len(set(first_to_second[i].values())) > 1:
            return -1

    for j in range(len(second_to_first)):
        if len(set(second_to_first[i].values())) > 1:
            return -1

    choices = set(sum([list(f.values()) for f in first_to_second], [])) | set(sum([list(s.values()) for s in second_to_first], []))
    return 0 if len(choices) > 1 else 1

