def solve(n, m, k, arr):
    if m<=k:
        return 0
    if sum(arr)+k-n < m:
        return -1

    count = 0
    n -= (k-1)

    for i in range(n):
        if n == 0:
            break
        if arr[i]-n == 0:
            n -= arr[i]
            count += 1
        elif arr[i] <= n:
            n -= (arr[i] - 1)
            count += 1
        else:
            n = 0
            count += 1
    if n == 0:
        return count
    else:
        return -1


