BASE = ( math.sqrt( 5 ) + 1 ) / 2.0 ;
EPS = 1e-10 ;

class Node : 
    def __init__( self , ta = 0 , tb = 0 ) :
        
        self.a = ta ; 
        self.b = tb ;
        
    def get( self ) :
        return self.a * BASE + self.b ; 
    
    def out( self ):
        print( "self.a: " , self.a , self.b ) ;


        
class Solution:

    def init( self ) :
        
        M = 100 ; 
        self.power = [ 0 ] * M ; 
        self.power [ 0 ] =1 ;
        self.power[ 1 ] = BASE ;
        for i in range(  2 , M ,1 ) :
            self.power[i] = self.power[i-1] * BASE ; 
            
    def to( self , val_list  , start ) :

        ret = 0 ; 
        for i in range( start , -1 , -1 ) : 
            
            ret += val_list[i] * self.power[i] ; 
            # ret = ret * BASE + val_list[i] ; 
        
        return ret ; 
    
    def get( self , a , b ) :
        
        n = len( a ) ;
        m = len( b ) ;
        
        i = n - 1 ; 
        j = m - 1 ; 
        
        while( i >= 0 and j >= 0  ) :
            while( i < n and a[i] == 0 ) :
                i = i - 1 ; 
            
            while( j < m and b[j] == 0 ) :
                j = j - 1 ; 
            
            if( i >= n and j >= m ) :
                return 0 ;
            
            if( i >= n ) :
                return -1 ;

            if( j >= m ) :
                return 1 ; 
            
            # print ( "i: ", i ,a[ 0 : i + 1 ] ) ;
            # print ( "j: " , j , b[ : j +1 ] ) ; 
            
            if( i - j >= 2 ) :
                return 1 ; 
            if( j - i >= 2 ) :
                return -1 ; 
            
            if( i == j ) :
                a[i] -= 1 ;
                b[j] -= 1 ; 
                continue ; 
            
            max_ij = max( i , j ) ; 
            if( max_ij <= 5 ) :
                
                # print( "max_ij: " ,max_ij ) ; 
                
                ya =  self.to( a , i ) ;
                yb =  self.to( b , j ) ; 
                
                # print( "ya " , ya , yb ) ; 
                
                if( ya > yb + EPS ) :
                    return 1 ; 
                    
                elif( ya < yb - EPS ) :
                    return -1 ; 

                return 0 ; 
            
            
            
            if( i < j ) :  # // i == j + 1 
                ta , tb = b , a  ; 
                di , dj = j , i ;
                
            elif( i > j ) : 
                ta , tb = a , b ;
                di , dj = i , j ; 
            
            
            if( dj + 1 != di ) :
                print ( "error \n" ) ;
                sys.exit( -1 ) ;
                
            ta[ di ] -= 1 ; 
            ta[ di - 1 ] += 1 ;
            ta[ di - 2 ] += 1 ;
            
            ta[ di - 1 ] -= 1 ; 
            tb[ dj ] -= 1 ; 
        
        return 0 ;   
        
    def input( self ) :
        
        self.init( ) ; 
        
        T = 1 ; 
        for _ in range( T ) : 
            
            a = [ int( x ) for x in input().strip() ] 
            b = [ int( x ) for x in input().strip() ] ; 
            
            a.reverse( ); 
            b.reverse( ) ; 
            
            ret = self.get( a , b ) ;
            
            
            ans= "=" ;
            if( ret == 1  ) :
                ans = ">" ; 
                
            elif( ret == -1  ) :
                ans = "<" ; 
            
            print( ans ) ; 
            
    
