            # check if has won
            if check_all_equals([(r, c), (r, c + 1), (r, c + 2)], p):
                return True
            if check_all_equals([(r, c), (r + 1, c), (r + 2, c)], p):
                return True
            if check_all_equals([(r, c), (r + 1, c + 1), (r + 2, c + 2)], p):
                return True
    return False


