import sys, threading

def main():

    n, m = map(int, input().split())
    grid = [list(input()) for _ in range(n)]

    sz, parent = {}, {}

    def find(x):
        if x == parent[x]:
            return x 
        parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        
        x = find(x)
        y = find(y)

        if y == x:
            return  

        if sz[x] > sz[y]:
            x, y = y, x 
        
        sz[y] += sz[x]
        parent[x] = y 

    DIR = [(-1, 0), (1, 0), (0, 1), (0, -1)]
    
    def fake(i, j):
        s = set()
        for di, dj in DIR:
            ni = i + di 
            nj = j + dj 
            if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == '.': 
                s.add(find((ni, nj)))
        
        res = 0 
        for x in s:
            res += sz[x]
        
        return res

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                sz[i, j] = 1
                parent[i, j] = (i, j)
                if i > 0 and grid[i - 1][j] == '.':
                    union((i, j), (i - 1, j))
                if j > 0 and grid[i][j - 1] == '.':
                    union((i, j), (i, j - 1))
    
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*':
                print(fake(i, j) % 10 + 1, end="", flush=False)
            else:
                print('.', end="", flush=False)
        print(flush=False)

