    elif data>=array[end]:
        return end+1
    else:
        while start<=end:
            mid=int((start+end)/2)
            if array[mid]<=data and array[mid+1]>data:
                return mid+1
            elif array[mid]<data:
                start=mid
            else:
                end=mid
        return start

