class Node :
    def __init__(self, ID) :
        self.ID = ID
        self.cons = []
        self.visited = 0

    def __str__(self) :
        out = "Node Number is " + str(self.ID) + " \n"
        out += "Connected to :-"
        for node in self.cons :
            out += "Node " + str(node.ID) + " "
#        out += "\n"
        return out


class Graph :
    def __init__(self, no_of_nodes = 0, start_index = 0) :
        self.Nodes = []
        self.no_of_nodes = no_of_nodes
        self.start_index = start_index
        for i in range(no_of_nodes) :
            self.Nodes.append(Node(start_index + i))

    def addEdge(self, Node1, Node2) :
        self.Nodes[Node1 - self.start_index].cons.append(self.Nodes[Node2 - self.start_index])
        self.Nodes[Node2 - self.start_index].cons.append(self.Nodes[Node1 - self.start_index])

    def __str__(self) :
        out = "Graph : Number of Nodes = " + str(self.no_of_nodes) + " \n"
        for node in self.Nodes :
            out += str(node)
        return out

    def clearVisits(self) :
        for node in self.Nodes :
            node.visited = 0

    def maxDepth(self, NodeID) :
        startNode = self.Nodes[NodeID - self.start_index]
        templist = []
        DFS(startNode, templist, 0, 0)
        self.clearVisits()
        return templist[-1]

    def diameter(self) :
        node, depth = self.maxDepth(self.Nodes[0].ID)
        return self.maxDepth(node.ID)
#        return (node, depth)

