from collections import defaultdict
def dijkstra(graph,visited):
    n = len(visited)
    infinite = float('inf')            #creating a variable which gives reference to infinite
    dist = [infinite]*(n-1)            #creating an distance list & assigning to infinite
    parent = [-1]*n                    #creating an array just to track the path 
    
    ind_hash = {}
    for i in range(n):
        ind_hash.update({visited[i]:i})

    try:
        dist.insert(visited.index(1),0)                   #assigning the distance value of source = 0 
    except:
        return -1
    
    while True:
        min_dist = min(dist)            #finding the minimum distance among all the node
        ind = dist.index(min_dist)      #finding the position of the node which has the minimum distance
        if min_dist != infinite:        #checking whether all the nodes aren't get visited
            if visited[ind] != False:
                i = visited[ind]
                visited[ind] = False         #checking that the node with the minimum distance is not visited
                for edge in graph[i]:
                    if visited[ind_hash[edge[0]]]:
                        di = min_dist + edge[1]
                        if di<dist[ind_hash[edge[0]]]:
                            dist[ind_hash[edge[0]]] = di
                            parent[ind_hash[edge[0]]] = ind
                dist[ind] = infinite
        else:
            break
    return parent
        
