def y(n) -> int:
    if n == 0:
        return False
    length = 0
    i = 0
    while 2 ** i <= n:
        length += 2 ** i
        i =i+1
    return insert(int(n), int(length), int((length + 1) / 2))

def insert(n, len, mid) -> int:
    if r < mid - len / 2 or l > mid + len / 2:
        return False
    if len == 1:
        return n % 2
    distance = int((len + 1) / 4)
    if l <= mid <= r:
        return insert(int(n / 2), int(len / 2), int(mid - distance)) + n % 2 + insert(int(n / 2), int(len / 2),int(mid + distance))
    if mid > r:
        return insert(int(n / 2), int(len / 2), int(mid - distance))
    if l > mid:
        return insert(int(n / 2), int(len / 2), int(mid + distance))

