def getSteps(n, m, results):
    if results[n] >= 0:
        return results[n]
    if n <= 0:
        return float('inf')
    if n >= m:
        return n - m
    results[n] = -1
    decr = float('inf')
    doubled= float('inf')
    if results[n-1] == -2:
        decr = getSteps(n-1, m, results)
    if results[2*n] == -2:
        doubled = getSteps(2*n, m, results)
    res = 1 + min(decr, doubled)
    results[n] = res
    return res

