def rotate(matrix):
    global n, m
    new_matrix = [[0 for i in range(n)] for j in range(m)]
    for i in range(n):
        for j in range(m):
            new_matrix[j][i] = matrix[i][j]
    return new_matrix


def check(tab, n, m):
    color = tab[0][0]
    for i in range(n // 3):
        for j in range(m):
            if tab[i][j] != color:
                return False
    color = tab[n // 3][0]
    for i in range(n // 3, n // 3 * 2):
        for j in range(m):
            if tab[i][j] != color:
                return False
    color = tab[n // 3 * 2][0]
    for i in range(n // 3 * 2, n):
        for j in range(m):
            if tab[i][j] != color:
                return False
    return True


