from collections import defaultdict
from queue import PriorityQueue

INF = 10000001

class AdjacentNode:
  def __init__(self, node: int, weight: int):
    self.node = node
    self.weight = weight


class WeightedGraph:
  def __init__(self):
    self.nodes = set([])
    self.value = defaultdict(list)

  def add_node(self, node: int):
    self.nodes.add(node)

  def add_edge(self, node_a: int, node_b: int, weight: int):
    self.nodes.add(node_a)
    self.nodes.add(node_b)
    self.value[node_a].append(AdjacentNode(node_b, weight))

class Dijkstra:
  def __init__(self, graph: WeightedGraph, origin: int, destination: int):
    self.destination = destination
    self.distances = defaultdict(int)
    self.previous = defaultdict(int)
    self.explored_nodes = defaultdict(bool)
    self.graph = graph
    for node in graph.nodes:
      if (origin == node):
        self.distances[origin] = 0
      else:
        self.distances[node] = INF
      self.explored_nodes[node] = False
      self.previous[node] = None
    self.queue = PriorityQueue()
    self.queue.put((0, origin))


  def run(self):
    while(not self.queue.empty()):
      min_value, current_node = self.queue.get()
      self.explored_nodes[current_node] = True
      for adjacent_node in self.graph.value[current_node]:
        if (self.explored_nodes[adjacent_node.node]): continue
        new_distance = self.distances[current_node] + adjacent_node.weight
        if (new_distance < self.distances[adjacent_node.node]):
          self.distances[adjacent_node.node] = new_distance
          self.previous[adjacent_node.node] = current_node
          self.queue.put((new_distance, adjacent_node.node))
      if (current_node == self.destination):
        return (self.previous, self.distances[self.destination])
    return (self.previous, INF)

