def find_indices(tapes, key) :
    i, j = 0, 0
    key_indices = []

    while i < len(tapes) :
        while i < len(tapes) and tapes[i] == key :
            i += 1

        j = i   

        while j < len(tapes) and tapes[j] != key :
            j += 1

        if i != len(tapes) or j != len(tapes) :
            key_indices.append((i, j))
        i = j

    return key_indices

