from heapq import heappush, heappop
import collections
class Vertex:
    def __init__(self, name):
        self.name = name
        self.scatch = 0
        self.prev = None
    def __lt__(self, other):
        return self.name - other.name

# 
def dijkstra(start, graph):
    # find path between 1 to vertex n
    hq = []
    seen = set()
    # cost to itself is zero (cost, vertex)
    heappush(hq, (0, Vertex(start)))
    while hq:
        cost, vertex = heappop(hq)
        if vertex.name == len(graph) - 1:
            res = []
            while vertex != None:
                res.append(vertex.name + 1)
                vertex = vertex.prev
            return ' '.join(str(i) for i in res[::-1])

        if vertex.name not in seen:
            seen.add(vertex.name)
            for item in graph[vertex.name]:
                if item[1] not in seen:
                    newVertex = Vertex(item[1])
                    newVertex.prev = vertex
                    heappush(hq, (item[0] + cost, newVertex))

    return -1


