class Point():
    def __init__(self, x, y):
        self.x = x
        self.y = y
        self.cords = (x, y)
        self.quad = 3

    def __repr__(self):
        return "({};{})".format(self.x, self.y)

    def find_quadrant(self):
        x, y = self.cords

        if x >= 0 and x >= y >= 0:
            self.quad = 0

        if x > 0 and y < 0 and x > (-y + 1):
            self.quad = 0

        if y > 0 and (abs(x/y) < 1 or x/y == -1):
            self.quad = 1

        if x < 0 and (abs(y/x) < 1 or y/x == 1):
            self.quad = 2

    def find_spiral_turn(self):
        if self.cords == (0, 0) or self.cords == (1, 0):
            return 0

        if self.quad == 0:
            return (self.x-1) * 4 + 1

        if self.quad == 1:
            return (self.y-1) * 4 + 2

        if self.quad == 2:
            return (abs(self.x)-1) * 4 + 3

        if self.quad == 3:
            return (abs(self.x)-1) * 4 + 3

        if self.quad == 4:
            return (abs(self.y)-1) * 4 + 4



