def retMaxConsecutive(string, n, k, choice):

    if string.count(choice) <= k:
        return n

    maxi = -1
    for i in range(n):
        count = 0
        limit = 0
        for j in range(i, n):
            if string[j] != choice:
                if limit > k:
                    break
                count += 1
                limit += 1
            else:
                count += 1
        maxi = max(maxi, count)
    return (maxi)




