import sys

MOD = 10 ** 9 + 7

class Matrix:
  def __init__(self, n):
    self.n = n
    self.matrix = [[0] * n for _ in range(n)]

  def __getitem__(self, pos):
    x, y = pos
    return self.matrix[x][y]

  def __setitem__(self, pos, value):
    x, y = pos
    self.matrix[x][y] = value

  def __mul__(self, other_matrix):
    n = self.n
    r = Matrix(n)
    for i in range(n):
      for j in range(n):
        for k in range(n):
          r[i, j] = (r[i, j] + self[i, k] * other_matrix[k, j]) % MOD
    return r

  def __str__(self):
    r = 'DIM N: %d\n' % self.n
    for i in range(self.n):
      r += ' '.join(list(map(str, self.matrix[i]))) + '\n'
    r += '-' * 2 * self.n + '\n'
    return r


def power(a, n):
  r = Matrix(a.n)
  for i in range(a.n):
    r[i, i] = 1
  while n > 0:
    if n % 2 == 1:
      r = r * a
    a = a * a
    n //= 2
  return r

