from collections import defaultdict


def get_top_left(x, y) -> tuple[int, int]:
    val = min(x, y) - 1
    new_x = x - val
    new_y = y - val
    if x <= 0 or y <= 0:
        return x, y
    else:
        return new_x, new_y


def get_top_right(x, y) -> tuple[int, int]:
    val = min(x - 1, 1000, y)
    new_x = x - val
    new_y = y + val
    if x <= 0 or y > 1000:
        return x, y
    else:
        return new_x, new_y


def get_number_of_attacks(cnt) -> int:
    return (cnt * (cnt - 1)) // 2


