import sys
from queue import heappush, heappop


class Node:
    def __init__(self, num):
        self.visited = False
        self.num = num
        self.prev = -1
        self.edges = {}

    def add_edge(self, edge):
        if edge[1] in self.edges:
            if edge[0] < self.edges[edge[1]]:
                self.edges[edge[1]] = edge[0]
            else:
                return
        else:
            self.edges[edge[1]] = edge[0]


def dijkstra(start, goal):
    queue = [(0, start, -1)]
    while len(queue) > 0:
        running_cost, node, origin = heappop(queue)
        node.prev = origin
        if node == goal:
            return goal
        node.visited = True        
        for d, c in node.edges.items():
            if not d.visited:
                heappush(queue, (running_cost + c, d, node.num))
    return -1

