def solve(n,x):
    from collections import Counter
    ct = Counter(map(int,input().split()))
    s = sum([v*ct[v] for v in ct.keys()])
    d = {s-v: ct[v] for v in ct.keys()}
    for v in sorted(d.keys()):
        if d[v]%x==0:
            k = 0
            while d[v]%x==0:
                k += 1
                d[v] //= x

            if v+k in d:
                d[v+k] += d[v]
            else:
                return v+k
        else:
            return v
    return -1

