from collections import defaultdict
def solve(poland, enemy):
    n = len(poland)
    m = len(enemy)
    if n < m:
        print("NO")
        return
    if n > m:
        print("YES")
        return
    d = defaultdict(int)

    for word in poland:
        d[word] += 1
    for word in enemy:
        d[word] += 1

    intersection = [word for word in d if d[word] == 2]

    for idx, word in enumerate(intersection):
        if idx % 2 == 0:
            enemy.remove(word)
        else:
