def costs(position,rooms,i):
    if position[1] - rooms[i][1] == 0:
        cost = abs(rooms[i][0] - position[0])
    else:
        temp_cost = position[0]
        new_position = [0, position[1]]
        temp_cost += (abs(rooms[i][0] - new_position[0]) + abs(rooms[i][1] - new_position[1]))
        temp_cost1 = abs(n_m[1] - position[0])
        new_position1 = [n_m[1], position[1]]
        temp_cost1 += (abs(rooms[i][0] - new_position1[0]) + abs(rooms[i][1] - new_position1[1]))
        if temp_cost > temp_cost1:
            cost = temp_cost1
        else:
            cost = temp_cost
    return cost

def path_cost(position,rooms):
    MIN=0
    index = 0
    y = rooms[0][1]
    for i in range(len(rooms)):
        if rooms[i][1]>y:
            continue
        cost=costs(position,rooms,i)
        if MIN==0:
            MIN = cost+1
        if (cost < MIN):
            MIN = cost
            index = i
            y = rooms[i][1]
        elif cost == MIN:
            index=judge(i,index,rooms)
            MIN=costs(position,rooms,index)
            y = rooms[index][1]
    return [MIN,index]




