from collections import deque
def reposts(n, d, start, end):
    queue = deque()
    queue.append((start, 1))
    visited = set()

    while len(queue) != 0:
        v = queue.popleft()
        if v[0] in visited:
            return
        visited.add(v[0])
        if v[0] == end:
            return v[1]
        neighbours = d[v[0]] if v[0] in d else []
        for neighbour in neighbours:
            if neighbour not in visited:
                queue.append((neighbour, v[1] + 1))

    return
