import random
def power(a,n,p) :
    res = 1
    while n > 0:
        if n & 1:
            res = (res * a)%p
        a = (a*a)%p
    return res
def is_prime(n,k=10):
    if n <= 1 or n == 4:
        return False
    if n <= 3:
        return True
    r,d = 0, n-1
    while d % 2 == 0:
        r += 1
        d //= 2
    for _ in range(k):
        a = random.randint(2,n-2)
        x = power(a,d,n)
        if x == 1 or x == n-1:
            continue
        for _ in range(r-1):
            x = (x*x)%n
            if x == n-1:
                break
        else:
            return False
    return True
