    if arr[i][0] == '+':
        x += 1
        n -= 1
        if n == 0:
            return x

    elif arr[i][-1] == '+':
        n -= 1
        if n == 0:
            return x
        x += 1

    elif arr[i][0] == '-':
        x -= 1
        n -= 1
        if n == 0:
            return x

    elif arr[i][-1] == '-':
        n -= 1
        if n == 0:
            return x
        x -= 1
    return calc(n, x, arr, i + 1)


