        s, t = t, s

    substring = ''
    if len(s) == 1:
        substring = s
    else:
        for i in range(len(s) - 1):
            if s[i:len(s)] in t:
                substring = s[i:len(s)]
                break

    if len(t.split(substring)) > 1 and t.split(substring)[1] != '':
        return len(s) + len(t)

