def u(aa,bb):
    if len(aa)-1==bb:
        return -1
    else:
        return int(aa[bb+1:len(aa)])

def seg_sum(n):
    j=len(n)-1
    total=h(0)
    for i in range(0,len(n)):
        x_i = int(n[i])
        total+=x_i*f(j-i)+g(x_i)*10**(j-i)+h(x_i)*(1+u(n,i))
    if n[j] != '0':
        total+=h(n[j])
    return int(total)

