class FindUnion:
    def __init__(self, n):
        self.n = n
        self.root = [i for i in range(n)]
        self.cnt = [1 for i in range(n)]

    def find(self, a) -> int:
        if self.root[a] == a:
            return a
        res = self.find(self.root[a])
        self.root[a] = res
        return res

    def join(self, a, b):
        roota = self.find(a)
        rootb = self.find(b)
        if roota == rootb:
            return None
        if self.cnt[roota] <= self.cnt[rootb]:
            [roota, rootb] = [rootb, roota]
        self.cnt[roota] += self.cnt[rootb]
        self.root[rootb] = roota
        return roota

    def get_roots(self):
        for i in range(self.n):
            if self.root[i] == i:
                yield i


