def gcd(a,b):
    if a == 0:
        return b
    elif b == 0:
        return a
    else:
        k = 0
        while (a|b)&1 == 0:
            a>>=1
            b>>=1
            k+=1

        while a and a&1 == 0:
            a>>=1

        while b and b&1 == 0:
            b>>=1

        if a>b:
            a,b = b,a

        b -= a

        return a<<k

