    if i==0:
        a=abs(lst[-1]-lst[0])
        b=abs(lst[1]-lst[0])
    elif i==len(lst)-1:
        a=abs(lst[i]-lst[0])
        b=abs(lst[i]-lst[i-1])
    else:
        d=abs(lst[i]-lst[i-1])
        e=abs(lst[i]-lst[i-1])
        f=abs(lst[i]-lst[0])
        g=abs(lst[i]-lst[-1])
        if d<e:
            b=d
        else:
            b=e
        if g<f:
            a=f
        else:
            a=g
    return b,a
