def solve(m,h1,a1,x1,y1,h2,a2,x2,y2):
    for i in range(m):
        h1 = (x1*h1 + y1) %m
        if h1 == a1:
            k1 = i+1
            for j in range(m):
                h1 = (x1*h1 + y1) %m
                if h1 == a1:
                    period1 = j+1
                    break
            else:
                period1 = 0
            break
    else:
        return -1

    for i in range(m):
        h2 = (x2*h2 + y2) %m
        if h2 == a2:
            k2 = i+1
            for j in range(m):
                h2 = (x2*h2 + y2) %m
                if h2 == a2:
                    period2 = j+1
                    break
            else:
                period2 = 0
            break
    else:
        return -1

    if k1 == k2:
        return k1
    elif period1 == 0 and period2 == 0:
        return -1
    else:
        gcd, l1, l2 = euclid_algorithm(period1, -period2)
        if (k2 - k1)%gcd : return -1
        l1 *= (k2 - k1)//gcd 
        l2 *= (k2 - k1)//gcd #now l1*period1 + k1 == l2*period2 + k2
        while l1 < 0 or l2 < 0:
            l1 += period2//gcd
            l2 += period1//gcd
        return l1*period1 + k1

