def solve(tree):
    ans = 0
    visited = {1}
    
    def dfs(node):
        nonlocal ans
        res = []
        for child in tree[node]:
            if child not in visited:
                visited.add(child)
                res.append(dfs(child))
        res.sort()
        if not res:
            ans = max(ans, 1)
            return 1
        if len(res) == 1:
            ans = max(ans, 1 + res[-1])
        else:
            ans = max(ans, 1 + res[-1] + res[-2])

        return 1 + res[-1]
        
    dfs(1)
    return ans if not ans else ans - 1

