def solve():
    def cntbit(x):
        ret = 0
        while x:
            ret += 1
            x >>= 1
        return ret

    # 判断 x 是否通过一定的偏移可以转化为 mask
    def check(mask, x):
        ret = -1
        maskcnt = cntbit(mask)
        xcnt = cntbit(x)
        for i in range(xcnt):
            # 向右移动 i 个位置，向左移动 maskcnt - xcnt + i 个位置，最后长度和 mask 一样
            left = maskcnt - xcnt + i
            if left < 0:
                continue
            if ((x >> i) << left) == mask:
                # 答案即为变化次数
                if ret < 0 or ret > i + left:
                    ret = i + left
        return ret

    n = int(input())
    a = list(map(int, input().split()))
    maxn = max(a)
    maxncnt = cntbit(maxn)
    mask = (1 << maxncnt) - 1

    # 处理成一样长度，mask 即为所有的公共前缀
    for i in a:
        mask &= (i << (maxncnt - cntbit(i)))

    ans = float("inf")
    for i in range(1, maxncnt):
        f = 1
        curans = 0
        curmask = (mask) >> (maxncnt - i)
        for j in a:
            cnt = check(curmask, j)
            # 只要有一个错误，这个前缀即为错误
            if cnt == -1:
                f = 0
                break
            else:
                curans += cnt
        # 如果当前前缀可行
        if f:
            ans = min(ans, curans)
    print(ans)


