def can_reach_end(n, k, road):
    current = 0
    last_no_rock_pos = -1

    while current < n:
        if road[current] == '#':
            current = last_no_rock_pos + k + 1
            if current >= n:
                return 'NO'
        else:
            if current == n - 1:
                return 'YES'
            elif current - last_no_rock_pos >= k:
                last_no_rock_pos = current
            current += 1
    return 'NO'

