def sq(m,n):
    if m<n:
        return sq(n,m)
    if m==1 or n==1:
        return((n//2) if m ==1 else m//2)
    if m%2 == 0 and n%2 == 0:
        return (m//2)*n
    elif m%2 == 0 and not n%2 == 0:
        return sq(m,n-1) + (n-1)//2
    elif not m%2 == 0 and n%2 == 0:
        return sq(m-1,n) + (m-1) // 2
    return sq(m-1,n-1) + (n-1)//2 + (m-1)//2
    
