def dfs(root: Node, left: int, right: int):
    global height
    p = root
    while p and (left >= p.index or right <= p.index):
        if left >= p.index:
            p = p.right
        else:
            p = p.left
    if not p or p.val > min(height[left], height[right]):
        return right - left - abs(height[left] - height[right])
    else:
        return dfs(p, left, p.index) + dfs(p, p.index, right)
    
