class Node:
    number = 0
    ins = None
    out = None
    
    def __init__(self, _number):
        self.number = _number
        self.ins = set()
        self.out = set()

    def addIns(self, _node):
        self.ins.add(_node)
        _node.out.add(self)
    
    def addOut(self, _node):
        self.out.add(_node)
        _node.ins.add(self)
    
    def removeIns(self, _node):
        self.ins.remove(_node)
        _node.out.remove(self)
        
    def removeOut(self, _node):
        self.out.remove(_node)
        _node.ins.remove(self)
        
    def get_ins(self):
        return self.ins
    
    def get_out(self):
        return self.out
    
    def has_ins(self):
        return (len(self.ins) > 0)
    
    def has_out(self):
        return (len(self.out) > 0)
    
    def get_number(self):
        return self.number
    
class Graph:
    nodes = None
    
    def __init__(self):
        self.nodes = {}
        self.edges = set()
        
    def addNode(self, _node):
        self.nodes[_node.get_number()] = _node

    def addEdge(self, _number1, _number2):
        if not _number1 in self.nodes:
            node = Node(_number1)
            self.addNode(node)
        if not _number2 in self.nodes:
            node = Node(_number2)
            self.addNode(node)
        self.nodes[_number1].addOut(self.nodes[_number2])
        
    def removeEdge(self, _number1, _number2):
        self.nodes[_number1].removeOut(self.nodes[_number2])
    
    def get_nodes(self):
        return self.nodes
    
    def sort(self):
        L = []
        Q = set()
        
        for n in self.nodes:
            if not self.nodes[n].has_ins(): Q.add(self.nodes[n])
        
        while len(Q) > 0:
            n = Q.pop()
            L.append(n)
            outs = list(n.get_out())
            for t in outs:
                self.removeEdge(n.get_number(), t.get_number())
                if not t.has_ins(): Q.add(self.nodes[t.get_number()])
        
        return L, Q
    
    def get_edges(self):
        edges = set()
        for n in self.nodes:
            for t in self.nodes[n].get_out():
                edges.add((n, t.get_number()))
        return edges
    
