def print_path(graph):
    path = []
    curr_node = graph[-1]
    while(curr_node is not None):
        path.insert(0, curr_node)
        curr_node = curr_node.previous

    if(path[0].idf != graph[0].idf):
        print(-1)
    else:
        for node in path:
            print(node.idf+1, end=" " )

def dijkstras(graph, start):
    start.cost = 0
    pq = [start]

    while(len(pq) > 0):
        curr_node = heapq.heappop(pq)
        curr_cost = curr_node.cost

        # Check out all neighbors of this node if not visited
        if not (curr_node.visited):
            for neighbor in curr_node.neighbors:
                next_node = neighbor.dest
                new_cost = curr_cost + neighbor.weight

                if(new_cost < next_node.cost):
                    next_node.cost = new_cost
                    next_node.previous = curr_node
                    heapq.heappush(pq, next_node)

        # Mark node as visited
        curr_node.visited = True


class Node():
    def __init__(self, idf):
        self.idf = idf
        self.neighbors = []
        self.cost = sys.maxsize
        self.visited = False
        self.previous = None

    def __lt__(self, other):
        return self.cost < other.cost

    def _eq__(self, other):
        return self.cost == other.cost

class Edge():
    def __init__(self, dest, weight):
        self.dest = dest
        self.weight = weight

def build_graph():
    n, m = [int(x) for x in input().split(" ")]
    graph = []

    # Init vertex arrays
    for x in range(0, n):
        graph.append(Node(x))

    for x in range(m):
        # Build edges
        source, sink, weight = [int(x) for x in input().split(" ")]
        # Convert to 0 indexing
        source -= 1
        sink -= 1
        add_undirected(graph, source, sink, weight)

    return graph

def add_undirected(graph, source, sink, weight=0):
    # Undirected, so add for both
    graph[source].neighbors.append(Edge(graph[sink], weight))
    graph[sink].neighbors.append(Edge(graph[source], weight))



