class Vector:
    def __init__(self, x = 0, y = 0, z = 0):
        self.x = x
        self.y = y
        self.z = z

    def __add__(self, v):
        ans = Vector(self.x + v.x, self.y + v.y, self.z + v.z)
        return ans

    def __sub__(self, v):
        ans = Vector(self.x - v.x, self.y - v.y, self.z - v.z)
        return ans

    def __str__(self):
        return "x: %d y: %d z: %d"%(self.x, self.y, self.z)

    def inEquilibrium(self):
        return "YES" if self.x + self.y + self.z == 0 else "NO"

