def print_array(array):
    """ Prints an array of values, the way CodeForces requires """
    stdout.write(" ".join(map(str, array)) + "\n")

def print_single_values(array, print_func=print):
    for value in array:
        print_func(value)
        
def binary_search(array, target):
    start, end = 0, len(array)-1
    while start <= end:
        mid = (start + end) // 2
        if array[mid] <= target:
            start = mid + 1
        else:
            end = mid - 1
    else:
        # return the index to put the target before it, if not found
        return end

def parity(x):
    return x >= 0

def solve(n, shops, q, coins):
    shops.sort()
    less_than = [0] * (shops[-1])
    shop_iterator = 0
    less_than_iterator = 1
    less_than_counter = 0
    
    while shop_iterator < n:
        if shops[shop_iterator] <= less_than_iterator + 1:
            less_than_counter += 1
            shop_iterator += 1
        else:
            less_than[less_than_iterator] = less_than_counter
            less_than_iterator += 1

    result = []

    for i in range(q):
        if coins[i] >= len(less_than):
            result.append(n)
        else:
            result.append(less_than[coins[i] - 1])
    return result

    
    
