		print(subjects)
	else:
		for num in range(1, subjects+1):
			min_failed_sum = num*2
			remaining_marks = total_marks-min_failed_sum
			remaining_subjects = subjects-num

			if not remaining_subjects or remaining_marks < 0:
				print(0)
				break
			elif remaining_subjects*2 == remaining_marks:
				print(subjects)
				break
			elif not remaining_marks or remaining_marks%remaining_subjects == 0:
