def lcm(A,B):
        # code here 
    maxm = max(A,B)
    minm = min(A,B)
    while maxm%minm!=0:
        temp = maxm
        maxm = minm
        minm = temp%minm
    gcd = minm
    
    lcm = (A*B)//gcd
    
    return lcm

def max_lcm(n):
    
    if n<4:
        if n==1:
            return 1
        elif n==2:
            return 2
        elif n==3:
            return 6
    max_val = 0
    for i in range(n,4,-1):
        lcm_val1 = lcm(lcm(i,i-1),i-3)
        lcm_val2 = lcm(lcm(i,i-1),i-2)
        if max(lcm_val1,lcm_val2)>max_val:
            max_val = max(lcm_val1,lcm_val2)
        #print(lcm_val,i)
    return max_val
