class prefixTrie:
    def __init__(self, string):
        self.root = {}
        self.endSymbol = "*"
        self.populateprefixTrieFrom(string)

    #O(n^2) st

    def populateprefixTrieFrom(self, string):

        for i in range(len(string)):
            self.insertprefix(i,string)

    def insertprefix(self,i,string):
        cur = self.root
        for k in range(0,i):
            if string[k] not in cur:
                cur[string[k]] = {}

            cur = cur[string[k]]

        cur[self.endSymbol] = True

    #O(m) / O(1)
        
    def contains(self, string):
        cur = self.root
        for i in range(len(string)):
            if string[i] not in cur:
                return False
            cur = cur[string[i]]
        if '*' in cur:
            return True
        return False
  
