def dijkstra(g, n, s, e):
    visited = [False for i in range(n+1)]
    prev = [None for i in range(n+1)]
    dist = [float('inf') for i in range(n+1)]
    dist[1] = 0

    pq = PriorityQueue()
    pq.put((0, s))

    while not pq.empty():
        minValue, index = pq.get()
        visited[index] = True
        if dist[index] < minValue:
            continue

        if index == e:
            break

        for weight, node in g[index]:
            if visited[node]: continue
            newDist = dist[index] + weight
            if newDist < dist[node]: #or (newDist == dist[node] and index < prev[node]):
                prev[node] = index
                dist[node] = newDist
                pq.put((newDist, node))



    return (dist, prev)


def findShortestPath(g, n, s, e):
    dist, prev = dijkstra(g, n, s, e)
    path = []
    if dist[e] == float('inf'): return -1

    while e != s:
        path.append(e)
        e = prev[e]

    path.append(1)
    path.reverse()
    return path

