def dijkstra(graph, src):
	path = [-1] * len(graph)
	visited = [1000001] * len(graph)
	visited[src] = 0
	queue = []
	queue.append(src)

	while queue:
		current = queue.pop(0)
		adj = graph[current]

		for vertex in range(0, len(adj)):
			if graph[current][vertex] != 0:
				if visited[current] + graph[current][vertex] < visited[vertex]:
					visited[vertex] = visited[current] + graph[current][vertex]
					path[vertex] = current

					if not queue:
						queue.append(vertex)
					else:
						inserted = False
						index = 0

						while not inserted and index < len(queue):
							if visited[vertex] < visited[queue[index]]:
								queue.insert(index, vertex)
								inserted = True

							index += 1

						if not inserted:
							queue.append(vertex)

	if path[len(graph)-1] == -1:
		print(-1)
	else:
		shortest = [str(len(graph))]
		findPath(path, len(graph)-1, shortest)
		shortest.reverse()
		print(" ".join(shortest))

def findPath(path, src, shortest):
	if path[src] != -1:
		shortest.append(str(path[src]+1))
		findPath(path, path[src], shortest)

