    def dfs(u):
        nonlocal visited
        nonlocal next

        if u in next:
            return True
        if u in visited:
            return False
        visited.add(u)
        for v in graph[u]:
            next[u] = v
            if dfs(v):
                return True
        if u in next:
            del next[u]
        return False

    for u in range(len(graph)):
        if u not in visited and dfs(u):
            cycle = [u, next[u]]
            while cycle[-1] != u:
                cycle.append(next[cycle[-1]])
            return cycle
    return None


def main():
    n, m = [int(x) for x in input().split()]
    graph = [set() for _ in range(n)]
    for _ in range(m):
        u, v = [int(x) for x in input().split()]
        graph[u - 1].add(v - 1)

    cycle = find_cycle(graph)
    if not cycle:
        print("YES")
        return

    for i in range(len(cycle) - 1):
        u = cycle[i]
        v = cycle[i + 1]
        graph[u].remove(v)
        if not find_cycle(graph):
            print("YES")
            return
        graph[u].add(v)
    print("NO")


