import heapq, sys
from collections import deque, defaultdict
from math import inf as INFINITY

def dijkstra_path_old(G, src, dst, get_neighbors=None):
	if get_neighbors is None:
		get_neighbors = G.get

	distance = defaultdict(lambda: INFINITY, {src: 0})
	queue    = [(0, src, (src,))]
	visited  = set()

	while queue:
		dist, node, path = heapq.heappop(queue)

		if node == dst:
			return path

		if node not in visited:
			visited.add(node)
			neighbors = get_neighbors(node)

			if not neighbors:
				continue

			for neighbor, weight in filter(lambda n: n[0] not in visited, neighbors):
				new_dist = dist + weight

				if new_dist < distance[neighbor]:
					distance[neighbor] = new_dist
					heapq.heappush(queue, (new_dist, neighbor, path + (neighbor,)))

	return ()

def dijkstra_path(G, src, dst, get_neighbors=None):
	if get_neighbors is None:
		get_neighbors = G.get

	distance = defaultdict(lambda: INFINITY, {src: 0})
	previous = {src: None}
	queue    = [(0, src)]
	visited  = set()

	while queue:
		dist, node = heapq.heappop(queue)

		if node == dst:
			path = deque()

			while node is not None:
				path.appendleft(node)
				node = previous[node]

			return tuple(path), dist

		if node not in visited:
			visited.add(node)
			neighbors = get_neighbors(node)

			if not neighbors:
				continue

			for neighbor, weight in filter(lambda n: n[0] not in visited, neighbors):
				new_dist = dist + weight

				if new_dist < distance[neighbor]:
					distance[neighbor] = new_dist
					previous[neighbor] = node
					heapq.heappush(queue, (new_dist, neighbor))

	return (), INFINITY

def main():
	n, e = map(int, sys.stdin.readline().split())
	G = defaultdict(list)

	for _ in range(e):
		a, b, w = map(int, sys.stdin.readline().split())
		G[a].append((b, w))
		G[b].append((a, w))

	print(*dijkstra_path(G, 1, n)[0])

