def compute_failure_function(s):
    m = len(s)
    failure = [0] * m
    j = 0

    for i in range(1, m):
        while j > 0 and s[i] != s[j]:
            j = failure[j - 1]

        if s[i] == s[j]:
            j += 1

        failure[i] = j

    return failure

