def bfsRook(king,dest,n):
    visited = set([king])
    queue = deque([(king,0)])
    rowDiff = abs(king[0] - dest[0])
    colDiff = abs(king[1]-dest[1])
    directions = [(0,colDiff ),(rowDiff,0),(0,-colDiff),(-rowDiff,0)]
    while queue:
        cur,level = queue.popleft()
        if cur == dest:
            return level
        for direc in directions:
            nx = cur[0] + direc[0]
            ny = cur[1] + direc[1]
            if nx > n or nx < 0 or ny > n or ny < 0:
                continue
            else:
                if (nx,ny) not in visited:
                    visited.add((nx,ny))
                    queue.append(((nx,ny),level+1))
        
    return 0
def bfsBishop(king,dest,n):
    visited = set([king])
    queue = deque([(king,0)])
    rowDiff = abs(king[0] - dest[0])
    colDiff = abs(king[1]-dest[1])
    rdirections = [(rowDiff,rowDiff),(-rowDiff,rowDiff),(rowDiff,-rowDiff),(-rowDiff,-rowDiff)]
