class Node:
    def __init__(self,val,priority):
        self.val=val
        self.priority=priority

class PriorityQueue:
    def __init__(self):
        self.values=[]

    def bubbleUp(self):
        currentIndex = len(self.values)-1
        element = self.values[currentIndex]
        while currentIndex > 0:
            parentIndex = int((currentIndex-1)//2)
            parent=self.values[parentIndex]
            if parent.priority <= element.priority:
                break
            self.values[currentIndex]=parent
            self.values[parentIndex]=element
            currentIndex=parentIndex

    def enqueue(self, val, priority):
        node = Node(val, priority)
        self.values.append(node)
        self.bubbleUp()

    def sinkDown(self):
        currentIndex = 0
        element=self.values[currentIndex]
        while True:
            swap=None
            leftIndex=2*currentIndex+1
            rightIndex=2*currentIndex+2
            if leftIndex <= len(self.values)-1:
                left = self.values[leftIndex]
                if left.priority < element.priority:
                    swap=leftIndex
            if rightIndex <= len(self.values)-1:
                right=self.values[rightIndex]
