class Graph:
    def __init__(self):
        self.adjacencyList={}

    def addVertex(self,vertex):
        if vertex not in self.adjacencyList:
            self.adjacencyList[vertex]=[]

    def addEdge(self,vertex1,vertex2,weight):
        self.adjacencyList[vertex1].append({"node": vertex2, "weight": weight})
        self.adjacencyList[vertex2].append({"node": vertex1, "weight": weight})

    def dfs(self,vertex):
        visited=[]
        result=[]
        lst=self.adjacencyList
        def dfsRecursive(vertex):
            visited.append(vertex)
            result.append(vertex)
            for neighbor in lst[vertex]:
                dfsRecursive(neighbor)
        dfsRecursive(vertex)
        return result

    def dijkstra(self,vertex1,vertex2):
        nodes=PriorityQueue()
        distances={}
        prev={}
        path=[]
        for vertex in self.adjacencyList:
            if vertex != vertex1:
                distances[vertex]=math.inf
                nodes.enqueue(vertex, math.inf)
            else:
                distances[vertex]=0
                nodes.enqueue(vertex, 0)
            prev[vertex] = None
        while len(nodes.values)!=0:
            smallest=nodes.dequeue().val
            if smallest == vertex2:
                while prev[smallest] is not None:
                    path.append(smallest)
                    smallest=prev[smallest]
                break
            if smallest or distances[smallest] != math.inf:
                for neighbor in self.adjacencyList[smallest]:
                    candidate = distances[smallest]+neighbor["weight"]
                    if candidate < distances[neighbor["node"]]:
                        distances[neighbor["node"]] = candidate
                        prev[neighbor["node"]] = smallest
                        nodes.enqueue(neighbor["node"], candidate)
        path.append(vertex1)
        path.reverse()
        return path
