def cut(n, prefix, suffix, left, right, ways):
    if left >= right - 1:
        return ways
    pre = prefix[left]
    suf = suffix[n-1-right]
    if pre != suf:
        return max((cut(n, prefix, suffix, left + 1, right, ways),
                    cut(n, prefix, suffix, left, right - 1, ways)))
    else:
        j = left
        while prefix[j] == pre and j <= n - 1:
            j += 1
        new_left = j - 1
        k = right
        while suffix[n-1-k] == suf and k >= 0:
            k -= 1
        new_right = k + 1
        if new_left >= new_right - 1:
            return ways
        else:
            mid = prefix[new_right-1] - prefix[new_left]
            if mid == pre:
                add = (new_left-left+1) * (right-new_right+1)
                return max(cut(n, prefix, suffix, new_left + 1, new_right, ways + add),
                           cut(n, prefix, suffix, new_left, new_right - 1, ways + add))
            else:
                return max(cut(n, prefix, suffix, left + 1, right, ways),
                           cut(n, prefix, suffix, new_left, new_right - 1, ways))


