def find_path(g, vs, ve, path=[]):
    path = path + [vs]
    if vs == ve:
        return path
    if not g[vs]:
        return None
    for v in g[vs]:
        if v not in path:
            newpath = find_path(g, v, ve, path)
            if newpath: return newpath
    return None

def count(g, vs):
    q = [vs]
    vis = set()
    while len(q):
        v = q.pop()
        vis.add(v)
        for vn in g[v]:
            if vn not in vis: q.append(vn)
    return len(vis)

def solve(g, x, y):
    if len(g) <= 1:
        return 0
    path = find_path(g, x, y)
    g[path[0]].remove(path[1])
    g[path[len(path)-1]].remove(path[len(path)-2])
    x_siz = count(g, x)
    y_siz = count(g, y)
    ans = n*(n-1) - (x_siz*y_siz)
    return ans

