def kosaraju(g):
 
    # 1. For each vertex u of the graph, mark u as unvisited. Let l be empty.
    size = len(g)
 
    vis = [False]*size # vertexes that have been visited
    l = [0]*size

    T = size
    t = [[]]*size   # transpose graph
 
    def visit(u):
        nonlocal T
        if not vis[u]:
            vis[u] = True
            for v in g[u]:
                visit(v)
                t[v] = t[v] + [u]
            T -= 1
            l[T] = u
 
    # 2. For each vertex u of the graph do visit(u)
    for u in range(len(g)):
        visit(u)
    c = [0]*size
 
    def assign(u, root):
        if vis[u]:
            vis[u] = False
            c[u] = root
            for v in t[u]:
                assign(v, root)
 
    # 3: For each element u of l in order, do assign(u, u)
    for u in l:
        assign(u, u)
 
    return c

def condensed(g,s):
    c = kosaraju(g)
    size = len(g)

    label = 0
    new_c = [-1]*(size)
    ref = dict()

    for i in range(size):
        if c[i] in ref:
            new_c[i] = ref[c[i]]
        else:
            ref[c[i]] = label
            new_c[i] = label
            label += 1
    
    new_g = [set() for _ in range(label)]

    for i in range(size):
        new_i = new_c[i]
        for j in g[i]:
            new_j = new_c[j]
            if new_i != new_j:
                new_g[new_i].add(new_j)

    return new_g, new_c[s]

