    if len(alist) == 0:
        return None
    else:
        center = len(alist) // 2
        if alist[center] == target:
            return 0
        elif alist[center] < target:
            temp = getMinDistance(alist[center + 1:], target, alist[center], after)
            if temp == None:
                if direction == 'R':
                    return after - target
                else:
                    return target - alist[center]
            else:
