    if from_sys != 10:
        string = str(a)
        counter = len(string) - 1
        a = 0
        for i in string:
            if i.isalpha():
                h = (ord(i) - 65) + 10
            else:
                h = int(i)
            a += h * (from_sys ** counter)
            counter -= 1
    else:
        a = int(a)

    res = ''
    while a:
        h = a % b
        if h > 9:
            h = chr(65 + (h - 10))
        res += str(h)
        a //= b

    return res[::-1]

