class weighted_graph():

    def __init__(self,vertex:int,directed = True):
        self.length = vertex
        self.vertices = [i for i in range(vertex)]
        self.adj_list = {}
        self.directed = directed
        for v in self.vertices:
            self.adj_list[v] = []

    def add_edge(self,start,end,weight=0):
        self.adj_list[start].append((end, weight))
        if not self.directed:
            self.adj_list[end].append((start,weight))

    def __str__(self):
        to_print = ""
        for v in self.vertices:
            to_print += f'{v} -> {self.adj_list[v]}\n'
        return to_print

    def __len__(self):
        return self.length

def dijkstra(graph,start):
    from math import inf
    import heapq
    distance = [inf for i in range(len(graph))]
    previous = [0 for i in range(len(graph))]
    distance[start[0]] = 0
    Q = []
    heapq.heappush(Q,start)
    for i in range(1,len(graph)):
        heapq.heappush(Q,(distance[i],i))
    while Q:
        length,u = heapq.heappop(Q)
        for edge in graph.adj_list[u]:
            if distance[u] + edge[1] < distance[edge[0]]:
                # now need to edit the distance of the edge in the heap
                #print(f"Checking the edge {(edge[0],distance[edge[0]])}")
                if (distance[edge[0]],edge[0]) in Q:
                    Q.remove((distance[edge[0]],edge[0]))
                    heapq.heappush(Q,(distance[u]+edge[1],edge[0]))
                distance[edge[0]] = distance[u] + edge[1]
                previous[edge[0]] = u
    return distance,previous

