def local_max(p, l1, l2):
    a0 = p[0]
    
    a1 = -1
    a2 = -2
    a3 = -2

    for i in p[1:]:
        if i < a0:
            a1 = i
            break
    if a1 != -1:
        for i in range(p.index(a1), len(p)):
            if p[i] < a1:
                a2 = p[i]
                if i+1 < len(p):
                    a3 = p[i+1]
                if a2 == a3 and a2+a3 > a1:
                    a1, a2 = a2, a1
                break
    l1.append(p.pop(p.index(a0)))
    if a1 != -2 and a2 != a3:
        l1.append(p.pop(p.index(a2)))
        l2.append(p.pop(p.index(a1)))
        l2.append(p.pop(p.index(a3)))
    elif a1 != -1:
        l2.append(p.pop(p.index(a1)))
    elif a1 == -1:
        l2.append(0)

    if len(p) > 0:
        local_max(p, l1, l2)
    

