def can_sell_tickets(people):
    # Initialize counts of 25 and 50 ruble bills.
    count_25 = 0
    count_50 = 0

    # Iterate through the line of people.
    for bill in people:
        if bill == 25:
            # Accept 25 ruble bill, no change needed.
            count_25 += 1
        elif bill == 50:
            # Need to give 25 ruble change.
            if count_25 >= 1:
                count_25 -= 1
                count_50 += 1
            else:
                return "NO"
        elif bill == 100:
            # Need to give 75 ruble change (50 + 25).
            if count_50 >= 1 and count_25 >= 1:
                count_50 -= 1
                count_25 -= 1
            elif count_25 >= 3:
                count_25 -= 3
            else:
                return "NO"

    # If we successfully serve all people, return "YES."
    return "YES"

