def is_in(x, y):
    if x[0]>=y[0] and x[1]<=y[1]:
        return True
    return False

def has_overlap(x, y):
    if x[0] >= y[0] and x[0] <=y[1]:
        return True 
    if x[1] >= y[0] and x[1] <=y[1]:
        return True
    return False

def f(tb, w, b, tree_ind):
    if not tree_ind in tree:
        tree[tree_ind] = {}
        tree[tree_ind]['b'] = b
    if is_in(b, tb) and not 'win' in tree[tree_ind]:
        tree[tree_ind]['win'] = w['win']
        tree[tree_ind]['time'] = w['time']
        return
    if has_overlap(tb, b):
        if b[0]!=b[1]:
            b1, b2 = new_b(b)
            f(tb, w, b1, 2*tree_ind)
            f(tb, w, b2, 2*tree_ind+1)

