        win = node['win']
        win_time = node['time']
    ans1, ans2 = find_ans(x, 2*tree_ind), find_ans(x, 2*tree_ind+1)
    for ans in [ans1, ans2]:
        if ans['win'] != 0 and ans['time']<win_time and ans['win']!=x:
            win = ans['win']
            win_time = ans['time']

