class Node:
    def __init__(self, u: int=0, d: int=0, s: int=0):
        self.up = u
        self.down = d
        self.sum = s
    
    def __add__(self, other):
        intetsect = min(self.up, other.down)
        return Node(
            self.up + other.up - intetsect, 
            self.down + other.down - intetsect, 
            self.sum + other.sum + intetsect)

tree = [Node()] * (4 * n)

def build(node: int, l: int, r: int) -> Node:
    global tree
    if l == r:
        if s[l] == '(':
            tree[node] = Node(u=1)
        else:
            tree[node] = Node(d=1)
    else:
        mid = l + r >> 1
        tree[node] = build(node * 2, l, mid) + build(node * 2 + 1, mid + 1, r)
    return tree[node]

def get(node: int, l: int, r: int, s: int, e: int) -> Node:
    global tree
    if s <= l and e >= r:
        return tree[node]
    if s > r or e < l:
        return Node()
    else:
        mid = l + r >> 1
        return get(node * 2, l, mid, s, e) + get(node * 2 + 1, mid + 1, r, s, e)
    
