# Initializing the visited set
visited = set()

# Function to perform DFS on the maze
def dfs(i, j, parent, visited):
    # Adding the current node to visited set
    visited.add((i, j))
    
    # Checking all the neighbors of the current node
    for di, dj in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
        ni, nj = i + di, j + dj
        
        # Checking if the neighbor is within the maze boundaries
        if ni >= 0 and ni < n and nj >= 0 and nj < m:
            # If the neighbor is not visited, continue exploring
            if (ni, nj) not in visited:
                if dfs(ni, nj, (i, j), visited):
