def solve(ns, costss):
    n = int(ns)
    cs = []
    for cstr in costss.split():
        cs+= [int(cstr)]
    summ = sum(cs)
    cs = sorted(cs, reverse=True)
    res = step6(0, cs)
    return summ - res

def step6(ec, cs):
    while True:
        if cs==[] or len(cs)==1:
            break
        [a,b]=cs[0:2]
        if a==b:
            for x in cs:
                if x!=a:
                    cs.remove(x)
                    ec+=x
                    break
            cs.remove(a) 
            continue
        if len(cs)==2:
            ec+=b
            break
        elif len(cs)==3:
            [a,b,c]=cs
            if a==b and b==c:
                break
            else:
                ec+=b
                break
        else:
            [a,b,c,d]=cs[0:4]
            if b!=c and c!=d:
                ec+=b+d
                del cs[0:4]
            elif b!=c and c==d:
                return max(step6(ec+b,cs[2:]), step6(ec+c+c,cs[4:]))
            else:
                ec+=b
                del cs[0:1]
    return ec

