from queue import PriorityQueue

class Graph:
    def __init__(self, num_of_vertices):
        self.v = num_of_vertices
        # self.edges = [[-1 for i in range(num_of_vertices)] for j in range(num_of_vertices)]
        self.edges = {}
        self.weights = {}
        for i in range(num_of_vertices):
            self.edges[i] = set()
        self.visited = []

    def add_edge(self, u, v, weight):
        self.edges[u].add(v)
        self.edges[v].add(u)
        self.weights[(min(u, v), max(u, v))] = weight

    def has_edge(self, u, v):
        return v in self.edges[u] or u in self.edges[v]

    def get_weight(self, u, v):
        key = (min(u, v), max(u, v))
        if key in self.weights:
            return self.weights[key]
        return -1

    def dijkstra(self, start_vertex):
        dist = [float('inf') for _ in range(self.v)]
        pred = [0 for _ in range(self.v)]
        dist[start_vertex] = 0

        Q = PriorityQueue()
        Q.put((dist[start_vertex], 0))

        while not Q.empty():
            key, u = Q.get()
            if dist[u] == key:
                for v in range(self.v):
                    if v in self.edges[u]:
                        if dist[v] > dist[u] + self.get_weight(u, v):
                            dist[v] = dist[u] + self.get_weight(u, v)
                            pred[v] = u
                            Q.put((dist[v], v))
        return dist, pred


