def dijkstra(n_v,adj,h):
    dt = [(10**6+1)*n_v for i in range(n_v+1)] 
    rot = [0 for i in range(n_v+1)]
    dt[1] = 0
    l_abertos = [i for i in range(1,n_v+1)]
    l_fechados = []
    heappush(h,(dt[1],1))
    while(len(l_fechados)!=n_v):
        menor = heappop(h)
        dis, v = map(int,menor)
        l_fechados.append(v)
        indice = l_abertos.index(v)
        del(l_abertos[indice])
        if v==n_v:
            break
        for vizinho in adj[v]:
            viz, peso = map(int,vizinho)
            if viz not in l_fechados:
                if (dt[viz],viz) not in h:
                    if dt[viz] > dis + peso:
                        dt[viz] = dis + peso
                        rot[viz] = v
                        heappush(h,(dt[viz],viz))
                else:
                    if dt[viz] > dis + peso:
                        h.remove((dt[viz],viz))
                        dt[viz] = dis + peso
                        rot[viz] = v
                        heappush(h,(dt[viz],viz))
    l = [n_v]
    antecessor = rot[n_v]
    l.append(antecessor)
    while(antecessor!=1):
        antecessor = rot[antecessor]
        l.append(antecessor)
    l.reverse()
    return l


