def compute_prefix(s):
    longest_prefix = [0]
    m = len(s)

    for i in range(1, m):
        k = 0
        while k > 0 and s[k] != s[i]:
            k = longest_prefix[k - 1]

        if s[k] == s[i]:
            k += 1

        longest_prefix.append(k)

    return longest_prefix

