def check_connection(grid, h, w, istart, grid2):
    global components
    tot = 0
    comps = []
    for ind in surroundings(h, w, istart):
        if grid2[ind] != "*" and int(grid2[ind]) not in comps:
            comps.append(int(grid2[ind]))
    for i in comps:
        tot += components[i]
    return tot + 1


def surroundings(h, w, ind):
    lst = []
    for i in [-1, 1]:
        if ind // w == (ind + i) // w:
            lst.append(i + ind)
    for i in [-w, w]:
        if 0 <= ind + i < h * w:
            lst.append(i + ind)
    return lst


