                cl_ind = stack[-1]
                closed.append(cl_ind)
                stack.pop()
                for ind in surroundings(rows, cols, cl_ind):
                    if grid[ind] == "." and ind not in closed and ind not in stack:
                        stack.append(ind)
            for ii in closed:
                grid2[ii] = count
            comps.append(len(closed))
            count += 1
    return comps



