################################################### SOLUTION

def multiply(M1, M2):
    if len(M1[0]) != len(M2): raise ValueError
    a = len(M1)
    b = len(M2[0])
    c = len(M1[0])
    # M1: a x c, M2: c x b, M: a x b
    ans = [[0]*b for _ in range(a)]
    for i in range(a):
        for j in range(b):
            for k in range(c):
                ans[i][j] += M1[i][k] * M2[k][j]
    return ans

def solve(n, m):
    M = [[0,1,0],[1,1,0],[0,1,2]]
    if n == 0:
        return [[1,0,0],[0,1,0],[0,0,1]]
    if n == 1:
        return M
    P = solve(n//2, m)
    S = multiply(P, P)
    if n%2: S = multiply(S, M)
    for i in range(3):
        for j in range(3):
            S[i][j] = S[i][j] % m
    return S

def main():
    n,k,l,m = read()
    kb = bin(k)[2:]
    if len(kb) > l: return 0
    kb = "0" * (l - len(kb)) + kb
    zero, one = 0, 0
    for i in kb:
        if i == "0":
            zero += 1
        else:
            one += 1

    multiplier = solve(n, m)
    _, _, ans_one = multiply(multiplier, [[1],[0],[0]])
    multiplier = multiply(multiplier, solve(2, m))
    _, ans_zero, _ = multiply(multiplier, [[1],[0],[0]])
    return (pow(ans_zero[0], zero, m) * pow(ans_one[0], one, m)) % m



