dp = {}

def rodCutting(length):
    m = min(a,b,c)
    if length%m == 0:
        return length//m
    if length in dp:
        return dp[length]
    if length == 0:
        return 0
    if length < min(a,b,c):
        return float('-inf')
    ans = 0
    for cut in a,b,c:
        if cut <= length:
            ans = max(ans, 1+rodCutting(length-cut))
    dp[length] = ans
    return ans

