A = [-1 for x in range( 100001)] ## 100k
RMQ = [-1 for x in range( 400001)]

def rmq(tleft, tright, a, b, i):
	tmid = int((tleft+tright)/2)
	## check range
	if a == b:
		return A[ a]
	elif a == tleft and b == tright:
		return RMQ[ i]
	elif a <= tmid and b > tmid: ## fixed!
		## cut in the middle
		r1 = rmq( tleft,  tmid,   a, tmid,   2*i+1 )
		r2 = rmq( tmid+1, tright, tmid+1, b, 2*i+2 )
		result = max( r1, r2)
		return result
	else:
		if b <= tmid:
			## left result
			return rmq( tleft,  tmid,   a, b, 2*i+1 )
		elif a > tmid:
			## right result
			return rmq( tmid+1, tright, a, b,  2*i+2 )
		else:
			print("did not expected this")
			return -1


def rmq_wrapper(a, b):
	return rmq( 1, N-1, a, b, 0)


