## inclusive-inclusive
def build_rmq(a, b, i):
	if a==b:
		return A[a]
	else:
		mid = int((a+b)/2)
		m1 = build_rmq( a, mid, 2*i+1)
		m2 = build_rmq( mid+1, b, 2*i+2)
		result = max( m1, m2)
		RMQ[ i] = result
		return result

def build_rmq_wrapper():
	total_max = build_rmq( 1, N-1, 0)


