	cnt += (farthest-pos)*1
	for i in range( 2, N):
		if farthest == N:
			break
		new_farthest = rmq_wrapper(pos+1, farthest) ## again, wrong
		pos = farthest
		farthest = new_farthest
		if pos > farthest:
			break
		cnt += (farthest-pos) * i
	return cnt



def solve():
