def merge(a, b: list) -> list:
    result = []
    j = 0
    for i in range(len(a)):
        while j < len(b) and b[j] < a[i]:
            result.append(b[j])
            j += 1
        result.append(a[i])
    result += b[j:]
    return result

def merge_sort(lst: list) -> list:
    if len(lst) == 1:
        return lst
    k = len(lst)//2
    left = merge_sort(lst[:k])
    right = merge_sort(lst[k:])
    return merge(left, right)


def bin_search_count(lst: list, target: int) -> int:
    l, r = -1, len(lst)
    while r > (l+1):
        mid = (l + r) // 2
        elem = lst[mid]
        if elem <= target:
            l = mid
        else:
            r = mid
    if l == -1:
        return 0
    elif l == len(lst):
        return len(lst)
    return l+1


