def bfs(st):
    visited = [False] * n
    queue = deque([st])

    while queue:
        vertex = graph[queue.pop()]
        if not visited[vertex]:
            visited[vertex] = True
            if graph[vertex] == -1:
                return visited[t - 1]
            queue.append(vertex)

    return visited[t - 1]


