def convert_sequence(sequence):
    if sequence == ".":
        return "0"
    elif sequence == "-.":
        return "1"
    elif sequence == "--":
        return "2"
    else:
        return ""

def process_string(input_string):
    output = []
    i = 0

    while i < len(input_string):
        for j in range(2, 0, -1):
            current_sequence = input_string[i:i + j]
            converted_value = convert_sequence(current_sequence)
            if converted_value:
                output.append(converted_value)
                i += j
                break
        else:
            
            i += 1
    
    return "".join(output)

