def dp(cx, cy, anton_used, dasha_used, turn):
    global x, y
    if abs(cx - x) + abs(cy - y) >= d:
        if turn == 0:
            if anton_used:
                return False
            else:
                return not dp(cy, cx, True, dasha_used, 1 - turn)
        else: # turn == 1
            if dasha_used:
                return False
            else:
                return not dp(cy, cx, anton_used, True, 1 - turn)

    if turn == 0 and not anton_used and not dp(cy, cx, True, dasha_used, 1 - turn):
        return True

    if turn == 1 and not dasha_used and not dp(cy, cx, anton_used, dasha_used, 1 - turn):
        return True

    for dx, dy in vectors:
        if not dp(cx + dx, cy + dy, anton_used, dasha_used, 1 - turn):
            return True

    return False

