    from collections import Counter

    guest_counts = Counter(guest_name)
    host_counts = Counter(host_name)
    pile_counts = Counter(letter_pile)

    for letter in guest_counts:
        if letter not in pile_counts or pile_counts[letter] < guest_counts[letter]:
            return False

    for letter in host_counts:
        if letter not in pile_counts or pile_counts[letter] < host_counts[letter]:
            return False


    for letter in pile_counts:
        if letter not in guest_counts and letter not in host_counts:
            return False

    return True

