def calculate_the_time(hours, minutes, toAdd):
    newMinutes = minutes + toAdd
    if newMinutes >= 60:
        newHours = hours + (newMinutes // 60)
        newMinutes %= 60
        if newHours == 24:
            newHours = 00
        elif newHours > 24:
            newHours = 00 + newHours - 24
        return newHours, newMinutes
    else:
        return hours, newMinutes
    
