    grid = []
    parent = defaultdict(list)
    cost = defaultdict(int)
    for i in range(n):
        row = list(input().strip())
        grid.append(row)
    
    for i in range(n):
        for j in range(m):    
            if grid[i][j] == '.':
                cost[(i,j)] = 1
                parent[(i,j)].extend([i,j])
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                for r,c in [(1,0),(-1,0),(0,1),(0,-1)]:
                    row = r + i
                    col = c + j
                    if isBound(row,col,n,m) and grid[row][col] == '.':
                        union(i,j,row,col,parent,cost)
   
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*':
                count = 1
                visited = set()
                for r,c in [(1,0),(-1,0),(0,1),(0,-1)]:
                    row = r + i
                    col = c + j
                    
                    if isBound(row,col,n,m) and grid[row][col] == '.':
                        
                        res = find(row,col,parent)
                      
                        if tuple(res) not in visited:
                            count += cost[tuple(res)]
                          
                            visited.add(tuple(res))
               
                grid[i][j] = count
    for i in range(n):
        print("".join(str(x) for x in grid[i]))
    
def union(i,j,r,c,parent,cost):
    parent1 = tuple(find(i,j,parent))
    parent2 = tuple(find(r,c,parent))
    
    if parent1 == parent2: return 
    
    if cost[parent1] > cost[parent2]:
        
        cost[parent1] = cost[parent1] + cost[parent2]
        parent[parent2] = parent1
    else:
         
        cost[parent2] = cost[parent2] + cost[parent1]
        
        parent[parent1] = list(parent2)
    return 

def find(i,j,parent):
   
    if parent[(i,j)] != [i,j]:
        
        parent[(i,j)] = find(parent[(i,j)][0],parent[(i,j)][1],parent)
    
    return parent[(i,j)]

            
    
def isBound(i,j,n,m):
   
    return i >= 0 and i < n and j >= 0 and j < m
    
    
    
            
            
            
    
    
        


 
