def partition(graph):
    colors = [None for _ in graph]
    
    def dfs(node, g):
        if not colors[node]:
            colors[node] = g
        else:
            return colors[node] == g
        for peeps in graph[node]:
            if not dfs(peeps, 2 if g == 1 else 1):
                return False
        return True
    
    dfs(1, 1)
    return colors

