from decimal import *
def init_tree(n):
    return [0] * (n + 1)

def update(tree, i, val):
    i += 1
    while i < len(tree):
        tree[i] += val
        i += i & -i

def range_update(tree, l, r, val):
    update(tree, l, val)
    update(tree, r + 1, -val)

def query(tree, i):
    i += 1
    res = 0
    while i > 0:
        res += tree[i]
        i -= i & -i
    return res


    

