def check_loss(n, m, k, moves):
    field = [[0] * m for _ in range(n)]  
    for move in moves:
        i, j = move
        field[i-1][j-1] = 1
        if i > 1 and j > 1 and field[i-2][j-2] == 1 and field[i-2][j-1] == 1 and field[i-1][j-2] == 1:
            return k
        if i > 1 and j < m and field[i-2][j] == 1 and field[i-2][j-1] == 1 and field[i-1][j] == 1:
            return k
        if i < n and j > 1 and field[i][j-2] == 1 and field[i][j-1] == 1 and field[i-1][j-2] == 1:
            return k
        if i < n and j < m and field[i][j] == 1 and field[i][j-1] == 1 and field[i-1][j] == 1:
            return k
    return 0

