    i=l
    k=l
    j=mid+1;
    while(i<=mid and j<=r):
        if(arr[i]>arr[j]):
            b[k]=arr[j];
            p.append([arr[i],arr[j]]);
            p.append([arr[j],arr[i]]);
            p.append([arr[j],arr[j]]);
            k+= 1;
            j+= 1;
         
        else:
            p.append([arr[i],arr[j]]);
            p.append([arr[j],arr[i]]);
            p.append([arr[i],arr[i]]);
            b[k]=arr[i];
            i+= 1;
            k+= 1;
         
     
 
    while(i<=mid):
        b[k]=arr[i];
        p.append([arr[i],arr[i]]);
        i+= 1;
        k+= 1;
     
    while(j<=r):
        b[k]=arr[j];
        p.append([arr[j],arr[j]]);
        j+= 1;
        k+= 1;
     
    for x in range(l, r + 1):
        arr[x]=b[x];
    
