class Solution:

    def __init__(self) -> None:
        self.prev = 0

    def readint(self):
        return int(stdin.readline())


    def readarray(self, typ):
        return list(map(typ, stdin.readline().split()))


    def readmatrix(self, n):
        M = []

        for _ in range(n):

            row = self.readarray(int)
            assert len(row) == n
            M.append(row)
        
        return M


    def mult(self, M, v):
        n = len(M)
        return [sum(M[i][j] * v[j] for j in range(n)) for i in range(n)]


    def freivalds(self, A, B, C):

        n = len(A)

        x = [randint(0, 1000000) for j in range(n)]
        return self.mult(A, self.mult(B, x) == self.mult(C, x))    


    def findRes(self, arr, i):
        res = 0
        for j in range(i, len(arr)):
            res += arr[j]
        return res\


    def insertSort2D(self, arr):

        swaps = 0
        for i in range(1, len(arr)):

            key = arr[i][0]

            keyRow = arr[i]

            j = i - 1

            while j >= 0 and arr[j][0] > key:
                arr[j+1] = arr[j]
                j = j - 1
                swaps += 1
            
            arr[j+1] = keyRow

        return swaps


    def isPrime(self, n: int) -> bool:

        if n > 1:
            for i in range(2, int(math.sqrt(n)) + 1):
                if n % i == 0:
                    return False
            return True    
        return False
    

    def inRange(self, x: int, n: int) -> bool:

        return 0 <= x < n
    
