from heapq import *
def dijkstra(d,n):
    heap,visited,way=[(0,0,[])],set(),{0:0}
    while heap:
        leng,x,path=heappop(heap)
        if x not in visited:
            visited.add(x)
            path=path+[x+1]
            if x==n:return path
            new=d[x]
            for i,elem in enumerate(new):
                l=new[elem]
                if elem in visited:continue
                item=way.get(elem)
                if item==None or leng+l<item:
                    way[elem]=leng+l
                    heappush(heap,[leng+l,elem,path])
    return -1
