    res = []
    for i in range(mid, len(pr)):
        if pr[i] == mid:
            res.append(i)
    if not res:
        return False
    elif len(res) == 1:
        return False
    else:
        for el in res:
            if not (el == len(pr) - 1 or el > mid and el < len(pr) - 1):
                return False
        return True



