        return
    
    if i == 0:
        if t[0][1]:
            yield 1
        if t[1][0]:
            yield n
    
    if 0 < i < n - 1:
        if t[0][i - 1]:
            yield i - 1
        if t[0][i + 1]:
            yield i + 1
        if t[1][i]:
            yield i + n
    
    if i == n - 1:
        if t[0][i - 1]:
            yield i - 1
        if t[1][i]:
            yield i + n
    
    if i == n:
        if t[0][i - n]:
            yield i - n
        if t[1][i + 1 - n]:
            yield i + 1
    
    if n < i < 2 * n - 1:
        if t[0][i - n]:
            yield i - n
        if t[1][i - 1 - n]:
            yield i - 1
        if t[1][i + 1 - n]:
            yield i + 1
    
    if i == 2 * n - 1:
