from sys import stdin, stdout
import bisect
import math


def gcd(a, b):
    if a == 0:
        return b
    if a < b:
        a, b = b, a
    return gcd(a % b, b)


def factorize(n):
    res = []
    nc = n
    for i in range(2, int(math.floor(math.sqrt(n)))+1):
        if nc==1:
            break
        cnt = 0
        while nc % i == 0:
            nc //= i
            cnt += 1
        if cnt > 0:
            res.append(i)
    return res


def solve(t):
    n = int(stdin.readline().strip())

    res = n * (n - 1)
    ln = factorize(n) + factorize(n - 1)
    ln.sort()

    p = n - 2
    while p:
        conflict = False
        lo = factorize(p)
        for o in lo:
            l = bisect.bisect_left(ln, o)
            if l<len(ln) and ln[l]==o:
                conflict = True
                break

        if conflict:
            p -= 1
        else:
            res *= p
            break

    print(res)
    pass


