class Maze:
    def __init__(self):
        self.mazeTop=input()
        self.mazeBottom=input()
        self.length = len(self.mazeTop)
    def coordinateList(self,n):
        return [n%self.length,(n//2)>self.length]
    def __str__(self):
        return self.mazeTop+"\n"+self.mazeBottom

class Cursor: #goal, n
    def __init__(self, goal, n, maze):
        self.maze = maze
        self.setNewCursor(goal,n)
        self.path = 0
    def isUp(self):
        return self.n <= self.maze.length
    def upOpen(self,n):
        return self.maze.mazeTop[n%self.maze.length-1]!="X"
    def downOpen(self,n):
        return self.maze.mazeBottom[n%self.maze.length-1]!="X"
    def changeDirection(self):
        self.left = not self.left
    def setNewCursor(self,goal,n):
        self.goal = goal
        self.n = n
        self.left = True
        if n in set(range(1,self.maze.length+1)):
            if goal in set(range(1,self.maze.length+1)):
                self.left = goal < n
            else:
                self.left = goal-self.maze.length < n
        else:
            if goal in set(range(1,self.maze.length+1)):
                self.left = goal+self.maze.length < n
            else:
                self.left = goal < n
        self.path = 0
    def move(self):
        #print(str(self))
        #print("Path Length: ",self.path)
        deltaN = 1
        if self.left:
            deltaN = -1
        if self.n%self.maze.length == self.goal%self.maze.length:
            if self.n == self.goal:
                #print("At goal.")
                #print(str(self))
                return self.path
            else:
                if self.isUp():
                    self.n += self.maze.length
                else:
                    self.n -= self.maze.length
                #print("Changed y position to reach goal.")
                #print(str(self))
                self.path += 1
                return self.path
        if self.isUp():
            if self.upOpen(self.n+deltaN):
                #print("Moved n "+str(deltaN))
                self.n += deltaN
                self.path += 1
            elif self.downOpen(self.n) and self.downOpen(self.n+deltaN):
                #print("Moved n "+str(deltaN)+" and changed y position. (2 moves)")
                self.n += deltaN+self.maze.length
                self.path += 2
            else:
                #print("No path possible.")
                return -1
        else:
            if self.downOpen(self.n+deltaN):
                #print("Moved n "+str(deltaN))
                self.n += deltaN
                self.path += 1
            elif self.upOpen(self.n) and self.upOpen(self.n+deltaN):
                #print("Moved n "+str(deltaN)+" and changed y position. (2 moves)")
                self.n += deltaN-self.maze.length
                self.path += 2
            else:
                #print("No path possible.")
                return -1
    def __str__(self):
        string = str(self.maze)
        if self.isUp():
            string = string[:self.n-1]+"A"+string[self.n:]
        else:
            string = string[:self.n]+"A"+string[self.n+1:]
        return string

