def left_check(num):
    cover = trees[num].coordinate - trees[num].height
    if trees[num - 1].coordinate >= cover:
        return False
    else:
        return True


def right_check(num):
    cover = trees[num].coordinate + trees[num].height
    if trees[num + 1].coordinate <= cover:
        return False
    else:
        return True


def wide_check(num):
    if trees[num].coordinate - trees[num - 1].coordinate >= trees[num].height + trees[num - 1].height:
        return True
    else:
        return False


def cut(first, last, wide):
    if wide:
        return last - first + 1
    else:
        return last - first


