import heapq

def Dijkstra(distances, n):
    current = 1
    stack = []
    unvisited = {node: float('inf') for node in distances}
    unvisited[current] = 0
    heapq.heappush(stack, [unvisited[current], current])
    visited = {}
    predok={}

    while unvisited:
        # print("stack", stack)
        u = heapq.heappop(stack)
        # print("вытащили минимальное значение", u)
        current_dist = u[0]
        current = u[1]
        if current in visited.keys():
            continue
        for keys, values in distances[current].items():
            if keys in visited.keys():
                continue
            if unvisited[keys] > (unvisited[current] + values):
                unvisited[keys] = (unvisited[current] + values)
                predok[keys] = current
            heapq.heappush(stack, [unvisited[keys], keys])
            visited.update({current: current_dist})

        del unvisited[current]
        # print("unvisited", unvisited)
        # print("predok", predok)
        # print("visited", visited)
        # print("current", current)

    return predok


