class tree_array:
    tree=[0]
    l=0
    def lowbit(self,x):
        return x&-x
    def __init__(self,arr) -> None:
        self.l=len(arr)
        self.tree=[0 for i in range(self.l+1)]
        for i in range(1,self.l+1):
            self.tree[i] += arr[i-1]
            if (fa := i+self.lowbit(i)) <= self.l:
                self.tree[fa] += self.tree[i]
    def add(self,x,k):
        #x是从1开始的下标
        while(x<=self.l):
            self.tree[x]+=k
            x+=self.lowbit(x)
    def query(self,x,y):
        #x,y是从1开始的下标
        #是原数组[x+1,y]的和
        ans=0
        while y>x:
            ans+=self.tree[y]
            y-=self.lowbit(y)
        while x>y:
            ans-=self.tree[x]
            x-=self.lowbit(x)
        return ans
