from queue import PriorityQueue
from math import inf as infinity

class Node:
    def __init__(self, num):
        self.num = num
        self.edges = {}
        #self.visited = False
        self.prev = None
        self.cost = infinity

    def add_edge(self, other, weight):
        if other not in self.edges or weight < self.edges[other].w:
            self.edges[other] = Edge(self, other, weight)
            other.edges[self] = Edge(other, self, weight)

    def __lt__(self, other):
        return self.cost < other.cost

    def __repr__(self):
        return str(self.num)

    _nodes = {}
    def get_node(num):
        if num in Node._nodes:
            return Node._nodes[num]
        else:
            n = Node(num)
            Node._nodes[num] = n
            return n

    def clear():
        Node._nodes = {}
class Edge:
    def __init__(self, a, b, weight):
        self.a = a
        self.b = b
        self.w = weight

    def __repr__(self):
        return str(self.a) + "->" + str(self.b) + " (" + str(self.w) + ")"

# O(ElogV)

def explore(node, target, prev, cost, pq):
    if cost >= node.cost:
        return False
    node.cost = cost
    node.prev = prev
    if node is target:
        return True
    for edge in node.edges.values():
        if cost + edge.w < edge.b.cost: #Only try if it might be shorter
            pq.put((cost + edge.w, edge.b, node))

# O(1) lookup/creation

def get_node(num):
    return Node.get_node(num)


# Get string of shortest path, must have explored
def get_path(node):
    ret = ""
    while node is not None:
        ret = str(node.num) + (" " + ret if len(ret) > 0 else "")
        node = node.prev
    return ret

