def GetPrimes(n):
    x = 2
    primes = dict()
    while n > 1:
        if n % x == 0:
            primes[x] = primes.get(x, 0) + 1
            n /= x
        elif x * x > n:
            primes[n] = primes.get(n, 0) + 1
            break
        else:
            x += 1
    return primes

def Eiler(primes):
    n = 1
    new_primes = dict()
    for prime, power in primes.items():
        n *= prime - 1
        if power > 1:
            new_primes[prime] = power - 1

    for prime, power in GetPrimes(n).items():
        new_primes[prime] = new_primes.get(prime, 0) + power
    return new_primes

def FromPrimesToN(primes):
    n = 1
    for prime, power in primes.items():
        n *= prime ** power
    return n

def Inverse(x, p):
    def modp(v):
        r = v % p
        if r >= 0:
            return r
        else:
            return p - r

    a, b = x, p
    x1, y1, v1 = 1, 0, a
    x2, y2, v2 = 0, 1, b

    while v2 != 0:
        r = a // b
        x1, x2 = x2, modp(x1 - r * x2)
        y1, y2 = y2, modp(y1 - r * y2)
        a, b = b, a % b
        v1, v2 = v2, b

    return x1

def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)

def ChT(r1, m1, r2, m2):
    g = gcd(r1, r2)
    if (m2 - m1) % g != 0:
        return None, None
    k = Inverse(r1 // g, r2 // g) * ((m2 - m1) //  g)
    r = r1 * r2 // g
    m = (r1 * k + m1) % r
    return r, m

def ModP(left, right, all_eilers):
    def ModPLocal(index):
        cur = w[left + index]
        cur_m = all_eilers[index][0]
        if cur == 1:
            return 1, 1
        if index == right - left - 1:
            if cur <= POROG:
                return cur, cur % cur_m
            else:
                return None, cur % cur_m
        if index == len(all_eilers) - 1:
            return None, cur % cur_m

        next_value, next_ost = ModPLocal(index + 1)
        if next_value is not None:
            if cur ** next_value <= POROG:
                value = cur ** next_value
                return value, value % cur_m
            else:
                return None, pow(cur, next_value, cur_m)

        KitTOst = []
        # print(cur, next_value, next_ost, all_eilers[index][1])
        for prime, power in all_eilers[index][1].items():
            ost = 0
            pp = prime ** power
            if cur % prime != 0:
                ost = pow(cur, next_ost, pp)
            KitTOst.append((ost, pp))
        # print(KitTOst)

        m1, r1 = KitTOst[0]
        for m2, r2 in KitTOst[1:]:
            r1, m1 = ChT(r1, m1, r2, m2)

        # print(r1, m1)
        return None, m1

    value, ost = ModPLocal(0)
    return ost


