def total_time(candle, b):
	if b > candle:
		return candle
	count = candle
	burned_candle = 0
	while candle > 0 and b <= candle:
		count += candle // b
		burned_candle += candle % b
		candle = candle // b
		if burned_candle >= b:
			candle += burned_candle // b
			burned_candle = burned_candle % b
	if candle:
		count += candle
	burned_candle += candle % b
	if burned_candle >= b:
		count += burned_candle // b

	return int(count)


