NUMBEROFNODES = 140005
LG = 18

class Trie:
    class Node:
        def __init__(self):
            self.child = [-1, -1]
            self.cnt = 0

    def __init__(self):
        self.nodes = [self.Node() for _ in range(NUMBEROFNODES)]
        self.cur = 0
        self.nodes[0].child = [-1, -1]
        self.nodes[0].cnt = 0

    def new_node(self):
        self.cur += 1
        self.nodes[self.cur].child = [-1, -1]
        self.nodes[self.cur].cnt = 0
        return self.cur

    def add_number(self, x):
        pos = 0
        for i in range(LG, -1, -1):
            c = (x >> i) & 1
            if self.nodes[pos].child[c] == -1:
                self.nodes[pos].child[c] = self.new_node()
            pos = self.nodes[pos].child[c]
            self.nodes[pos].cnt += 1

    def query(self, x):
        pos = 0
        res = 0
        for i in range(LG, -1, -1):
            c = (x >> i) & 1

            if (
                self.nodes[pos].child[c] != -1
                and self.nodes[self.nodes[pos].child[c]].cnt == (1 << i)
            ):
                pos = self.nodes[pos].child[c ^ 1]
                res += (1 << i)
            else:
                pos = self.nodes[pos].child[c]

            if pos == -1:
                break
        return res

