			for tup in g[a]:
				if tup[1]==b:
					if tup[0]>w: 
						g[a].remove(tup)
						g[a].append((w,b))
						for anotherTup in g[b]:
							if anotherTup[1]==a: 
								g[b].remove(anotherTup)
								g[b].append((w,a))
								break
					break
			g[a].append((w,b))
			g[b].append((w,a))
		else:
			g[a].append((w,b))
			g[b].append((w,a))

	path=dijkstra(1,n,g)
	if path!=():
		l=len(path)
		for i in range(l-1,-1,-1): print(path[i],end=' ')
	else: print(-1)

