from collections import defaultdict, deque
import math

def solution():
    def rec(_range, n, target):
        st, end = _range
        mid = (st + end)//2
        if mid == target:
            return n % 2

        # left
        if target < mid:
            return rec((st, mid - 1),n//2, target)
        else:
            return rec((mid + 1, end),n//2, target)

    n, l, r = map(int, input().split())

    h = int(math.log2(n))
    n_nodes = 2**(h+1) - 1

    res = 0
    for target in range(l, r+1):
        if target > n_nodes:
            break;
        res += rec((1,n_nodes), n, target)
    print(res)


