        return False

    def erase(id):
        nonlocal t, m, memory, block_pointer
        if id <= 0 or id >= len(block_pointer) or block_pointer[id] < 0:
            return False
        i = block_pointer[id]
        while i < m and memory[i] == id:
            memory[i] = 0
            i += 1
        block_pointer[id] = -1
        return True

    def defragment():
        nonlocal m, memory, block_pointer
        i = 0
        for j in range(m):
            if memory[j] > 0:
                memory[i] = memory[j]
                if j > 0 and memory[j] != memory[j-1]:
                    block_pointer[memory[j]] = i
                i += 1
        while i < m:
            memory[i] = 0
            i += 1


