def update(BIT, i, value):
    while i <= len(BIT) - 1:
        BIT[i] += value
        i += i & -i


def query(BIT, start, end):
    if start > 0:
        return query(BIT, 0, end) - query(BIT, 0, start - 1)
    res = 0
    while end > 0:
        res += BIT[end]
        end -= end & -end
    return res


