def get_input():
    input_list = []
    for line in sys.stdin:
        input_list.append(line.rstrip("\n"))
    return input_list

def generate_graph(input_list):
    graph = defaultdict(set)
    edges = [[int(x) for x in y.split(" ")] for y in input_list[1:]]
    for edge in edges:
        graph[edge[0]].add(edge[1])
        graph[edge[1]].add(edge[0])
    return graph

def solve(input_list):
    global bipartite_set
    graph = generate_graph(input_list)
    generate_bipartite_sets(graph)
    num_edges = 0
    for edge in graph:
        num_edges += len(graph[edge])
    return int(bipartite_set["U"] * bipartite_set["V"] - (num_edges / 2))

def generate_bipartite_sets(graph):
    global bipartite_set
    bipartite_set["U"] = 0
    bipartite_set["V"] = 0
    dfs(graph, 1, set(), 0)
    return None

def dfs(graph, vertex, visited, depth):
    global bipartite_set
    if vertex not in visited:
        visited.add(vertex)
        if depth % 2 == 0:
            bipartite_set["U"] += 1
        else:
            bipartite_set["V"] += 1
        for adjacent in graph[vertex]:
            dfs(graph, adjacent, visited, depth + 1)
    return None

