memo = {} 


def solve_1(a , b, c):

    global memo
    a , b , c = sorted([a , b , c])
    if (a+b+c) < 3:
        return 0
    if (a+b == 0 or b + c == 0 or c+a == 0):
        return 0
    
    if (a,b,c) in memo:
        return memo[(a , b , c)]
    ans1 = min(a,b,c)
    if(ans1 > 0):
        ans1 += solve_1(a - ans1 , b - ans1 , c - ans1)
        
    ans2 = min(c//2 , b)
    if(ans2 >0):
        ans2 += solve_1(a,b-ans2,c-ans2*2)
    ans3 =  min(c//2 , b)-1
    if(ans3 >0):
        ans3 += solve_1(a,b-ans3,c-ans3*2)
    ans =  max(ans1 , ans2 , ans3)
    memo[(a , b , c)] = ans
    return ans

