def longestPrefix(s):
    lsp = [0]*len(s)
    j = 0
    for i in range(1, len(lsp)):
        if s[i] == s[j]:
            lsp[i] = j+1
            j += 1
        else:
            while j != 0 and s[i] != s[j]:
                j = lsp[j-1]

            if s[i] == s[j]:
                lsp[i] = j+1
                j += 1

    # print(lsp)
    return s[:lsp[-1]]


def strStr(haystack, needle):
    if not needle:
        return -1

    def buildLPS(string):
        lps = [0]*len(string)

        j = 0
        for i in range(1, len(string)):
            if string[i] == string[j]:
                lps[i] = j+1
                j += 1
            elif string[i] != string[j]:
                j = lps[i-1]
                while j != 0 and string[i] != string[j]:
                    j = lps[j-1]
                if string[i] == string[j]:
                    lps[i] = j+1
                    j += 1
                else:
                    lps[i] = 0

        return lps

    lps = buildLPS(needle)

    j = 0
    i = 0
    while i < len(haystack):
        if haystack[i] == needle[j]:
            j += 1
            i += 1
        else:
            while j != 0 and haystack[i] != needle[j]:
                j = lps[j-1]
            if haystack[i] != needle[j]:
                i += 1

        if j == len(needle):
            return i-len(needle)

    return -1


def solve(s):
    pre = longestPrefix(s)
    pre = list(pre)
    temp = list(s[1:-1])
    l = set(pre)
    if len(l) == 1:
        while pre and len(temp) < len(pre):
            pre.pop()

    res = strStr(temp, pre)
    if res == -1:
        return "Just a legend"
    return pre


