def get_neighbors(curr):
    s1, s2 = curr
    s1, s2 = curr
    neighbors = [] # holds tuples of (neighbor, weight)
    if s1 and s2:
        if s1[0] == s2[0]:
            # can just stop looking at the first letter
            rest_of_strings = tuple(sorted((s1[1:], s2[1:])))
            if rest_of_strings not in visited:
                visited.add(rest_of_strings)
                neighbors.append((rest_of_strings, 0))
        else:
            # first letters are not the same, add edges from changings
            l1, l2 = s1[0], s2[0]
            for l1c_next_letter, weight in changings[l1].items():
                neighbor = tuple(sorted((l1c_next_letter + s1[1:], s2)))
                if neighbor not in visited:
                    visited.add(neighbor)
                    neighbors.append((neighbor, weight))

            for l2c_next_letter, weight in changings[l2].items():
                neighbor = tuple(sorted((s1, l2c_next_letter + s2[1:])))
                if neighbor not in visited:
                    visited.add(neighbor)
                    neighbors.append((neighbor, weight))

    return neighbors

heap_elements_dict = dict()
distances_heap = []
heapq.heapify(distances_heap)

# also update parent?
def add_or_update_node_distance(n, distance, parent):
    if n in heap_elements_dict:
        remove_node_distance(n)
    new_element = [distance, n, parent]
    heap_elements_dict[n] = new_element
    heapq.heappush(distances_heap, new_element)

def remove_node_distance(n):
    heap_element = heap_elements_dict[n]
    heap_element[-1] = ("REMOVED", "REMOVED")

def pop_lowest_distance(): # pop top of heap
    while distances_heap and distances_heap[0][-1] == ("REMOVED", "REMOVED"):
        heapq.heappop(distances_heap)
    if distances_heap:
        ans = heapq.heappop(distances_heap)
        d, lowest_node, p = ans
        if lowest_node in heap_elements_dict:
            del heap_elements_dict[lowest_node]
        return ans
    return None

