def smallest_divisor(n, k):
    fact = []
    i = 1
    while i < math.sqrt(n):
        if n % i == 0:
            if n / i == i:
                fact.append(int(i))
            else:
                fact.append(int(i))
                fact.append(int(n / i))
        i += 1
    fact = sorted(fact)
    if k > len(fact):
        return -1
    return fact[k - 1]

