N, K = 0, 0
edges = []

# output
result = 0

def read_input():
    global N, K
    readline = sys.stdin.readline
    N, M, K = [int(w) for w in readline().split()]
    for _ in range(M):
        edges.append([int(w) - 1 for w in readline().split()])

def solve():
    global result
    uf = UnionFind(N)
    for u, v in edges:
        uf.union(u, v)
    if K == 1:
        result = max(0, uf.count - 2)
        return
    max_tunnel_cap = 0
    seen = set()
    for i in range(N):
        x = uf.find(i)
        if x in seen:
            continue
        seen.add(x)
        max_tunnel_cap += min(K, uf.size[x])
    result = max(0, N - (max_tunnel_cap // 2) - 1)

def write_output():
    print(result)


