def ad(d,c):
	"""add to dict"""
	d.setdefault(c,0)
	d[c]+=1

def wtd(s):
	"""word to dict"""
	d=dict()
	for c in s:
		ad(d,c)
	return d

def mid(fd,sd):
	"""min in dicts"""
	v=[]
	for c in fd.keys():
		v.append(sd[c]//fd[c])
	return min(v)
	
def hmw(w,s):
	"""how many word from str"""
	dw=wtd(w)
	dc=dict()
	for c in s:
		if c in dw:
			ad(dc,c)
	return mid(dw,dc)
	
