import math


def can_eat_half(n, k):
    tot = n
    cur = 0
    while True:
        tot -= k
        if tot <= 0:
            cur += (k + tot)
            break
        cur += k
        if cur >= math.ceil(n / 2):
            return True
        tot = math.ceil(0.9 * tot)
    return cur >= math.ceil(n/2)


