class PoV:
    def __init__(self,x,y):
        self.x  = x
        self.y  = y
        self.u  = x*int(2e9+9)+y #unique

    def __sub__(self,o):
        return PoV(self.x-o.x,self.y-o.y)

    def __mul__(self,o):
        return self.x*o.x + self.y*o.y

