def solve(n, m, grid):
    for i in range(n):
        wbcnt = 0
        for j in range(1, m):
            if grid[i][j] == 'B' and grid[i][j - 1] == 'W':
                wbcnt += 1
                if wbcnt > 1:
                    return False

    for j in range(m):
        wbcnt = 0
        for i in range(1, n):
            if grid[i][j] == 'B' and grid[i - 1][j] == 'W':
                wbcnt += 1
                if wbcnt > 1:
                    return False

    bps = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'B':
                bps.append((i, j))
    for bp1 in bps:
        for bp2 in bps:
            if bp1 != bp2:
                #print(bp1[0], bp2[1], ' //// ', bp2[0], bp1[1])
                if not ( (grid[bp1[0]][bp2[1]] == 'B') or (grid[bp2[0]][bp1[1]] == 'B') ):
                    return False
    return True

