def dijkstra(grafo, n):
    distancias = {}
    nodo_previo = {}
    no_visitados = grafo
    for nodo in no_visitados:
        distancias[nodo] = 9999999999999999
    distancias["1"] = 0

    while no_visitados:
        nodo_mas_cercano = None

        for nodo in no_visitados:
            if nodo_mas_cercano is None:
                nodo_mas_cercano = nodo
            elif distancias[nodo] < distancias[nodo_mas_cercano]:
                nodo_mas_cercano = nodo

        vecinos = grafo[nodo_mas_cercano].items()

        for vecino, distancia in vecinos:
            if distancia + distancias[nodo_mas_cercano] < distancias[vecino]:
                distancias[vecino] = distancia + distancias[nodo_mas_cercano]
                nodo_previo[vecino] = nodo_mas_cercano
        no_visitados.pop(nodo_mas_cercano)

    nodo_actual = n
    camino_mas_corto = ""

    while nodo_actual != "1":
        if nodo_actual in nodo_previo:
            camino_mas_corto = nodo_actual + " " + camino_mas_corto
            nodo_actual = nodo_previo[nodo_actual]
        else:
            camino_mas_corto = "-1"
            break
    camino_mas_corto = "1" + " " + camino_mas_corto
    return camino_mas_corto

