import math
from math import ceil, log2


def getMiddle(start, end):
    return start + (end - start) // 2


def RMQU(segmentTree, startSegment, endSegment, i, j, index):
    if i <= startSegment and j >= endSegment:
        return segmentTree[index]

    if endSegment < i or startSegment > j:
        return 0

    mid = getMiddle(startSegment, endSegment)
    return RMQU(segmentTree, startSegment, mid, i, j, 2 * index + 1) + RMQU(segmentTree, mid + 1, endSegment, i, j, 2 * index + 2)


def RMQ(segmentTree, n, i, j):
    if i < 0 or j > n - 1 or i > j:
        return -1

    return RMQU(segmentTree, 0, n - 1, i, j, 0)


def updateValue(arr, segmentTree, startSegment, endSegment, index, value, n):
    if index < startSegment or index > endSegment:
        return

    if startSegment == endSegment:

        arr[index] = value
        segmentTree[n] = value
    else:
        mid = getMiddle(startSegment, endSegment)

        if index >= startSegment and index <= mid:
            updateValue(arr, segmentTree, startSegment, mid, index,
                        value, 2 * n + 1)
        else:
            updateValue(arr, segmentTree, mid + 1, endSegment,
                        index, value, 2 * n + 2)

        segmentTree[n] = segmentTree[2 * n + 1] + segmentTree[2 * n + 2]
    return


def buildSegmentTree(arr, startSegment, endSegment, segmentTree, startIndex):
    if startSegment == endSegment:
        segmentTree[startIndex] = arr[startSegment]
        return arr[startSegment]

    mid = getMiddle(startSegment, endSegment)
    segmentTree[startIndex] = buildSegmentTree(arr, startSegment, mid, segmentTree, startIndex * 2 + 1) + buildSegmentTree(arr, mid + 1, endSegment, segmentTree, startIndex * 2 + 2)

    return segmentTree[startIndex]


def initSegmentTree(arr, n):
    x = int(ceil(log2(n)))
    maxSize = 2 * (int)(2 ** x) - 1
    segmentTree = [0] * maxSize
    buildSegmentTree(arr, 0, n - 1, segmentTree, 0)
    return segmentTree


def getDivisors(n):
    counter = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:

            if n / i == i:
                counter = counter + 1
            else:
                counter = counter + 2

    return counter


def main():
    n, m = list(map(int, input().split(' ')))
    arr = list(map(int, input().split(' ')))
    segmentTree = initSegmentTree(arr, n)

    for i in range(m):
        operation, x, y = list(map(int, input().split(' ')))
        #replace
        if operation == 1:
            for i in range(x,y+1):
                numDivisors = getDivisors(arr[i-1])
                updateValue(arr, segmentTree, 0, n - 1, i-1, numDivisors, 0)
        #query
        else:
            print(RMQ(segmentTree, n, x-1, y-1))

