class Trie:
    def __init__(self):
        self.root = TrieNode()
    def insert(self, word: str) -> None:
        ptr = self.root
        for i, c in enumerate(word):
            c = ord(c)-97
            if ptr.children[c] is  None:
                ptr.children[c] = TrieNode()

            ptr = ptr.children[c]
        ptr.is_end = True

    def search(self, word: str)-> None:

        prefix, is_end = self.searchPrefix(word)
        return prefix == word and is_end

    def searchPrefix(self, word:str) -> None:

        ptr =  self.root
        i = 0
        prefix = ""
        while ptr and i < len(word):
            c = ord(word[i])-97
            ptr = ptr.children[c]
            if ptr:
                prefix+=word[i]
            i+=1

        if ptr:
            return prefix, ptr.is_end
        return prefix, False

    def startsWith(self, word:str) -> None:

        prefix, is_end = self.searchPrefix(word)
        return prefix == word

    def findCommonPrefix(self):

        ptr = self.root
        cur = ""
        while ptr and not ptr.is_end:
            nonNone = [i for i, c in enumerate(ptr.children) if c is not None]

            if len(nonNone) == 1:
                cur+=chr(97 + nonNone[0])
            else:
                return cur
            ptr = ptr.children[nonNone[0]]

        return cur



