import sys


class Record:

    def __init__(self, prev, number):
        self.prev = prev
        self.next = None
        self.number = number
        self.cnt = 1


def sort_record_by_cnt(r: Record):
    if r is None:
        return -1
    return r.cnt


class Records:

    def __init__(self):
        self.last_record = None  # type: Record
        self.records = []

    def add(self, number):
        if self.last_record is not None and self.last_record.number == number:
            self.last_record.cnt += 1
        else:
            record = Record(self.last_record, number)
            if self.last_record is not None:
                self.last_record.next = record
                self.last_record = record
            self.records.append(record)
            self.last_record = record

    def sort(self, clear=False):
        if clear:
            new_records = []
            for record in self.records:
                if record is not None and record.cnt > 0:
                    new_records.append(record)
            self.records = new_records
        self.records.sort(key=sort_record_by_cnt)

    def find_max(self):
        """ :rtype: Record """
        return self.records.pop()

    def process_next(self):
        record = self.find_max()  # type: Record
        prev = record.prev  # type: Record
        next = record.next  # type: Record
        if prev is None and next is None:
            return True
        if prev is None:
            next.prev = None
            record.cnt = 0
            return False
        if next is None:
            prev.next = None
            record.cnt = 0
            return False
        if prev.number == next.number:
            next2 = next.next  # type: Record
            prev.cnt += next.cnt
            prev.next = next.next
            next.cnt = 0
            record.cnt = 0
            if next2 is not None:
                next.prev = prev
            self.sort()
            return False
        prev.next = next
        next.prev = prev
        record.cnt = 0
        return False

    def process(self):
        cnt = 0
        while not self.process_next():
            cnt += 1
        return cnt


