def good(semi, x, y):
  size = y - x + 1
  if size % 2 != 0:
    return False
    
  count = semi[y]
  if x > 0:
    count -= semi[x - 1]
  return count == size // 2
  
def exists(semi, size):
  if size % 2 != 0:
    return False
    
  for i in range(size - 1, len(semi)):
    left = i - size + 1
    if good(semi, left, i):
      return True
  return False
  
