from math import floor
def search(key, array):
    left = 0
    right = len(array) - 1
    mid = floor((left + right) / 2)

    while left <= right:
        if array[mid] == key:
            return mid
        
        if array[mid] < key:
            left = mid + 1
            mid = floor((left + right) / 2)
            continue

        if array[mid] > key:
            right = mid - 1
            mid = floor((left + right) / 2)
            continue

    return right


def binary_search(key, array):
    """
    w/o proximity,
    return -1 if not found
    """
    mid = floor((len(array) - 1) / 2)

    if len(array) <= 0:
        return -1
    
    if array[mid] == key:
        return mid
    
    if array[mid] > key:
        return binary_search(key, array[:mid])
    
    if array[mid] < key:
        return binary_search(key, array[mid + 1:])
    


