def dfs_len(x):

    if len.get(x, 0):
        return len[x]
    if x == 1 or x == 0:
        len[x] = 1
    else:
        len[x] = 2 * dfs_len(x // 2) + 1
    return len[x]


def dfs_one(x):
    if one.get(x, 0):
        return one[x]
    if x == 1:
        one[x] = 1
    elif x == 0:
        one[x] = 0
    else:
        one[x] = 2 * dfs_one(x // 2) + x % 2
    return one[x]


def dfs(x, cnt, ans):
    if cnt == 0:
        return 0
    else:
        if cnt == len[x // 2]:
            ans += one[x // 2]
            return ans
        elif cnt < len[x // 2]:
            return dfs(x // 2, cnt, ans)
        else:
            ans += one[x // 2] + x % 2
            cnt -= len[x // 2] + 1
            if cnt:
                return dfs(x // 2, cnt, ans)
            else:
                return ans


