def tree4graph(g):
    visited = [False] * n
    st = [0]
    pt = {}
    while st:
        v = st.pop()
        if visited[v]:
            continue
        visited[v] = True
        for v2 in g[v]:
            st.append(v2)
            if v2 not in pt and pt.get(v, None) != v2:
                pt[v2] = v
    return pt


def leaves4tree(t):
    return set(range(n)) - set(t.values())


def path4leaf(v, t):
    pth = [v]
    while t.get(v, None) is not None:
        v = t[v]
        pth.append(v)
    return pth


