        else:
            keys.remove(close_high)
        lowest.append(min(temp,temp_low,temp_high))
    return max(lowest)

def time(loc,keys,low,high,close,close_low,close_high):
    if (low<=high):
        mid=(low+high)//2
        if (keys[mid]==loc):
            close=keys[mid]
            return
        elif (keys[mid]<loc):
            close_low=keys[mid]
            return time(loc,keys,mid+1,high,close,close_low,close_high)
        else:
            close_high=keys[mid]
            return time(loc,keys,low,mid-1,close,close_low,close_high)
    return (close,close_low,close_high)
