def prefix_suffix(s):
    n = len(s)
    pi = [0] * n  # pi[i] stores the length of the longest proper prefix which is also a suffix of s[:i+1]

    for i in range(1, n):
        j = pi[i - 1]
        while j > 0 and s[i] != s[j]:
            j = pi[j - 1]
        if s[i] == s[j]:
            j += 1
        pi[i] = j

    k = pi[n - 1]
    if k == 0:
        print("Just a legend")
    else:
        for i in range(n - 2, 0, -1):
            if pi[i] == k:
                print(s[:k])
                return
        for i in range(1, n - 1):
            if pi[i] == k:
                print(s[n - k:])
                return
        print("Just a legend")


