class Segtree:
    def __init__(self, n):
        self.size = 1
        while self.size < n:
            self.size *= 2
        self.tree = [0] * self.size * 2

    def change(self, pos, val, v, tl, tr):
        if tl + 1 == tr:
            self.tree[v] = val
        else:
            m = (tl + tr) // 2
            if pos < m:
                self.change(pos, val, v*2+1, tl, m)
            else:
                self.change(pos, val, v*2+2, m, tr)
            self.tree[v] = self.tree[v*2+1] + self.tree[v*2+2]

    def calculate(self, l, r, v, tl, tr):
        if tl >= l and tr <= r:
            return self.tree[v]
        if tl >= r or tr <= l:
            return 0
        m = (tl + tr) // 2
        return self.calculate(l, r, v*2+1, tl, m) + self.calculate(l, r, v*2+2, m, tr)

