def solve(n,a,b,seq) :
    index = 0
    emptySpace = 0
    ans = 0
    while index < n and (a > 0 or b > 0) :
        if seq[index] == '*' :
            half = emptySpace//2
            half2 = emptySpace - half
            if a > b :
                if a >= half2 and b >= half :
                    a -= half2
                    b -= half
                    ans += emptySpace
                elif a < half2 :
                    if b == a-1 :
                        ans += a + b
                        a = 0
                        b = 0
                    else :
                        ans += b + (b + 1)
                        b = 0
                        a -= b + 1
                elif b < half :
                    ans += b + b + 1
                    a -= b + 1
                    b = 0
            else :
                if b >= half2 and a >= half :
                    b -= half2
                    a -= half
                    ans += emptySpace
                elif b < half2 :
                    if a >= b-1 :
                        ans += a + b
                        a = 0
                        b = 0
                    else :
                        ans += a + (a + 1)
                        a = 0
                        b -= a + 1
                elif a < half :
                    ans += a + a + 1
                    b -= a + 1
                    a = 0                
            emptySpace = 0
        else :
            emptySpace += 1
        index += 1
    
    if emptySpace > 0 :
        half = emptySpace//2
        half2 = emptySpace - half
        if a > b :
            if a >= half2 and b >= half :
                a -= half2
                b -= half
                ans += emptySpace
            elif a < half2 :
                if b == a-1 :
                    ans += a + b
                    a = 0
                    b = 0
                else :
                    ans += b + (b + 1)
                    b = 0
                    a -= b + 1
            elif b < half :
                ans += b + b + 1
                a -= b + 1
                b = 0
        else :
            if b >= half2 and a >= half :
                b -= half2
                a -= half
                ans += emptySpace
            elif b < half2 :
                if a >= b-1 :
                    ans += a + b
                    a = 0
                    b = 0
                else :
                    ans += a + (a + 1)
                    a = 0
                    b -= a + 1
            elif a < half :
                ans += a + a + 1
                b -= a + 1
                a = 0   
    return ans 
    
