import bisect


def bsearch(li, l, r):
    while l < r:
        m = l + (r - l + 1) // 2

        if m < len(li) // 2:
            l = m
            continue

        vis = [False] * len(li)
        res = True
        for i in range(m):
            p = bisect.bisect_left(li, li[i] * 2, m)

            while p < len(li) and vis[p]:
                p += 1

            if p < len(li):
                vis[p] = True
            else:
                res = False
                break

        if res:
            l = m
        else:
            r = m - 1

    return r


