class AcyclicGraph:

    def __init__(self):
        self.v = {}
        self.root = None

    def add(self, key, value):
        if key in self.v:
            self.v[key] = value
        else:
            self.v[key] = [value]
        if self.root is None:
            self.root = key

    def change_root(self, root):
        self.root = root

    def get_max_len(self):

        max_depth = 0

        def max_len(name, depth):
            nonlocal max_depth
            if name in self.v:
                for v in self.v[name]:
                    self.max_depth = max(max_depth, depth+1)
                    max_len(v, depth+1)

        max_len(self.root, 0)
        return self.max_depth



