import sys

def UpperBound(x):
    left=0;right=len(alive)
    while left<=right:
        m=(left+right)//2
        if alive[m]<=x:
            left=m+1
        else:
            right=m-1
    for i in range(max(0,right-2),min(len(alive),left+2)):
        if alive[i]>=x:
            return i
    return min(len(alive),left+2)-1

