def binary_search(c1, c2):
    c = (c1 + c2 + 1) // 2
    while abs(c1 - c2) > 1:
        c = (c1 + c2 + 1) // 2
        if ok(c):
            c2 = c
        else:
            c1 = c
    ans = max(c - 2, 0)
    while not ok(ans):
        ans += 1
    return ans

