class StackArray:
    
    def __init__(self):
        
        self._data=[]
        self._n=0
    
    def isEmpty(self):
        
        return self._n==0
    
    def push(self,ele):
        
        self._data.append(ele)
        self._n+=1
    
    def pop(self):
        
        if self.isEmpty():
            return 0
        temp=self._data[-1]
        self._data.pop()
        self._n-=1
        return temp
    
    def top(self):
        if self.isEmpty():
            return 0
        
        return self._data[-1]
    
    def Getdata(self):
        return self._data
    
