import sys
from enum import Enum
from collections.abc import Generator, Iterator


def to_iterable(fn, stack=None):
    if not stack:
        stack = []

    def inner(*args, **kwargs):
        if stack:
            return fn(*args, **kwargs)
        else:
            to = fn(*args, **kwargs)
            while True:
                if isinstance(to, Generator):
                    stack.append(to)
                    to = next(to)
                else:
                    val = stack.pop()
                    if not stack:
                        break
                    to = stack[-1].send(val)
        return to
    return inner


class States(Enum):
    UNVISITED = -1
    EXPLORED = 0
    VISITED = 1


moves = [(0, 1), (0, -1), (1, 0), (-1, 0)]


@to_iterable
def dfs(graph, i, j, color, prev_length, status: list[list[States]], prev_i, prev_j) -> Iterator[bool]:
    status[i][j] = States.EXPLORED

    for dr, dc in moves:
        if i + dr < 0 or i + dr >= len(graph):
            continue
        if j + dc < 0 or j + dc >= len((graph[0])):
            continue
        if graph[i + dr][j + dc] != color:
            continue
        if status[i + dr][j + dc] == States.VISITED:
            # No need to consider forwards edges
            continue
        # Ignore trivial loops
        if prev_i == i + dr and prev_j == j + dc:
            continue
        # We need to check if it is a back edge, which means ancestor -> parent, and parent is still exploring
        # and it is not a trivial cycle
        if prev_length + 1 >= 4 and status[i + dr][j + dc] == States.EXPLORED:
            yield True
        # If found stop doing work and just return
        found = dfs(graph, i + dr, j + dc, color, prev_length + 1, status, i, j)
        if found:
            yield True

    # We have completly visited the node so now we are done
    status[i][j] = States.VISITED
    yield False


def main() -> None:
    read = sys.stdin.readline
    m, n = (int(i) for i in read().split())
    status = [[States.UNVISITED for _ in range(n)] for _ in range(m)]
    graph = []
    for _ in range(m):
        graph.append(read().strip())
    for row in range(m):
        for col in range(n):
            if status[row][col] == States.UNVISITED:
                color = graph[row][col]
                found = dfs(graph, row, col, color, 0, status, None, None)
                if found:
                    print('Yes')
                    return
    print('No')


