def binary_search(n, l):
    low = 0
    high = len(l) - 1
    while low <= high:
        m = (low + high) // 2
        if l[m] < n:
            low = m + 1
        elif l[m] > n:
            high = m - 1
        else:
            return (l[m])
    return (l[low-1], l[min(high+1, len(l)-1)])

