def solve(val, denom):
    den = sorted(denom, reverse=True)
    counter = 0
    i = len(denom)-1
    memo = dict()
    
    def min_bills(amount, memo={}):
        if amount in memo:
            return memo[amount]

        if amount == 0:
            return 0

        min_bills_count = float('-inf')

        nonlocal den
        denominations = den

        for denom in denominations:
            if amount >= denom:
                num_bills = amount // denom
                remaining_amount = amount - num_bills * denom
                num_bills += min_bills(remaining_amount, memo)
                min_bills_count = max(min_bills_count, num_bills)

        memo[amount] = min_bills_count
        return min_bills_count
    
    return min_bills(val, memo)

