def bishop(a,b,x,y):
    if a==x and b==y:
        return 0
    if abs(a-x) == abs(b-y):
        return 1
    for i in range(-7,8):
        if x+i<=0:
            continue
        if abs(a-x-i)==abs(b-y-i):
            return 2
    return 0

def king(a,b,x,y):
    if a==x:
        return abs(b-y)
    if b==y:
        return abs(a-x)
    if x>a and y>b:
        return 1+king(a+1,b+1,x,y)
    if x>a and y<b:
        return 1+king(a+1,b-1,x,y)
    if x<a and y>b:
        return 1+king(a-1,b+1,x,y)
    return 1+king(a-1,b-1,x,y)
    
