class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y


class Segment:
    def __init__(self, p1, p2):
        self.p1 = p1
        self.p2 = p2

    @property
    def k(self):
        dy = self.p2.y - self.p1.y
        dx = self.p2.x - self.p1.x
        if dx == 0:
            return dy * float('inf')
        return dy / dx

    def __lt__(self, other):
        return self.k < other.k

    def __eq__(self, other):
        return abs(self.k - other.k) < 1e-6


