        L = len(segments[i])
        if L < 2:
            continue
        res = L * (L - 1) // 2
        prev_k = segments[i][0].k
        k_counter = 1
        for j in range(1, L):
            if segments[i][j].k == prev_k:
                k_counter += 1
            else:
                res -= k_counter * (k_counter - 1) // 2
                prev_k = segments[i][j].k
                k_counter = 1
        res -= k_counter * (k_counter - 1) // 2
        result += res

    print(result)


