import sys
import heapq

def cin():
    return sys.stdin.readline()

def solve():
    n, m = [int(x) for x in cin().split(" ")]

    graph = {x:{} for x in range(1, n+1)}

    for _ in range(m):
        u, v, w = [int(x) for x in cin().split(" ")]
        graph[u][v] = w
        graph[v][u] = w


    # djikstra
    p_q = [(0, 1)]
    distances = {x: float('inf') for x in graph}
    predecessor = {}
    distances[1] = 0
    visited = set()

    while p_q:
        weight, node = heapq.heappop(p_q)

        if node in visited:
            continue

        visited.add(node)

        for n_node, n_weight in graph[node].items():
            new_dist = n_weight + weight
            if new_dist < distances[n_node]:
                distances[n_node] = new_dist
                predecessor[n_node] = node
                heapq.heappush(p_q, (new_dist, n_node))

    #
    if len(visited) != n:
        print(-1)

    # create path
    path = []
    current_node = n
    while current_node != 1:
        path.append(current_node)
        current_node = predecessor[current_node]
    path.append(1)

    path.reverse()

    print(*path)

