import math

# Function to check if a number is prime
def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

# Function to determine if a number is T-prime
def is_t_prime(n):
    if n == 1:
        return False
    sqrt_n = int(math.sqrt(n))
    if sqrt_n * sqrt_n == n and is_prime(sqrt_n):
        return True
    return False

