def bisearch(l:list,k:int):
    if k>l[-1]:return False
    n=len(l)
    start,end=0,n-1
    while start<end:
        mid=(start+end)//2
        if l[mid]==k:return True
        elif l[mid]<k:start=mid
        else: end=mid
        if end-start<=1 and l[mid]<k<l[mid+1]:return False

