    else:
        if (s:=int(sqrt(n)))<=prime[-1]:
            for prime in primes:
                if n%prime==0:
                    return False
            return True
        else:
            for i in range(prime[-1]+1,s+1):
                for prime in primes:
                    if n%prime:return False
                    if i%prime==0:break
                else:primes.append(i)
            return True

def isTprime(n:int)->bool:
    sq=int(n**0.5)
    if sq*sq==n and isprime(sq):
