def find_range(a, seq):
    return (seq.find(a), seq.rfind(a))


def solve(rs, k):
    count = [0] * (10**6 + 1)
    for r in rs:
        if r[0] == -1:
            continue
        for i in range(r[0], r[1] + 1):
            count[i] += 1
    return max(count) > k


