class Node:
  def __init__(self):
    self.endWord = False
    self.children = {}


def addNode(root, num, s, changed):
  if root.endWord == True:
    return ''
  

  if num == 0:
    root.endWord = True

    if changed == False:
      return ''
    
    return s

  for c in ['0', '1']:
    if c not in root.children:
      root.children[c] = Node()
      changed = True
    temp = addNode(root.children[c], num - 1, s + c, changed)
    if temp != '':
      return temp
  
  return ''



