def sq2_treug(x1,y1, x2,y2, x3,y3) -> int:
    ''' doubled square of triangle with sign. '''
    return (x3-x1)*(y2-y1) - (y3-y1)*(x2-x1)

def point_in_square(x,y, x1,y1, x2,y2, x3,y3, x4,y4, sq2) -> bool:
    sq1 = abs(sq2_treug(x,y, x1,y1, x2,y2)) \
        + abs(sq2_treug(x,y, x2,y2, x3,y3)) \
        + abs(sq2_treug(x,y, x3,y3, x4,y4)) \
        + abs(sq2_treug(x,y, x4,y4, x1,y1))
    return sq2 == sq1

