def main():
    n, m = map(int, input().split())
    nei_L = [[] for _ in range(n)]
    for _ in range(m):
        x, y, z = map(int, input().split())
        x -= 1
        y -= 1
        nei_L[x].append([y, z])
        nei_L[y].append([x, z])
    limit_mat = []
    for _ in range(n):
        L = list(map(int, input().split()))
        L = L[1:]
        flag = []
        for i, num in enumerate(L):
            flag.append([num, num - i])  # 记录限制的时间，限制时间与索引的关系
        limit_mat.append(flag)
    # 将目标点的限制改为空，后续就不用特判了
    limit_mat[-1] = []
    dist = [float("inf")] * n
    if len(limit_mat[0]) == 0 or limit_mat[0][0][0] > 0:
        dist[0] = 0
    else:
        limit_index = limit_mat[0][0][1]
        if limit_mat[0][-1][1] == limit_index:
            dist[0] = limit_mat[0][-1][0] + 1
        else:
            left = 0
            right = len(limit_mat[0]) - 1
            while left < right:
                middle = (left + right) // 2
                if limit_mat[0][middle][1] > middle:
                    right = middle
                else:
                    left = middle + 1
            dist[0] = limit_mat[0][left][1]
    q = [(dist[0], 0)]
    while len(q) > 0:
        distance, x = heapq.heappop(q)
        for y, z in nei_L[x]:
            old = distance + z
            if len(limit_mat[y]) == 0 or old < limit_mat[y][0][0] or old > limit_mat[y][-1][0]:
                new = old
            else:
                left = 0
                right = len(limit_mat[y]) - 1
                while left < right:
                    middle = (left + right + 1) // 2
                    if limit_mat[y][middle][0] <= old:
                        left = middle
                    else:
                        right = middle - 1
                if limit_mat[y][left][0] != old:
                    # 当前到达时间没有被限制
                    new = old
                else:
                    limit_index = limit_mat[y][left][1]
                    new_left = left
                    new_right = len(limit_mat[y]) - 1
                    while new_left < new_right:
                        middle = (new_left + new_right + 1) // 2
                        if limit_mat[y][middle][1] <= limit_index:
                            new_left = middle
                        else:
                            new_right = middle - 1

                    new = limit_mat[y][new_left][0] + 1
            if new < dist[y]:
                dist[y] = new
                heapq.heappush(q, (dist[y], y))
    if dist[-1] == float("inf"):
        print(-1)
    else:
        print(dist[-1])




