class Node(object):
    def __init__(self, value):
        self.value = value
        self.visited = False
        self.childrens = []

    def visit(self):
        self.visited = True

    def next(self):
        for index in range(len(self.childrens),-1,-1):
            if index < len(self.childrens) and not self.childrens[index].visited:
                return self.childrens[index]

class Stack(object):
    def __init__(self):
        self.stack = []

    def push(self, value):
        self.stack.append(value)

    def top(self):
        if self.__len__() > 0:
            return self.stack[-1]

    def pop(self):
        self.stack.pop()

    def __len__(self):
        return len(self.stack)

    def __iter__(self):
        self.index = self.__len__()
        return self

    def __next__(self):
        if self.index >= 0:
            result = self.stack[self.index]
            self.index -= 1
            return result
        else:
            raise StopIteration

def main():
    home,d = input().split(" ")
    home,d = int(home),int(d)
    inp = input()
    current_node = Node(1)
