    stack.push(current_node)
    dx=1
    jump=0
    run = True
    leng = len(inp)
    while run:
        if current_node.value == home:
            run = False
        elif jump == -1:
            run = False
        elif dx < d:
            if (current_node.value + dx -1 ) < leng  and inp[current_node.value - 1 + dx] == "1":
                node = Node(current_node.value + dx)
                current_node.childrens.append(node)
