                node = Node(current_node.value + dx)
                current_node.childrens.append(node)
            current_node.visit()
            if len(current_node.childrens) == 0:
                stack.pop()
                current_node = stack.top()
                if current_node == None:
                    jump =-1
                    run = False
                else:
                    dx = 1
                    jump -= 1
