def pow(x, exp, mod=-1):
    res = 1
    if mod == -1:
        while exp:
            if exp & 1:
                res *= x
            x *= x
            exp >>= 1
    else:
        while exp:
            if exp & 1:
                res = (res * x) % mod
            x = (x * x) % mod
            exp >>= 1
    return res


