def phi(n):
  def is_prime(n):
    if n == 1:
      return False
    if n % 2 == 0:
      return False
    i = 3
    while i * i <= n:
      if n % i == 0:
        return False
      i += 2
    return True

  def prime_factors(n):
    prime_factor_list = []
    while not n % 2:
      prime_factor_list.append(2)
      n //= 2
    while not n % 3:
      prime_factor_list.append(3)
      n //= 3
    i = 5
    while n != 1:
      if is_prime(i):
        while not n % i:
          prime_factor_list.append(i)
          n //= i
        i += 2

    return prime_factor_list

  res = n
  primes = set(prime_factors(n))
  for p in primes:
    res *= (1-1/p)
  return int(res)

def phi_sympy(n):
  from sympy.ntheory import factorint
  res = n
  primes = factorint(n).keys()
  for p in primes:
    res *= (1-1/p)
  return int(res)

