def modulo(M):
    M = deepcopy(M)
    m = 1000000007
    for i in range(len(M)):
        for j in range(len(M[i])):
            M[i][j] %= m
    return M


def mult_M(M1, M2):
    Mr = deepcopy(M1)
    for i in range(len(M)):
        for j in range(len(M[i])):
            Mr[i][j] = 0
            for k in range(len(M[i])):
                Mr[i][j] += M1[i][k] * M2[k][j]
    Mr = modulo(Mr)
    return Mr


def square_M(M1):
    return mult_M(M1, M1)


def pow_M(M1, power):
    M2 = deepcopy(M1)
    if power == 0:
        for i in range(len(M2)):
            for j in range(len(M2[i])):
                M2[i][j] = (i==j) * 1
        return M2
    if power < 4:
        for i in range(power-1):
            M2 = mult_M(M2, M1)
        return M2
    r = int(power / 2)
    MS = square_M(pow_M(M1, r))
    return mult_M(MS, pow_M(M1, power - 2*r))

