def fullsq2(n, p1, p2):
    if p1 + 1 == p2:
        if p1 * p1 <= n:
            return p1
        else:
            return p2
    p = (p1 + p2) // 2
    pp = p * p
    if pp == n:
        return p
    if pp < n:
        return fullsq2(n, p, p2) 
    else:
        return fullsq2(n, p1, p)

def fullsq(n):
    if n == 0:
        return 0 
    if n <= 3:
        return 1
    return fullsq2(n, 0, n)

