from sys import stdin


def gcd(a, b):
    if a < b:
        a, b = b, a

    while b:
        a, b = b, a % b
    return a


def solve(tc):
    n = int(stdin.readline().strip())
    seq = list(map(int, stdin.readline().split()))

    candidates = []
    for i in range(n-1, -1, -1):
        attached = False
        for j in range(len(candidates)):
            if gcd(candidates[j][0], seq[i]) > 1:
                attached = True
                candidates[j][0] = seq[i]
                candidates[j][1] += 1
        if not attached:
            candidates.append([seq[i], 1])

    ans = 0
    for res in candidates:
        ans = max(ans, res[1])

    print(ans)



tcs = 1
for tc in range(tcs):
    solve(tc)

