    g[a].add(b)
    g[b].add(a)

used = [0] * n
s = [0] * n

def sizes(v, p):
    s[v] = 1
    for u in g[v]:
        if u != p and not used[u]:
            sizes(u, v)
            s[v] += s[u]

def centroid(v, p, n):
    ret = v
    for u in g[v]:
        if u != p and not used[u] and s[u] > n/2:
            ret = centroid(u, v, n)
    return ret


def dfs(v, p, d, t):
    t.append(d)
    for u in g[v]:
        if u != p and not used[u]:
            dfs(u, v, d + 1, t)

ans = 0
def solve(v):
    global ans
    sizes(v, -1)
    d = [0] * (n + 1)
    d[0] = 1
    for u in g[v]:
        if not used[u]:
            t = []
            dfs(u, v, 1, t)
            for x in t:
                if x <= k:
                    ans += d[k - x]
            for x in t:
                d[x] += 1
    used[v] = 1
    for u in g[v]:
        if not used[u]:
            solve(centroid(u, v, s[u]))
