class Python:

    def __init__(self, modulus):
        self.levels = 0
        self.choices = 1
        self.modulus = modulus
        self.last_statement_is_for = False

    def add_choices(self):
        self.choices += self.levels
        if self.choices >= self.modulus:
            self.choices = self.choices % self.modulus

    def add_for_statement(self):
        if self.last_statement_is_for:
            self.levels += 1
        else:
            self.add_choices()
            self.last_statement_is_for = True

    def add_simple_statement(self):
        if self.last_statement_is_for:
            self.levels += 1
            self.last_statement_is_for = False
        else:
            self.add_choices()


