from math import sqrt
def compute(array,n):
	block_size = int(sqrt(n))
	temp=(n+block_size-1)//block_size
	block = {x:{} for x in range(temp)}
	block_index=-1
	#print(block_size)
	for i in range(n):
		if i%block_size == 0:
			block_index+=1
		if array[i] not in block[block_index]:
			block[block_index][array[i]]=1

		else:
			block[block_index][array[i]]+=1		
	return block

def query(array,block,l,r,n):
	block_size = int(sqrt(n))
	final= {}
	sum=0
	while l<r and not(l%block_size) and not(l):
		if array[l] not in final:
			final[array[l]]=1
		else:
			final[array[l]]+=1
		l+=1

	while l+block_size <= r+1 :
		temp=l//block_size
		for x in block[temp]:
			if x not in final:
				final[x]=block[temp][x]
			else:
				final[x]+=block[temp][x]
		l+=block_size

	while l<=r:
		if array[l] not in final:
			final[array[l]]=1
		else:
			final[array[l]]+=1
		l+=1

	for x in final:
		t=final[x]**2
		sum+=t*x
	return sum

