        a=(a*a)%m
        b>>=1
    return res%m

def phi(n):
    res=n
    for i in range(2,int(m.sqrt(n))+1):
        if n%i==0:
            while (n % i) == 0:
                n//=i
            res-=(res//i)
    if n>1:
        res-=(res//n)
    return res

