class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class Graph:
    def __init__(self, V):
        self.V = V
        self.adj = [None] * V

    def add_edge(self, u, v):
        node = Node(v)
        node.next = self.adj[u]
        self.adj[u] = node

    def is_reachable(self, u, v):
        visited = [False] * self.V
        queue = []
        visited[u] = True
        queue.append(u)
        while queue:
            s = queue.pop(0)
            if s == v:
                return True
            temp = self.adj[s]
            while temp:
                try:
                    if not visited[temp.data]:
                        visited[temp.data] = True
                        queue.append(temp.data)
                    temp = temp.next
                except:
                    return False
        return False

