import math

n, m = 0, 0
right_distance = []
left_distance = []


def calculate_left_distance(floor_structure):
    global left_distance
    for i in range(n):
        for j in range(m, 0, -1):
            if floor_structure[i][j] == '1':
                left_distance.append(j)
                break
        else:
            left_distance.append(0)


def calculate_right_distance(floor_structure):
    global right_distance
    for i in range(n):
        for j in range(1, m + 1):
            if floor_structure[i][j] == '1':
                right_distance.append(m+1-j)
                break
        else:
            right_distance.append(0)


def calculate_time(floor_structure, pos, index):
    if index == 0:
        if pos=='l':
            return left_distance[index]
        return right_distance[index]
    if pos == 'l':
        return min(calculate_time(floor_structure, 'l', index - 1) + (2 * left_distance[index])+1,calculate_time(floor_structure,'r',index-1)+m+2)
    else :
        return min(calculate_time(floor_structure,'r',index-1)+(2*right_distance[index])+1,calculate_time(floor_structure,'l',index-1)+m+2)


def main():
    global n, m
    n, m = [int(x) for x in input().split()]
    floor_structure = []
    for i in range(n):
        temp = input()
        floor_structure.append(temp)

    calculate_left_distance(floor_structure)
    calculate_right_distance(floor_structure)
    print(calculate_time(floor_structure, 'l', n - 1))


