def solve_problem_193A(n, m, a): 
  tot = sum(row.count('#') for row in a) 
  if tot < 3: 
    return -1

  dir4 = [(-1, 0), (1, 0), (0, -1), (0, 1)]
  vis = [[0] * m for _ in range(n)]

  def dfs(x, y, t):
      nonlocal cnt
      if x < 0 or x >= n or y < 0 or y >= m or vis[x][y] == t or a[x][y] != '#':
          return False
      vis[x][y] = t
      cnt += 1
      for dx, dy in dir4:
          dfs(x + dx, y + dy, t)
      return True

  t = 0
  for i, row in enumerate(a):
      for j, b in enumerate(row):
          if b != '#':
              continue
          row[j] = '.'
          t += 1
          cnt = 0
          for dx, dy in dir4:
              if dfs(i + dx, j + dy, t):
                  break
          if cnt < tot - 1:
              return 1
          row[j] = '#'
  return 2
