#version 2 with priority queue
from collections import defaultdict
from queue import PriorityQueue

class Node:
    def __init__(self,data):
        self.data = data
        self.next = None
        self.prev = None

class Stack:
    def __init__(self):
        self.head = None
        self.last = None
            
    def push (self,data):
        new_node = Node(data)
        if self.head == None:
            self.head = new_node
            self.last = new_node
        else:
            self.last.next = new_node
            new_node.prev = self.last
            self.last = new_node
        del new_node
        
    def pop (self):
        temp = self.last
        a = temp.data
        self.last = temp.prev
        if temp.prev == None:
            a = temp.data
            temp = None
            self.head = None
            return a
        self.last.next = None
        return a

def dijkstra(k,graph,visited):
    n = len(visited)
    parent = [-1]*n                    #creating an array just to track the path 
    infinite = float('inf')            #creating a variable which gives reference to infinite
    dist = [infinite]*(n)            #creating an distance list & assigning to infinite
    ind_hash = {}
    for i in range(n):
        ind_hash.update({visited[i]:i})
        
    que = PriorityQueue()
    que.put((0,ind_hash[1]))
    
    while not que.empty() and visited[ind_hash[k]]:
        min_dist,ind = que.get()    

        if visited[ind] != False:
            i = visited[ind]
            visited[ind] = False         #checking that the node with the minimum distance is not visited
            for edge in graph[i]:
                vind = ind_hash[edge[0]]
                if visited[vind]:
                    di = min_dist + edge[1]
                    if di<dist[vind]:
                        que.put((di,vind))
                        parent[vind] = ind
                        dist[vind] = di
    return parent
        
