def MinimumTrokeNumber(left, right, painted):
    
    if left > right:
        return 0
    
    # Find the position of the shortest plank in range from left to right
    mini = plankLs[left]
    posMin = left
    for idx in range(left, right+1):
        if plankLs[idx] < mini:
            mini = plankLs[idx]
            posMin = idx
    
    recursive = plankLs[posMin] - painted + MinimumTrokeNumber(left, posMin-1, plankLs[posMin]) + \
        MinimumTrokeNumber(posMin+1, right, plankLs[posMin])
    
    allPlanks = right - left + 1 # Will paint vertical when having only 1 plank

    return min(recursive, allPlanks)
    

