def binary_search(array,low,high,target):
    if low <= high:
        mid = (low + high) // 2

        if array[mid] == target:
            return mid

        elif array[mid] < target:
            return binary_search(array,mid + 1,high,target)
        
        elif array[mid] > target:
            return binary_search(array,low,mid - 1,target)
    else:
        return -1

def binary_search_closest(array,low,high,target):
    if low <= high:
        mid = (low + high) // 2

        if array[mid] == target:
            return mid
        
        elif array[mid] > target:
            if mid == 0 or array[mid - 1] <= target:
                return mid
            else:
                return binary_search_closest(array,low,mid - 1,target)
        else:
            return binary_search_closest(array,mid+1,high,target)
    else:
        return -1
    
