def find_max(m, s):
    if s == 0:
        return ['0'] if m == 1 else ['-1']
    if s > 9*m:
        return -1

    res = [0]*m
    for i in range(m):
        if s >= 9:
            res[i] = 9
            s -= 9
        else:
            res[i] = s
            s = 0

    return list(map(str, res))


