thing = namedtuple('item', ['val', 'index'])
def topsort(adjList, inDeg,vals,  N):
	retval = 1
	count =0
	pq = queue.PriorityQueue()
	for k in range(0,N):
		if inDeg[k]==0:
			pq.put(thing(vals[k], k))
	while(pq.empty()!=True):
		maybe = 0
		count = count+1
		cur = pq.get()
		if pq.empty()==True and cur.val==1:
			maybe = 1
		for adj in adjList[cur.index]:
			inDeg[adj]-=1
			if inDeg[adj]==0:
				pq.put(thing(vals[adj],adj))
				if vals[adj] ==0:
					retval +=maybe
	if count == N:
		return retval
	else:
		return 'error?', count

