def isPowerOfTwo(n):
    if (n == 0):
        return False
    while (n != 1):
            if (n % 2 != 0):
                return False
            n = n // 2
    return True
def sib_sum(n):
    s=0
    for i in range(1,n+1):
        if (isPowerOfTwo(i)):
            s=s-i
        else:
            s=s+i
    return s
