    if n == 1:
        return int(l <= x <= r)
    if n == 2:
        return int(l <= 11*x <= r)
    lo = 0
    hi = int("9"*(n-2))
    if get(n, x, hi) < l or get(n, x, lo) > r:
        return 0

    while hi - lo > 1:
        mid = (hi + lo) // 2
        if get(n, x, mid) > r:
