from sys import stdin
def bubble(alist):
    cont = 0
    for i in range(len(alist)-1,0,-1):
        for j in range(i):
            if int(alist[j]) < int(alist[j+1]):
                temp = int(alist[j])
                alist[j]=int(alist[j+1])
                alist[j+1]= temp
                cont += 1
    return alist

def mayor(lista):
    maxi = lista[0]
    for k in lista:
        if maxi < k:
            maxi = k
    return maxi

def pos(lista,num):
    pos = 0
    for l in lista:
        if l == num:
            return pos
        else:
            pos+=1

