import sys

def ans(mat):
    emma = []
    for i in range(len(mat)):
        emma.append(mat[i][0])
    
    visited = [False]*len(emma)
    
    while True:
        m, n = max_from_emma(emma, visited)
        current_max = sys.maxsize
        for i in range(len(mat[0])):
            if mat[n][i] < current_max:
                current_max = mat[n][i]
        
        if current_max >= m or n is -1:
            return current_max
        
        pass
    pass

def max_from_emma(emma, visited):
    ref = -sys.maxsize
    index = -1
    for i in range(len(emma)):
        if emma[i] >= ref and visited[i] is False:
            index = i
            ref = emma[i]
    if index is not -1:
        visited[index] = True

    return ref, index


