class FastIO:
    def __init__(self):
        return

    @staticmethod
    def _read():
        return sys.stdin.readline().strip()

    def read_int(self):
        return int(self._read())

    def read_float(self):
        return float(self._read())

    def read_ints(self):
        return map(int, self._read().split())

    def read_floats(self):
        return map(float, self._read().split())

    def read_ints_minus_one(self):
        return map(lambda x: int(x) - 1, self._read().split())

    def read_list_ints(self):
        return list(map(int, self._read().split()))

    def read_list_floats(self):
        return list(map(float, self._read().split()))

    def read_list_ints_minus_one(self):
        return list(map(lambda x: int(x) - 1, self._read().split()))

    def read_str(self):
        return self._read()

    def read_list_strs(self):
        return self._read().split()

    def read_list_str(self):
        return list(self._read())

    @staticmethod
    def st(x):
        return sys.stdout.write(str(x) + '\n')

    @staticmethod
    def lst(x):
        return sys.stdout.write(" ".join(str(w) for w in x) + '\n')

    @staticmethod
    def round_5(f):
        res = int(f)
        if f - res >= 0.5:
            res += 1
        return res

    @staticmethod
    def max(a, b):
        return a if a > b else b

    @staticmethod
    def min(a, b):
        return a if a < b else b

    @staticmethod
    def bootstrap(f, queue=[]):
        def wrappedfunc(*args, **kwargs):
            if queue:
                return f(*args, **kwargs)
            else:
                to = f(*args, **kwargs)
                while True:
                    if isinstance(to, GeneratorType):
                        queue.append(to)
                        to = next(to)
                    else:
                        queue.pop()
                        if not queue:
                            break
                        to = queue[-1].send(to)
                return to
        return wrappedfunc


def main(ac=FastIO()):
    n, m = ac.read_ints()
    dct = [defaultdict(lambda: inf) for _ in range(n)]
    for _ in range(m):
        u, v, w = ac.read_list_ints()
        u -= 1
        v -= 1
        dct[u][v] = ac.min(dct[u][v], w)
        dct[v][u] = ac.min(dct[v][u], w)
    if n == 1:
        ac.st(1)
        return
    # 模板：Dijkstra求最短路，变成负数求可以求最长路（还是正权值）
    dis = [inf] * n
    stack = [[0, 0]]
    dis[0] = 0
    father = [-1] * n
    while stack:
        d, i = heapq.heappop(stack)
        if dis[i] < d:
            continue
        for j in dct[i]:
            dj = dct[i][j] + d
            if dj < dis[j]:
                dis[j] = dj
                father[j] = i
                heapq.heappush(stack, [dj, j])
    if dis[n - 1] == inf:
        ac.st(-1)
    else:
        path = []
        i = n - 1
        while i != -1:
            path.append(i + 1)
            i = father[i]
        path.reverse()
        ac.lst(path)
    return


