def dfs(graph,n,currnode):
    visited=[False for x in range(n)]
    stack=[currnode]   ###keep track of current node
    ans=[]
    while stack:
        currnode=stack[-1]
        if visited[currnode]==False:
            visited[currnode]=True
            #ans.append(currnode)(normal dfs)
        if currnode in graph:
            for neighbour in graph[currnode]:
                if visited[neighbour]==False:
                    visited[neighbour]=True
                    stack.append(neighbour)
                    #ans.append(neighbour)   (normal dfs)
                    break
            else:
                ans.append(stack.pop()) ####we are backtracking to previous node which is in  our stack
        else:
            ans.append(stack.pop())
    return ans[-1::-1]
