    d = {}
    n = len(S)
    total_substrings = n*(n+1)//2
    if k > total_substrings:
        return 'No such line.'
    for i in range(n):
        c = S[i]
        if c not in d:
            d[c] = [[], 0]
        d[c][0].append(i)
        d[c][1]+=(n-i)
    total = 0
    for c in sorted(d):
        if total+d[c][1] < k:
            total+=d[c][1]
        else:
            first_letter = c
            k = k-total
            curr = d[c][0]
            total_strings = d[c][1]
            break
    if k <= len(curr):
        return first_letter
    l = 2
    while len(curr) > 0:
        d = {}
        if k >= len(curr):
            i = curr[0]
            return S[i:i+l]
        for i in curr:
            if i+l-1 <= n-1:
                c2 = S[i+l-1]
                if c2 not in d:
                    d[c2] = [[], 0]
                d[c2][0].append(i)
                d[c2][1]+=(n-i-l+1)
        total = 0
        for c in sorted(d):
            if total+d[c][1] < k:
                total+=d[c][1]
            else:
                next_letter =  c
                k = k-total
                curr = d[c][0]
                break 
        l+=1
            
