import bisect


class Slot:
	def __init__(self, w, h, i) -> None:
		self.w = w
		self.h = h
		self.i = i
	def __str__(self):
		return str(self.i)
	def __repr__(self):
		return f"({self.w}, {self.h})"

[n, w, h] = list(map(int, input().split(' ')))
slots: list[Slot] = []
for i in range(n):
	[wi, hi] = list(map(int, input().split(' ')))
	if wi > w and hi > h:
		min = bisect.bisect_left(slots, wi, key=lambda x: x.w)
		max = bisect.bisect_right(slots, wi, key=lambda x: x.w)
		bisect.insort(slots, Slot(wi, hi, i + 1), min, max, key=lambda x: x.h)

chains: list[list[Slot]] = [[slots[0]]]

for slot in slots[1:]:
	for chain_i in reversed(range(len(chains))):
		if chains[chain_i][-1].h < slot.h:
			if chain_i != len(chains) - 1:
				chains.pop(chain_i + 1)
			chains.insert(chain_i + 1, chains[chain_i] + [slot])
			break
	else:
		chains.insert(0, [slot])
		chains.pop(1)

print(len(chains[-1]))
print(' '.join([str(c) for c in chains[-1]]))

