    if num >= l[-1]:
        return len(l)
    elif num <= l[0]:
        return 0
    else:
        left,right = 0,len(l) - 1
        while left < right :
            mid = (left + right) // 2
            if l[left] <= num and l[left + 1] > num:
                return left + 1
            elif l[mid] <= num:
                left = mid + 1
            elif l[mid] > num:
               right = mid
