class Point():
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __str__(self):
        return str(self.x) + ',' + str(self.y)

class Vec():
    def __init__(self, x, y):
        self.x = x
        self.y = y

def cross(a, b):
    return a.x * b.y - a.y * b.y

def toVec(a,b):
    return Vec(b.x - a.x, b.y - a.y)

def ccw(p, q, r):
    return cross(toVec(p, q), toVec(p, r)) > 0


