def dijk(t):
    global graph
    global dist
    global prev

    seen = set()

    q =  [(0, 1)]
    heapq.heapify(q)
    dist = {}
    dist[1] = 0

    while len(q) != 0:
        d, u = heapq.heappop(q)
        if d == float('inf') or u == t:
            return
        if u in seen:
            continue
        seen.add(u)
        
        for v, v_len in graph[u].items():
            d_ = v_len + d
            if v not in dist:
                dist[v] = float("inf")
            if d_ < dist[v]:
                dist[v] = d_
                prev[v] = u
                if v not in seen:
                    heapq.heappush(q, (d_, v))

