from math import gcd


def func(n, a, b):
    # print(n, a, b)
    if n % gcd(a, b) != 0:
        return
    if a == b:
        if n % a:
            return n // a
        else:
            return
    small = min(a, b)
    large = max(a, b)

    end = n // large
    for i in range(0, end+1):
        # print(n - i * large)
        if (n - i * large) % small == 0:
            return (n - i * large) // small + i


def main():
    n, a, b, c = [int(i) for i in input().split(sep=' ')]
    if n % gcd(a, gcd(b, c)):
        return
    arr = [a, b, c]
    arr.sort(reverse=True)
    max_value = arr[0]
    new_a, new_b = arr[1:]
    end = n // max_value
    for i in range(0, end+1):
        new_n = n - i * max_value
        res = func(new_n, new_a, new_b)
        if res:
            return res + i


