def f2(n, k, x, M, D):
    if x > M:
        return -1
    A = n//(k*x)
    B = n % (k*x)
    if B < x:
        if A <= D:
            return A*x
        else:
            return -1
    else:
        if (A+1) <= D:
            return (A+1)*x
        else:
            return -1
    

def process(n, k, M, D):
    x1 = n//(D*k-k+1)
    if x1==0:
        x1 = M
    else:
        x1 = min(x1, M)
    answer = f2(n, k, x1, M, D)
    return answer

