from functools import lru_cache


def helper_min(m: int, s: int) -> str:
    @lru_cache(None)
    def helper(i: int, j: int, token: str) -> str:
        if j > s:
            return None
        if i == m:
            if j == s:
                return token
            return None

        best_token = None

        for k in range(max(0, s - j - (9 * (m - i - 1))), 10):
            if i == 0 and k == 0:
                continue
            result = helper(i + 1, j + k, token + str(k))
            if result:
                return result
        return best_token

    return helper(0, 0, "")


def helper_max(m: int, s: int) -> str:
    @lru_cache(None)
    def helper(i: int, j: int, token: str) -> str:
        if j > s:
            return None
        if i == m:
            if j == s:
                return token
            return None

        best_token = None

        for k in range(9, max(0, s - j - (9 * (m - i - 1))) - 1, -1):
            if i == 0 and k == 0:
                continue
            result = helper(i + 1, j + k, token + str(k))
            if result:
                return result
        return best_token

    return helper(0, 0, "")


def handle() -> str:
    m, s = input().split(" ")
    m = int(m)
    s = int(s)

    min_value = helper_min(m, s)
    max_value = helper_max(m, s)

    if min_value is None or max_value is None:
        return "-1 -1"

    return f"{min_value} {max_value}"


