from sys import stdin
from random import randint

def quickSort(L, ascending=True):
    if len(L) <= 1:
        return L
    smaller, equal, larger = [], [], []
    pivot = L[randint(0, len(L) - 1)][0]

    for x in L:
        if x[0] < pivot:
            smaller.append(x)
        elif x[0] == pivot:
            equal.append(x)
        else:
            larger.append(x)

    larger = quickSort(larger, ascending=ascending)
    smaller = quickSort(smaller, ascending=ascending)

    if ascending:
        final = smaller + equal + larger
    else:
        final = larger + equal + smaller
    return final

def busqueda_binaria(lista, x):

    izq = 0 
    der = len(lista) -1 

    while izq <= der:
        medio = (izq+der)//2
        if lista[medio][0] == x:
            return medio
        elif lista[medio][0] > x:
            der = medio-1
        else:
            izq = medio+1
    return -1


def get_data(n,array_b,m,queries):
    vasya = 0
    petya = 0
    for q in queries:
        pos = busqueda_binaria(array_b,q)
        vasya += array_b[pos][1] + 1
        petya += n - array_b[pos][1] 
    return [vasya,petya]

def get_array(array,n):
    for cont in range(n):
        array[cont].append(cont)
    array_arreglado = quickSort(array, ascending=True)
    return array_arreglado
    

