    if counts['B'] == 0:
        p_b = 0
    if counts['S'] == 0:
        p_s = 0
    if counts['C'] == 0:
        p_c = 0

    money = iline()

    def div(x):
        if counts[x] == 0:
            return float("inf")
        else:
            if x == 'B':
                return n_b // counts['B']
            if x == 'S':
                return n_s // counts['S']
            if x == 'C':
                return n_c // counts['C']

    can_be_made = min(div('B'), div('S'), div('C'))

    n_b -= can_be_made * counts['B']
    n_s -= can_be_made * counts['S']
    n_c -= can_be_made * counts['C']

    # Check if we can make one more.
    money_required = (counts['B'] - n_b) * p_b + (counts['S'] - n_s) * p_s + (counts['C'] - n_c) * p_c
    if money_required > money:
        return can_be_made

    money -= money_required
    can_be_made += 1

    # We're at 0, 0, 0 quanitities. How many more can we make?
    lo = 0
    hi = int(1e12)
    can_make = lambda q: q * p_b * counts['B'] + q * p_s * counts['S'] + q * p_c * counts['C'] <= money
    while lo <= hi:
        if lo == hi:
            return can_be_made + lo
        elif lo == hi - 1:
            if can_make(hi):
                return can_be_made + hi
            else:
                return can_be_made + lo

        mid = (lo + hi) // 2
        if can_make(mid):
            lo = mid
        else:
            hi = mid

