def dpApproach():
	"""
	dp[day][0] = minimum days rested up to the current day if we rest on current day
	dp[day][1] = minimum days rested up to the current day if we choose contest on current day
	dp[day][2] = minimum days rested up to the current day if we choose gym on current day
	"""

	dp = [[sys.maxsize for _ in range(3)] for _ in range(100)]

	dp[0][0] = 1
	if a[0] == 1:
		dp[0][1] = 0
	if a[0] == 2:
		dp[0][2] = 0	


	for i in range(1, n):
		dp[i][0] = 1 + min(dp[i-1][0], min(dp[i-1][1], dp[i-1][2]))
		
		if a[i] == 1 or a[i] == 3:
			dp[i][1] = min(dp[i-1][0], dp[i-1][2])

		if a[i] == 2 or a[i] == 3:
			dp[i][2] = min(dp[i-1][0], dp[i-1][1])

	return min(dp[n-1][0], min(dp[n-1][1], dp[n-1][2]))		


