def div_number(n):
    result = []
    stack = [n]
    while stack:
        current = stack.pop()
        if current == 0 or current == 1:
            result.append(current)
        else:
            stack.append(current // 2)
            stack.append(current % 2)
            stack.append(current // 2)
    return result

