import sys

def fn(s,a):
    b = a.copy()
    if b == a.sort():
        return 0
    for i in range(s-1):
        if b[i]>b[i+1]:
            break
    c = b[:i+1]
    d = b[i+1:]
    if d+c==a:
        return (s-(i+1))
    return -1    
    
