shortest = ""
best_total = 99999
def backtracking(graph, visited, current, total, n):
    global shortest
    global best_total
    if current == str(n):
        if total < best_total:
            shortest = (" ").join(visited)
            best_total = total
    for i in list(graph[current].keys()):
        if i not in visited:
            backtracking(graph, visited+[i], i, total+graph[current][i], n)
    return 0

