def look_for_number(x, m):
    start = 0
    end = len(x) - 1
    mid = -1
    while start <= end:
        mid = start + ((end - start) // 2)
        if x[mid] == m:
            break
        elif m > x[mid]:
            start = mid + 1
        else:
            end = mid -  1

    if m < x[mid]:
        mid -= 1
    
    mid += 1
    if mid < 0:
        return 0
    else:
        return mid

