class Deque:
    def __init__(self):
        self.items = []

    def isEmpty(self):
        return self.items == []

    def addFront(self, item):
        self.items.append(item)

    def addRear(self, item):
        self.items.insert(0,item)

    def removeFront(self):
        return self.items.pop()

    def removeRear(self):
        return self.items.pop(0)

    def size(self):
        return len(self.items)

    def front(self):
        return self.items[len(self.items)-1]

    def last(self):
        return self.items[0]

def groups(num,max,list):

    total = 0

    while len(list) >= 3:

        deq = Deque()
        delete = 0
        for i in list :
            deq.addRear(int(i))

        while (deq.last() - deq.front()) > max:
            deq.removeRear()
            delete += 1

        remain = len(list) - delete
        if remain >= 3:
            total =( (remain - 1) * (remain - 2) )/ 2 + total

        list.pop(0)

    return int(total)

