def a_burger_final():
    """
    每次计算制作汉堡的花费，如果原材料充足，那么花费为0，否则支出每个汉堡需要的花费，
    直到money不足以制作一个汉堡或用完。
    :return: 制作的汉堡数量
    """
    dict_burger = {'B': 0, 'C': 0, 'S': 0}
    burger = input().strip()
    for e in burger:
        dict_burger[e] += 1
    nb, ns, nc = tuple([int(e) for e in input().strip().split(" ")])
    pb, ps, pc = tuple([int(e) for e in input().strip().split(" ")])
    money = int(input().strip())

    if nb == 0 and nc == 0 and ns == 0:
        return money // (pb * dict_burger['B'] + pc * dict_burger['C'] + ps * dict_burger['S'])
    else:
        max_2 = 0
        while True:
            mb, ms, mc = 0, 0, 0  # 每制作一个汉堡需要的原料花费，如果原料充足，花费为0
            if nb >= dict_burger['B']:
                mb = 0
                nb -= dict_burger['B']
            else:
                mb = (dict_burger['B'] - nb) * pb
                nb = 0
            if ns >= dict_burger['S']:
                ms = 0
                ns -= dict_burger['S']
            else:
                ms = (dict_burger['S'] - ns) * ps
                ns = 0
            if nc >= dict_burger['C']:
                mc = 0
                nc -= dict_burger['C']
            else:
