min_steps = 100
def do_rec(lines, level = 0, memo = True):
    global min_steps
    if level >= min_steps:
        return None

    if not lines:
        return level

    if memo:
        key = lines
        if key not in do_rec.memo:
            do_rec.memo[key] = do_rec(lines, level, False)

        return do_rec.memo[key]

