def gcd(a, b):  # Функция нахождения наибольшего общего делителя
    i = 1
    mas = []
    while i ** 2 <= a or i ** 2 <= b:
        if a % i == 0 and b % i == 0:
            mas.append(i)
            if i != a // i and i != b // i and max(a, b) % min(a, b) == 0:
                mas.append(min(a, b) // i)
        i += 1
    return max(mas)


