    def search(self, word: str) -> None:
        curr = self.root
        for i, w in enumerate(word):
            idx = ord(w) - 97
            if not curr.children[idx]:
                return len(word) - i + self.findCount(curr)
            
            curr = curr.children[idx]
        
        return curr.is_end
    
    def findCount(self, curr):
        cnt = 0
        while curr:
            nxt = None
            for i, child in enumerate(curr.children):
                if child:
                    cnt += 1
                    nxt = child
                    break
            curr = nxt
        
        return cnt


