def solve(n,k,d):
    @lru_cache(None)
    def dp(used,total):
        if total == n:
            return 1 if used else 0
        if total > n:
            return 0
        res = 0
        for i in range(1,k + 1):
            if i >= d:
                res += dp(True,total + i)
            else:
                res += dp(used,total + i)
        return res
    return dp(False,0)
