def dijkstra(graph, src):
	path = [-1] * (len(graph)+1)
	visited = [1000001] * (len(graph)+1)
	visited[src] = 0
	queue = []

	for v in range(1, len(graph)+1):
		queue.append(v)

	while queue:
		current = queue[0]
		for vert in queue:
			if visited[vert] < visited[current]:
				current = vert

		queue.remove(current)
		adj = graph[current]

		for dest, weight in adj.items():
			if visited[current] + weight < visited[dest]:
				visited[dest] = visited[current] + weight
				path[dest] = current

	if path[len(graph)] == -1:
		print(-1)
	else:
		shortest = [str(len(graph))]
		findPath(path, len(graph), shortest)
		shortest.reverse()
		print(" ".join(shortest))

def findPath(path, src, shortest):
	if path[src] != -1:
		shortest.append(str(path[src]))
		findPath(path, path[src], shortest)


