    esquerda = 0
    direita = len(vetor) - 1
    indice = -1

    while esquerda <= direita:
        meio = (esquerda + direita) // 2

        if vetor[meio] <= valor:
            indice = meio
            esquerda = meio + 1
        else:
            direita = meio - 1

    return indice

