def quicksort(arr):
    if len(arr) <= 1:
        return arr
    else:
        d = arr[0]
        f = [x for x in arr[1:] if x <= d]
        g = [x for x in arr[1:] if x > d]
        return quicksort(f) + [d] + quicksort(g)

