def extGCD(a, b):
    if b == 0:
        x = 1
        y = 0
        return a, x, y
    g, x, y = extGCD(b, a%b)
    x0 = y
    y0 = x - y * (a//b)
    return g, x0, y0

def find_any_solution(a, b, c):
    g, x0, y0 = extGCD(abs(a), abs(b))
    if c % g != 0:
        return False
    x0 *= c // g
    y0 *= c // g
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0
    return True

