class DSNode:
    def __init__(self, val):
        self.val = val
        self.rank = 0
        self.size = 1
        self.parent = self
        self.correct = True

    def __str__(self):
        return str(self.find().val)

    def find(self):
        x = self
        if x != x.parent:
            x.parent = x.parent.find()
        return x.parent

def union(x, y):
    x = x.find()
    y = y.find()
    if x == y:
        return
    if x.rank > y.rank:
        y.parent = x
        x.size += 1
    else:
        x.parent = y
        y.size += 1
        if x.rank == y.rank:
            y.rank += 1


