class Circle:
     
    def __init__(self,x,y,r):
        self.centerX=x
        self.centerY=y
        self.radio=r

    def Belong(self,x,y):
        return ((x-self.centerX)**2+(y-self.centerY)**2)==self.radio**2

    def FindIntercepts(self, c2):
        intercepts=[]
        a_1=2*-c2.centerX-2*-self.centerX 
        b_1=2*-c2.centerY-2*-self.centerY
        c_1=c2.centerX**2+c2.centerY**2-c2.radio**2-self.centerX**2-self.centerY**2+self.radio**2

        if b_1==0 :
            A= 1
            B=-2*self.centerY
            C=-self.radio**2+ (-c_1/a_1 - self.centerX)**2
            D=B**2-4*A*C
            if(D<0):return (False,intercepts)
            x=-c_1/a_1
            if(D==0):
                y=sqrt(abs((self.radio**2) -((x-self.centerX)**2)))+self.centerY
                intercepts.append((x,y))
            else:
                y1=sqrt(abs((self.radio**2) -((x-self.centerX)**2)))+self.centerY
                y2=-sqrt(abs((self.radio**2) -((x-self.centerX)**2)))+self.centerY
                intercepts.append((x,y1))
                intercepts.append((x,y2))
            return (True,intercepts)
        elif a_1==0 :
            A= 1
            B=-2*self.centerX
            C=-self.radio**2+ (-c_1/b_1 - self.centerY)**2
            D=B**2-4*A*C
            if(D<0):return (False,intercepts)
            y=-c_1/b_1
            if(D==0):
                x=sqrt((self.radio**2) -((y-self.centerY)**2))+self.centerX
                intercepts.append((x,y))
            else:
                x1=sqrt((self.radio**2) -((y-self.centerY)**2))+self.centerX
                x2=-sqrt((self.radio**2) -((y-self.centerY)**2))+self.centerX
                intercepts.append((x1,y))
                intercepts.append((x2,y))
            return (True,intercepts)
        
        A=1+(a_1/b_1)**2  
        B=2*-self.centerX - 2*(a_1/b_1)*-self.centerY + (2*c_1*a_1 )/(b_1**2)
        C=self.centerX**2 +(c_1/b_1)**2 - (2*c_1)/b_1* -self.centerY + self.centerY**2-self.radio**2
        D=B**2-4*A*C
        if(D<0):return (False,intercepts)
        x1=round((-B+sqrt(D))/(2*A),5)
        x2=round((-B-sqrt(D))/(2*A),5)
        #y1=round( math.sqrt(abs((self.radio**2)-((x1-self.centerX)**2)))+self.centerY,5)
        #y2= round(math.sqrt(abs((self.radio**2) -((x2-self.centerX)**2)))+self.centerY,5)
        y1=(-c_1-a_1*x1)/b_1
        y2=(-c_1-a_1*x2)/b_1

        intercepts.append((x1,y1))
        intercepts.append((x2,y2))
        return (True,intercepts)
