from math import gcd


class Ratio:
    def __init__(self, a, b):
        if a * b < 0:
            self.sign = -1
        else:
            self.sign = 1

        a = abs(a)
        b = abs(b)
        gcd_ab = gcd(a, b)
        if gcd_ab > 0:
            a //= gcd_ab
            b //= gcd_ab

        self.a = a
        self.b = b

    def __eq__(self, other):
        if self.a > other.a:
            return self.__eq__(other, self)

        if self.a == self.b == 0:
            return True

        return self.sign == other.sign and self.a * other.b == self.b * other.a


class Line:
    COINCIDENT_LINES_INTERSECTIONS = -1
    PARALLEL_LINES_INTERSECTIONS = 0
    INTERSECTING_LINES_INTERSECTIONS = 1

    def __init__(self, a, b, c):
        self.a = a
        self.b = b
        self.c = c

    def is_plane(self):
        return self.a == self.b == self.c == 0

    def count_intersections(self, other):
        if self.is_plane() or other.is_plane():
            return Line.COINCIDENT_LINES_INTERSECTIONS

        ratio_a = Ratio(self.a, other.a)
        ratio_b = Ratio(self.b, other.b)
        ratio_c = Ratio(self.c, other.c)

        if ratio_a == ratio_b:
            if ratio_a == ratio_c:
                return Line.COINCIDENT_LINES_INTERSECTIONS
            else:
                return Line.PARALLEL_LINES_INTERSECTIONS
        else:
            return Line.INTERSECTING_LINES_INTERSECTIONS


