def dfs(graph, vertexes, n, m):
    visited = [False] * (n + 1)
    stack = [(1, vertexes[1])]
    res = 0
    while stack:
        x, c = stack.pop()
        if visited[x]:
            break
        visited[x] = True
        is_leaf = False
        for v in graph[x]:
            if not visited[v]:
                if vertexes[v]:
                    if c < m:
                        is_leaf = True
                        stack.append((v, c + 1))
                else:
                    is_leaf = True
                    stack.append((v, 0))
        if not is_leaf:
            res += 1
    return res


