def find_path(g, vs, ve):
    q = [(vs, None)]
    vis = set()
    while len(q):
        v, x_ = q.pop()
        vis.add(v)
        for vn in g[v]:
            if vn == ve:
                return x_ or vn, v
            if vn not in vis: q.append((vn, x_ or vn))
    return None

def count(g, vs):
    q = [vs]
    vis = set()
    while len(q):
        v = q.pop()
        vis.add(v)
        for vn in g[v]:
            if vn not in vis: q.append(vn)
    return len(vis)

def solve(g, x, y):
    if len(g) <= 1:
        return 0
    x_, y_ = find_path(g, x, y)
    g[x].remove(x_)
    g[y].remove(y_)
    x_siz = count(g, x)
    y_siz = count(g, y)
    ans = n*(n-1) - (x_siz*y_siz)
    return ans

