                pos = next_occ[c][0]
        length.append((count, pos))
    return length

def get_period(length):
    count, num, pos = 0, 0, 0
    seen = dict()
    seen[0] = (0, 0)
    while True:
        num_inc, next_pos = length[pos]
        count, num, pos = count + 1, num + num_inc, next_pos
        if pos in seen:
            prev_num, prev_count = seen[pos]
            num_period = num - prev_num
            count_period = count - prev_count
            return num_period, count_period, pos, prev_num, prev_count
        else:
            seen[pos] = (num, count)
    return 0, 0, 0, 0, 0

def get_count(length, b, pos):
    count = 0
    num = 0
    while num < b:
        num_inc, next_pos = length[pos]
        count, num, pos = count + 1, num + num_inc, next_pos
    if pos != 0:
        count -= 1
    return count

def solve(length, b):
    num_period, count_period, pos, num_offset, count_offset = get_period(length)
    if  num_offset + num_period >= b:
        return get_count(length, b, 0)
    else:
        periods = (b - num_offset)//num_period
        count = count_offset + count_period*periods
        b -= (num_offset + num_period*periods)
        return count + get_count(length, b, pos)

