import math
import heapq
    
def initializeShortestPath(V,n):
    V[1] = {}
    V[1]['p'] = 0 
    V[1]['d'] = 0
    for v in range(2,n+1):
        V[v] = {}
        V[v]['p'] = 0 
        V[v]['d'] = math.inf
        
def initializeQ(Q,V,n):
    for i in range(1,n+1):
        heapq.heappush(Q,(V[i]['d'],i))
        
def relax(V,E,Q,u,v):
    if V[v]['d'] > V[u]['d'] + E[u][v]:
        V[v]['d'] = V[u]['d'] + E[u][v]
        V[v]['p'] = u
        heapq.heappush(Q,(V[v]['d'],v))
    
def dijkstra(V,E,Q,n):
    i = n
    while(i >0):
        u = heapq.heappop(Q)[1]
        adj = set()
        if u in E:
            for v in E[u]:
                adj.add(v)
        for v in list(adj):
            relax(V,E,Q,u,v)
        i-=1
        
def findPath(V,n):
    path = [n]
    i = n
    while(i != 1):
        if V[i]['p'] == 0:
            return [-1] 
        path.append(V[i]['p'])
        i = V[i]['p']
    return path
    
def printAnswer(path):
    ans = ""
    for i in range(len(path)-1,-1,-1):
        ans += str(path[i])
        if i > 0:
            ans += " "
    print(ans)
    
