# Function to generate a list of prime numbers
def sieve_of_eratosthenes(limit):
    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False
    primes = []
    for p in range(2, int(math.sqrt(limit)) + 1):
        if sieve[p]:
            primes.append(p)
            for i in range(p * p, limit + 1, p):
                sieve[i] = False
    return primes

# Function to determine if a number is Т-prime
def is_t_prime(x, primes):
    if x == 1:
        return False
    sqrt_x = int(math.sqrt(x))
    if sqrt_x * sqrt_x != x:
        return False
    if sqrt_x in primes:
        return True
    return False

