from math import inf
from queue import PriorityQueue


class Graph:
    def __init__(self):
        self.graph = {}

    def add(self, a, b, w):
        if str(a) in self.graph:
            self.graph[str(a)].append((b, w))
        else:
            self.graph[str(a)] = [(b, w)]
        if str(b) in self.graph:
            self.graph[str(b)].append((a, w))
        else:
            self.graph[str(b)] = [(a, w)]

    def vertices(self):
        v = []
        for key in self.graph.keys():
            v.append(int(key))
        return v

    def get_neighbors(self, u):
        return self.graph[str(u)]

    def add_key(self, key):
        self.graph[str(key)] = []

    def __str__(self):
        out = ""
        for key in self.graph.keys():
            out += key + ": " + str(self.graph[key]) + "\n"
        return out


def recover_path(prev, end):
    path = []
    i = end
    while prev[i] is not None:
        path.append(i + 1)
        i = prev[i]
    path.append(1)
    for i in range(len(path) - 1, -1, -1):
        print(path[i], end=" ")
    print()


def djikstra(g: Graph, start: int, end: int):
    vertices = g.vertices()
    dist = []
    prev = []
    closed = []
    Q = PriorityQueue()
    for vertex in vertices:
        if vertex == start:
            dist.append(0)
            Q.put((0, vertex))
        else:
            dist.append(inf)
        prev.append(None)
        closed.append(False)
    while not Q.empty():
        u = Q.get()
        if u[1] == end:
            break
        closed[u[1] - 1] = True
        neighbors = g.get_neighbors(u[1])
        for neighbor in neighbors:
            alt = u[1] + neighbor[1]
            if alt < dist[neighbor[0] - 1] and not closed[neighbor[0] - 1]:
                dist[neighbor[0] - 1] = alt
                prev[neighbor[0] - 1] = u[1] - 1
                Q.put((alt, neighbor[0]))

    if dist[end - 1] == inf:
        print(-1)
    else:
        recover_path(prev, end - 1)


