def genome_sort(genome):    
    for i in range(1, len(genome)):
        tmp = genome[i]
        hole = i
        while (tmp < genome[hole - 1]) & (hole > 0):
            genome = string_assignment(genome, genome[hole - 1], hole)
            hole -= 1
        genome = string_assignment(genome, tmp, hole)
    return genome
        
