import math
def level2(child,node,level):

    if child==node:
        return level
    while child !=node:
        if child<node:
            node=node-2**(level)
            level-=1
        else:
            node=node-2**(level)
            level-=1
        return level
def rchild(child,node,level):
    if level < 0:
        return None
    if node==child:
        if level>=0:
            return node+2**(level)
        else:
            return None
    else:
        if child<node:
            a=rchild(child,node-2**(level),level-1)
        else:
            a=rchild(child,node+2**(level),level-1)
        return a
def lchild(child,node,level):
        if level < 0:
            return None
        if node==child:
            if level>=0:
                return node-2**(level)
            else:
                return None
        else:
            if child<node:
                a=lchild(child,node-2**(level),level-1)
            else:
                a=lchild(child,node+2**(level),level-1)
            return a
def parent(child,node,level):
    # print(level)
    if level < 0:
        return None
    if (node-2**(level)) == child:
        return node
    elif (node+2**(level)) == child:
        return node
    else:
        if child<node:
            a=parent(child,node-2**(level),level-1)
        else:
            a=parent(child,node+2**(level),level-1)
        return a

