    def __init__(self):
        self.data = []
    def push(self, data):
        self.data.append(data)
    def pop(self):
        return self.data.pop
    def peek(self):
        if self.is_empty():
            return None
        else:
            return self.data[-1]
    def is_empty(self):
        return len(self.data) == 0
    def get_count(self, data):
        return self.data.count(data)

