def get_position(dic):
    return (dic["U"] - dic["D"], dic["R"] - dic["L"])
def foo(raw_line):
    line = raw_line.strip()
    out = 0
    dic = {"U":0, "D":0, "R":0, "L":0}
    if len(line) % 2 == 1:
        return -1
    for i in line:
        dic[i] += 1
    y, x = get_position(dic)
    while x != 0 and y != 0:
        if x > 0:
            if y > 0:
                dic["R"] -= 1
                dic["D"] += 1
                out += 1
            elif y < 0:
                dic["R"] -= 1
                dic["U"] += 1
                out += 1
            else:
                dic["R"] -= 1
                dic["L"] += 1
        elif x < 0:
            if y > 0:
                dic["L"] -= 1
                dic["D"] += 1
                out += 1
            elif y < 0:
                dic["L"] -= 1
                dic["U"] += 1
                out += 1
            else:
                dic["L"] -= 1
                dic["R"] += 1
        elif x == 0:
            if y > 0:
                dic["U"] -= 1
                dic["D"] += 1
                out += 1
            elif y < 0:
                dic["D"] -= 1
                dic["U"] += 1
                out += 1
            else:
                return out
        y, x = get_position(dic)
    return out


