import math

def mag(v):
    return math.sqrt(v[0]*v[0] + v[1]*v[1]);

def dot(v1, v2):
    return (v1[0]*v2[0]) + (v1[1]*v2[1]);

def calc_angle(v1, v2, sorting):
    # returns angle between vectors v1 and v2
    # if sorting is False limits range to [0, pi]
    arg = dot(v1, v2)/(mag(v1) * mag(v2))
    if sorting:
        if v1[1] < 0:
            return 2*math.pi - math.acos(arg)
    return math.acos(arg)

