def waste_search(row, col, n):
    if n == 0:
        return 0
    movingi = n//2
    lower_bound = 0
    upper_bound = n - 1  # Bounds for moving i
    while upper_bound - lower_bound > 1:
        if waste[movingi] == (row, col):
            return -1
        elif waste[movingi][0] > row:
            change = max((1, (movingi - lower_bound)//2))
            upper_bound = movingi
            movingi -= change
        elif waste[movingi][0] < row:
            change = max((1, (upper_bound - movingi)//2))
            lower_bound = movingi
            movingi += change
        else:  # Same row
            break
    while upper_bound - lower_bound > 1:
        if waste[movingi] == (row, col):
            return -1
        elif waste[movingi][1] > col:
            change = max((1, (movingi - lower_bound)//2))
            upper_bound = movingi
            movingi -= change
        elif waste[movingi][1] < col:
            change = max((1, (upper_bound - movingi)//2))
            lower_bound = movingi
            movingi += change
        else:
            break
    if waste[upper_bound] == (row, col) or waste[lower_bound] == (row, col):
        return -1
    else:
        if waste[lower_bound] > (row, col):
            return lower_bound
        elif waste[lower_bound] < (row, col) < waste[upper_bound]:
            return lower_bound + 1
        else:
            return upper_bound + 1


