st = [None for _ in range(1000)]
class node:
    def __init__(self,optimal,open,close) -> None:
        self.optimal = optimal
        self.open = open 
        self.close = close
    
    def __add__(self, _node):
        _node: node = _node
        tmp = min(self.open,_node.close)
        opt = self.optimal + _node.optimal + 2*tmp
        open = self.open + _node.open - tmp
        close = self.close + _node.close - tmp
        return node(opt,open,close)

    def __str__(self) -> str:
        return str([self.optimal,self.open,self.close])

def build(i,l,r):
    if l==r:
        if arr[l] == '(':
            st[i] = node(0,1,0)
        else:
            st[i] = node(0,0,1)
    else:
        mid = (l+r)//2
        build(i*2+1,l,mid)
        build(i*2+2,mid+1,r)
        st[i] = st[i*2+1]+st[i*2+2]
    
    
def query(id,l,r,u,v):
    if l > v or r < u:
        return node(0,0,0)
    if u <= l and r <=v:
        return st[id]
    mid = (l+r)//2
    return query(id*2+1,l,mid,u,v) + query(id*2+2,mid+1,r,u,v)


