class Answer(Exception):
	def __init__(self, answer):
		super(Answer, self).__init__()
		self.answer = answer


class Node:
	UNDEF = -1

	def __init__(self, name=None):
		self.name = name
		self.neighbour_nodes = []
		self.height = None
		self.edge_heights = None
		pass

	def sym_add_node(self, node):
		self.neighbour_nodes.append(node)
		node.neighbour_nodes.append(self)

	def calc_height_dfs(self, fr):
		heights = set()
		for node in self.neighbour_nodes:
			if node != fr:
				node.calc_height_dfs(self)
				heights.add(node.height)

		if len(heights) == 0:
			#list
			self.height = 0
		elif len(heights) == 1 and Node.UNDEF not in heights:
			self.height = list(heights)[0] + 1
		else:
			self.height = Node.UNDEF

	def optimize_dfs(self, fr):
		if len(self.neighbour_nodes) <= 3:
			return 

		heights = {}
		for i in range(len(self.neighbour_nodes)-1, -1, -1):
			node = self.neighbour_nodes[i]
			if node != fr:
				h = node.height

				if h in heights and h != Node.UNDEF:
					self.neighbour_nodes.pop(i)
					# optimize node

				else:
					if h not in heights:
						heights[h] = []

					heights[h].append(node)

		if len(self.neighbour_nodes) > 3:
			raise Answer(-1)


	def dfs_call(self, func, fr):
		for node in self.neighbour_nodes:
			if node != fr:
				node.dfs_call(func, self)
		func(self)

	def get_height_by_edges(self, fr):
		heights = []
		for node, h in zip(self.neighbour_nodes, self.edge_heights):
			if node != fr:
				heights.append(h)
		heights = set(heights)
		if len(heights) == 0:
			return 1
		elif len(heights) == 1 and Node.UNDEF not in heights:
			return list(heights)[0] + 1
		else:
			return Node.UNDEF

	def calc_edge_heights_dfs(self, fr):
		if self.edge_heights is None:
			self.edge_heights = [None] * len(self.neighbour_nodes)

		for i in range(len(self.neighbour_nodes)):
			node = self.neighbour_nodes[i]
			if node != fr:
				if self.edge_heights[i] is None:
					node.calc_edge_heights_dfs(self)
					self.edge_heights[i] = node.get_height_by_edges(self)

	def calc_answer(self):
		all_edge_heights = set(self.edge_heights)
		if len(all_edge_heights) <= 2 \
			and Node.UNDEF not in all_edge_heights:

			answer = sum(all_edge_heights)
			while answer % 2 == 0:
				answer //= 2
			raise Answer(answer)


def main():
	n = int(input())
	nodes = [Node(i) for i in range(n)]

	for i in range(n-1):
		a, b = map(int, input().strip().split())
		nodes[a-1].sym_add_node(nodes[b-1])

	try:
		#optimize
		nodes[0].calc_height_dfs(None)
		nodes[0].optimize_dfs(None)


		#calc_answer
		nodes[0].dfs_call(lambda node: node.calc_edge_heights_dfs(None), None)
		nodes[0].dfs_call(lambda node: node.calc_answer(), None)

	except Answer as a:
		print(a.answer)
	else:
		print(-1)


