import math
from collections import deque, defaultdict


def read_int():
    return int(input().strip())


def read_ints():
    return list(map(int, input().strip().split(' ')))


def solve():
    """
    4 4 2
    1 3
    2 3 0
    3 4 0
    2 4 1
    2 1 2

    n, m, k
    k
    ui vi xi

    1 2 2 2
    """
    n, m, k = read_ints()
    C = read_ints()
    types = []
    for i, c in enumerate(C):
        for t in range(c):
            types.append(i)

    G = defaultdict(list)
    for _ in range(m):
        u, v, x = read_ints()
        G[u-1].append((v-1, x))
        G[v-1].append((u-1, x))

    G_type = [
        [math.inf for _ in range(k)] for _ in range(k)
    ]

    def count_reachables(src):
        Q = [src]
        visited = set()
        while len(Q) != 0:
            node = Q.pop()
            visited.add(node)
            for child, weight in G[node]:
                if types[node] != types[child]:
                    t_node, t_child = types[node], types[child]
                    G_type[t_node][t_child] = G_type[t_node][t_child] = min(G_type[t_node][t_child], weight)
                elif weight == 0 and child not in visited:
                    Q.append(child)
        return len(visited)

    start = 0
    for i in range(k):
        reachables = count_reachables(start)
        if reachables != C[i]:
            print('No')
            return
        start += C[i]
    # floyd-warshall
    for i in range(k):
        G_type[i][i] = 0
    for m in range(k):
        for i in range(k):
            for j in range(k):
                G_type[i][j] = min(G_type[i][j], G_type[i][m]+G_type[m][j])
    print('Yes')
    for row in G_type:
        print(' '.join(map(str, [c if c != math.inf else -1 for c in row])))


if __name__ == '__main__':
    solve()

