def deikstra(graph):
    n = len(graph)
    d = [float('+inf') for i in range(n)]
    used = [False for i in range(n)]
    parent = [None for i in range(n)] # массив предков для восстановления ответа
    d[0] = 0
    for i in range(n):
        next = -1
        for v in range(n):
            if (next == -1 or d[v] < d[next]) and not used[v]:
                next = v
        # if d[next] == float('+inf')
        #     break

        if debug:
            print(f'next verticies is {next + 1}')
        used[next] = True

        if debug:
            print(f'update distances')
        for u, w in enumerate(graph[next]):
            if w is not None:
                if d[next] == d[u] + w:
                    parent[next] = u
                    if debug:
                        print(f'parent[next={next+1}] = u={u+1}')
                else:
                    if debug:
                        print(f'w={w}; d[u={u+1}] = {d[u]}; d[next={next+1}] = {d[next]}')
                d[u] = min(d[u], d[next] + w)
                if debug:
                    print(f'd[u={u+1}] = {d[u]}')

    return d, parent


