    global count
    for l in left:
        for r in right:
            if r[1] >= l[1]:
                right.remove(r)
            elif r[1] >= l[0] and r[1] < l[1]:
                left.remove(l)
            else:
                left.remove(l)
                count+=1
    return left + right

