BASE = ( math.sqrt( 5 ) + 1 ) / 2.0 ;

class Node : 
    def __init__( self , ta = 0 , tb = 0 ) :
        
        self.a = ta ; 
        self.b = tb ;
        
    def get( self ) :
        return self.a * BASE + self.b ; 
    
    def out( self ):
        print( "self.a: " , self.a , self.b ) ;


        
class Solution:
    
    def init( self ) : 
        
        self.f =  [ Node(  0  , 0 ) for i in range( self.n  ) ] ;
        
        self.f [0] = Node( 0 , 1 ) ;
        self.f[ 1 ] = Node( 1 , 0 ) ;
        
        for  i in range( 2 , self.n , 1 ) :
            
            a = self.f[i-1].a ;
