class KosarjuSCC:
    def __init__(self, n):
        self.scc = [-1] * n
        self.components = [[] for _ in range(n)]
        self.built = False

    def build(self, adj, is_digraph=True):
        if is_digraph:
            rgraph = self.build_rgraph(adj)
        else:
            adj, rgraph = self.decompose_graph(adj)

        postorder = self.build_postorder(adj)
        self.build_scc(rgraph, postorder)
        self.built = True

    def build_rgraph(self, adj):
        n = len(adj)
        radj = [[] for _ in range(n)]
        for u in range(n):
            for v in adj[u]:
                radj[v].append(u)
        return radj

    def decompose_graph(self, graph):
        n = len(graph)
        forward_graph = [[] for _ in range(n)]
        reverse_graph = [[] for _ in range(n)]
        red_group = set()
        seen = set()

        def dfs(u):
            seen.add(u)
            for v in graph[u]:
                if v not in seen:
                    red_group.add((u, v))
                    dfs(v)

        for u in range(n):
            dfs(u)

        for u in range(n):
            for v in graph[u]:
                if (u, v) in red_group:
                    forward_graph[u].append(v)
                else:
                    reverse_graph[u].append(v)

        return forward_graph, reverse_graph

    def build_postorder(self, graph):
        n = len(graph)
        seen = set()
        postorder = []

        def dfs(u):
            if u not in seen:
                seen.add(u)
                for v in graph[u]:
                    dfs(v)
                postorder.append(u)

        for u in range(n):
            dfs(u)

        return postorder

    def build_scc(self, radj, postorder):
        def dfs(u, color):
            if self.scc[u] == -1:
                self.scc[u] = color
                self.components[color].append(u)
                for v in radj[u]:
                    dfs(v, color)

        for u in reversed(postorder):
            dfs(u, u)

    def get_all_components(self):
        assert self.built
        return self.components

    def get_components(self, x):
        assert self.built
        return self.components[x]

    def __getitem__(self, x):
        assert self.built
        return self.scc[x]


class DSU:
    def __init__(self, n):
        self.parents = list(range(n))
        self.sizes = [1 for _ in range(n)]
        self.components = n

    def __len__(self):
        return self.components

    def __getitem__(self, x):
        return self.find(x)

    def find(self, x):
        if x != self.parents[x]:
            self.parents[x] = self.find(self.parents[x])
        return self.parents[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)

        if root_x == root_y:
            return False

        if self.sizes[root_y] < self.sizes[root_x]:
            root_x, root_y = root_y, root_x

        self.sizes[root_y] += self.sizes[root_x]
        self.parents[root_x] = root_y
        self.components -= 1

        return True

    def size(self, x):
        return self.sizes[self.find(x)]

    def get_all_components(self):
        n = len(self.parents)
        components = [[] for _ in range(n)]
        for u in range(n):
            components[self.find(u)].append(u)
        return components


def get_reachable_nodes(adj, start):
    seen = {start}
    queue = [start]

    for u in queue:
        for v in adj[u]:
            if v not in seen:
                seen.add(v)
                queue.append(v)

    return queue


def solve():
    n, m, start = map(int, input().split())
    start -= 1
    adj = [[] for _ in range(n)]
    scc = KosarjuSCC(n)

    for _ in range(m):
        u, v = map(int, input().split())
        u, v = u - 1, v - 1
        adj[u].append(v)

    scc.build(adj)
    sccs = {scc[u] for u in range(n)}
    ranks = {scc[u]: i for i, u in enumerate(sccs)}
    sz = len(ranks)

    dsu = DSU(sz)
    queue = [start]
    seen = {start}
    for node in queue:
        for v in adj[node]:
            if v not in seen:
                a = ranks[scc[start]]
                b = ranks[scc[v]]
                dsu.union(a, b)
                queue.append(v)

    return len(dsu) - 1


