def merge(a, b):
    merged = []
    j = 0
    for i in range(len(a)):
        while j < len(b) and b[j] < a[i]:
            merged.append(b[j])
            j += 1
        merged.append(a[i])
    merged += b[j:]
    return merged


def merge_sort(a):
    n = len(a)
    if n <= 1:
        return a
    left = merge_sort(a[:n // 2])
    right = merge_sort(a[n // 2:])
    return merge(left, right)


