def solve(ns, costss):
    n = int(ns)
    cs = []
    for cstr in costss.split():
        cs+= [int(cstr)]
    summ = sum(cs)
    cs = sorted(cs, reverse=True)
    res = step3(0, cs)
    return summ - res

def step3(ec, cs):
    if cs==[] or len(cs)==1:
        return ec
    [a,b]=cs[0:2]
    if a==b:
        succ = 0
        for x in cs:
            if x != a:
                cs.remove(x)
                succ = x
                break
        return step3(ec+succ, cs[1:])
    elif len(cs)==2:
        return ec+b
    elif len(cs)==3:
        [a,b,c]=cs
        if a==b and b==c:
            return ec
        else:
            return ec+b
    else:
        [a,b,c,d]=cs[0:4]
        if b!=c and c!=d:
            return step3(ec+b+d,cs[4:])
        elif b!=c and c==d:
            if b>2*c:
                return step3(ec+b,cs[4:])
            else:
                return step3(ec+c+c,cs[4:])
        else:
            return step3(ec+b,cs[2:])

