def queue_time(customers,n):
    for i in range(1,len(customers)):
        i = i%n
        while i%n<n and customers[i%n]>customers[(i+1)%n]:
            i+=1
            customers[i%n] =customers[i%n] + customers[i]
            customers[i] = 0
    return customers

def phi(n):
    result = n
    for i in range(2,int(pow(n,0.5))+1):
        while n%i == 0:
            n/=i
            result-=result/i
    if n>1:
        result -= result/n
    return result

class heap:
    def __init__(self,data):
        self.data = data
    def parent(self,j):
        return (j-1)//2
    def left(self,j):
        return 2*j+1
    def right(self,j):
        return 2*j+2
    def hasr(self,j):
        return self.right(j)<len(self.data)
    def hasl(self,j):
        return self.left(j)<len(self.data)
    def swap(self,i,j):
        self.data[i],self.data[j] = self.data[j],self.data[i]
    def upheap(self,j):
        parent = self.parent(j)
        if j>0 and self.data[j]<self.data[parent]:
            self.swap(j,parent)
            self.upheap(parent)
    def downheap(self,j):
        if self.hasl(j):
            left = self.left(j)
            small = left
            if self.hasr(j):
                right = self.right(j)
                if self.data[left]>self.data[right]:
                    small = right
            if self.data[small]<self.data[j]:
                self.swap(j,small)
                self.downheap(small)
    def __str__(self):
        return ' '.join(map(str,self.data))

