        n = len(s)
        z = [0] * len(s)
        l, r = 0, 0
        for i in range(1, n):
            if i <= r and z[i - l] < (r - i + 1):
                z[i] = z[i - l]
            else:
                while (i + z[i]) < n and s[z[i]] == s[i + z[i]]:
                    z[i] += 1
            if (i + z[i] - 1) > r:
