class Node:
    def __init__(self, value):
        self.left = None
        self.right = None
        self.val = value


def process1(root):
    if root is None:
        return [], 0
    work_l, not_l = process1(root.left)
    work_r, not_r = process1(root.right)
    work_here = []
    not_here = not_l+not_r
    if len(work_l) > 0:
        if work_l[-1] <= root.val:
            work_here = work_l
        elif work_l[0] > root.val:
            not_here+=len(work_l)
        else:
            s = 0
            e = len(work_l)-1
            while s+1 < e:
                m = (s+e)//2
                if work_l[m] <= root.val:
                    s, e = s, m
                else:
                    s, e = m, e
            work_here = work_l[:e+1]
            not_here+=(len(work_l)-e)
    work_here.append(root.val)
    if len(work_r) > 0:
        if work_r[0] >= root.val:
            for x in work_r:
                work_here.append(x)
        elif work_r[-1] < root.val:
            not_here+=len(work_r)
        else:
            s = 0
            e = len(work_r)-1
            while s+1 < e:
                m = (s+e)//2
                if work_r[m] >= root.val:
                    s, e = s, m
                else:
                    s, e = m, e
            for x in work_r[e:]:
                work_here.append(x)
            not_here+=e
  #  print(work_here, not_here, not_l, not_r)
    return [work_here, not_here]

def process(A):
    Nodes = []
    n = len(A)
    for i in range(n):
        value = A[i][0]
        Nodes.append(Node(value))
    roots = set(range(n))
    for i in range(n):
        l = A[i][1]
        r = A[i][2]
        if l != -1:
            Nodes[i].left = Nodes[l-1]
            if l-1 in roots:
                roots.remove(l-1)
        if r != -1:
            Nodes[i].right = Nodes[r-1]
            if r-1 in roots:
                roots.remove(r-1)
    for root in roots:
        break
    a1, a2 = process1(Nodes[root])
    return a2
    
