        d[i] += 1
    ans = 0
    while nb >= d['B'] and nc >= d['C'] and ns >= d['S']:
        ans += 1
        nb -= d['B']
        ns -= d['S']
        nc -= d['C']

    while r > 0:
        if d['B'] > nb:
            if (d['B'] - nb) * pb > r:
                break
            else:
                r -= (d['B'] - nb) * pb

                nb = d['B']
        if d['C'] > nc:
            if (d['C'] - nc) * pc > r:
                break
            else:
                r -= (d['C'] - nc) * pc

                nc = d['C']
        if d['S'] > ns:
            if (d['S'] - ns) * ps > r:
                break
            else:
                r -= (d['S'] - ns) * ps

                ns = d['S']
        ans += 1
        nb -= d['B']
        ns -= d['S']
        nc -= d['C']
        if nb == 0 and nc == 0 and ns == 0:
            break
    price = d['B'] * pb + d['C'] * pc + d['S'] * ps
    ans += (r // price)
