from heapq import heapify, heappop, heappush
from typing import List, Optional, Tuple


class Node:
    def __init__(self, i: int):
        self.idx = i
        self.children: List[Tuple[int, int]] = []
        self.visited = False
        self.added = False
        self.distance: Optional[int] = None
        self.prev: Optional[Node] = None

    def __lt__(self, other: "Node"):
        if self.distance is None:
            return False
        if other.distance is None:
            return True
        return self.distance < other.distance

    def __repr__(self) -> str:
        return f"Node({self.idx}, {self.distance}, {self.visited}, {self.added})"


def solve():
    n, m = map(int, input().strip().split())
    nodes = [Node(i) for i in range(n)]
    for _ in range(m):
        u, v, w = map(int, input().strip().split())
        nodes[u-1].children.append((v-1, w))
        nodes[v-1].children.append((u-1, w))

    nodes[0].visited = True
    nodes[0].added = True
    nodes[0].distance = 0
    heap = [nodes[0]]
    while len(heap) > 0:
        node = heappop(heap)
        node.visited = True
        for i, w in node.children:
            child = nodes[i]
            if not child.visited:
                assert node.distance is not None
                if child.distance is None or child.distance > (node.distance + w):
                    child.distance = node.distance + w
                    child.prev = node
                if child.added:
                    heapify(heap)
                else:
                    child.added = True
                    heappush(heap, child)
        if node.idx == n-1:
            break
    path = []
    node = nodes[-1]
    while node is not None and node.idx != 0:
        path.append(node.idx + 1)
        node = node.prev
    path.append(1)
    print(" ".join(map(str, reversed(path))))


def main():
    # t = int(input())
    t = 1
    for _ in range(t):
        solve()


if __name__ == "__main__":
    main()

