def solve(n,x):
    from collections import Counter
    ct = Counter(map(int,input().split()))
    s = sum([v*ct[v] for v in ct.keys()])
    d = {k: 0 for k in range(s-max(ct.keys()), s-min(ct.keys()) + 50)}
    for v in ct:
        d[s-v] += ct[v]
    for v in sorted(d.keys()):
        if d[v]%x==0:
            k = 0
            while d[v]%x==0:
                k += 1
                d[v] //= x
            d[v+k] += d[v]
        else:
            return v
    return -1

