class Solution:
    def balancedSubstring(self, n: int, s: str) -> int:
        ones, zeroes = s.count('1'), s.count('0')
        if not ones or not zeroes:
            return 0
        elif ones == zeroes:
            return n
        elif ones < zeroes:
            small = ['1', ones]
        else:
            small = ['0', zeroes]
        # print(ones, zeroes, small)
        l = r = ans = more = less = 0
        while r < n:
            if s[r] != small[0]:
                more += 1
            else:
                less += 1
                
            if less == small[1]:
                ans = max(ans, less * 2)
                break
            
            if less < small[1] < more:
                ans = max(ans, less * 2)
                if s[l] != small[0]:
                    more -= 1
                    l += 1
                else:
                    while more > small[1]:
                        if s[l] == small[0]:
                            small[1] -= 1
                            less -= 1
                        else:
                            more -= 1
                        l += 1
            
                        if not small[1]:
                            break
            
            r += 1
        
        return ans
        
        

