import random

def solve(a,b):
    count = 0

    while True:
        if a == b:
            return count + 1

        if b == 1:
            return count + a

        count += 1
        a -= b
        if b > a:
            a,b = b,a

    return count


def solve_simple(a,b):
    if a == b:
        return 1

    a -= b
    if b > a:
        a,b = b,a

    return 1 + solve(a,b)

