class Solution:
    def balancedSubstring(self, n, s):
        ones = s.count('1')
        zeroes = s.count('0')
        
        if not ones or not zeroes:
            return 0
        elif ones == zeroes:
            return n
        elif ones > zeroes:
            one = True
        else:
            one = False
        
        more, less = 0, min(zeroes, ones)
        l = r = 0
        while r < n:
            if one and s[r] == '1':
                more += 1
            elif one and s[r] == '0':
                less -= 1
            elif not one and s[r] == '1':
                less -= 1
            elif not one and s[r] == '0':
                more += 1
            
            if more == min(zeroes, ones) and not less:
                return r - l + 1
            
            if more >= min(zeroes, ones) and less:
                if (one and s[l] == '1') or (not one and s[l] == '0'):
                    l += 1
                    more -= 1
                else:
                    while more > min(zeroes, ones):
                        if (one and s[r] == '1') or (not one and s[r] == '0'):
                            r -= 1
                            more -= 1
                        else:
                            break
                    return r - l + 1
            
            r += 1
                    
        
    
        

