    if arr[0]>target:
        return -1
    while l+1<r:
        mid=(l+r)//2
        if arr[mid]==target:
            return mid
        else:
            if arr[mid]>target:
                r=mid 
            else:
                l=mid
    if arr[r]<=target:
        return r
    return l
