def find_root(x, roots):
    if x not in roots:
        return x
    L = []
    while roots[x] != x:
        x = roots[x]
        L.append(x)
    for y in L:
        roots[y] = x
    return x
    
def process(G):
    g = {}
    roots = {}
    root_dict = {}
    for a, b in G:
        if a not in g:
            g[a] = set([])
        if b not in g:
            g[b] = set([])
        g[a].add(b)
        g[b].add(a)
        if a not in roots and b not in roots:
            roots[a] = min(a, b)
            roots[b] = min(a, b)
            root_dict[min(a, b)] = [2, 1]
        elif a not in roots and b in roots:
            b2 = find_root(b, roots)
            roots[a] = b2
            root_dict[b2][0]+=1
            root_dict[b2][1]+=1
        elif a in roots and b not in roots:
            a2 = find_root(a, roots)
            roots[b] = a2
            root_dict[a2][0]+=1
            root_dict[a2][1]+=1
        else:
            a2 = find_root(a, roots)
            b2 = find_root(b, roots)
            if a2 != b2:
                if len(root_dict[a2]) <= len(root_dict[b2]):
                    roots[a2] = b2
                    nodes, edges = root_dict[a2]
                    root_dict[b2][0]+=nodes
                    root_dict[b2][1]+=(edges+1)
                    root_dict.pop(a2)
                else:
                    roots[b2] = a2
                    nodes, edges = root_dict[b2]
                    root_dict[a2][0]+=nodes
                    root_dict[a2][1]+=edges
                    root_dict.pop(b2)
    for R in root_dict:
        nodes, edges = root_dict[R]
        if nodes != edges*(edges-1):
            return 'NO'
    return 'YES'
 
