def generate_primes(n):
    sieve = [1] * (n + 1)
    primes = []

    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n + 1, i):
                sieve[j] = 0

    for i in range(2, n + 1):
        if sieve[i]:
            primes.append(i)

    return primes

