def solve(n,m,s,f,li):
    res=""
    if s<f:
        time=1
        pos=s
        for t,l,r in li:
            if time==t and pos+1>=l and pos+1<=r:
                res+="X"
            else:
                res+="R"
                pos+=1
            if pos==f:break
            time+=1
    else:
        time=1
        pos=s 
        for t,l,r in reversed(li):
            if time==t and pos-1>=l and pos-1<=r:
                res+="X"
            else:
                res+="L"
                pos-=1
            if pos==f:break
            time+=1
    return res
