def bootstrap(f, stack=[]):
    def wrappedfunc(*args, **kwargs):
        if stack:
            return f(*args, **kwargs)
        to = f(*args, **kwargs)
        while True:
            if type(to) is GeneratorType:
                stack.append(to)
                to = next(to)
            else:
                stack.pop()
                if not stack:
                    break
                to = stack[-1].send(to)
        return to

    return wrappedfunc


def solution():
    @bootstrap
    def dp(j: int, prev: int) -> int:
        if (j, prev) in cache:
            yield cache[(j, prev)]
        if j == m:
            ans = 0
        else:
            ans = 10 ** 20
            for i in range(1, n):
                if a[i - 1][prev] == a[i][prev] and a[i][j] < a[i - 1][j]:
                    ans = min(ans, 1 + (yield dp(j + 1, prev)))
                    break
            else:
                ans = min(ans, 1 + (yield dp(j + 1, prev)))
                ans = min(ans, (yield dp(j + 1, j)))
        cache[(j, prev)] = ans
        yield ans

    n, m = [int(num) for num in input().split()]
    a = []
    for i in range(n):
        a.append(input() + 'a')
    cache = dict()
