def dp():
    b = [0]
    global ind
    for ind in range(1, n):
        x = bs(0, ind - 1)
        if x == 0:
            if a[x][0] >= a[ind][0] - a[ind][1]:
                b.append(ind)
            else:
                b.append(ind - 1)
        else:
            b.append(ind - x - 1 + b[x])
    best = n
    for i in range(n):
        if n - 1 - i + b[i] < best:
            best = n - 1 - i + b[i]
    return best

