import math 
class point():
    def __str__(self):
        return str((self.x, self.y))
    def __init__(self, x=0, y=0):
        self.x = x; self.y = y 
    def __mul__(self, other): # косое
        return self.x * other.y - self.y * other.x
    def __and__(self, other): # скаляр
        return self.x * other.x + self.y * other.y 
    
    def __sub__(self, other): # перенос
        return point(self.x - other.x, self.y - other.y) 
    def __add__(self, other):
        return point(self.x + other.x, self.y + other.y)
    def __floordiv__(self, other: int):
        return point(self.x//other, self.y//other)
    def len(self):
        return math.sqrt(self & self) 
class line():
    def __init__(self, p, q):
        self.a = q.y - p.y 
        self.b = p.x - q.x 
        self.c = -p.y * p.x - q.x * q.y
    def normal(self, m):
        n = point(-self.b, self.a)
        res = line(point(), point())
        res.a = n.x 
        res.b = n.y 
        res.c = -n.x * m.x - n.y * m.y
        return res
    def check(self, x, y):
        return self.a * x + self.b * y == self.c
    def y(self, x):
        return (-self.c - self.a*x)/self.b 
    def x(self, y):
        return (-self.c - self.b*y)/self.a
 
