	if a[0]>target:
		return 0
	low = 0
	high= len(a)-1
	ans=len(a)
	while low<=high:
		mid = low+(high-low)//2
		if a[mid]>target:
			ans = min(ans,mid)
			high=mid-1
		else:
			low=mid+1
	return ans
