def div_number(n):
    first_div = []
    while n > 1:
        first_div.append(n%2)
        n //= 2
    list1 = [1] + [first_div[-1]] + [1]
    for i in range(len(first_div)-1,0,-1):
        result = list1 + [first_div[i-1]] + list1
        list1 = result
    return result

