def alpha(q):
    for i in range(len(q)-1):
        if q[i]>q[i+1]:
            return 0
    return 1

def lol(q):
    for i in range(len(q)-1):
        if q[i][0]>q[i+1][0]:
            return 0
    return 1

def rem(q,count):
    while alpha(q) == 1:
        count += 1
        p = q
        for i in range(len(p)):
            p[i] = p[i][:count]+p[i][count+1:]
    for i in range(len(q)):
        q[i] = q[i][:count]+q[i][count+1:]
    return q
    
