def gcd(a, b):
    return a if b == 0 else gcd(b, a%b)
#O(log(min(p,q))
def ext_gcd(p,q): # px+qy=gcd
    if q==0:
        return (p,1,0)
    (g,y,x) = ext_gcd(q, p%q)
    return (g,x,y - (p//q)*x)

