def crt(a1,mo1,a2,mo2): # return (x,y) y=lcm(a1,a2),x%mo1=a1,x%mo2=a2
    g,x,y=ext_gcd(mo1,mo2)
    a1%=mo1
    a2%=mo2
    if a1%g != a2%g:
        return (-1,0)
    lcm=mo1*(mo2/g)
    return ((a1+((a2-a1)%lcm)*x%lcm*(mo1/g)) % lcm,lcm)
