            upper_angle_from_x_axis.append(0.0)
        elif y == 0 and x > 0 :
            upper_angle_from_x_axis.append(0.0)
        elif y == 0 and x < 0:
            lower_angle_from_x_axis.append(180.0)
        elif x == 0 and y > 0:
            upper_angle_from_x_axis.append(90.0)
        elif x == 0 and y < 0:
            lower_angle_from_x_axis.append(270.0)
        else:
            alpha = math.atan(abs(y)/abs(x))
            alpha = (alpha *  180.0)/math.pi
            if x > 0 and y > 0 :
                upper_angle_from_x_axis.append(alpha)
            elif y > 0  and x < 0 :
                upper_angle_from_x_axis.append(180.0-alpha)
            elif x < 0 and y < 0:
                lower_angle_from_x_axis.append(180.0+alpha)
            else:
                lower_angle_from_x_axis.append(360.0-alpha)
    
    #print(angle_from_x_axis)
    if len(upper_angle_from_x_axis) == 0:
        max_y_lt_0 = max(lower_angle_from_x_axis)
        min_y_lt_0 = min(lower_angle_from_x_axis)
        final_viewing_angle = max_y_lt_0 - min_y_lt_0

    elif len(lower_angle_from_x_axis) == 0:
        max_y_gt_0 = max(upper_angle_from_x_axis)
        min_y_gt_0 = min(upper_angle_from_x_axis)
        final_viewing_angle = max_y_gt_0 - min_y_gt_0
    
    else:
        max_y_lt_0 = max(lower_angle_from_x_axis)
        min_y_lt_0 = min(lower_angle_from_x_axis)
        max_y_gt_0 = max(upper_angle_from_x_axis)
        min_y_gt_0 = min(upper_angle_from_x_axis)

