def main():
    n, m = map(int, input().split())
    data = []
    l = [[] for _ in range(n + 1)]
    for _ in range(m):
        u, v = map(int, input().split())
        l[u].append(v)
        data.append((u, v))
    childs = [[] for _ in range(n + 1)]
    avail = [True] * (n + 1)
    for u, v in data:
        childs[u].append(v)
        avail[v] = False
    avail = [u for u, v in enumerate(avail) if v]
    if len(avail) != 2:
        print(-1)
        return
    chain = [0] * n
    chain[-1] = avail[1]
    avail = [True] * (n + 1)

    def deeper(lvl):
        if lvl:
            t = chain[lvl]
            lvl -= 1
            for t in childs[t]:
                if avail[t]:
                    avail[t] = False
                    chain[lvl] = t
                    deeper(lvl)
                    avail[t] = True
        else:
            raise TabError

    try:
        deeper(n - 1)
    except TabError:
        s = {(v, u) for u, v in zip(chain, chain[1:])}
        for i, e in enumerate(data, 1):
            s.discard(e)
            if not s:
                print(i)
                return
    print(-1)


