def can_form_names(guest_name, host_name, pile_letters):
    # Count the frequency of each letter in guest_name and host_name
    guest_freq = {}
    host_freq = {}

    for letter in guest_name:
        guest_freq[letter] = guest_freq.get(letter, 0) + 1

    for letter in host_name:
        host_freq[letter] = host_freq.get(letter, 0) + 1

    # Count the frequency of each letter in the pile_letters
    pile_freq = {}
    for letter in pile_letters:
        pile_freq[letter] = pile_freq.get(letter, 0) + 1

    # Check if all letters in the names can be formed from the pile_letters
    for letter, freq in guest_freq.items():
        if letter not in pile_freq or pile_freq[letter] < freq:
            return False

    for letter, freq in host_freq.items():
        if letter not in pile_freq or pile_freq[letter] < freq:
            return False

    return True

