def split_into_triplets (a:str):
    """ Функция делает строку делимой на триплеты, а потом делит строку на триплеты цифр и сравнивает их с возможными для счастливого числа
    """
    while len(a)%3 !=0:
        x = a[-1]
        if (x!= '1' and x!='4'):
            return "NO"
        a = a[:-1]
    for i in range (3, len(a), 3):
        triplet = a[(i-3):i]
        if (triplet!="111" and triplet!="114" and triplet!="144" and  triplet!="141" and triplet!="411" and triplet!="441"):
            return "NO"
    return "YES"


    


