    reverse_count = int( (len(word)/2)-1 )
    for i in range(int(len(word)/2), len(word)):
      if(word[i] != word[reverse_count]):
        return False;
      reverse_count = reverse_count - 1
  else: 
    reverse_count = int((len(word)/2)-1)
    for i in range(int(len(word)/2)+1, len(word)):
      if(word[i] != word[reverse_count]):
        return False;
      reverse_count = reverse_count -1
  return True;

def check_Mirrored(word):
