    if yr == 0 or yr == '':
        return False
    
    return True if int(yr % 4) == 0 else False

def noofWeeks(yr,wk):
    wk = int(wk)
    cd = 0
    st= datetime.date(day=1, year=wk, month=1)
    if isLeapYear(yr):
        n = 365
    else:
        n = 364    
    
    while n > 1:
        
        d = st + datetime.timedelta(days=n)
        
        if  int(d.isoweekday()) == wk:
            cd = cd + 1
        
        n = n - 1
        
        if n <= 0:
            break
    
    return cd

