class Node:
    def __init__(self,start,end):
        self.start=start
        self.end = end
        self.left = None
        self.right = None
        self.val = 0
        
class SegmentTree:
    def __init__(self,arr):
        self.arr = arr
        self.root = self.build(0,n-1)
        
    def build(self,start,end):
        if start>end:
            return 
        node = Node(start,end)
        
        if start==end:
            node.val = self.arr[start]
            return node
        
        mid = (start+end)//2
        
        node.left = self.build(start,mid)
        node.right = self.build(mid+1,end)
        
        node.val = node.left.val+node.right.val
        
        return node
    
    def getSum(self,node,low,high):
        start = node.start
        end = node.end
        
        if low>end or high<start:
            return 0
        
        if low<=start and high>=end:
            return node.val
        
        return self.getSum(node.left,low,high)+self.getSum(node.right,low,high)

    def update(self,node,low,high):
        if low>node.end or high<node.start:
            return
        
        if node.start == node.end:
            node.val = self.getCount(node.val)
            
            return
        
        self.update(node.left,low,high)
        self.update(node.right,low,high)
        
        node.val = node.left.val+node.right.val
        return
    def getCount(self,val):
        from math import sqrt
        from math import ceil
        if val == 1:
            return 1
        if val == 2:
            return 2
        
        if val == 3:
            return 2
        count = 0
        for i in range(1,ceil(sqrt(val))+1):
            #print(i)
            if val%i == 0:
                # print(i,val)
                if i!=sqrt(val):
                    count += 2
                else:
                    count += 1
        return count
        
