def teletransporte(caminho, posicao, salto, contador):
    if (posicao == len(caminho) - 1):
        return contador

    if (caminho[posicao] == 0 or posicao > len(caminho)):
        return 1000

    i = salto

    while (i > 0):
        if (i + posicao <= len(caminho) - 1 and caminho[i + posicao] == '1'):
            tmp = teletransporte(caminho, posicao + i, salto, contador + 1)
            if (tmp != 1000):
                return tmp
        i -= 1

    return 1000


