def possible(arr):
    tr=arr[::-1]
    t=len(arr)-tr.index(min(tr))-1
    f=arr[:t]
    e=arr[t+1:]
    fa=f[:]
    fa.sort()
    ea=e[:]
    ea.sort()
    if(len(fa)==0):
        if(ea==e):
            return True 
        else:
            return False
    if(len(ea)==0):
        if(fa==f):
            return True 
        else:
            return False
    if(fa==f and ea==e and ea[len(ea)-1]<=fa[0]):
        return True 
    return False


