import math

def is_t_prime(number):
    # 特殊情况处理
    if number < 4:
        return False
    
    sqrt = int(math.sqrt(number)) + 1
    
    # 判断平方根是否为质数
    if sqrt * sqrt != number:
        return False
    
    # 判断平方根是否有两个非自身的因数
    for divisor in range(2, int(math.sqrt(sqrt)) + 1):
        if sqrt % divisor == 0:
            return False
    
    return True

