import heapq

class Graph:

    def __init__(self):
        self.g = {}

    def add_vertex(self, u):
        self.g[u] = []

    def add_edge(self, u, v, w):
        if u not in self.g.keys():
            self.add_vertex(u)

        if v not in self.g.keys():
            self.add_vertex(v)

        self.g[u].append((w, v))
        self.g[v].append((w, u))

    def dijkstra(self, u, v):
        heap, visited = [], set()
        heapq.heappush(heap, (0, u, [str(u)]))

        while heap:
            cost, node, path = heapq.heappop(heap)
            if node == v:
                return path
            if node not in visited:
                visited.add(node)
                for weight, neighbor in self.g[node]:
                    if neighbor not in visited:
                        heapq.heappush(heap, (cost + weight, neighbor,
                                              path + [str(neighbor)]))
        return [str(-1)]

