def calculateParticles(positions,movement):
    p = positions
    newPosition = []
    count = 1
    while count < 999:
        for index in range(len(p)):
            if str(movement[index]) == "R":
                if int(p[index])+1 not in newPosition:
                    newPosition.append(int(p[index])+1)
                    continue
                else:
                    return count
            if str(movement[index]) == "L":
                if int(p[index])-1 not in newPosition:
                    newPosition.append(int(p[index])-1)
                    continue
                else:
                    return count

        p = newPosition.copy()
        newPosition.clear()
        count+=1
    return -1


