import heapq


def validRadius(radius, street, l):
    intervals = []
    
    for lantern_pos in street:
        intervals.append((lantern_pos-radius, lantern_pos+radius))
    
    intervals.sort(reverse=True)
    start = 0
    heap = []
    while intervals and intervals[-1][0] <= start:
        heapq.heappush(heap, intervals.pop())
        
    while heap:
        curr_start, curr_end = heapq.heappop(heap)
        start = curr_end
        
        if start >= l:
            return True
        
        while intervals and intervals[-1][0] <= start:
            heapq.heappush(heap, intervals.pop())
            
    return False



def binarySearchUpperBound(street, l):
    ans = l
    lo, hi = 0, l
    
    while lo <= hi:
        mid = (lo+hi)//2
        if validRadius(mid, street, l):
            ans = mid
            hi = mid-1
        else:
            lo = mid+1
            
    return ans
    
    
    
def binarySearchRadius(street, l, hi):
    ans = hi
    lo, hi = 0, hi
    
    gap = 10**-9
    while hi-lo >= gap:
        mid = (lo+hi)/2
        if validRadius(mid, street, l):
            ans = mid
            hi = mid-gap
        else:
            lo = mid+gap
            
    return ans
    


