def letter():
    n, m = map(int, input().split())
    data = [input() for _ in range(n)]

    i = 0
    while '*' not in set(data[i]):
        i += 1
    data = data[i:]
    if len(data) == 0:
        return ''

    i = len(data) - 1
    while '*' not in set(data[i]):
        i -= 1
    if i <= 0:
        return ''
    data = data[:i + 1]

    min_x, max_x = m - 1, 0
    for i in range(len(data)):
        j = 0
        while data[i][j] != '*':
            j += 1
        min_x = min(j, min_x)

        j = m - 1
        while data[i][j] != '*':
            j -= 1
        max_x = max(j, max_x)

    for i in range(len(data)):
        data[i] = data[i][min_x:max_x + 1]

    return '\n'.join(data)


