      for j in range(i+1, len(arr)):
        arr[j] += arr[i-1] - arr[i]
        ans += arr[i-1] - arr[i]
      ans += arr[i-1] - arr[i]
      arr[i] = arr[i-1]
  if flag == 1:
    return ans + sum(arr)
  else:
    return ans

