from collections import defaultdict

class Graph:
    def __init__(self):
        self.outgoing = defaultdict(list)
    def AddEdge(self, u, v):
        self.outgoing[u].append((1, v, 0))
        self.outgoing[v].append((1, u, 0))
        
triplets = {}

pq = []

def Dijkstra(g, dist):
    while len(pq):
        pq.sort()
        e = pq.pop(0)
        distance, u, prev = e[0], e[1], e[2]

        if dist[u][prev] != distance:
            continue

        for item in g.outgoing[u]:
            t = item[1]

            if (prev, u, t) in triplets:
                continue

            if (dist[u][prev] + 1 < dist[t][u]):
                dist[t][u] = dist[u][prev] + 1
                pq.append((dist[t][u], t, u))
                parents[t][u] = [u, prev]

def drawpath(u, prev_u):
    try:
        parents[u][prev_u][0] == 0
    except:
        print(u, end=' ')
        return
    back = parents[u][prev_u]
    
    drawpath(back[0], back[1])
    print(u, end=' ')
    
