def power(x, y, p):
    result = 1
    x = x % p
    while y > 0:
        if y % 2 == 1:
            result = (result * x) % p
        y = y // 2
        x = (x * x) % p
    return result

def phi(n):
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def count_primitive_roots(p):
    phi_p = phi(p)
    primitive_roots = 0
    for x in range(2, p):
        is_primitive_root = True
        residues = set()
        for k in range(1, phi_p):
            residue = power(x, k, p)
            residues.add(residue)
            if residue == 1:
                is_primitive_root = False
                break
        if is_primitive_root and len(residues) == phi_p - 1:
            primitive_roots += 1
    return primitive_roots

