def get_integer_input():
    values = input().split()
    return int(values[0]) if len(values) > 0 else None

def get_queue_sizes():
    return list(map(int, input().split()))

def find_entrance():
    num_entrances = get_integer_input()
    queue_sizes = get_queue_sizes()

    minimum_size = min(queue_sizes)
    initial_position = queue_sizes.index(minimum_size)

    while queue_sizes[initial_position] - minimum_size > 0:
        minimum_size += 1
        initial_position = (initial_position + 1) % num_entrances

    return initial_position + 1

