def getLps(st):
    if len(st)==0:
        return []
    lps=[0]

    for i in range(1,len(st)):
        if st[i]==st[lps[-1]]:
            lps.append(lps[-1]+1)
        else:
            j=lps[-1]-1
            while j>=0 and st[i]!=st[lps[j]]:
                j=lps[j]-1
            lps.append(j+1)

    return lps

def solve(st):
    lps = getLps(st)
    k = lps[-1]
    if k==0:
        return "Just a legend"

    for i in range(len(lps)-1):
        if lps[i]==k:
            return st[:k]
    k=lps[k]
    if k==0:
        return "Just a legend"
    return st[:k]

