def check_right(s):
  found = False
  seq_sum, partial_sum = 0, 0
  for i in range(len(s) - 1, 0, -1):
    partial_sum += s[i]
    if found:
      if s[i] % 2 == 0: return False
      seq_sum += s[i]
      if seq_sum % 2 == 1: return True
    if s[i] % 2 == 0:
      seq_sum += partial_sum
      found = True
  return False
  

def check_left(s):
  found = False
  seq_sum, partial_sum = 0, 0
  for i in range(len(s) - 1):
    partial_sum += s[i]
    if found:
      if s[i] % 2 == 0: return False
      seq_sum += s[i]
      if seq_sum % 2 == 1: return True
    if s[i] % 2 == 0:
      seq_sum += partial_sum
      found = True
  return False


