def solve():
    n,m=geti()
    target=n-1
    edges=dd(list)
    weight=[]
    seen=set()
    mini=[float('inf')]*n
    parent=[None]*n
    for i in range(m):
        u,v,w=geti()
        u-=1
        v-=1
        edges[u].append((v,w))
        edges[v].append((u,w))
    heappush(weight,[0,0,None])
    while weight:
        cost,node,par=heappop(weight)
        if node in seen:
            continue
        seen.add(node)
        mini[node]=cost
        parent[node]=par
        if node==target:
            break
        for child,price in edges[node]:
            if child in seen:
                continue
            if mini[child]>mini[node]+price:
                heappush(weight,[mini[node]+price,child,node])
    path=[]
    node=target
    # print(parent,mini)
    while node!=None:
        path.append(node+1)
        node=parent[node]
    path.reverse()
    if 1 not in path and n not in path:
        print(-1)
    print(*path)



