def is_leap_year(y):
    if y % 400 == 0:
        return True
    if y % 100 == 0:
        return False
    return y % 4 == 0

def month_days(y, m):
    if m == 2:
        if is_leap_year(y):
            return 29
        else:
            return 28
    elif m <= 7 and m % 2 == 1:
        return 31
    elif m <= 7 and m % 2 == 0:
        return 30
    elif m >= 8 and m % 2 == 1:
        return 30
    elif m >= 8 and m % 2 == 0:
        return 31
    return -1

