def quick_sort(lst: list) -> list:
    if len(lst) == 0:
        return []
    pivot = lst[0]
    less = [elem for elem in lst[1:] if elem < pivot]
    greater = [elem for elem in lst[1:] if elem >= pivot]
    return quick_sort(less) + [pivot] + quick_sort(greater)

def bin_search_count(lst: list, target: int) -> int:
    l, r = -1, len(lst)
    while r > (l+1):
        mid = (l + r) // 2
        elem = lst[mid]
        if elem <= target:
            l = mid
        else:
            r = mid
    if l == -1:
        return 0
    elif l == len(lst):
        return len(lst)
    return l+1


