def ciel(x, y):
    if x >= 2 and y >= 2:
        x -= 2
        y -= 2
    elif x == 1 and y >= 12:
        x -= 1
        y -= 12
    elif x == 0 and y >= 22:
        y -= 22
    else:
        return "Hanako"
    return "Ciel"


def hanako(x, y):
    if y >= 22:
        y -= 22
    elif x == 1 and y >= 12:
        x -= 1
        y -= 12
    elif x >= 2 and y >= 2:
        x -= 2
        y -= 22
    else:
        return "Ciel"
    return "Hanako"


