def matrix(rowNum, colNum, val=0):
    mat = []
    for i in range(rowNum):
        collumn = [val for j in range(colNum)]
        mat.append(collumn)
    return mat


def pascle(lim):
    p = matrix(lim, lim)
    for i in range(lim):
        p[i][i] = p[i][0] = 1
    for i in range(1, lim):
        for j in range(1, lim):
            p[i][j] = (p[i - 1][j - 1] + p[i - 1][j]) % mod
    return p


