def dijkstra_with_moments(graph, moves):
    unvisited = [x+1 for x in range(n)]
    shortest_paths = {}
    for i in range(n):
        shortest_paths[i+1] = 999999999999
    shortest_paths[1] = 0
    for i in range(n):
        minimal = 9999999999999
        minimal_num = 0
        for j in range(n):
            path = shortest_paths[j+1]
            if path != 999999999999:
                while path in moves[j+1]:
                    path += 1
            if path < minimal and j+1 in unvisited:
                minimal = path
                minimal_num = j+1
        unvisited.remove(minimal_num)
        for planet, weight in graph[minimal_num]:
            if minimal + weight < shortest_paths[planet]:
                shortest_paths[planet] = minimal + weight
    if shortest_paths[n] == 999999999999:
        return -1
    else:
        return shortest_paths[n]
