    arr = []
    for _ in range(n):
        arr.append(list(input()))

    amount = int(input())
    letters = sorted(input())

    index = {}
    for row_index, j in enumerate(arr):
        for col_index in range(m):
            if j[col_index] not in index:
                index[j[col_index]] = [(row_index, col_index)]
            else:
                index[j[col_index]].append((row_index, col_index))

    total = 0
    for i in range(amount):
        # Uppercase letter but no shift key
        if letters[i].isupper() and 'S' not in index:
            print(-1)
            return

        # All uppercase letters have been checked
        elif letters[i].islower() and letters[i] not in index:
            print(-1)
            print(letters[i])
            return

        # Check uppercase letter
        elif letters[i].isupper():
            current = letters[i].lower()
            current_indexes = index[current]

            capital = index['S']
            is_possible = False

            # Check if can use one hand to type
            for j in current_indexes:
                for k in capital:
                    if ((j[1] - k[1])**2 + (j[0] - k[0])**2)**0.5 <= x:
                        is_possible = True

            if is_possible == False:
                total += 1

    print(total)
