    if n == 0:
        return 0
    if len(a) <= n:
        return 1
    l = [[i] for i in a[:n]]
    ind = 0
    for i in a[n:]:
        starting_pos = ind
        while l[ind][-1] == 0:
            ind += 1
            ind %= len(l)
            if ind == starting_pos:
                return 0
        l[ind] += [i]
    return 1

