def fact(n):
    p = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            p[d-1] = p.get(d-1,0)+1
            n //= d
        d += 1
    if n > 1:
        p[n-1] = p.get(n-1,0) + 1
    return p

def isPrime(n):
    if n % 2 == 0:
        return n == 2
    d = 3
    while d * d <= n and n % d != 0:
        d += 2
    return d * d > n

