    if p == 2:
        return True
    elif p == 1:
        return False
    else:
        for i in range(2, p):
            if p % i == 0:
                return False
            else:
                continue
        return True

def prime_div(n, target = 2):
    count = 0
    if target == 1:
        if n == 1:
            return False
        else:
            cp = 0
            for l in range(2, n):
                if is_prime(l) and n % l == 0:
                    cp += 1
                if cp > 1:
                    return False
            return True
    if n % 2 == 0:
        m = n
        while m % 2 == 0:
            m = int(m/2)
        #  print(m, end = ' ')
        return prime_div(m, 1)
    else:
        for j in range(2, n):
            if is_prime(j):
                if n % j == 0:
                    count += 1
                if count > target:
                    return False
        if count < target:
            return False
        else:
            return True

