from collections import deque

def DLBranch(way, cities, dlCities):
    for i in range(len(way) - 1, -1, -1):
        for city in cities[way[i]]:
            if dlCities[city - 1] == False:
                break
        
        dlCities[way[i] - 1] = True

def AppendTail(way, tailStartNode, tailEndNode, memo):
    cNode = tailStartNode
    while(cNode != tailEndNode):
        cNode = memo[cNode][2]
        way.append(cNode)

def GetWay(startNode):
    way = []
    cNode = startNode
    while(len(cNode[1]) != 0):
        way.append(cNode[0])
        cNode = cNode[1]
    way.append(cNode[0])
    way.reverse()
    return way

def MemoizeWay(way2Cache, fullPath, pathTime, maxTime, memo, cities):
    pathLen = len(fullPath)
    for i in range(len(way2Cache) - 1):
        if pathTime <= maxTime:
            if way2Cache[i] in memo:
                if pathLen > memo[way2Cache[i]][0]:
                    memo.update({ way2Cache[i] : [ pathLen, pathTime, fullPath ] })
            else:
                memo.update({ way2Cache[i] : [ pathLen, pathTime, fullPath ] })
        
        pathLen -= 1
        pathTime -= cities[way2Cache[i]][way2Cache[i+1]]


