def DFS2(adjList, v, discovered, cycle, parent=-1):
    if discovered[v]:
        return v
    discovered[v] = True
    for u in adjList[v]:
        if u != parent:
            k = DFS2(adjList, u, discovered, cycle, v)
            if k != -1:
                cycle.add(v)
            if k == -2:
                return -2
            if k == v:
                return -2
            return k
    return -1


