class info:
    def __init__(self,open=0,close=0,full=0):
        self.open = open
        self.close = close
        self.full = full
class segment_tree:
    def __init__(self,n):
        self.seg =[info() for _ in range(4*n)]
    def merge(self,node1,node2):
        s= info()
        s.full = node1.full+node2.full+min(node1.open,node2.close)
        s.open = node1.open+node2.open-min(node1.open,node2.close)
        s.close = node1.close +node2.close-min(node1.open,node2.close)
        return s
    def build(self,ind,low,high,arr):
        if low==high:
            if arr[low]=='(':
                self.seg[ind].open+=1
            else:
                self.seg[ind].close += 1
            return
        mid = (low+high)//2
        self.build(2*ind+1,low,mid,arr)
        self.build(2*ind+2,mid+1,high,arr)
        self.seg[ind] = self.merge(self.seg[2*ind+1],self.seg[2*ind+2])

    def query(self,ind,low,high,l,r):

        if l>high or r<low:
            return info()
        if low>=l and high<=r:
            return self.seg[ind]
        mid = (low+high)//2
        left = self.query(2*ind+1,low,mid,l,r)
        right = self.query(2 * ind + 2, mid+1,high,l,r)
        return self.merge(left,right)

    def update(self,ind,low,high,i,val):
        if low==high:
            self.seg[ind] = val
            return
        mid =(low+high)>>1
        if i<=mid:
            self.update(2*ind+1,low,mid,i,val)
        else:
            self.update(2*ind+2,mid+1,high,i,val)
        self.seg[ind] = self.merge(self.seg[2*ind+1],self.seg[2*ind+2])



