import enum

class PointSet(enum.Enum):
    EMPTY = 0   # Empty set of points
    PLANE = 1
    HLINE = 2   # Horizontal line
    VLINE = 3   # Vertical line
    ALINE = 4   # Angled line

def classify_set(a, b, c):
    if a == 0 and b == 0:
        # The set is empty, therefore 0 points satisfy it.
        if c != 0:
            return PointSet.EMPTY
        return PointSet.PLANE
    elif a == 0:
        return PointSet.HLINE
    elif b == 0:
        return PointSet.VLINE
    else:
        return PointSet.ALINE

def main():
    a1, b1, c1 = tuple(map(int, input().split()))
    a2, b2, c2 = tuple(map(int, input().split()))

    set1_type = classify_set(a1, b1, c1)
    set2_type = classify_set(a2, b2, c2)

    if set2_type == PointSet.EMPTY or set2_type == PointSet.EMPTY:
        return 0

    if set1_type == PointSet.PLANE or set2_type == PointSet.PLANE:
        return -1

    if set1_type == PointSet.VLINE:
        if set2_type == PointSet.VLINE:
            if c1 / a1 == c2 / a2:
                return -1
            else:
                return 0
        elif set2_type == PointSet.HLINE or set2_type == PointSet.ALINE:
            return 1
        else:
            raise ValueError("Unknown enum value")
    elif set1_type == PointSet.HLINE:
        if set2_type == PointSet.HLINE:
            if c1 / b1 == c2 / b2:
                return -1
            else:
                return 0
        elif set2_type == PointSet.VLINE or set2_type == PointSet.ALINE:
            return 1
        else:
            raise ValueError("Unknown enum value")
    elif set1_type == PointSet.ALINE:
        if set2_type == PointSet.ALINE:
            if b1 / a1 == b2 / a2:
                if c1 / b1 == c2 / b2:
                    return -1
                else:
                    return 0
            else:
                return 1
        elif set2_type == PointSet.HLINE or set2_type == PointSet.VLINE:
            return 1
        else:
            raise ValueError("Unknown enum value")
    else:
        raise ValueError("Unknown enum value")

