def dfs(g, u): #construct DFS-tree from vertex u
    stack = [u]
    colors = [0] * len(g) #0-white, 1-gray, 2-black
    while len(stack):
        v = stack.pop()
        if colors[v] == 0: #if v is white
            colors[v] = 1 #draw it gray
            for av in g[v]:
                if colors[av] == 0:
                    stack.append(av)
                elif colors[av] == 1: #if adjacency vertex is gray then cycle found and that vertex become black
                    colors[av] = 2
                    return True
    return False

