def find_path(graph, s, t, path=[]):
    path = path + [s]
    if s == t:
        return path
    if not s in graph:
        return None
    sort = None
    for node in graph[s]:
        if node not in path:
            newpath = find_path(graph, node, t, path)
            if newpath:
                if not sort or len(newpath) < len(sort):
                    sort = newpath
    return sort


