        min_value=min(min_value,arr[i])
        i+=1
    j=i+1
    max_value=arr[i]
    while j<n:
        if arr[j]<arr[j-1]:
            return -1
        max_value=max(max_value,arr[j])
        j+=1
    if min_value>=max_value:
        return n-i
    return -1
