    def __init__(self, flowerMood):
        self.flowerMood = flowerMood
        self.n = len(self.flowerMood)
        
    def maximizeHappiness(self, numSubArray, subArray):
        maxHappiness = 0
        
        positiveValue = self.findNumberPositiveMood(0, self.n-1)
        if positiveValue == self.n:
            return self.n
        elif positiveValue == 0:
            return maxHappiness
        else:
            choosenSubArray = []
            for (i,j) in subArray:
              t = self.findNumberPositiveMood(i,j)
              if t > (j-i+1)//2:
                  choosenSubArray.append((i,j))
            
            for i,v in enumerate(self.flowerMood):
                cnt = 0
                for (l,r) in choosenSubArray:
                    if (i >= l) & (i <= r):
                        cnt += 1
                maxHappiness += (v*cnt)
        return maxHappiness
    
    def findNumberPositiveMood(self, start, end):
        positiveMood = 0
        for i in range(start, end+1):
            if self.flowerMood[i] > 0:
                positiveMood += 1
        return positiveMood
        

