class Node:
    def __init__(self, info, next_=None):
        self.info = info
        self.next = next_


class Stack:
    def __init__(self, *args):
        self.head = None
        self.tail = None
        self.length = 0
        if args is not None:
            for el in args:
                self.append_back(el)

    def append_front(self, new_info):
        new_elem = Node(new_info)

        new_elem.next = self.head
        self.head = new_elem

        if self.tail is None:
            self.tail = new_elem

        self.length += 1

    def append_back(self, new_info):
        new_elem = Node(new_info)

        if self.head is None:
            self.append_front(new_info)
        else:
            self.tail.next = new_elem
            self.tail = new_elem
            self.length += 1

    def get_length(self):
        return self.length

    def is_empty(self):
        return self.length == 0

    def pop_front(self):
        if self.head is not None:
            removed = self.head
            self.head = self.head.next
            if self.head is None:
                self.tail = None
            self.length -= 1
            return removed.info

    def pop_back(self):
        if self.tail is not None:
            removed = self.tail
            p = self.head
            if p.next is not None:
                while p.next is not self.tail:
                    p = p.next
                self.tail = p
                p.next = None
            else:  # if 1 element in list
                return self.pop_front()
            self.length -= 1
            return removed.info

    def get_front(self):
        if self.head is None:
            return None
        return self.head.info

    def get_back(self):
        if self.tail is None:
            return None
        return self.tail.info

    def __get(self, n):
        if n < self.length:
            p = self.head
            count = 0
            while count != n:
                p = p.next
                count += 1
            return p
        else:
            return None

    def get(self, n):
        return self.__get(n).info

    def print(self):
        if self.head is not None:
            p = self.head
            while p is not None:
                print(p.info, "->", end=" ")
                p = p.next
            print()
        else:
            print("None")


