def sol(nums):
    ans = 0
    dp = {}
    def helper(n):            
        if n < 0:
            return 0
        
        if n in dp:
            return dp[n]
        
        temp = 1
        for i in range(n):
            if nums[i] < nums[n]:
                temp = max(temp, 1 + helper(i))
        
        nonlocal ans
        ans = max(temp, ans)
        dp[n] = temp
        return temp
    
    for i in range(len(nums)):
        helper(i)
    return ans 


