def solve(n, xs):
    '''
    最初公倍数を求める
    '''
    fs = [0 for _ in xs]

    def go(flag = True):
        m = min(xs)
        for i, x in enumerate(xs):
            cnt = 0
            while x > m:
                cnt += 1
                x = x // 2
            fs[i] += cnt
            xs[i] = x
            if x < m:
                m = x
                flag = False
                go(flag)
                break
        return flag
    flag = go()
    if flag:
        fs = sorted(fs)
        s = fs[len(fs) // 2]
        return sum([abs(s - f) for f in fs])
    else:
        return sum(fs)


def getinput():
    def getints_line():
        return list(map(int, input().split(' ')))
    n = int(input())
    return n, getints_line()


