    for station in stations:
        if station - cpl > car[1]:
            return False
        dtime = (station - cpl) * 2 - (car[1] - (station - cpl))
        if dtime < (station - cpl):
            dtime = station - cpl
        time += dtime
        cpl = station
    if s - cpl > car[1]:
        return False
    dtime = (s - cpl) * 2 - (car[1] - (s - cpl))
    if dtime < s - cpl:
        dtime = s - cpl
    time += dtime
    if time > t:
