    fact=[1]
    invfact=[1]
    for i in range(1,K+1):
        temp=fact[i-1]*i
        temp%=MOD
        fact+=[temp]
        temp=invfact[i-1]*pow(i,MOD-2,MOD)
        temp%=MOD
