from dataclasses import dataclass

DIRECTIONS = {
    -1: 'L',
    0: 'X',
    1: 'R'
}


@dataclass(frozen=True)
class Solver:
    spies: int
    _: int
    spy_start: int
    spy_target: int

    def solve(self) -> None:
        time = 1
        note = self.spy_start
        while not self.has_arrived(note):
            stage_time, watched_l, watched_r = map(int, input().split())
            while time <= stage_time and not self.has_arrived(note):
                direction = self.get_direction(note, watched_l, watched_r)
                print(DIRECTIONS[direction], end='')
                note += direction
                time += 1

    def has_arrived(self, note: int) -> bool:
        return note == self.spy_target

    def get_direction(self, note, watched_l, watched_r) -> int:
        '''Returns -1, 0 or 1 (for L, X and R)'''
        direction = sign(self.spy_target - note)
        next_spy = note + direction
        if note >= watched_l and note <= watched_r or next_spy >= watched_l and next_spy <= watched_r:
            return 0
        return direction


def sign(x: int) -> int:
    if x == 0:
        return 0
    return 1 if x > 0 else -1


def main() -> None:
    solver = Solver(*map(int, input().split()))
    solver.solve()


