def L(x) : 
    return int(int(x)<<1)
def R(x): 
    return int((int(x)<<1)+1) 
def F(x): 
    return int((int(x)>>1))

class Node: 
    def __init__(self, l, r, f, value):
        self.l =l 
        self.r =r
        self.f =f 
        self.value =value
    def __repr__(self):
        return '[l: {0}, r: {1}, f: {2}, value: {3}]'.format(
            self.l, self.r, self.f, self.value)

def create(node, l, r, f, tree, index) :
    tree[node] = Node(l, r, f, 0)
    if l == r- 1:
        index[l] = node
    else :
        mid = int((l+r) >> 1)
        create(L(node), l, mid, node,tree, index)
        create(R(node),mid,r ,node, tree,index)  

def push(node, l, r, value, tree) :
    if tree[node].l ==l and tree[node].r ==r and tree[node].value==0:
        tree[node].value = value
    elif tree[node].value ==0 :
        if tree[L(node)].r >= r : 
            push(L(node), l, r, value, tree) 
        elif tree[R(node)].l <= l :
            push(R(node), l, r, value, tree) 
        else :
            push(L(node), l, tree[L(node)].r, value, tree) 
            push(R(node), tree[R(node)].l, r, value, tree) 

def up(node, tree) : 
    if tree[node].f == -1 : 
        return 0 
    else :
        if tree[node].value  != 0  : 
            return tree[node].value
        else :
            return up(F(node), tree) 


