def z_function(s):
    """Compute the Z-array for the given string."""
    n = len(s)
    Z = [0] * n
    l, r = 0, 0
    for i in range(1, n):
        if i <= r:
            Z[i] = min(r - i + 1, Z[i - l])
        while i + Z[i] < n and s[Z[i]] == s[i + Z[i]]:
            Z[i] += 1
        if i + Z[i] - 1 > r:
            l, r = i, i + Z[i] - 1
    return Z



def find_substring(s):
    z = z_function(s)
    n = len(s)

    # Find maximum length prefix which is also a suffix
    max_len = 0
    for i in range(1, n):
        if i + z[i] == n:
            max_len = max(max_len, z[i])

    # Check if this prefix also exists inside the string
    while max_len > 0:
        if max_len in z[1:-max_len]:
            return s[:max_len]
        max_len -= 1

    return "Just a legend"


