cache = {}

def getPalindrome(value):
    if len(value) ==  1:
        return 1
    else:
        mid = len(value)//2 # always giv integer floor of the result
        prefix = value[:mid]
        sufix = value[-1*mid:]
        reverseSufix = sufix[::-1] # ''.join(reversed(suffix))

        if prefix == reverseSufix:
            return getPalindrome(prefix) + 1
        else:
            return 0

def getSumAllPalindrome(inputStr):
    sum = 0
    for i in range(1, len(inputStr)+1):
        prefixStr = inputStr[:i]
        if cache.get(prefixStr) != None:
            sum = sum + cache.get(prefixStr)
        else:
            result = getPalindrome(prefixStr)
            sum = sum + result 
    return sum

