_key, _red, _left, _right, _p = 0, 1, 2, 3, 4


class RedBlackTree():
    _nil = [None, False, None, None, None]

    def __init__(self):
        self._root = RedBlackTree._nil

    def insert_key(self, key):
        y = self.search(key)
        z = [key, False, None, None, y]
        if y is RedBlackTree._nil:
            self._root = z
        else:
            y[_left if z[_key] < y[_key] else _right] = z
        z[_left] = z[_right] = RedBlackTree._nil
        z[_red] = True
        self._insert_fixup(z)

    def _insert_fixup(self, z):
        while z[_p][_red]:
            if z[_p] is z[_p][_p][_left]:
                y = z[_p][_p][_right]
                if y[_red]:
                    z[_p][_red] = y[_red] = False
                    z[_p][_p][_red] = True
                    z = z[_p][_p]
                else:
                    if z is z[_p][_right]:
                        z = z[_p]
                        self._left_rotate(z)
                    z[_p][_red] = False
                    z[_p][_p][_red] = True
                    self._right_rotate(z[_p][_p])
            else:
                y = z[_p][_p][_left]
                if y[_red]:
                    z[_p][_red] = y[_red] = False
                    z[_p][_p][_red] = True
                    z = z[_p][_p]
                else:
                    if z is z[_p][_left]:
                        z = z[_p]
                        self._right_rotate(z)
                    z[_p][_red] = False
                    z[_p][_p][_red] = True
                    self._left_rotate(z[_p][_p])
        self._root[_red] = False

    def _left_rotate(self, x):
        y = x[_right]
        x[_right] = y[_left]
        if y[_left] is not RedBlackTree._nil:
            y[_left][_p] = x
        y[_p] = x[_p]
        if x[_p] is RedBlackTree._nil:
            self._root = y
        elif x is x[_p][_left]:
            x[_p][_left] = y
        else:
            x[_p][_right] = y
        y[_left] = x
        x[_p] = y

    def _right_rotate(self, y):
        x = y[_left]
        y[_left] = x[_right]
        if x[_right] is not RedBlackTree._nil:
            x[_right][_p] = y
        x[_p] = y[_p]
        if y[_p] is RedBlackTree._nil:
            self._root = x
        elif y is y[_p][_right]:
            y[_p][_right] = x
        else:
            y[_p][_left] = x
        x[_right] = y
        y[_p] = x

    def search(self, key):
        x, g = self._root, RedBlackTree._nil
        while x is not RedBlackTree._nil:
            g, x = x, x[_left if key < x[_key] else _right]
        return g

    def search2(self, key):
        a = b = None
        x = self._root
        while x is not RedBlackTree._nil and key != x[_key]:
            if key < x[_key]:
                a, x = x, x[_left]
            else:
                b, x = x, x[_right]
        if key != x[_key]:
            return a, b


