def binSearch(arr,x):
  l = -1
  r = len(arr)
  mid = 0
  while l < r:
    m = (l+r)//2 
    if 2*arr[m] < x:
      if m == len(arr)-1 or x< 2*arr[m+1]:
        return m
      elif x > 2*arr[m+1]:
        l = m+1
      else:
        return m+1
    elif 2*arr[m] == x:
      return m 
    else: 
      r = m 
  return -1 

def visibleKang(n,arr):
  hid = arr[0:(n//2)]
  max = arr[-1]
  hidden_kang = 1+ binSearch(hid,max)
  return n-(hidden_kang)

