from collections import deque


def dfs(graph, start, visited, node):
    stack = deque()
    stack.append(start)
    while stack:
        v = stack.pop()
        if v in visited:
            continue
        visited.append(v)
        for i in graph[v]:
            if i == node:
                return str(visited[len(visited) - 1]) + ' '
            if i not in visited:
                stack.append(i)


def solve(nodes, r1, r2, n):
    graph = {}

    for i in range(1, n + 1):
        graph[i] = set()

    f = 0
    for i, v in enumerate(nodes):
        i += 1
        if r1 == i:
            graph[i + 1].add(v)
            graph[v].add(i + 1)
            f = 1
        else:
            if f:
                graph[i + 1].add(v)
                graph[v].add(i + 1)
            else:
                graph[i].add(v)
                graph[v].add(i)

    ans = ''
    for i in range(1, n + 1):
        if i == r2:
            continue
        ans += dfs(graph, r2, [], i)

    print(str(ans).replace(',', '').replace('[', '').replace(']', ''))


