from sys import stdout


class Bracket:
    def __init__(self, left=0, right=0, complete=0):
        self.left = left
        self.right = right
        self.complete = complete
    __slots__ = ['left', 'right', 'complete']

    @classmethod
    def merge(cls, b1, b2):
        c = min(b1.left,  b2.right)
        left = b1.left - c  + b2.left
        right = b1.right - c + b2.right
        complete = b1.complete + b2.complete + c 
        return cls(left, right, complete)

    def __repr__(self):
        return f"B({self.left},{self.right},{self.complete})"


class Seg_Tree:

    def __init__(self, arr, fun, sentinel):
        self.fun = fun
        self.sentinel = sentinel
        self.n = 1 << (len(arr)).bit_length()
        tree = [Bracket() for i in range(self.n*2)]
        self.tree = tree
        for i, v in enumerate(arr):
            if v == "(":
                tree[i+self.n-1].left = 1
            else:
                tree[i+self.n-1].right = 1
        for i in range(self.n-2, -1, -1):
            tree[i] = fun(tree[i*2+1], tree[i*2+2])
    __slots__ = ['fun', 'n', 'tree', 'sentinel']

    def query(self, qlow, qhigh):
        left, right = self.n + qlow - 1, self.n + qhigh 
        res_l = Bracket()
        res_r = Bracket()

        while left < right:
            # If r is a left child of P, then include it
            if right & 1:
                # print(f"Right {right-2}, {self.tree[right-2]} {res_r}")
                right = right - 1
                res_r = self.fun(self.tree[right-1], res_r)
            # If l is a right child of P, then include it
            if left & 1:
                # print(f"Left {left-1}, {res_l} {self.tree[left-1]}")
                res_l = self.fun(res_l, self.tree[left-1])
                left += 1
            left =  left  >> 1
            right = right >> 1

        return self.fun(res_l, res_r)


