import fileinput

def abc(args):
	
	a,b = 0, len(args) - 1
	suma, sumb = 0, 0
	num_a, num_b = 0, 0
	while a <= b:
		while suma <= sumb:
			suma = suma + args[a]
			a += 1
			num_a += 1
		while sumb < suma:
			sumb = sumb + args[b]
			b -= 1
			num_b += 1
	return str(num_a) + " " + str(num_b)

