from math import gcd

def extended_euclid(a,b,c):
    if b==0:
        return (1,0)
    x1,y1=extended_euclid(b,a%b,c)
    return ((y1, x1-(a//b)*y1))

def diophantine_using_euclid(a,b,c):
    g=gcd(a,b)
    if c%g!=0:
        return -1
    xg,yg=extended_euclid(a,b,g)
    
    return ((c//g)*xg,(c//g)*yg)

def num_sol_in_range(a,b,c,xmin,ymin,xmax,ymax):
    g=gcd(a,b)
    if c%g!=0:
        return 0
    x,y=diophantine_using_euclid(a,b,c)
    # print(a,b,c,g,x,y)
    sm=c
    
    c=b//g
    if x<xmin:
          xmn=x+c*((xmin-x)//c)
          if xmn<xmin:
              xmn+=c
    else:
        xmn=x-c*((x-xmin)//c)
        
    # print(xmn)
        
    if x>xmax:
        xmx=x-c*((xmax-x)//c)
        if xmx>xmax:
            xmx-=c
    else:
        xmx=x+c*((xmax-x)//c)
    
    # print(xmx)
    c=a//g
    
    if y<ymin:
          ymn=y+c*((ymin-y)//c)
          if ymn<ymin:
              ymn+=c
    else:
