import random

def is_prime(n, k=5):
    if n <= 1:
        return False
    if n <= 3:
        return True

    def witness(a, n):
        t = n - 1
        s = 0
        while t % 2 == 0:
            t //= 2
            s += 1

        x = pow(a, t, n)
        if x == 1 or x == n - 1:
            return True

        for _ in range(s - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                return True

        return False

    for _ in range(k):
        a = random.randint(2, n - 2)
        if not witness(a, n):
            return False

    return True

