from bisect import bisect
def move_generator(P):
  for i,p in enumerate(P):
    for j in range(p.bit_length()):
      q = (p & ((1 << j) - 1)) | (p >> (j+1))
      k = bisect(P,q)
      if q == 0:
        yield P[:i]+P[i+1:]
      if k < i:
        yield (*P[:k],q,*P[k:i],*P[i+1:])
      elif k == i:
        yield (*P[:i],q,*P[i+1:])
      else:
        yield (*P[:i],*P[i+1:k],q,*P[k:])

def helper(L):
  memo = {tuple():False}
  def rec(P):
    try:
      return memo[P]
    except KeyError:
      return not all(rec(Q) for Q in move_generator(P))
  return rec(L)

