VOWELS = "aeiou"
CONSONANT_EXCEPTION = "n"

def is_vowel(char):
    return char in VOWELS

def is_consonant(char):
    return not(is_vowel(char))

def is_berlanese(word):
    not_alphabets = not(word.isalpha())
    empty_word = len(word) < 0
    
    if(not_alphabets or empty_word):
        return False
    
    prev_char = word[0]
    last_char = word[-1]
    it_ends_with_consonant = is_consonant(last_char)
    
    if(it_ends_with_consonant and last_char != CONSONANT_EXCEPTION):
        return False
        
    for char in word[1:]:
        if(is_consonant(prev_char) and is_consonant(char) and prev_char != "n" and char != "n"):
            return False
        
        prev_char = char
    
    return True

