import math

# Function to check if a number is prime
def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

# Function to precompute prime numbers up to the square root of 10^12
def sieve(n):
    primes = [i for i in range(2, n + 1) if is_prime(i)]
    return set(primes)

# Precompute prime numbers
primes = sieve(int(math.sqrt(10**12)))

# Read input
n = int(input())
numbers = list(map(int, input().split()))

# Check if each number is T-prime
for num in numbers:
    root = int(math.sqrt(num))
    
    if num in primes and root * root == num:
        print("YES")
    else:
        print("NO")

