def gcd(x, y):
    if x > y:
        x, y = y, x
    if y % x == 0:
        return x
    return gcd(x, y % x)

def _lcm(x, y):
    return x * y // gcd(x, y)

def init():
    global dp, book
    num = 0
    for i in range(1, MOD + 1):
        if MOD % i == 0:
            num += 1
            book[i] = num

def dfs(pos, he, lcm, sp):
    global dp, shu, book
    if pos == -1:
        return he % lcm == 0
    if not sp and dp[pos][he][book[lcm]] != -1:
        return dp[pos][he][book[lcm]]
    ans = 0
    MAX = shu[pos] if sp else 9
    for i in range(MAX + 1):
        next_he = (he * 10 + i) % MOD
        next_lcm = lcm
        if i != 0:
            next_lcm = _lcm(next_lcm, i)
        ans += dfs(pos - 1, next_he, next_lcm, sp and i == MAX)
    if not sp:
        dp[pos][he][book[lcm]] = ans
    return ans

