def mergesort_logic(arr, l_child, r_child):
    arr_itr = 0
    lchild_itr = 0
    rchild_itr = 0

    while (lchild_itr < len(l_child)) & (rchild_itr < len(r_child)):
        if l_child[lchild_itr] < r_child[rchild_itr]:
            arr[arr_itr] = l_child[lchild_itr]
            lchild_itr += 1
            arr_itr += 1
        else:
            arr[arr_itr] = r_child[rchild_itr]
            rchild_itr += 1
            arr_itr += 1
    if lchild_itr >= rchild_itr:
        while arr_itr < len(arr):
            arr[arr_itr] = r_child[rchild_itr]
            arr_itr += 1
            rchild_itr += 1
    else:
        while arr_itr < len(arr):
            arr[arr_itr] = l_child[lchild_itr]
            arr_itr += 1
            lchild_itr += 1
    return(arr)

