def sum(BIT, i):
    s = 0
    while i > 0:
        s += BIT[i]
        i -= i & (-i)
    return s


def update(BIT, i, v):
    while i < len(BIT):
        BIT[i] += v

        i += i & (-i)


def find(fen, k):
    curr = 0
    ans = 0
    prevsum = 0
    for i in range(19, -1, -1):
        if ((curr + (1 << i) < n) and fen[curr + (1 << i)] + prevsum < k):
            ans = curr + (1 << i)
            curr = ans
            prevsum += fen[curr]
    return ans + 1

