from collections import defaultdict
class Graph():
    def __init__(self, vertexCount):
        self.graph = defaultdict(defaultdict)
        self.vertexCount = vertexCount + 1

    def addEdgeBidirectional(self, u, v, distance):
        self.graph[u][v] = distance
        self.graph[v][u] = distance

    def Dijkstra(self, startNode, finalNode):
        minDistance = defaultdict(lambda: 1e7)
        prev = defaultdict(lambda: None)
        unvisitedNodes = set()

        for item in self.graph.keys():
            unvisitedNodes.add(item)

        minDistance[startNode] = 0
        unvisitedNodes.remove(startNode)
        currentNode = startNode
        while unvisitedNodes:
            currentMin = 1e7
            for node in unvisitedNodes:
                if minDistance[node] == 0:
                    continue
                if minDistance[node] < currentMin:
                    currentNode = node
                    currentMin = minDistance[node]

            if currentNode in unvisitedNodes:
                unvisitedNodes.remove(currentNode)

            for neighbor in self.graph[currentNode].keys():
                if neighbor not in unvisitedNodes:
                    continue
                else:
                    altDistance = minDistance[currentNode] + self.graph[currentNode][neighbor]
                    if altDistance < minDistance[neighbor]:
                        minDistance[neighbor] = altDistance
                        prev[neighbor] = currentNode

        if minDistance[finalNode] == 1e7:
            print(-1)
        else:
            outputList = []
            currentTest = finalNode

            while currentTest != startNode:
                outputList.append(currentTest)
                currentTest = prev[currentTest]
            outputList.append(currentTest)
            print(*reversed(outputList))

