import math

def point_in_polygon(x, y, P):
    n = len(P)
    intersections = []
    for i in range(n):
        x1, y1 = P[i]
        if i < n-1:
            x2, y2 = P[i+1]
        else:
            x2, y2 = P[0]
        if x1==x2:
            if x1 >= x:
                intersections.append((x1, y))
        else:
            slope = (y2-y1)/(x2-x1)
            if slope != 0:
                intercept = y1-slope*x1
                y_int = y
                x_int = (y_int-intercept)//slope
                if min(x1, x2) <= x_int <= max(x1, x2) and min(y1, y2) <= y_int <= max(y1, y2):
                    if x <= x_int:
                        intersections.append((x_int, y_int))
            else:
                if y==y1:
                    if min(x1, x2) >= x:
                        intersections.append((x1, y))
                    if max(x1, x2) >= x:
                        intersections.append((x2, y))
    return len(intersections) % 2==1
            
              
