def find_maxes(A):
    n = len(A)
    d1 = float('inf')
    d2 = -1*float('inf')
    for i in range(n):
        x1, y1 = A[i]
        d1 = min(d1, x1**2+y1**2)
        d2 = max(d2, x1**2+y1**2)
        if i < n-1:
            x2, y2 = A[i+1]
        else:
            x2, y2 = A[0]
        if x1==x2:
            if min(y1, y2) <= 0 <= max(y1, y2):
                d1 = min(d1, x1)
                d2 = max(d2, x2)
        else:
            slope = (y2-y1)/(x2-x1)
            intercept = y1-slope*x1
            x3 = -1*slope*intercept/(slope**2+1)
            y3 = slope*x3+intercept
            if min(x1, x2) <= x3 <= max(x1, x2):
                d3 = x3**2+y3**2
                d1 = min(d1, d3)
                d2 = max(d2, d3)
    return [d1, d2]
            

def process(p1, p2, A):
    A = [[x-p1, y-p2] for x, y in A]
    min_dist, max_dist = find_maxes(A)
    if point_in_polygon(0, 0, A):
        min_dist = 0
    answer = math.pi*max_dist-math.pi*min_dist
    return answer


