class myStack:
    def __init__(self, content = None):
        if(content == None):
            self.arr = []
        else:
            self.arr = list(content)
    def __len__(self):
        return len(self.arr)
    def back(self):
        return self.arr[-1]
    def pop(self):
        self.arr.pop(-1)
    def push_back(self, value):
        return self.arr.append(value)
    def clear(self):
        while(len(self)):
            self.pop()
    def __repr__(self):
        return "Stack ({})".format(self.arr)

