def is_palindrome(num):

    copia = num
    if num < 10:
        return True

    nums = []
    while(True):
        nums.append(copia % 10)
        copia //= 10

        if copia == 0:
            break

    digitos = len(nums) // 2
    j = len(nums) - 1
    for i in range(digitos):
        if nums[i] != nums[j]:
            return False
        j -= 1

    return True

def primes(x):

    primes = [True] * x
    primes[0] = False
    i = 1

    while(i * i < x):
        if primes[i] == True:

            for j in range(i + (i + 1), x, i + 1):
                primes[j] = False
        i += 1

    return primes

