	for level in range(numFloors - 1, -1, -1):
		levelTokens = input()
		if "1" not in levelTokens:
			empty[level] = True
			continue
		l = 0
		while (int(levelTokens[l]) != 1):
			l = l + 1
		leftmost[level] = l
		r = numRooms + 1
		while (int(levelTokens[r]) != 1):
			r = r - 1
		rightmost[level] = r

