	pq = PriorityQueue()
	pq.put(leftmost[0], leftmost[0])
	current = pq.get()
	while ((current[1] != topNonEmptyFloor*(numRooms + 2) + leftmost[topNonEmptyFloor]) and (current[1] != topNonEmptyFloor*(numRooms + 2) + rightmost[topNonEmptyFloor])):
		floor = int(current[1] / (numRooms + 2))
		position = current[1] % (numRooms + 2)
		time = current[0]
		if (not empty[floor]):
			time = time + rightmost[floor] - leftmost[floor]
			position = rightmost[floor]
		pq.put((floor + 1)*(numRooms + 2) + leftmost[floor + 1], time + leftmost[floor + 1] + position + 1)
		pq.put((floor + 1)*(numRooms + 2) + rightmost[floor + 1], time + numRooms + 1 - rightmost[floor + 1] + numRooms + 2 - position)
		current = pq.get()

	print(current[0] + rightmost[topNonEmptyFloor] - leftmost[topNonEmptyFloor])

