def inp():
  n, m = input().split()
  grid = []
  for _ in range(eval(n)):
    row = input()
    grid.append(row)
  
  solution(grid)

def solution(grid):
  parent = {(i, j): (i, j) for j in range(len(grid[0])) for i in range(len(grid))}
  rank = {(i, j): (1 if grid[i][j] == "." else 0) for j in range(len(grid[0])) for i in range(len(grid))}
  inBounds = lambda i, j: 0 <= i < len(grid) and 0 <= j < len(grid[0])
  
  dirs = [[0, 1], [0, -1], [1, 0], [-1, 0]]
  def find(node):
    i, j = node
    if (i, j) == parent[(i, j)]:
      return parent[(i, j)]
    
    parent[(i, j)] = find(parent[(i, j)])
    return parent[(i, j)]
  
  def unite(a, b):
    pa = find(a)
    pb = find(b)
    
    if pa != pb:
      if rank[pa] >= rank[pb]:
        parent[pb] = pa
        rank[pa] += rank[pb]
        rank[pb] = 0
      else:
        parent[pa] = pb
        rank[pb] += rank[pa]
        rank[pa] = 0
  
  for i in range(len(grid)):
    for j in range(len(grid[0])):
      if grid[i][j] == ".":
        for x, y in dirs:
          new_i, new_j = i + x, j + y
          if inBounds(new_i, new_j) and grid[new_i][new_j] == ".":
            unite([i, j], [new_i, new_j])
  
  ans = [['.' for j in range(len(grid[0]))] for i in range(len(grid))]
  for i in range(len(grid)):
    for j in range(len(grid[0])):
      used = set()
      if grid[i][j] == "*":
        curr = 0
        for x, y in dirs:
          new_i, new_j = x + i, y + j
          if inBounds(new_i, new_j) and parent[(new_i, new_j)] not in used:
            curr += rank[parent[new_i, new_j]]
            used.add(parent[(new_i, new_j)])
        ans[i][j] = str(1 + curr)
    print("".join(ans[i]))
    
  # return ans
  
