def isPalind(inp):
    left, right = 0, len(inp) - 1
    while left < right:
        if inp[left] == inp[right]:
            left += 1
            right -= 1
        else:
            return False
    return True

def helper(inp, memo):
    # print(inp)
    if len(inp) == 0:
        return 0
    if len(inp) == 1:
        return 1
    if inp in memo:
        return memo[inp]
    if isPalind(inp) == False:
        memo[inp] = 0
        return 0
    prefix = inp[0:len(inp)//2]
    suffix = inp[-(len(inp)//2):]
    k1 = helper(prefix, memo)
    k2 = helper(suffix, memo)
    k = 0
    if k1 == k2:
        k = k1 + 1
    memo[inp] = k
    return k

