from collections import deque


def shortest_path(adj, n, edgemap):
    que, pathlength = deque([1]), [-1] * (n + 1)
    pathlength[1] = 0
    pathroot = [-1] * (n + 1)
    pathroot[1] = -1
    while que:
        v = que.popleft()
        for u in adj[v]:
            if pathlength[u] == -1:
                que.append(u)
                pathroot[u] = v
                pathlength[u] = pathlength[v] + \
                    (edgemap[(v, u)] if (v, u) in edgemap else edgemap[(u, v)])
            else:
                pl = pathlength[v] + (edgemap[(v, u)] if (v, u) in edgemap else edgemap[(u, v)])
                if pathlength[u] > pl:
                    pathroot[u] = v
                    pathlength[u] = pl
    return pathroot

