                    if i*j in non_prime:
                        pass
                    else:
                        non_prime.append(i*j)
        else:
            prime.append(i)
            for j in prime:
                if i*j>x:
                    break
                else:
                    if i*j in non_prime:
                        pass
                    else:
                        non_prime.append(i*j)
    return prime

