from collections import defaultdict
class graph():
    def __init__(self):
        self.dict=defaultdict(str)
    def add_edge(self,node1,node2,weight):
        if node1 in self.dict.keys():
            try :
                assert node2 in self.dict.keys()
                self.dict[node1].append((node2,weight))
                self.dict[node2].append((node1,weight))

            except AssertionError:
                print("second node not defined")
    def add_node(self,node):
        self.dict[node]=[]
    def remove_edge(self,node1,node2):
        i=-1
        if node1 in self.dict.keys():
            for j,(v,w) in enumerate(zip(len(self.dict[node1]),self.dict[node1])):
                if v==node2:
                    i=0
            if i>=0:
                self.dict[node1].pop(i)
        i=-1
        if node2 in self.dict.keys():
            for j,(v,w) in enumerate(zip(len(self.dict[node2]),self.dict[node2])):
                if v==node1:
                    i=0
            if i>=0:
                self.dict[node1].pop(i)
    def Dijkstra(self,source):
        distances={}
        prev={}
        for v in self.dict.keys():
            distances[v]=float("inf")
            prev[v]=None
        distances[source]=0
        unexplored=[source]
        explored=[]
        while unexplored!=[]:
            v=unexplored.pop(0)
            explored.append(v)
            for (u,w) in self.dict[v]:
                if distances[v]+w<distances[u]:
                    distances[u]=distances[v]+w
                    prev[u]=v
                    if explored.count(u)==0:
                        unexplored.append(u)
        return(prev,distances)
    def chemin_dijkstra(self,source,goal):
        prev,distances=self.Dijkstra(source)
        chemin=[goal]
        v=goal
        test=True
        while v!=source:
            if prev[v]!=None:
                chemin=[prev[v]]+chemin
                v=prev[v]
            else:
                test=False
                break
        if test==False:
            return(str(-1))
        else:

            ch=""
            for vertex in chemin :
                ch=ch+vertex+" "
            return(ch[:-1])



