#埃氏筛算法生成范围内所有素数
def sushu(n):
    primes=[True]*(n+1)
    primes[0]=primes[1]=False
    x=2
    while x*x<=n:
        if primes[x]:
            for i in range(x*x,n+1,x):
                primes[i]=False
        x+=1
    return primes
