from heapq import *

def dijkstra(g, f, t):
    q, seen = [(0,f,[])], set()
    while q:
        (cost,v1,path) = heappop(q)
        if v1 not in seen:
            seen.add(v1)
            npath  = [x for x in path]
            npath.append(v1)
            if v1 == t: return npath

            for v2 in g[v1].keys():
                if v2 not in seen:
                    heappush(q, (cost+g[v1][v2], v2, npath))

    return float("inf")


