class Solution():
	def get_printable_string(self, ans):
		return "YES" if ans else "NO"

	def solve(self, first, second, third):
		counter = Counter(first + second)
		counter2 = Counter(third)
		count = 0
		ans = True
		for char, value in counter.items():
			try:
				if counter2[char] == value:
					count += 1
				else:
					ans = False
					break
			except KeyError:
				ans = False
				break
		return ans
		# return "YES" if ans else "NO"


class Driver():
	def __init__(self):
		self._solver = Solution()

	def drive(self):
		first = input().strip()
		second = input().strip()
		third = input().strip()
		ans = self._solver.solve(first, second, third)
		print(self._solver.get_printable_string(ans))


