def solve(hh, mm, H, D, C, N):
    current_cost = ((N - 1 + H) // N) * C
    if hh >= 20:
        return current_cost
    minutes_to_discount = 60 - mm + ((20 - 1 - hh) * 60)
    H += (minutes_to_discount * D)
    discounted_cost = ((N - 1 + H) // N) * C * 0.8
    return min(current_cost, discounted_cost)

