class FastIO:
    def __init__(self):
        return

    @staticmethod
    def _read():
        return sys.stdin.readline().strip()

    def read_int(self):
        return int(self._read())

    def read_float(self):
        return float(self._read())

    def read_ints(self):
        return map(int, self._read().split())

    def read_floats(self):
        return map(float, self._read().split())

    def read_ints_minus_one(self):
        return map(lambda x: int(x) - 1, self._read().split())

    def read_list_ints(self):
        return list(map(int, self._read().split()))

    def read_list_floats(self):
        return list(map(float, self._read().split()))

    def read_list_ints_minus_one(self):
        return list(map(lambda x: int(x) - 1, self._read().split()))

    def read_str(self):
        return self._read()

    def read_list_strs(self):
        return self._read().split()

    def read_list_str(self):
        return list(self._read())

    @staticmethod
    def st(x):
        return sys.stdout.write(str(x) + '\n')

    @staticmethod
    def lst(x):
        return sys.stdout.write(" ".join(str(w) for w in x) + '\n')

    @staticmethod
    def round_5(f):
        res = int(f)
        if f - res >= 0.5:
            res += 1
        return res

    @staticmethod
    def max(a, b):
        return a if a > b else b

    @staticmethod
    def min(a, b):
        return a if a < b else b

    @staticmethod
    def bootstrap(f, queue=[]):
        def wrappedfunc(*args, **kwargs):
            if queue:
                return f(*args, **kwargs)
            else:
                to = f(*args, **kwargs)
                while True:
                    if isinstance(to, GeneratorType):
                        queue.append(to)
                        to = next(to)
                    else:
                        queue.pop()
                        if not queue:
                            break
                        to = queue[-1].send(to)
                return to
        return wrappedfunc


def find_floor_point(fun, left, right):
    # 求解下凸函数取得最大值时的点

    error = 1
    while left < right - error:
        diff = (right - left) / 3
        mid1 = left + diff
        mid2 = left + 2 * diff
        dist1 = fun(mid1)
        dist2 = fun(mid2)
        if dist1 < dist2:
            right = mid2
        elif dist1 > dist2:
            left = mid1
        else:
            left = mid1
            right = mid2
    return left


def main(ac=FastIO()):
    n, m = ac.read_ints()
    a = ac.read_list_ints()
    b = ac.read_list_ints()
    floor = min(a)
    ceil = max(b)
    if floor >= ceil:
        ac.st(0)
        return

    def check(x):
        cost = sum(x - num for num in a if num < x)
        cost += sum(num - x for num in b if num > x)
        return cost

    point = int(find_floor_point(check, floor, ceil))

    ans = inf
    for x in [-1, 0, 1]:
        if floor <= point + x <= ceil:
            ans = ac.min(ans, check(point + x))
    ac.st(ans)
    return


