def rainy(S):
    IN = 0
    OUT = 0
    if S[0] == '+':
        IN = 1
    else:
        OUT = 1

    counter = 1
    while counter < len(S):
        if S[counter] == '+':
            IN += 1
            OUT -= 1
        else:
            IN -= 1
            OUT += 1
        counter += 1

    if IN == OUT:
        return 1 * IN

    elif IN > OUT:
        return IN
    else:
        return OUT


