class Node:
    def __init__(self, value: float, parent=None):
        self.left_child: Node = None
        self.right_child: Node = None
        self.parent: Node = parent
        self.value: float = value

    def put(self, value):
        if value == self.value:
            raise Exception('Низя класть в родителя с таким же значением')
        if value < self.value:
            if self.left_child:
                self.left_child.put(value)
            else:
                self.left_child = Node(value, self)
        else:
            if self.right_child:
                self.right_child.put(value)
            else:
                self.right_child = Node(value, self)

    def get(self, value):
        if value < self.value:
            return self.left_child.get(value)
        elif value > self.value:
            return self.right_child.get(value)
        else:
            return self

    def remove(self, value):
        if value < self.value:
            self.left_child.remove(value)
        elif value > self.value:
            self.right_child.remove(value)
        else:
            if not self.left_child and not self.right_child:
                if self.value > self.parent.value:
                    self.parent.right_child = None
                else:
                    self.parent.left_child = None
                self.parent = None
            elif (not self.left_child and self.right_child) or \
                    (self.left_child and not self.right_child):
                if self.value > self.parent.value:
                    if self.left_child:
                        self.parent.right_child = self.left_child
                        self.left_child.parent = self.parent
                    else:
                        self.parent.right_child = self.right_child
                        self.right_child.parent = self.parent
                else:
                    if self.left_child:
                        self.parent.left_child = self.left_child
                        self.left_child.parent = self.parent
                    else:
                        self.parent.left_child = self.right_child
                        self.right_child.parent = self.parent
                self.parent = None
            elif self.left_child and self.right_child:
                new = self.right_child
                while new.left_child:
                    new = new.left_child

                new.parent = self.parent
                new.left_child = self.left_child
                if self.right_child != new:
                    new.right_child = self.right_child
                else:
                    new.right_child = None

                if self.value > self.parent.value:
                    self.parent.right_child = new
                else:
                    self.parent.left_child = new
                self.parent = None

    def getDict(self, c=True):
        retTree = {self.value: {}}
        if self.left_child:
            retTree[self.value][self.left_child.value] = \
                self.left_child.getDict(False)
        if self.right_child:
            retTree[self.value][self.right_child.value] = \
                self.right_child.getDict(False)
        if not c:
            return retTree[self.value]
        if c:
            return retTree


