def isprime(b):
    Min = 2  # 范围最小值
    Max = 10000000  # 范围最大值
    Loop = 0  # 计算循环次数
    Result = []  # 结果
    Natural = [True for P in range(Max)]  # 自然数列表标记为True
    for P in range(2, Max):
        if Natural[P]:  # 标记如果为True，就是质数
            if P >= Min:
                Result.append(P)  # 添加范围之内的质数
