def performOperation(set, target):
    mex = calculateMex(set)
    if mex < target:
        set += [mex]
        return 0
    if mex > target:
        if mex in set:
            set -= [mex]
        else:
            #print(set[-1])
            del set[-1]
        return 0
    return 1

