def cross(m, a, b):
    if len(m) <= a + 1 or a == 0:
        return False
    if len(m[a]) <= b + 1 or b == 0:
        return False

    return m[a][b] == '#' and m[a - 1][b] == '#' and m[a + 1][b] == '#' and m[a][b - 1] == '#' and m[a][b + 1] == '#'

def emptyCross(m, a, b):
    m[a][b] = '.'
    m[a - 1][b] = '.'
    m[a + 1][b] = '.'
    m[a][b - 1] = '.'
    m[a][b + 1] = '.'

