import sys


class Elem:
    def __init__(self, value, n_open, n_close, l, r):
        self.value = value
        self.o = n_open
        self.c = n_close
        self.l = l
        self.r = r

    def __str__(self):
        return str(self.value) + " " + str(self.l) + " " + str(self.r)


def construct(s):
    n = 1
    h = 1
    while n < len(s):
        n *= 2
        h += 1
    n *= 2

    tree = [None for _ in range(n)]
    pointer = len(s) - 1

    for i in range(n - 1, -1, -1):
        if i * 2 + 2 < n:
            tmp = min(tree[2 * i + 1].o, tree[2 * i + 2].c)
            tree[i] = Elem(tree[2 * i + 1].value + tree[2 * i + 2].value + tmp,
                           tree[2 * i + 1].o + tree[2 * i + 2].o - tmp,
                           tree[2 * i + 1].c + tree[2 * i + 2].c - tmp,
                           tree[2 * i + 1].l, tree[2 * i + 2].r
                           )
        elif n - 1 - i > 2 ** (h - 1) - len(s):
            if s[pointer] == '(':
                tree[i] = Elem(0, 1, 0, i - 2 ** (h - 1) + 1, i + 1 - 2 ** (h - 1))
            else:
                tree[i] = Elem(0, 0, 1, i - 2 ** (h - 1) + 1, i + 1 - 2 ** (h - 1))
            pointer -= 1
        else:
            tree[i] = Elem(0, 0, 0, i - 2 ** (h - 1) + 1, i + 1 - 2 ** (h - 1))

    return tree, h - 1


def query(tree, p, l, r):
    if tree[p].l == l and tree[p].r == r:
        return tree[p]
    if tree[p * 2 + 1].r >= r:
        return query(tree, p * 2 + 1, l, r)
    elif tree[p * 2 + 2].l <= l:
        return query(tree, p * 2 + 2, l, r)

    left = query(tree, p * 2 + 1, l, tree[p * 2 + 1].r)
    right = query(tree, p * 2 + 2, tree[p * 2 + 2].l, r)

    return Elem(left.value + right.value + min(left.o, right.c), left.o + right.o - min(left.o, right.c),
                left.c + right.c - min(left.o, right.c), tree[p].l, tree[p].r)


if __name__ == '__main__':
    s = sys.stdin.readline().strip()
    tree, h = construct(s)
    n = int(sys.stdin.readline())
    for _ in range(n):
        l, r = [int(x) for x in sys.stdin.readline().split()]
        sys.stdout.write(str(2 * query(tree, 0, l - 1, r - 1).value) + "\n")
        sys.stdout.flush()

