def select(num, char_code = ord('a'), indices_to_remove = []):
  # is the letter we are observing is 'more' than 'z'
  if char_code > ord('z'):
    return indices_to_remove

  letter = chr(char_code)

  # if the letter is not there in the dict
  if not letter_dict.get(letter):
    return select(num, char_code + 1, indices_to_remove)
  
  letter_count = len(letter_dict[letter])
  if (num < letter_count):
    indices_to_remove += letter_dict[letter][:num]
    return indices_to_remove;
  else:
    new_num = num - letter_count
    next_char_code = char_code + 1
    new_indices = indices_to_remove + letter_dict[letter]
    return select(new_num, next_char_code, new_indices)

