from copy import copy
from itertools import chain
from bisect import bisect_left as lower_bound, bisect_right as upper_bound, \
                   insort


def readline(): return map(int, input().split())


def readlines(count): return (readline() for __ in range(count))


class Slots(object):
    def __init__(self, **kwargs):
        for (key, value) in kwargs.items():
            setattr(self, key, value)

    def __iter__(self):
        for slot in self.__slots__:
            yield slot, copy(getattr(self, slot))

    def __eq__(self, other):
        return all(getattr(self, slot) == getattr(other, slot)
                   for slot in self.__slots__)

    def __repr__(self):
        return f"{self.__class__.__name__}(" \
               + ", ".join(f"{k}={v}" for (k, v) in self) + ")"

    def copy(self):
        return self.__class__(**dict(self))


class Position(Slots):
    __slots__ = 'floor payload time'.split()

    def is_not_full(self):
        return len(self.payload) < 4

    def take(self, b):
        insort(self.payload, b)
        return self

    def free(self, x, y):
        lo = lower_bound(self.payload, min(x, y))
        up = upper_bound(self.payload, max(x, y))
        del self.payload[lo:up]
        return self

    def hook(self, pivot, finish):
        self.time += abs(self.floor - pivot) + abs(pivot - finish)
        self.floor = finish
        self.free(*sorted([pivot, finish]))
        return self

    def possibilities_to_take_next(self, a, b):
        pivots = self.payload[upper_bound(self.payload, self.floor):] \
                 if a <= self.floor else \
                 self.payload[:lower_bound(self.payload, self.floor)]
        pivots.append(self.floor)

        for pivot in pivots:
            possibility = self.copy().hook(pivot, a)
            if possibility.is_not_full():
                yield possibility.take(b)

    def get_free(self):
        if self.payload:
            lo, up = self.payload[0], self.payload[-1]
            if self.floor <= (lo + up) // 2:
                self.hook(lo, up)
            else:
                self.hook(up, lo)
            assert not self.payload
        return self


assert Position(floor=2, payload=[1, 2, 3, 3, 4, 5, 5, 6, 7], time=3)\
