def solve():
    def rotate(x, y):
        for i in range(4):
            x[i], y[i] = x[i] + y[i], x[i] - y[i]
        return x, y

    def read(p1, p2):
        xp = [p1[i] for i in range(0, 8, 2)]
        yp = [p1[i] for i in range(1, 8, 2)]
        xr = [p2[i] for i in range(0, 8, 2)]
        yr = [p2[i] for i in range(1, 8, 2)]
        return xp, yp, xr, yr

    p1 = list(map(int, input().split()))
    p2 = list(map(int, input().split()))
    xp, yp, xr, yr = read(p1, p2)

    xr_min, xr_max, yr_min, yr_max = min(xr), max(xr), min(yr), max(yr)
    xp_min, xp_max, yp_min, yp_max = min(xp), max(xp), min(yp), max(yp)

    inside = (xr_min > xp_min) and (xr_max < xp_max) and (yr_max < yp_max) and (yr_min > yp_min)
    if inside:
        print("YES")
        return

    touching = False

    for i in range(2):
        xp_min, xp_max, yp_min, yp_max = min(xp), max(xp), min(yp), max(yp)
        for side_r in range(4):
            if (xp_min <= xr[side_r] <= xp_max) and (yp_min <= yr[side_r] <= yp_max):
                touching = True
        xp, yp = rotate(xp, yp)
        xr, yr = rotate(xr, yr)
        xr, yr, xp, yp = xp, yp, xr, yr

    if touching:
        print("YES")
    else:
        print("NO")


