    for i in range(2, int(a**(1/2)) + 1):
        if a % i == 0:
            return False
    return True

def razl(a):
    res = []
    for i in range(2, int(a**(1/2)) + 1):
        while a % i == 0:
            res.append(i)
            a //= i
    if a != 1:
        res.append(a)
    return res

