def check(d, a, b, x, y, mx):
    d2 = defaultdict(int)
    d2[0] = 1
    for i in range(1, mx + 1):
        rt = max(i - 1 - max(i - (b - y), 0) - max(i - x - 1, 0), 0)
        lt = max(i - 1 - max(i - y - 1, 0) - max(i - x - 1, 0), 0)
        lb = max(i - 1 - max(i - y - 1, 0) - max(i - (a - x), 0), 0)
        rb = max(i - 1 - max(i - (b - y), 0) - max(i - (a - x), 0), 0)
        t = 1 if x >= i else 0
        l = 1 if y >= i else 0
        r = 1 if b - y > i else 0
        bot = 1 if a - x > i else 0
        t = rt + lt + rb + lb + t + r + l + bot
        if t > 0:
            d2[i] += t
    return d == d2


def solve(n, arr):
    d = defaultdict(int)
    mx = 0
    for x in arr:
        d[x] += 1
        mx = max(mx, x)

    i = 1
    sh1, sh2 = None, None
    while sh1 is None:
        dd = d.get(i, 0)
        if dd < 4 * i:
            sh1 = i
            if 4 * i - dd > 1:
                sh2 = i
        i += 1
    while sh2 is None:
        if d.get(i, 0) < 4 * i - 2 * (i - sh1) - 1:
            sh2 = i
        i += 1

    sq = int(sqrt(n))
    for i in range(1, sq + 1):
        if n % i:
            continue

        if sh1 + sh2 - 1 == i:
            a = i
            b = n // i
            x = sh1 - 1
            y = mx - (sh2 - 1)
            if check(d, a, b, x, y, mx):
                return a, b, x, y
        else:
            if mx == i + n // i - sh1 - sh2:
                if check(d, i, n // i, sh1 - 1, sh2 - 1, mx):
                    return i, n // i, sh1 - 1, sh2 - 1
                if check(d, i, n // i, sh2 - 1, sh1 - 1, mx):
                    return i, n // i, sh2 - 1, sh1 - 1
    return None, None, None, None


