def do_dfs(n, graph, mask):
	time = 0
	d = [0]*(n+1)
	f = [0]*(n+1)
	c = {}
	for u in graph.keys():
		if not u in mask.keys():
			c = {}
			b,c,v = dfs(u,graph,mask,time,d,f,c)
			if b:
				return (0, c, v)
	return (1, c, u)


def dfs(u, graph, mask, time, d, f, c):
	time += 1
	d[u] = time
	mask[u] = True
	for v in graph[u]:
		if d[v] < d[u] < f[u] < f[v]:
			c[v] = -1
			return (1, c, u)
		if not v in mask.keys():
			c[v] = u
			if dfs(v,graph,mask,time,d,f,c):
				return (1,c, u)
	time += 1
	f[u] = time
	return (0,c,u)

