def find(l,x):
    n = len(l)
    start = 0
    end = n-1
    if l[end] <= x:
        return end+1
    if l[start] > x:
        return start
    while end-start > 1:
        mid = (start+end)//2
        if l[mid+1] > x and l[mid] <= x:
            return mid+1
        if l[mid+1] < x:
            start = mid
            continue
        if l[mid+1] > x and l[mid] > x:
            end = mid
            continue
    if end-start == 1:
        if l[end] > x and l[start] <= x:
            return end
        if l[start] > x and l[start-1] <= x:
            return start

