def gd(f,l):
	"""get delta"""
	return 2*int(l>f)-1

def fe(v,zf,zl,xf,xl,iv):#iv is vertical
	"""find edge"""
	dz=gd(zf,zl)
	dx=gd(xf,xl)
	for c in range(zf,zl,dz):
		for d in range(xf,xl,dx):
			t=v[c][d] if iv else v[d][c]
			if t==bl:
				return c
				
def cir(v,t,b,l,r):
	"""count of white cell in region"""
	s=0
	for c in range(t,b+1):
		for d in range(l,r+1):
			if v[c][d]==wt:
				s+=1
	return s
	
def pes(v,h,w,t,b,l,r):
	"""possible extention square"""
	lw,lh=r-l+1,b-t+1
	ld,lm=abs(lw-lh),max(lw,lh)
	ps=lm*ld
	if lw<lh:
		pf,pl,pm=l-ld,r+ld,w
	elif lw>lh:
		pf,pl,pm=t-ld,b+ld,h
	else:
		return 0
	if pf>=0 or pl<pm:
			return ps
	return -1

def ge(v,h,w):
	"""get edges"""
	t=fe(v,0,h,0,w,1)
	b=fe(v,h-1,-1,0,w,1)
	l=fe(v,0,w,0,h,0)
	r=fe(v,w-1,-1,0,h,0)
	#print('top={} bottom={} left={} right={}'.format(t,b,l,r))
	return t,b,l,r
	
def wp(v,h,w):
	"""get count of white cell for paint"""
	t,b,l,r=ge(v,h,w)
	if t==None:
		return 1
	si=cir(v,t,b,l,r)
	so=pes(v,h,w,t,b,l,r)
	if so<0:
		return -1
	return si+so
	
