class Size:
	def __init__(self, width, height):
		self.width = width;
		self.height = height;

def set_size():
	param = input().split(' ')
	width = int(param[0])
	height = int(param[1])
	if (1 <= width <= 10) and (1 <= height <= 1000):
		return Size(width, height)
	else:
		return None
	
def algorithm():
	try:	
		count = int(input())
		if not (2 <= count <= 200000):
			return None
		peoples = [set_size() for i in range(0, count)]
		result = ''
		for i in range(0, count): # Номер фотографии
			photo = Size(0, 0)
			for j in range(0, count): # Номер человека
				if peoples[j] == None: return None
				if i == j: continue
				photo.width += peoples[j].width
				if peoples[j].height > photo.height:
					photo.height = peoples[j].height
			result += str(photo.width * photo.height)
			if i < count - 1: result += ' '
		print(result)
	except BaseException:
		return None
		
algorithm()

