def solve(arr):
    @lru_cache(None)
    def dp(prev,i):
        if i == len(arr):
            return 0
        if arr[i] == 0:
            return 1 + dp(0,i + 1)
        if arr[i] == 1:
            # Can only do contest
            if prev == 1:
                return 1 + dp(0,i + 1)
            else:
                return dp(1,i + 1)
        if arr[i] == 2:
            # Can only do gym
            if prev == -1:
                return 1 + dp(0,i + 1)
            return dp(-1, i + 1)
        if arr[i] == 3:
            if prev == 0:
                return max(dp(-1,i + 1),dp(1,i + 1))
            elif prev == 1:
                return dp(-1,i + 1)
            elif prev == -1:
                return dp(1,i + 1)
    return dp(0,0)
            
        
        
