def weights(nElements, nQueries):
    def bounds():
        l, u = map(int, input().split())
        return l - 1, u

    ranges = tuple(bounds() for _ in range(nQueries))

    def isInRange(i, j):
        return ranges[j][0] <= i < ranges[j][1]

    w = sorted((sum(isInRange(i, j)
             for j in range(nQueries))
         for i in range(nElements)), reverse=True)

    i = nElements - 1
    while i != -1:
        if w[i] != 0:
            return w[:i+1]
        i -= 1

    return 0


