def binary_search(key, array):
    """
    w/o proximity,
    return -1 if not found
    """
    mid = floor((len(array) - 1) / 2)
 
    if len(array) <= 0:
        return -1
    
    if array[mid] == key:
        return mid
    
    if array[mid] > key:
        return binary_search(key, array[:mid])
    
    if array[mid] < key:
        return binary_search(key, array[mid + 1:])

def proximity_sort(target, array):
    return sorted(array, key = lambda x: abs(x - target))

