def game(arr):
    ans=0
    s=arr.index(min(arr))
    while arr.count(0)!=len(arr):
        ans+=1
        for i in range(len(arr)):
            if i!=s:
                arr[i]-=1
                if arr[i]<0:
                    arr[i]=0
        s=arr.index(min(arr))
        if arr[s]==0:
            return ans+max(arr)
    return ans

