def count_digits(number):
    dig = [0] * 10
    for d in map(int, str(number)):
        dig[d] += 1
    return dig

def has_enough(digits, dig):
    for a, b in zip(dig, digits):
        if a > b:
            return False
    return True

def solution(cubes):
    digits = [0] * 10
    for c in cubes:
        for d in c:
            digits[d] += 1

    for a in range(1000):
        dig = count_digits(a)
        if not has_enough(digits, dig):
            return a - 1
    return -1

