def extendPrimes(a):
    p = primes[-1]
    while primes[-1] <= a:
        newp = p+2
        flag = False
        sqnp = ceil(sqrt(newp))
        for prime in primes:
            if prime<= sqnp and newp%prime == 0:
                flag = True
                break
        p = newp
        if not flag: primes.append(p)
        
def isPrime(a):
    if a<primes[-1]: extendPrimes(a)
    if a in primes: return True
    return False

