from math import ceil

def get_arithm_term(a:int, n:int, d:int):
    return int(a+(n-1)*d)

def find_term_position(x:int, a:int, d:int):
    return ceil((x-a)/d +1)


def main():
    'given a value x I want to find the 1st term in an arithmetic sequence that is >= to x'
    x = I()
    y = 0
    for i in range(x):
        a, d = IA()
        if i==0:
            y = a
        else:
            pos = find_term_position(y, a, d)
            term = get_arithm_term(a, pos, d)
            if term == y:
                term = get_arithm_term(a, pos+1, d)
            y = term 
        # print(y)
    
    return y
    

