    print(main())

import math

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def count_primer(a):
    count = 0
    for i in range(2, a + 1):
        divisors = 0
        for j in range(2, i):
            if is_prime(j) and i % j == 0:
                divisors += 1
        if divisors == 2:
            count += 1
    return count

