def binSearch(x, a, begin, end):
    if begin >= end:
        return begin
    mid = (begin+end)//2
    if x == a[mid]:
        return mid
    if mid > 0 and a[mid-1] > x and x > a[mid]:
        return mid
    if  x > a[mid]:
        return binSearch(x, a, begin, mid)
    return binSearch(x, a, mid+1, end)

def linSearch(x, a):
    if len(a) == 0:
        return 0
    i = 0
    while i < len(a) and x < a[i]:
        i += 1
    return i

