from typing import NamedTuple, Optional, Tuple
import sys


class Node(NamedTuple):
    lo: int
    hi: int
    a: int = 0
    b: int = 0
    c: int = 0
    l: "Optional[Node]" = None
    r: "Optional[Node]" = None


def combine_node(l: Node, r: Node) -> Node:
    t = min(l.b, r.c)
    a = l.a + r.a + t
    b = l.b + r.b - t
    c = l.c + r.c - t
    return Node(l.lo, r.hi, a, b, c, l, r)


def make_node(line: str, indices: Optional[Tuple[int, int]] = None) -> Node:
    if indices is None:
        indices = (0, len(line) - 1)
    lo, hi = indices
    if lo == hi:
        c = line[lo]
        if c == "(":
            n = Node(lo, hi, b=1)
            return n
        if c == ")":
            n = Node(lo, hi, c=1)
            return n
        raise ValueError(f"Unexpected character `{c}`")
    mid = (lo + hi) // 2
    l = make_node(line, (lo, mid))
    r = make_node(line, (mid + 1, hi))
    return combine_node(l, r)


def search(n: Node, indices: Tuple[int, int]) -> Node:
    lo, hi = indices
    if lo == n.lo and hi == n.hi:
        return n
    l = search(n.l, (lo, min(hi, n.l.hi))) if n.l is not None and lo <= n.l.hi else None
    r = search(n.r, (max(n.r.lo, lo), hi)) if n.r is not None and hi >= n.r.lo else None
    if l is not None and r is not None:
        return combine_node(l, r)
    if l is not None:
        return l
    if r is not None:
        return r
    raise ValueError(f"Invalid indices {lo} and {hi}")


