class Node:
    def __init__(self,value,op):
        self.value = value
        self.op = op

class SegmentTree:
    def __init__(self,arr):
        self.arr = arr
        self.n = len(arr)
        self.tree = [0] * (2 * self.n)
        self.build(self.arr)

    def build(self,arr):
        for i in range(self.n):
            self.tree[self.n + i] = Node(arr[i],"or")
        for i in range(self.n - 1, 0, -1):
            operation = self.tree[2*i].op
            if operation == 'or':
                self.tree[i] = Node(self.tree[2 * i].value | self.tree[2 * i + 1].value , 'xor')
            else:
                self.tree[i] = Node(self.tree[2 * i].value ^ self.tree[2 * i + 1].value,'or')

    def update(self,p, value):
        p += self.n
        operation = self.tree[p].op
        self.tree[p] = Node(value,operation)
        while p > 1:
            if p % 2 == 0:
                sibling = p + 1
            else:
                sibling = p - 1
            operation = self.tree[p].op
            if operation == 'or':
                self.tree[p // 2] = Node(self.tree[p].value | self.tree[sibling].value,'xor')
            else:
                self.tree[p // 2] = Node(self.tree[p].value ^ self.tree[sibling].value,'or')
            p //= 2

    def query(self,l, r):
        res = 0
        l += self.n
        r += self.n
        while l < r:
            if l % 2 == 1:
                res += self.tree[l].value
                l += 1
            if r % 2 == 1:
                r -= 1
                res += self.tree[r].value
            l //= 2
            r //= 2
        return res


