import sys
T = sys.stdin.readline().rstrip('\n')

def preprocess(T):
    """Turn P into a list Z_i, where Z_i is the maximum that obeys P[:Z_i] = P[i:i+Z_i]"""
    Z = [0]*len(T)
    n = len(T)

    l = r = 0
    for k in range(1, len(T)):
        if k >= r:
            tmp = 0
            while k + tmp < n and T[tmp] == T[k + tmp]:
                tmp += 1

            if tmp >= 0:
                Z[k] = tmp
                l, r = k, k + tmp

        else:
            # at this point we are in a Z-Box. Note T[:r-l] = T[r:l]
            if k + Z[k-l] < r:
                Z[k] = Z[k-l]
            else:
                tmp = 0
                while r + tmp < n and T[r - k + tmp] == T[r + tmp]:
                    tmp += 1

                Z[k] = r - k + tmp
                l,r = k, r + tmp

    return Z

def lower_bound(S, t):
    lower, upper = 0, len(S)
    while lower < upper:
        mid = (lower + upper)//2
        if S[mid] >= t:
            upper = mid
        elif S[mid] < t:
            lower = mid + 1
    return upper

def upper_bound(S, t):
    lower, upper = 0, len(S)
    while lower < upper:
        mid = (lower + upper)//2
        if S[mid] > t:
            upper = mid
        elif S[mid] <= t:
            lower = mid + 1
    return upper


def search(T):
    
    Z = preprocess(T)
    n = len(Z)

    suffix = [i for i in range(n) if Z[-i] == i]
    best = 0
    for pos, z in enumerate(Z):
        if pos + z == n:
            z -= 1

        mid = max(upper_bound(suffix, z) - 1, 0)
        best = max(best, suffix[mid])

    if best > 0:
        return T[:best]
    else:
        return "Just a legend"
    
print(search(T))

