class Node:
    def __init__(self, start, end, sum=0, up=0, down=0, left=None, right=None):
        self.left = left
        self.right = right
        self.start = start
        self.end = end
        self.sum = sum
        self.up = up
        self.down = down

        if left and right:
            if left.up < right.down:
                self.sum = left.sum + right.sum + left.up
                self.down = left.down + right.down - left.up
                self.up = right.up
            else:
                self.sum = left.sum + right.sum + right.down
                self.down = left.down
                self.up = left.up - right.down + right.up

    def __str__(self) -> str:
        return '[' + str(self.start) + ', ' \
            + str(self.end) + ', ' \
            + str(self.sum) + ', ' \
            + str(self.up) + ', ' \
            + str(self.down) + ', ' \
            + str(self.left) + ', ' \
            + str(self.right) + ']'

def build(start: int, end: int, s) -> Node:
    if start == end - 1:
        if s[start] == '(':
            return Node(start, end, up=1)
        else:
            return Node(start, end, down=1)
    else:
        mid = start + end >> 1
        return Node(start, end, left=build(start, mid, s), right=build(mid, end, s))

def check(root: Optional[Node], start: int, end: int):
    if not root or end <= root.start or start >= root.end:
        return Node(start, end)
    elif start <= root.start and end >= root.end:
        return root    
    else:
        return Node(start, end, left=check(root.left, start, end), right=check(root.right, start, end))
    
