def find_shortest_path(graph, start='1', end=None):
    if not end:
        end = str(len(graph))

    queue = {start: 0}
    paths = {}
    visited = set([])
    while len(queue) != 0:
        current = min(queue, key=queue.get)
        current_d = queue.pop(current)

        for neighbor, d in graph[current]:
            changed = False # Flag to know if updated queue with a minimum distance
            # Check that my neighbor is not already in my queue
            if neighbor not in visited:
                if neighbor in queue:
                    if d + current_d < queue[neighbor]:
                        queue[neighbor] = d + current_d
                        changed = True
                else:
                    queue[neighbor] = d + current_d
                
                if neighbor in paths:
                    if changed:
                        paths[neighbor] = paths[current] + [neighbor]
                else:
                    if current not in paths:
                        paths[neighbor] = [current, neighbor]
                    else:
                        paths[neighbor] = paths[current] + [neighbor]


        visited.add(current)

    if end in paths:
        return paths[end]
    else:
        return['-1']

