class DSU:
    # FYI - i wrote this now(just to clarify)
    def __init__(self, n):
        self.parents = [i for i in range(n)]
        self.sizes = [1 for _ in range(n)]

    def find(self, cell):
        while self.parents[cell] != cell:
            self.parents[cell] = self.parents[self.parents[cell]]
            cell = self.parents[cell]
        return self.parents[cell]

    def union(self, cell1, cell2):
        parentA, parentB = self.find(cell1), self.find(cell2)
        if parentA != parentB:
            if self.sizes[parentA] > self.sizes[parentB]:
                self.parents[parentB] = parentA
                self.sizes[parentA] += self.sizes[parentB]
            else:
                self.parents[parentA] = parentB
                self.sizes[parentB] += self.sizes[parentA]

        


