def leftRight(aa):
    l, r, a= aa[0], aa[1], aa[2]
    if l < r:
        if a >= (r -l):
            a -= (r-l)
            l += (r-l)
        else:
            l += a
            a = 0
    elif r > l:
        if a >= (l - r):
            a -= (l-r)
            r += (l-r)
        else:
            r += a
            a = 0
    res = min(r,l)*2
    if a >= 2:
        res += (a//2) * 2
    return res

