def binSearch(ar, val):
    "return idx such that ar[i] is <= val with i < idx"
    lo, hi = 0,len(ar)-1
    if len(ar) == 0:
        return 0
    if len(ar) == 1:
        return 1*(ar[0][1] <= val)
    if ar[0][1] > val:
        return 0
    if ar[-1][1] < val:
        return len(ar)
    #print("f")
    while lo <= hi:
        mid = (lo+hi)//2
        #print(lo,mid,hi)
        if ar[mid+1][1] > val and ar[mid][1] <= val:
            return mid+1
        elif ar[mid][1] <= val:
            lo = mid+1
        else:
            hi = mid-1

