def find_substring_t(s):
    n = len(s)
    lps = [0] * n  # Longest Prefix which is also a Suffix array
    j = 0

    # Compute the Longest Prefix which is also a Suffix (LPS) array
    for i in range(1, n):
        while j > 0 and s[i] != s[j]:
            j = lps[j - 1]
        if s[i] == s[j]:
            j += 1
        lps[i] = j

    # Check for common prefix and suffix
    common_length = lps[-1]
    if common_length == 0:
        return "Just a legend"

    # Check if the common substring exists in the middle of the string
    for i in range(n - 1):
        if lps[i] == common_length:
            return s[:common_length]

    # If common substring exists as prefix/suffix, return it
    return s[:common_length]

