def f2(n, k, x, M, D):
    if x > M:
        return -1
    A = n//(k*x)
    B = n % (k*x)
    #n = A*(kx)+B
    if B < x:
        if A <= D:
            return A*x
        else:
            return -1
    else:
        if (A+1) <= D:
            return (A+1)*x
        else:
            return -1
    

def process(n, k, M, D):
    answer = 0
    for x in range(1, M+1):
        answer = max(answer, f2(n, k, x, M, D))
    return answer

