def getCharacters(s):
    res = {}
    for l in s:
        res[l] = 0
    return res

def minKValue(chr, s, lenS, k=2):
    while k <= lenS:
        chr = getCharacters(s)
        window = [0, k]
        qtdParts = lenS - k + 1
        while window[1] <= lenS:
            subs = s[window[0]:window[1]]
            letters = set()
            #print("substring: {}".format(subs))
            for letter in subs:
                if letter not in letters:
                    chr[letter] += 1
                    letters.add(letter)
            window[0] += 1
            window[1] += 1
        #print("map: {}".format(chr))
        for char in chr.keys():
            if chr[char] == qtdParts:
                return k
        k += 1
    return k

def process(s, lenS):
    characters = getCharacters(s)
    if lenS == 1 or len(characters.keys()) == 1:
        return 1
    else:
        return minKValue(characters, s, lenS)

def run():
    s = input()
    lenS = len(s)
    minK = process(s, lenS)
