def binary_search(arr, n, k):
    l, r = 1, n
    while (l <= r):
        mid = l+r >> 1
        if (arr[mid][1] < k):
            l = mid+1
        elif (arr[mid][0] > k):
            r = mid-1
        else:
            return mid
    return -1

