def find_smaller_than_in_asc_sorted(x, l):
    if len(l) == 0 or l[0] > x:
        return (None, None)

    if len(l) == 1:
        if l[0] < x:
            return (l[0], 0)
        else:
            return (None, None)

    sep = len(l) // 2
    sample = l[sep]

    if sample < x:
        (sol, sub_pos) = find_smaller_than_in_asc_sorted(x, l[sep:])
        return (sol, None if sub_pos is None else sub_pos + sep)
    elif sample == x:
        return (l[sep-1], sep-1)
    else:
        return find_smaller_than_in_asc_sorted(x, l[:sep])


