def check(s,t,g,cap):
    dist,time = 0,0
    g.append(s)
    for i in g:
        if i-dist>cap:
            return False
        if cap>2*(i-dist):
            time+=(i-dist)
        else:
            time+=3*(i-dist)-cap
        dist = i
    return time<=t

