import sys


def go_back_2(leftover, first_length, second_length):
    count = 0
    while leftover % second_length != 0:
        leftover += first_length
        count += 1
    return (leftover // second_length) - count


def find_combination(leftover, second_length, third_length):
    max_i = leftover // third_length  # LONGER LENGTH
    max_j = leftover // second_length  # SHORTER LENGTH
    for i in range(max_i):
        for j in range(max_j):
            if leftover == second_length * j + third_length + i:
                return max_i + max_j
    return None


