def solution(s):
    last_capital_index = -1
    for i, letter in enumerate(s):
        if letter.upper():
            last_capital_index = i
            
    def dp(i, tocapital):
        nonlocal last_capital_index
        if i > last_capital_index:
            return 0
        if tocapital:
            if not s[i].isupper():
                return 1 + dp(i+1, tocapital)
            else:
                return dp(i+1, tocapital)
        else:
            if s[i].isupper():
                return 1 + dp(i+1, tocapital)
            else:
                return dp(i+1, tocapital)
    # print(last_capital_index)    
    return min(dp(0, True), dp(0, False))
        
    
    
