class Node():
	def __init__(self, n, parent):
		self.n = n
		self.c = 0
		self.parent = parent
		self.children = []
	def add(self, child):
		if(self.parent != None and self.c == 0):
			self.parent.c -= 1
		self.c += 1
		self.children.append(child)
	def DFS(self, n):
		if(self.n == n):
			return self
		if(len(self.children) == 0):
			return None
		field = []
		field.extend(self.children)
		for node in field:
			x = node.DFS(n)
			if(x != None):
				return x
	def spruce(self):
		if(self.c < 3 and self.c != 0):
			return False
		else:
			field = []
			field.extend(self.children)
			for node in field:
				node.spruce()
	def __repr__(self):
		return str(self.n)
