import math

def Trident():
    s = input()
    up = s.count('U')
    down = s.count('D')
    left = s.count('L')
    right = s.count('R')
    changes = 0
    
    ud_value = math.floor(abs(up-down)/2)+ min(up,down)
    up_change = abs(up-ud_value)
    down_change = abs(down-ud_value)
    lr_value = math.floor(abs(left-right)/2)+ min(left,right)
    left_change = abs(left-lr_value)
    right_change = abs(right-lr_value)

    
    if up_change == down_change:
        changes += up_change
        if left_change == right_change:
            changes += left_change
        else:
            changes = -1
    else:
        if left_change == right_change:
            changes = -1
        else:
            if abs(up-down) == abs(left-right):
                changes += abs(up-down)
            else:
                changes = -1
    print (changes)

