def fg(n):
    primes = [] #存放质数
    is_prime = [1]*(n+1) #假设所有数都是质数，做标记。1表示是质数，0表示不是质数。
    is_prime[0] = is_prime[1] = 0 #0和1不是质数
    for i in range(2, n+1):
        if is_prime[i]:
            primes.append(i)
        for p in primes:
            if i * p > n:
                break
            is_prime[i * p] = 0
            if i % p == 0:  #保证每个合数只会被它的最小的质因数筛选掉
                break
    return [i for i in range(2, n+1) if is_prime[i]]
