                i += 1
        p1t = not p1t
    return p1 == p2

def fair(cards):
    cards.sort()
    count = 1
    prev = cards[0]
    for i in range(len(cards)):
        if cards[i] != prev:
            count += 1
            prev = cards[i]
    if count != 2:
        return False
    return True
    
    

