from heapq import heappush, heappop, heapify, heapreplace

class Vertex:
    def __init__(self, val, dist, path, edges):
        self.val = val
        self.path = path
        self.dist = dist
        self.edges = edges
        self.visited = False
    
    def __lt__(self, value):
        return self.dist < value.dist
    def __le__(self, value):
        return self.dist <= value.dist
    def __gt__(self, value):
        return self.dist > value.dist
    def __ge__(self, value):
        return self.dist >= value.dist
    def __eq__(self, value):
        return self.dist == value.dist
    def __repr__(self):
        return str(self.val) + ", dist: " + \
                str(self.dist) + ", " + \
                str(self.path) + " vis? " + \
                str(self.visited)
        
def dijkstra(graph, goal):
    graph[1].dist = 0
    graph[1].path = [1]
    pq = [graph[1]]
    
    while len(pq):
        curr = heappop(pq)
        
        if curr.val == goal:
            return ' '.join(map(str, curr.path))
        if not curr.visited:
            # print("currently exploring:", curr)
            curr.visited = True
            
            for w, cost in curr.edges:
                dist_to_w = curr.dist + cost
                vertex_w = graph[w]
                if vertex_w.dist > dist_to_w:
                    graph[w].dist = dist_to_w
                    graph[w].path = curr.path + [w]
                    
                if not vertex_w.visited:
                    heappush(pq, vertex_w)
                    
    return -1
    
    
