def gcd(a, b):
    def stein(a, b):
        if a == b:
            return a
        elif a % 2 == 0:
            return stein(a // 2, b)
        elif b % 2 == 0:
            return stein(b // 2, a)
        elif a >= b:
            return stein(((a - b) // 2), b)
        else:
            return stein(((b - a) // 2), a)
    a = abs(a)
    b = abs(b)
    if a < 1 or b < 1:
        return 1
    if a % 2 == 0 and b % 2 == 0:
        return 2 * stein(a // 2, b // 2)
    else:
        return stein(a, b)


