def dijkstra(g):
    n = len(g)
    d, used = [INF for _ in range(n)], [False for _ in range(n)]
    d[0] = 0
    p = [-1 for _ in range(n)]
    for i in range(n):
        v = None
        for j in range(n):
            if not used[j] and (v is None or d[j] < d[v]):
                v = j
        if v is None or d[v] == INF:
            break
        used[v] = True
        for e in range(n):
            if g[v][e] == 0:
                continue
            l = d[v] + g[v][e]
            if l < d[e]:
                d[e] = l
                p[e] = v
    if d[n - 1] == INF:
        return [-1]
    return p


def restore_path(p):
    ans = [len(p)]
    i = len(p) - 1
    while i != 0:
        ans.append(p[i] + 1)
        i = p[i]
    return reversed(ans)


