def solve(s):
    n = len(s)
    p = 31
    m = 2 ** 30 - 1
    pow = 1
    suffix_hash = 0
    prefix_hash = 0
    candidates = []
    for i in range(n):
        suffix_hash = (suffix_hash + (ord(s[n - 1 - i]) - ord('a')) * pow) & m
        prefix_hash = ((prefix_hash * p) + (ord(s[i]) - ord('a'))) & m
        if prefix_hash == suffix_hash:
            candidates.append(i + 1)
        pow = (pow * p) & m
    if not candidates or s[:candidates[0]] not in s[1:-1]:
        return None
    if s[:candidates[-1]] in s[1:-1]:
        return s[:candidates[-1]]
    low = 0
    high = len(candidates) - 1
    while low + 1 < high:
        mid = (low + high) // 2
        if s[:candidates[mid]] in s[1:-1]:
            low = mid
        else:
            high = mid
    return s[:candidates[low]]


