from collections import  defaultdict
def zeta(s):
    """z[i] contiene la longitud del mayor
    prefijo de s que tambien arranque en i"""
    n = len(s)
    z = [0]*n
    l,r = 0,0
    for i in range(1,n):
        if(i<=r): z[i] = min(r-i+1,z[i-l])
        while(i+z[i]<n and s[z[i]]==s[i+z[i]]):
            z[i]+=1
        if(i+z[i]-1>r):
            l=i
            r = i+z[i]-1
    return z

