import sys
def init():
	for i in range(m):
		parent[i]=parent[m+i]
		if parent[i]>=m:
			parent[i]-=m
	parent[m:]=[-1]*m
def find(i):
	if parent[i] == i:
		return i
	parent[i]=find(parent[i])
	return parent[i]
def union(i,j):
	if parent[i]==-1 or parent[j]==-1:
		return False
	i=find(i)
	j=find(j)
	if i==j:
		return False
	if i > j:
		parent[j]=i
	else:
		parent[i]=j
	return True
