def tob(valChar):
    v = int(valChar, 16)
    v = bin(v)
    v = list(v[2:])
    v = ['0'] * (4-len(v)) + v
    return v


def one_index(a, r):
    ones = [0] * N
    for c in range(N // 4):
        v = tob(a[r][c])
        for i in range(4):
            if v[i] == '1':
                ones[c*4+i] = 1

    groups = set()
    if ones[0] != 0:
        groups.add(1)
    for i in range(1, N):
        if ones[i] == 1:
            if ones[i-1] != 0:
                ones[i] = ones[i-1]
            else:
                ones[i] = i + 1
                groups.add(i + 1)

    return ones, groups

def one_index2(a, r):
    ones = []
    for c in range(N // 4):
        v = tob(a[r][c])
        t = []
        for i in range(4):
            if v[i] == '1':
                j = c * 4 + i
                if t and t[-1][1] == j - 1:
                    u = t.pop()
                    t.append((u[0], j))
                else:
                    t.append((j, j))
        if t:
            if ones and ones[-1][1] == t[0][0] - 1:
                u = ones.pop()
                ones.append((u[0], t[0][1]))
                for u in t[1:]:
                    ones.append(u)
            else:
                for u in t:
                    ones.append(u)
    return ones

