def q_mul(multiple_num1, multiple_num2, mod):
    residual = multiple_num1 * multiple_num2 - math.floor(multiple_num1 * multiple_num2 / mod) * mod
    return residual


def q_pow(base, exponent, mod):
    residual = 1
    while exponent:
        if exponent & 1:
            residual = q_mul(residual, base, mod)
        base = q_mul(base, base, mod)
        exponent >>= 1
    return residual


def miller_rabin(num):
    if num == 2:
        return True
    if not num & 1 or num == 1:
        return False
    exponent_num = num - 1
    exponent_2 = 0
    while not exponent_num & 1:
        exponent_2 += 1
        exponent_num >>= 1
    for check_base in check_bases:
        if num % check_base == 0:
            return False
        check_pow = q_pow(check_base, exponent_num, num)
        if check_pow == 1 or check_pow == num - 1:
            continue
        for k in range(0, exponent_2):
            check_pow = q_mul(check_pow, check_pow, num)
            if check_pow == n - 1 and k + 1 != exponent_2:
                check_pow = 1
                break
            if check_pow == 1:
                return False
        if check_pow != 1:
            return False
    return True


def if_t_prime(num: int):
    root = math.floor(math.sqrt(num))
    if root ** 2 == num and miller_rabin(root):
        return True
    else:
        return False


