def p(a, n):
    if n == 0:
        res_dict[0] = 1
        return res_dict[n]
    if n == 1:
        res_dict[1] = a % mod
        return res_dict[n]
    if n % 2 == 0:
        tmp = p(a, int(n / 2))
        res_dict[n] = (tmp * tmp) % mod
        return res_dict[n]
    else:
        tmp = p(a, int((n - 1) / 2))
        res_dict[n] = (((tmp * tmp) % mod) * a) % mod
        return res_dict[n]

def q(a, n):
    if n == 1:
        return 1
    if n % 2 == 0:
        tmp = q(a, int(n / 2))
        return (tmp + ((res_dict[int(n / 2)] * tmp) % mod)) % mod
    else:
        tmp = q(a, int((n - 1) / 2))
        return (((a * tmp) % mod) + ((((a * res_dict[int((n - 1) / 2)]) % mod) * tmp) % mod) + 1) % mod

