    res = 0
    while x > 0:
        x //= 10
        res += 1
    return res


def first(x):
    last = 0
    while x > 0:
        last = x % 10
        x //= 10
    return last


def last(x):
    return x % 10


def cut(x):
    x //= 10
    x -= first(x) * 10 ** (size(x) - 1)
    return x


