import sys
import heapq

class path:
    def __init__(self, start_node):
        self.distance = 0
        self.node = start_node
        self.cities = []

    def __lt__(self, other):
        return self.distance < other.distance

class node:
    def __init__(self, ident):
        self.id = ident
        self.edge = []

class edge:
    def __init__(self, dist, node):
        self.dist = dist
        self.connected_node = node
        
n_vertices, n_edges = tuple([int(x) for x in sys.stdin.readline().split()])
nodes = {}

for i in range(n_edges):
    a, b, weight = tuple([int(x) for x in sys.stdin.readline().split()])
    node_a, node_b = None, None

    if a not in nodes:
        node_a = node(a)
        nodes[a] = node_a
    else:
        node_a = nodes[a]

    if b not in nodes:
        node_b = node(b)
        nodes[b] = node_b
    else:
        node_b = nodes[b]

    node_a.edge.append(edge(weight, node_b))
    node_b.edge.append(edge(weight, node_a))

def dijkstra(start, end):
    heap = [path(nodes[start])]
    while len(heap) != 0:
        top = heapq.heappop(heap)
        if top.node.id == end:
            #print(top.distance)
            return [1] + top.cities

        for edges in top.node.edge:
            distance = edges.dist
            new_path = path(edges.connected_node)
            new_path.cities = top.cities + [edges.connected_node.id]
            new_path.distance = top.distance + distance
            heapq.heappush(heap, new_path)
    return []
    
