def searchInsert(nums, target: int) -> int:
    idx = 0
    while len(nums) != 1:
        if nums[len(nums)//2] == target:
            return len(nums)//2 + idx
        if nums[len(nums)//2] > target:
            nums = nums[:len(nums)//2]
        else:
            idx += len(nums)//2
            nums = nums[len(nums)//2:]
    if nums[0] < target:
        return idx+1
    else:
        return idx

