def run_dp(a, b, i, dp):
	# print("Called for : {}".format(i))
	if dp[i] is not None:
		# print("returning for : {}".format(i))
		return dp[i]

	count = 0
	for j in reversed(range(i)):
		# print("j: {}, a[j]: {}, last pos: {}".format(j, a[j], (a[i] - b[i])))
		if a[j] < (a[i] - b[i]):
			dp[i] = count + run_dp(a, b, j, dp)
			# print("returning for : {}".format(i))
			return dp[i]
		else:
			count += 1
	dp[i] = count
	# print("returning for : {}".format(i))
	return dp[i]


def main():
	inp = Input()
	n = inp.readInt()
	a = []
	b = []
	for i in range(n):
		l, m = inp.readIntArray()
		a.append(l)
		b.append(m)

	dp = [None for i in range(n)]
	dp[0] = 0
	for i in reversed(range(n)):
		run_dp(a, b, i, dp)

	ans = len(a)
	for i in range(n):
		ans = min(ans, dp[i] + len(dp[i+1:]))

	print(ans)

