def isPrime(n):
    if(n<=3):
        return False
    if(n%2==0 or  n%3==0):
        return False
    for i in range(5,int(math.sqrt(n))+1,6):
        if(n%i==0 or n%(i+2)==0):
            return False
    return True
def nextPrime(n,m):
    if(n<=1 and m==2):
        return True
    prime=n
    found=False
    while(prime<m and not found):
        prime+=1
        if(isPrime(prime)==True):
            found =True
    if(prime==m):
        return True
    else:
        return False
