def isPossible(size):
    a_count = 1 if string[0] == "a" else 0
    b_count = 0 if string[0] == "b" else 0
    l = 0
    r = l+1
    while r-l < size and r < len(string):
        if string[r] == "a":
            a_count += 1
        else:
            b_count += 1
        r += 1
    
    if max(a_count, b_count)+k >= size:
        return True
    else:
        while r < len(string):
            if string[l] == "a":
                a_count -= 1
            else:
                b_count -= 1
            
            if string[r] == "a":
                a_count += 1
            else:
                b_count += 1
            
            if min(a_count, b_count)+k >= size:
                return True
            else:
                l += 1
                r += 1
    return False

