    l = 1
    r = length
    ans = 0
    while l <= r:
        mid = (l+r)//2
        # print(mid, isPossible(mid))
        if isPossible(mid):
            ans = max(ans, mid)
            l = mid+1
        else:
            r = mid-1
    
    return ans

