import sys, math

def factorization(num):
    res = dict()
    x = 2
    while x ** 2 <= num:
        while num % x == 0:
            if x in res:
                res[x] += 1
            else:
                res.update({x : 1})
            num //= x
        x += 1
    if num > 1:
        if num in res:
            res[num] += 1
        else:
            res.update({num : 1})
    return res



