def getsum(l, r):
    return pref[r - 1] - pref[l - 1]


def solve(l, r):
    #print(l, r)
    if r - l == 1:
        return 0
    if r - l == 2:
        return getsum(l, r)
    if r - l == 3:
        return getsum(l, r)
    if r - l == 4:
        return getsum(l, r) + getsum(l, l + 2)
    if r - l == 5:
        return getsum(l, r) + getsum(l, l + 3)
    if r - l == 6:
        return getsum(l, r) + getsum(l, l + 3) + getsum(l + 3, l + 5)
    ll = l + 1
    rr = r
    x = getsum(l, r) // 3
    while ll + 1 < rr:
        mm = (ll + rr) // 2
        if getsum(ll, mm) >= x:
            rr = mm
        else:
            ll = mm
    m1 = ll
    ll = l
    rr = r - 1
    while ll + 1 < rr:
        mm = (ll + rr) // 2
        if getsum(mm, rr) >= x:
            ll = mm
        else:
            rr = mm
    m2 = rr
    return getsum(l, r) + solve(l, m1) + solve(m1, m2) + solve(m2, r)


