import sys

class Node:
    def __init__(self):
        self.children = {}
        self.is_end = False

    def visit(self):
        """
        Returns [can_win, can_lose].
        """
        if len(self.children) == 0:
            return [False, True]
        can_win = False
        can_lose = False
        for child in self.children:
            [win, lose] = self.children[child].visit()
            if win and not lose:
                can_lose = True
            if not win and lose:
                can_win = True
        return [can_win, can_lose]

class Trie:
    def __init__(self):
        self.root = Node()

    def insert(self, word):
        current = self.root
        for char in word:
            if char not in current.children:
                current.children[char] = Node()
            current = current.children[char]
        current.is_end = True    

def solve():
    trie = Trie()
    [n, k] = map(int, sys.stdin.readline().split())
    for _ in range(n):
        trie.insert(sys.stdin.readline().strip())

    [win, loss] = trie.root.visit()
    if win and loss:
        print("First")
    elif loss:
        print("Second")
    else:
        if k % 2 == 0:
            print("Second")
        else:
            print("First")


