input = sys.stdin.readline

def bipart(graph, n):
    visited = [False]*(n+1)
    index = [-1]*(n+1)
    u = set()
    v = set()
    
    for i in range(1,n+1):
        if not visited[i]:
            if len(u)<len(v):
                u.add(str(i))
                index[i] = 0
            else:
                v.add(str(i))
                index[i] = 1
            
            stack = [i]
            visited[i] = True
            while(stack):
                temp = stack[-1]
                for child in graph[temp]:
                    if not visited[child]:
                        stack.append(child)
                        visited[child] = True
                        if not index[temp]:
                            v.add(str(child))
                            index[child] = 1
                        else:
                            u.add(str(child))
                            index[child] = 0
                        break
                else:
                    stack.pop()
    return (len(u)*len(v)-n+1)

