from collections import deque

def reachable(v, edges):
    stack = deque()
    stack.append(v)
    seen = set()
    while stack:
        v = stack.pop()
        if v not in seen:
            seen.add(v)
            for u in edges[v]:
                stack.append(u)
    return seen

def post_numbers(vertices, edges):
    post = []
    seen = set()
    stack = deque()
    for v in vertices:
        if v not in seen:
            stack.append((v, 0))
        while stack:
            v, b = stack.pop()
            if b == 1:
                post.append(v)
            elif v not in seen:
                seen.add(v)
                stack.append((v, 1))
                for u in edges[v]:
                    if u in vertices:
                        stack.append((u, 0))
    return list(reversed(post))


def find_scc(vertices, edges, transpose):
    post = post_numbers(vertices, edges)
    scc_counter = -1
    scc = dict()
    scc_edges = dict()
    scc_edges_transpose = dict()
    for v in post:
        if v not in scc:
            scc_counter += 1
            scc_edges[scc_counter] = []
            scc_edges_transpose[scc_counter] = []
            stack = deque()
            stack.append(v)
            while stack:
                v = stack.pop()
                if v not in scc:
                    scc[v] = scc_counter
                    for u in edges[v]:
                        if u in vertices:
                            stack.append(u)
                        if u in scc and scc[u] != scc[v]:
                            scc_edges[scc[v]].append(scc[u])
                            scc_edges_transpose[scc[u]].append(scc[v])
    return scc_counter, scc, scc_edges, scc_edges_transpose

