def get(cur, need, x, y):
    ret = [cur]
    for i in range(2 * m):
        cur = (cur * x + y) % m
        ret.append(cur)

    if need not in ret:
        return None, 0

    idx = ret.index(need)

    if need not in ret[idx + 1:]:
        return idx, None

    idx2 = ret.index(need, idx + 1)

    return (idx, idx2 - idx)

def on_path(p, c, x):
    if x < p or (x - p) % c:
        return -1
    return x

def get_min(p1, c1, p2, c2):
    for t1 in range(2 * m):
        x = p1 + t1 * c1
        if x >= p2 and (x - p2) % c2 == 0:
            return x
    return -1

