memo = {0: 1 }
def dp(weight, flag):
    
    global k, d, memo

    if (weight, flag) in memo:
        return memo[(weight, flag)]
    if flag and weight == 0:
        return 1
    elif weight < 0:
        return 0
    
    path = 0
    for i in range(1, k+1):
        path += dp(weight - i, flag or i >= d)
    
    memo[(weight, flag)] = path
    return path

