def findNumUsed(uNum, uDen):
    u10Times  = 0;
    uNumUsed = uNum;

    while(uNumUsed < uDen):
        uNumUsed *= 10;
        u10Times += 1;

    return (uNumUsed, u10Times);


def findPosition(uNum, uDen, uTarget):
    uRemain = uNum;
    uNumUsed = None;
    u10Times = 0;
    uResult = 0;
    uPosition = 0;
    bEnd = False;

    while(not(bEnd)):
        (uNumUsed, u10Times) = findNumUsed(uRemain, uDen);

        uPosition += u10Times;

        if(uTarget == 0):#Special case for Target is 0, during findNumUsed
            if(u10Times >= 2):#one or more zero is added
                uPosition = uPosition - u10Times +1;#get the closest zero position                
                bEnd = True;
                break;
        #end of uTarget == 0

        uResult = uNumUsed //uDen;
        uRemain = uNumUsed % uDen;

        if(uResult == uTarget):#find out
            bEnd = True;
        elif(uRemain == 0):#Can not going on
            bEnd = True;
            if(uTarget == 0):
                uPosition += 1;
        elif(uRemain == uNum):#Repeat, can not find
            bEnd = True;
            uPosition = -1;
        else:#Continue:
            pass;

    #end of while
    return uPosition;

