    def __init__(self,max_size):
        self.stack = [None for x in range(max_size)]
        self.top_pointer = -1
    def push(self,new_element):
        self.top_pointer = self.top_pointer+1
        self.stack[self.top_pointer] = new_element
    def pop(self):
        last_element = self.stack[self.top_pointer]
        self.top_pointer = self.top_pointer -1
        return last_element
    def peek(self):
        return self.stack[self.top_pointer]
    def show(self):
        for k in self.stack:
            print(k)
    def is_empty(self):
        if self.top_pointer == -1:
            return  True


def checkBalance(expression):
    result = 0
    mystack = Stack(len(expression))
    for e in expression:
        if e == '(':
            mystack.push(e)
        elif e == ')' :
            if mystack.is_empty() == True :
                return print(result)
            elif mystack.peek() == '(':
                mystack.pop()
                result = result + 2
    print(result)
