def distancia(n1, n2):
    if n1 > n2:
        n1, n2 = n2, n1

    if n1 < 0 and n2 > 0:
        return -n1 + n2
    elif n1 < 0 and n2 < 0:
        return n2 - n1
    elif n1 > 0 and n2 > 0:
        return n2 - n1
    elif n1 == 0:
        return n2
    elif n2 == 0:
        return n1


