def s2(n,a,b):
  x = sorted([a,b])
  a,b = x[0],x[1]
  if n < a:
    return -1
  if n == a:
    return 1
  if n < b:
    if not n % a:
      return n // a
    return -1
  if n == b:
    if not n % a:
      return n // a
    return 1

  c = s2(n-a,a,b)+1
  if c != -1:
    return c
  return s2(n-b,a,b)+1


def solve(n,a,b,c):
  x = sorted([a,b,c])
  a,b,c = x[0],x[1],x[2]
  if n == a:
    return 1
  if n < a:
    return 1
  if n < b:
    if n % a == 0:
      return n//a
    return -1
  if n == b:
    if n % a == 0:
      return n // a
    return 1
  d = s2(n,a,b)
  if d != -1:
    return d
  if n < c:
    return -1
  if n == c:
    return 1


  e = solve(n-a,a,b,c)+1
  if e != -1:
    return e
  f = solve(n-b,a,b,c)+1
