from math import factorial, gcd
def limit(n, m, a0, b0):
    if n<m:
        return "0/1"
    
    elif n>m:
        if a0/b0<0:
            return "-Infinity"
        else:
            return "Infinity"
        
    else:
        if a0==0:
            return "0/1"
        elif b0==0:
            if a0>=0:
                return "Infinity"
            else:
                return "-Infinity"
            
        a = a0*factorial(n)
        b = b0*factorial(m)
        hcf = gcd(a,b)

        a = a//hcf
        b = b//hcf

        return (str(a)+"/"+str(b))


