def KMPCount(s):
    m = len(s)
    prefix = [0] * m
    i = 1
    j = 0
    
    while i < m:
        if s[i] == s[j]:
            j += 1
            prefix[i] = j
            i += 1
        else:
            if j != 0:
                j = prefix[j - 1]
            else:
                prefix[i] = 0
                i += 1
    l = prefix[m - 1]
    flag = True
    #print(prefix)
    if l > 0:
        i = 0
        j = m - l
        #print(flag)
        while i < l:
            #print(s[i], s[j])
            if s[i] != s[j]:
                flag = False
                break
            i += 1
            j += 1
        #print(flag)
        if i >= (m-l-1):
            flag = False
        else:
            j = m - l - 1
            cnt = 0
            for k in range(j, i+1, -1):
                if prefix[k] == l:
                    cnt = 1
                    while cnt <= l:
                        if s[k] != s[m - cnt]:
                            break
                        cnt += 1
                        k -= 1
                    if cnt > l:
                        break
            if cnt == 0:
                flag = False
        if flag == True:
            return s[m-l:m]
        else:
            return -1
    return -1
