from dataclasses import dataclass
from typing import Tuple
from math import inf

DIRECTIONS = {
    -1: 'L',
    0: 'X',
    1: 'R'
}


@dataclass(frozen=True)
class TurnState:
    note: int
    time: int


@dataclass(frozen=True)
class Solver:
    spies: int
    stages: int
    spy_start: int
    spy_target: int

    def solve(self) -> None:
        state = TurnState(self.spy_start, 1)
        stages_read = 0
        while not self.has_arrived(state):
            if stages_read == self.stages:
                stage_time = inf
            else:
                stage_time, watched_l, watched_r = map(int, input().split())
                stages_read += 1
            while state.time < stage_time and not self.has_arrived(state):
                direction = self.get_direction(state)
                state = pass_note(direction, state)
            if not self.has_arrived(state):
                direction = self.get_direction_watched(state, watched_l, watched_r)
                state = pass_note(direction, state)

    def has_arrived(self, state: TurnState) -> bool:
        return state.note == self.spy_target

    def get_direction(self, state: TurnState) -> int:
        '''Returns -1, 0 or 1 (for L, X and R)'''
        return sign(self.spy_target - state.note)

    def get_direction_watched(self, state: TurnState, watched_l: int, watched_r: int) -> int:
        direction = self.get_direction(state)
        next_spy = state.note + direction
        if state.note >= watched_l and state.note <= watched_r or next_spy >= watched_l and next_spy <= watched_r:
            return 0
        return direction


def pass_note(direction: int, state: TurnState) -> TurnState:
    print(DIRECTIONS[direction], end='')
    return TurnState(state.note + direction, state.time + 1)


def sign(x: int) -> int:
    if x == 0:
        return 0
    return 1 if x > 0 else -1


def main() -> None:
    solver = Solver(*map(int, input().split()))
    solver.solve()


main()

