input = sys.stdin.readline
def inlt():
    return  list(map(int, input().strip().split()))

class Solution:
    def enough(self, length, sum_):
        return  sum_ >= 0 and sum_ <= 9 * length
    
    def places(self, row1, col1, row2, col2):
        rook = 2
        if row1 == row2 or col1 == col2:
            rook = 1
        
        king = max(abs(row1-row2), abs(col1-col2))
        
        if (col1-row1) % 2 !=   (col2-row2) % 2:
            return rook, 0, king
        bishop = 2
        if col1+row1 == col2+row2 or col1-row1 == col2+row2:
            bishop = 1
        
        return rook, bishop, king
    
def main():
    s = Solution()
    row1, col1, row2, col2 = inlt()
    print(*s.places(row1, col1, row2, col2))

main()
